let currentLang = localStorage.getItem('user_lang') || 'es';

function setLanguage(lang) {
  if (lang !== 'es' && lang !== 'en') return;
  currentLang = lang;
  localStorage.setItem('user_lang', currentLang);
  applyLanguage(currentLang);
  closeLangDropdown();
}

function applyLanguage(lang) {
  const elements = document.querySelectorAll('[data-i18n]');
  elements.forEach((el) => {
    const key = el.getAttribute('data-i18n');
    if (translations[lang] && translations[lang][key]) {
      el.innerHTML = iconize(translations[lang][key]);
    }
  });

  document.querySelectorAll('[data-i18n-html]').forEach((el) => {
    const key = el.getAttribute('data-i18n-html');
    if (translations[lang] && translations[lang][key]) {
      el.innerHTML = iconize(translations[lang][key]);
    }
  });

  document.querySelectorAll('[data-i18n-alt]').forEach((el) => {
    const key = el.getAttribute('data-i18n-alt');
    if (translations[lang] && translations[lang][key]) el.setAttribute('alt', translations[lang][key]);
  });

  document.querySelectorAll('[data-i18n-placeholder]').forEach((el) => {
    const key = el.getAttribute('data-i18n-placeholder');
    if (translations[lang] && translations[lang][key]) el.setAttribute('placeholder', translations[lang][key]);
  });

  document.querySelectorAll('[data-i18n-title]').forEach((el) => {
    const key = el.getAttribute('data-i18n-title');
    if (translations[lang] && translations[lang][key]) {
      el.setAttribute('title', translations[lang][key]);
      el.setAttribute('aria-label', translations[lang][key]);
    }
  });

  const langLabel = document.getElementById('lang-label');
  if (langLabel) {
    langLabel.textContent = lang.toUpperCase();
  }

  // Actualizar estado activo en el menú desplegable
  const dropdownItems = document.querySelectorAll('.lang-dropdown-item');
  dropdownItems.forEach((item) => {
    if (item.getAttribute('data-lang') === lang) {
      item.classList.add('active');
    } else {
      item.classList.remove('active');
    }
  });

  document.documentElement.lang = lang;
}

function closeLangDropdown() {
  const wrapper = document.getElementById('lang-dropdown-wrapper');
  const toggleBtn = document.getElementById('lang-toggle');
  if (wrapper) wrapper.classList.remove('open');
  if (toggleBtn) toggleBtn.setAttribute('aria-expanded', 'false');
}

function setupLanguageDropdown() {
  const wrapper = document.getElementById('lang-dropdown-wrapper');
  const toggleBtn = document.getElementById('lang-toggle');
  const menu = document.getElementById('lang-dropdown-menu');
  if (!wrapper || !toggleBtn || !menu) return;

  toggleBtn.addEventListener('click', (e) => {
    e.stopPropagation();
    const isOpen = wrapper.classList.toggle('open');
    toggleBtn.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
  });

  const items = menu.querySelectorAll('.lang-dropdown-item');
  items.forEach((item) => {
    item.addEventListener('click', (e) => {
      e.stopPropagation();
      const selected = item.getAttribute('data-lang');
      if (selected) {
        setLanguage(selected);
      }
    });
  });

  // Cerrar al hacer clic fuera del dropdown
  document.addEventListener('click', (e) => {
    if (!wrapper.contains(e.target)) {
      closeLangDropdown();
    }
  });

  // Cerrar al presionar la tecla Escape
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      closeLangDropdown();
    }
  });
}

function setupCopyButton() {
  document.querySelectorAll('.copy-btn').forEach((copyBtn) => {
    const targetId = copyBtn.dataset.copyTarget || (copyBtn.id === 'copy-code-btn' ? 'ps-code' : null);
    if (!targetId) return;
    const codeElem = document.getElementById(targetId);
    if (!codeElem) return;

    copyBtn.addEventListener('click', () => {
      const textToCopy = codeElem.textContent.trim();
      navigator.clipboard.writeText(textToCopy).then(() => {
        copyBtn.textContent = translations[currentLang].copied_code;
        setTimeout(() => {
          copyBtn.textContent = translations[currentLang].copy_code;
        }, 2000);
      });
    });
  });
}

function setupDetector() {
  const btn = document.getElementById('detect-btn');
  const box = document.getElementById('detect-results');
  if (!btn || !box) return;
  const set = (id, val) => { const el = document.getElementById(id); if (el) el.textContent = val; };

  btn.addEventListener('click', async () => {
    const t = translations[currentLang];
    const na = t.detect_na;
    let os = na, browser = na;
    const ua = navigator.userAgent || '';

    if (navigator.userAgentData) {
      try {
        const hints = await navigator.userAgentData.getHighEntropyValues(['platform']);
        if (hints.platform) os = hints.platform;
        const brands = navigator.userAgentData.brands || [];
        const main = brands.find(b => /Chrome|Edge|Opera/i.test(b.brand));
        if (main) browser = main.brand.replace('Google ', '') + ' ' + main.version;
      } catch (e) { /* se usa el UA clasico */ }
    }
    if (os === na) {
      if (/Windows NT 10/.test(ua)) os = 'Windows 10/11';
      else if (/Windows/.test(ua)) os = 'Windows';
      else if (/Android/.test(ua)) os = 'Android';
      else if (/iPhone|iPad/.test(ua)) os = 'iOS';
      else if (/Mac OS X/.test(ua)) os = 'macOS';
      else if (/Linux/.test(ua)) os = 'Linux';
    }
    if (browser === na) {
      let m;
      if ((m = ua.match(/Edg\/([\d.]+)/))) browser = 'Edge ' + m[1].split('.')[0];
      else if ((m = ua.match(/OPR\/([\d.]+)/))) browser = 'Opera ' + m[1].split('.')[0];
      else if ((m = ua.match(/Chrome\/([\d.]+)/))) browser = 'Chrome ' + m[1].split('.')[0];
      else if ((m = ua.match(/Firefox\/([\d.]+)/))) browser = 'Firefox ' + m[1].split('.')[0];
      else if (/Safari\//.test(ua)) browser = 'Safari';
    }
    set('det-os', os);
    set('det-browser', browser);
    set('det-cores', navigator.hardwareConcurrency ? String(navigator.hardwareConcurrency) : na);
    set('det-ram', navigator.deviceMemory ? '\u2248 ' + navigator.deviceMemory + ' GB' : na);

    let gpu = na;
    try {
      const cv = document.createElement('canvas');
      const gl = cv.getContext('webgl') || cv.getContext('experimental-webgl');
      if (gl) {
        const ext = gl.getExtension('WEBGL_debug_renderer_info');
        const raw = ext ? gl.getParameter(ext.UNMASKED_RENDERER_WEBGL) : gl.getParameter(gl.RENDERER);
        if (raw && /brave/i.test(String(raw))) {
          gpu = t.detect_gpu_private;
        } else if (raw) {
          let g = String(raw).replace(/^ANGLE \(/, '').replace(/\)$/, '');
          const parts = g.split(',').map(x => x.trim());
          g = (parts[1] || parts[0] || g).replace(/\s*\(0x[0-9a-fA-F]+\)/, '').replace(/\s+Direct3D.*$/, '').replace(/\s+OpenGL.*$/, '').trim();
          if (g) gpu = g;
        }
      }
    } catch (e) { /* sin WebGL */ }
    set('det-gpu', gpu);
    set('det-screen', screen.width + ' \u00d7 ' + screen.height + ' px');

    if (navigator.getBattery) {
      navigator.getBattery()
        .then(b => set('det-battery', Math.round(b.level * 100) + '%' + (b.charging ? ' (' + t.detect_charging + ')' : '')))
        .catch(() => set('det-battery', na));
    } else set('det-battery', na);

    box.hidden = false;
  });
}

function setupMobileMenu() {
  const menuBtn = document.getElementById('menu-toggle');
  const navMenu = document.getElementById('nav-menu');
  if (!menuBtn || !navMenu) return;

  menuBtn.addEventListener('click', () => {
    const isActive = navMenu.classList.toggle('is-active');
    navMenu.classList.remove('submenu-active');
    navMenu.querySelectorAll('.nav-item-dropdown').forEach((dropdown) => dropdown.classList.remove('is-open'));
    menuBtn.setAttribute('aria-expanded', isActive ? 'true' : 'false');
    menuBtn.innerHTML = isActive ? '<span class="menu-icon-inner mono-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg></span>' : '<span class="menu-icon-inner mono-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="3" y1="12" x2="21" y2="12"></line><line x1="3" y1="6" x2="21" y2="6"></line><line x1="3" y1="18" x2="21" y2="18"></line></svg></span>';
  });

  const links = navMenu.querySelectorAll('a');
  links.forEach((link) => {
    link.addEventListener('click', () => {
      if (navMenu.classList.contains('is-active')) {
        navMenu.classList.remove('is-active');
        menuBtn.setAttribute('aria-expanded', 'false');
        menuBtn.innerHTML = '<span class="menu-icon-inner mono-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="3" y1="12" x2="21" y2="12"></line><line x1="3" y1="6" x2="21" y2="6"></line><line x1="3" y1="18" x2="21" y2="18"></line></svg></span>';
      }
    });
  });
}

function setupSectionNavigation() {
  const cleanUrl = () => window.location.pathname + window.location.search;

  const scrollToSection = (targetId) => {
    const target = document.getElementById(targetId);
    if (!target) return false;
    target.scrollIntoView({ behavior: 'smooth', block: 'start' });
    window.history.replaceState(null, '', cleanUrl());
    return true;
  };

  const pendingTarget = sessionStorage.getItem('nvision_pending_section');
  if (pendingTarget) {
    sessionStorage.removeItem('nvision_pending_section');
    window.requestAnimationFrame(() => scrollToSection(pendingTarget));
  }

  document.querySelectorAll('a[href*="#"]').forEach((link) => {
    link.addEventListener('click', (event) => {
      const href = link.getAttribute('href');
      if (!href) return;

      const destination = new URL(href, window.location.href);
      if (destination.origin !== window.location.origin) return;

      const targetId = destination.hash.slice(1);
      if (!targetId) {
        if (destination.pathname !== window.location.pathname) return;
        event.preventDefault();
        window.scrollTo({ top: 0, behavior: 'smooth' });
        window.history.replaceState(null, '', cleanUrl());
        return;
      }

      if (destination.pathname === window.location.pathname) {
        if (scrollToSection(targetId)) event.preventDefault();
        return;
      }

      event.preventDefault();
      sessionStorage.setItem('nvision_pending_section', targetId);
      window.location.assign(destination.pathname + destination.search);
    });
  });
}

function setupNavigationDropdowns() {
  const dropdowns = document.querySelectorAll('.nav-item-dropdown');
  const navLinks = document.querySelector('.nav-links');

  dropdowns.forEach((dropdown) => {
    const trigger = dropdown.querySelector('.nav-dropdown-trigger');
    if (!trigger) return;

    trigger.addEventListener('click', () => {
      if (window.matchMedia('(min-width: 821px)').matches) {
        dropdown.classList.remove('is-open');
        trigger.setAttribute('aria-expanded', 'false');
        return;
      }

      const willOpen = !dropdown.classList.contains('is-open');
      dropdowns.forEach((item) => {
        item.classList.remove('is-open');
        const itemTrigger = item.querySelector('.nav-dropdown-trigger');
        if (itemTrigger) itemTrigger.setAttribute('aria-expanded', 'false');
      });
      dropdown.classList.toggle('is-open', willOpen);
      trigger.setAttribute('aria-expanded', String(willOpen));
      if (navLinks) navLinks.classList.toggle('submenu-active', willOpen);
    });

    const backButton = dropdown.querySelector('.nav-mobile-back button');
    if (backButton) {
      backButton.addEventListener('click', (event) => {
        event.stopPropagation();
        dropdown.classList.remove('is-open');
        trigger.setAttribute('aria-expanded', 'false');
        if (navLinks) navLinks.classList.remove('submenu-active');
      });
    }
  });

  document.addEventListener('click', (event) => {
    if (event.target instanceof Node && !event.target.closest('.nav-item-dropdown')) {
      dropdowns.forEach((dropdown) => {
        dropdown.classList.remove('is-open');
        const dropdownTrigger = dropdown.querySelector('.nav-dropdown-trigger');
        if (dropdownTrigger) dropdownTrigger.setAttribute('aria-expanded', 'false');
      });
      if (navLinks) navLinks.classList.remove('submenu-active');
    }
  });
}

function setupThemeToggle() {
  const themeToggleBtn = document.getElementById('theme-toggle');
  const themeIcon = document.getElementById('theme-icon');
  
  const savedTheme = localStorage.getItem('user_theme');
  const currentTheme = savedTheme || 'light';
  
  function applyTheme(theme) {
    document.documentElement.setAttribute('data-theme', theme);
    if (themeIcon) {
      const sunSvg = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="5"></circle><line x1="12" y1="1" x2="12" y2="3"></line><line x1="12" y1="21" x2="12" y2="23"></line><line x1="4.22" y1="4.22" x2="5.64" y2="5.64"></line><line x1="18.36" y1="18.36" x2="19.78" y2="19.78"></line><line x1="1" y1="12" x2="3" y2="12"></line><line x1="21" y1="12" x2="23" y2="12"></line><line x1="4.22" y1="19.78" x2="5.64" y2="18.36"></line><line x1="18.36" y1="5.64" x2="19.78" y2="4.22"></line></svg>';
      const moonSvg = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"></path></svg>';
      themeIcon.innerHTML = theme === 'light' ? sunSvg : moonSvg;
    }
    if (themeToggleBtn) {
      themeToggleBtn.setAttribute('title', theme === 'light' ? 'Cambiar a modo oscuro / Switch to dark mode' : 'Cambiar a modo claro / Switch to light mode');
      themeToggleBtn.setAttribute('aria-label', theme === 'light' ? 'Cambiar a modo oscuro' : 'Cambiar a modo claro');
    }
  }

  applyTheme(currentTheme);

  if (themeToggleBtn) {
    themeToggleBtn.addEventListener('click', () => {
      const activeTheme = document.documentElement.getAttribute('data-theme') === 'light' ? 'light' : 'dark';
      const nextTheme = activeTheme === 'light' ? 'dark' : 'light';
      localStorage.setItem('user_theme', nextTheme);
      applyTheme(nextTheme);
    });
  }
}

function setupLocalAssistant() {
  if (document.querySelector('.local-assistant')) return;

  /* ===== Base de conocimiento entrenada (modelo tipo FinBot) =====
     c = categoría · k = formas de preguntar (ES/EN) · r = respuesta [ES, EN] · href = sección del sitio */
  const KB = [
{ c: 'Hardware', k: ['que es el socket', 'socket del procesador', 'socket cpu'], r: ['El **socket** es el conector de la placa base donde encaja el procesador. Cada generación usa un socket distinto: por eso no puedes poner cualquier CPU en cualquier placa, aunque se vean iguales.', 'The **socket** is the motherboard connector where the processor fits. Each generation uses a different socket: that is why you cannot put any CPU in any board, even if they look alike.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['que es overclock', 'overclocking', 'overclock cpu'], r: ['El **overclocking** es forzar al procesador (o la GPU) a correr por encima de su frecuencia de fábrica para ganar rendimiento. Da más velocidad, pero también más calor y consumo, y puede acortar la vida del componente si no se refrigera bien.', '**Overclocking** means pushing the processor (or GPU) above its factory frequency for extra performance. It gives more speed, but also more heat and power draw, and it can shorten the component\u2019s life without good cooling.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['que es el tdp', 'tdp procesador', 'tdp que significa'], r: ['El **TDP** (Thermal Design Power) es el calor máximo, en vatios, que un procesador o GPU genera en uso típico. Sirve para elegir refrigeración y fuente: un TDP alto pide mejor disipador y más vatios.', '**TDP** (Thermal Design Power) is the maximum heat, in watts, a processor or GPU generates under typical load. It tells you which cooling and PSU you need: a high TDP demands a better cooler and more watts.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['que es la cache del procesador', 'cache l1 l2 l3', 'memoria cache cpu'], r: ['La **caché** es una memoria diminuta y ultra rápida dentro del procesador, en niveles **L1, L2 y L3**: guarda los datos que la CPU usa una y otra vez para no ir a buscarlos a la RAM, que es más lenta.', '**Cache** is a tiny, ultra-fast memory inside the processor, in **L1, L2 and L3** levels: it holds the data the CPU reuses constantly so it does not have to fetch it from the slower RAM.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['frecuencia base y boost', 'frecuencia boost cpu', 'ghz base boost'], r: ['La **frecuencia base** es la velocidad normal del procesador (en GHz) y la **boost** es la velocidad máxima que alcanza por momentos cuando hay trabajo pesado y temperatura de sobra. Más GHz no siempre es más rápido: también importan núcleos y arquitectura.', '**Base frequency** is the processor\u2019s normal speed (in GHz) and **boost** is the maximum speed it reaches briefly under heavy work when temperature allows. More GHz is not always faster: cores and architecture matter too.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['grafica integrada en el procesador', 'igpu', 'que es igpu'], r: ['La **iGPU** es la tarjeta gráfica integrada dentro del procesador: no tiene VRAM propia y usa parte de la RAM. Sirve para ofimática, video y juegos livianos; para juegos exigentes hace falta una GPU dedicada.', 'An **iGPU** is the graphics chip built into the processor: it has no VRAM of its own and borrows system RAM. It handles office work, video and light games; demanding games need a dedicated GPU.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['como elegir un procesador', 'que cpu elegir', 'elegir cpu por uso', 'como elijo un procesador'], r: ['Para elegir CPU piensa en el uso: ofimática y estudio van bien con 4-6 núcleos; juegos, 6-8; edición y streaming, 8 o más. Revisa que el **socket** sea compatible con tu placa y que tu refrigeración aguante su TDP.', 'To pick a CPU, think about the use: office and study do fine with 4-6 cores; gaming, 6-8; editing and streaming, 8 or more. Check the **socket** matches your board and your cooling handles its TDP.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['que es el cuello de botella', 'bottleneck', 'cuello de botella pc'], r: ['El **cuello de botella** pasa cuando un componente frena a los demás: por ejemplo, una GPU potente con un CPU viejo rinde menos de lo que debería, porque el CPU no le entrega datos a tiempo.', 'A **bottleneck** happens when one component holds the rest back: for example, a powerful GPU with an old CPU performs below its potential, because the CPU cannot feed it data fast enough.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['que es dual channel', 'doble canal ram', 'dual channel memoria'], r: ['El **dual channel** (doble canal) es usar dos módulos de RAM iguales en los slots correctos para que trabajen en paralelo: el ancho de banda se duplica frente a un solo módulo y el equipo responde mejor, sobre todo con gráfica integrada.', '**Dual channel** means using two identical RAM sticks in the right slots so they work in parallel: bandwidth doubles versus a single stick and the machine feels faster, especially with integrated graphics.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['latencia cl ram', 'que es cl en ram', 'latencia de la memoria'], r: ['La **latencia CL** (CAS Latency) es el retraso de la RAM al responder: a menor número, más rápida. Se combina con la frecuencia: una RAM de muchos MHz pero CL alto no siempre gana a una de menos MHz con CL bajo.', '**CL latency** (CAS Latency) is the RAM\u2019s delay when responding: lower is faster. It pairs with frequency: high-MHz RAM with high CL does not always beat lower-MHz RAM with low CL.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['que es so-dimm', 'so-dimm vs dimm', 'ram de portatil'], r: ['La **SO-DIMM** es la versión pequeña de la RAM, usada en portátiles y mini PC; la **DIMM** es la grande, de escritorio. No son intercambiables: cada placa acepta un tamaño.', '**SO-DIMM** is the small RAM format used in laptops and mini PCs; **DIMM** is the full-size desktop one. They are not interchangeable: each board takes one size.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['que es la memoria virtual', 'memoria virtual paginacion', 'archivo de paginacion'], r: ['La **memoria virtual** es espacio del disco que el sistema usa como RAM de emergencia cuando la RAM real se llena. Evita cierres, pero es mucho más lenta: si el equipo vive paginando, lo que falta es RAM física.', '**Virtual memory** is disk space the system uses as emergency RAM when real RAM fills up. It prevents crashes, but it is far slower: if the machine pages constantly, what it really needs is more physical RAM.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['que es el tbw', 'tbw ssd vida util', 'duracion de un ssd'], r: ['El **TBW** (terabytes escritos) es la cantidad total de datos que un SSD aguanta escribir antes de que el fabricante deje de garantizarlo: mide su vida útil. Para uso normal, un SSD dura años antes de acercarse a su TBW.', '**TBW** (terabytes written) is the total data an SSD can be written before the maker stops warranting it: it measures its lifespan. Under normal use, an SSD lasts years before getting near its TBW.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['que es una particion de disco', 'particionar disco', 'particion'], r: ['Una **partición** es una división lógica del disco: el sistema la ve como si fueran discos separados (C:, D:). Sirve para separar sistema y datos, o para tener dos sistemas en el mismo disco.', 'A **partition** is a logical split of a disk: the system sees it as separate drives (C:, D:). It separates system from data, or lets two systems share one disk.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['ntfs fat32 exfat', 'sistemas de archivos', 'ntfs o exfat'], r: ['El **sistema de archivos** organiza cómo se guardan los datos: **NTFS** es el de Windows (archivos grandes, permisos), **FAT32** es viejo y universal (límite de 4 GB por archivo) y **exFAT** es el moderno para USB que se mueven entre Windows y Mac.', 'A **file system** organizes how data is stored: **NTFS** is Windows\u2019 (big files, permissions), **FAT32** is old and universal (4 GB per-file limit) and **exFAT** is the modern one for USB drives shared between Windows and Mac.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['que es clonar un disco', 'clonar disco ssd', 'copiar disco completo'], r: ['**Clonar un disco** es copiarlo entero, sistema y programas incluidos, a otro disco. Es la forma de pasar de HDD a SSD sin reinstalar nada: el equipo arranca igual, pero más rápido.', '**Cloning a disk** means copying it entirely, system and programs included, to another disk. It is how you move from HDD to SSD without reinstalling anything: the machine boots the same, just faster.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['m.2 sata o nvme', 'm2 sata vs nvme', 'diferencia m2 sata nvme'], r: ['El conector **M.2** acepta dos tipos de SSD: **SATA** (hasta ~550 MB/s) y **NVMe** (varios GB/s por PCIe). Se ven iguales por fuera: revisa que tu placa soporte NVMe antes de comprar, o pagarás velocidad que no vas a usar.', 'The **M.2** slot takes two SSD types: **SATA** (up to ~550 MB/s) and **NVMe** (several GB/s over PCIe). They look alike: check your board supports NVMe before buying, or you will pay for speed you cannot use.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['desfragmentar disco', 'desfragmentar hdd', 'trim ssd', 'desfragmentar ssd'], r: ['**Desfragmentar** reordena los datos de un HDD para que el cabezal los lea sin saltar: en HDD viejos se nota. En un SSD **no se desfragmenta**: el sistema usa **TRIM**, que avisa qué bloques ya no sirven para mantenerlo rápido.', '**Defragmenting** reorders HDD data so the head reads it without jumping: it helps old HDDs. An SSD is **never defragmented**: the system uses **TRIM**, which flags dead blocks to keep it fast.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['que es ray tracing', 'trazado de rayos', 'ray tracing gpu'], r: ['El **ray tracing** (trazado de rayos) simula cómo rebota la luz real en espejos, agua y sombras: los juegos se ven mucho más realistas, pero exige una GPU moderna y potente.', '**Ray tracing** simulates how real light bounces off mirrors, water and shadows: games look far more realistic, but it demands a modern, powerful GPU.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['que es dlss', 'dlss fsr', 'escalado dlss'], r: ['**DLSS** (NVIDIA) y **FSR** (AMD) son técnicas que renderizan el juego a menor resolución y lo escalan con inteligencia para que se vea casi igual pero con muchos más fotogramas por segundo. Son la razón por la que una GPU media hoy juega tan bien.', '**DLSS** (NVIDIA) and **FSR** (AMD) render games at lower resolution and upscale them smartly so they look nearly identical but with many more frames per second. They are why a mid-range GPU games so well today.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['tasa de refresco hz', 'que son los hz del monitor', '144 hz monitor'], r: ['La **tasa de refresco** (Hz) es cuántas veces por segundo el monitor redibuja la imagen: 60 Hz es lo normal, 144 Hz o más se siente mucho más fluido en juegos y al mover el mouse. Necesitas una GPU que genere esos fotogramas para notarlo.', '**Refresh rate** (Hz) is how many times per second the monitor redraws the image: 60 Hz is standard, 144 Hz or more feels far smoother in games and mouse movement. You need a GPU producing those frames to notice it.'] },
    { c: 'Hardware', k: ['resolucion 1080p 1440p 4k', 'que es 1080p', 'que es 4k'], r: ['La **resolución** es la cantidad de píxeles de la pantalla: **1080p** (1920×1080) es Full HD, **1440p** (2560×1440) es QHD y **4K** (3840×2160) es Ultra HD. Más resolución = imagen más nítida, pero también más trabajo para la GPU.', '**Resolution** is how many pixels the screen has: **1080p** (1920×1080) is Full HD, **1440p** (2560×1440) is QHD and **4K** (3840×2160) is Ultra HD. More resolution means a sharper image, but also more work for the GPU.'] },
    { c: 'Hardware', k: ['que es una fuente modular', 'fuente modular vs no modular', 'fuente de poder modular'], r: ['Una **fuente modular** deja desconectar los cables que no usas: el interior queda limpio, con mejor flujo de aire y más fácil de armar. La no modular trae todos los cables fijos, aunque sobren.', 'A **modular PSU** lets you unplug cables you do not use: the interior stays clean, with better airflow and an easier build. A non-modular one has every cable fixed, even the spare ones.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['que es un ups', 'ups o regulador', 'ups para pc'], r: ['Un **UPS** es una batería para tu PC: si se va la luz, te da minutos para guardar y apagar sin perder nada, y filtra picos de voltaje. Un regulador solo estabiliza el voltaje, sin batería.', 'A **UPS** is a battery for your PC: if power fails, it gives you minutes to save and shut down without losing anything, and it filters voltage spikes. A voltage regulator only stabilizes voltage, with no battery.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['atx microatx mini-itx', 'formatos de placa base', 'tamaños de placa madre'], r: ['Los **formatos de placa** son sus tamaños: **ATX** (grande, más ranuras), **microATX** (mediana, lo común) y **mini-ITX** (pequeña, para equipos compactos). El formato debe coincidir con el gabinete y con lo que quieras conectar.', '**Board form factors** are their sizes: **ATX** (big, more slots), **microATX** (medium, the common one) and **mini-ITX** (small, for compact builds). The form factor must match the case and what you plan to plug in.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['que es el chipset', 'chipset de la placa', 'chipset que hace'], r: ['El **chipset** es el conjunto de chips de la placa que conecta CPU, RAM, USB, SATA y PCIe: define qué procesadores, cuántos puertos y qué velocidades soporta tu placa. Dos placas con el mismo socket pueden diferir solo por el chipset.', 'The **chipset** is the board\u2019s chip set connecting CPU, RAM, USB, SATA and PCIe: it decides which processors, how many ports and which speeds your board supports. Two boards with the same socket may differ only by chipset.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['que es thermal throttling', 'limitacion termica', 'throttling cpu'], r: ['El **thermal throttling** es cuando CPU o GPU bajan su velocidad solos para no sobrecalentarse: el equipo se vuelve lento de repente en juegos o render. La causa suele ser polvo, pasta vieja o mala ventilación.', '**Thermal throttling** is when the CPU or GPU slows itself down to avoid overheating: the machine suddenly feels slow in games or rendering. The cause is usually dust, old paste or bad ventilation.'], href: 'pc3d.html#mantenimiento' },
    { c: 'Hardware', k: ['temperatura normal cpu gpu', 'cuantos grados debe tener el procesador', 'temperatura normal del pc'], r: ['Temperaturas orientativas: en reposo, CPU y GPU entre **30 y 50 °C**; con carga fuerte, **70-85 °C** es normal. Por encima de 90-95 °C el equipo baja velocidad para protegerse: toca limpiar y revisar ventilación.', 'Rough guide: at idle, CPU and GPU sit at **30-50 °C**; under heavy load, **70-85 °C** is normal. Above 90-95 °C the machine slows down to protect itself: time to clean and check ventilation.'], href: 'pc3d.html#mantenimiento' },
    { c: 'Hardware', k: ['cuando cambiar la pasta termica', 'cada cuanto pasta termica', 'duracion pasta termica'], r: ['La **pasta térmica** se cambia cada **2 a 4 años**, o antes si las temperaturas suben sin explicación. Es la que transfiere el calor del procesador al disipador: vieja y seca, enfría mucho peor.', '**Thermal paste** is replaced every **2 to 4 years**, or sooner if temperatures climb for no reason. It transfers heat from the processor to the cooler: old and dry, it cools far worse.'], href: 'pc3d.html#mantenimiento' },
    { c: 'Hardware', k: ['switch administrable vs no administrable', 'switch gestionable', 'switch administrable'], r: ['Un **switch administrable** se configura: VLAN, velocidad por puerto y seguridad; el **no administrable** solo conecta y listo. En casa basta el simple; en empresas se usa el administrable para separar redes y controlar tráfico.', 'A **managed switch** is configurable: VLANs, per-port speed and security; an **unmanaged** one just connects and works. At home the simple one is enough; companies use managed ones to separate networks and control traffic.'], href: 'redes.html#redes' },
    { c: 'Hardware', k: ['que es un punto de acceso', 'punto de acceso ap', 'access point'], r: ['Un **punto de acceso (AP)** es un equipo que crea una red WiFi donde ya hay red por cable: se conecta al switch o al módem y emite señal. No es un repetidor: usa cable hasta el punto, así que no pierde velocidad.', 'An **access point (AP)** creates a WiFi network where wired network already exists: it plugs into the switch or modem and broadcasts signal. It is not a repeater: it uses cable all the way, so it loses no speed.'], href: 'redes.html#redes' },
    { c: 'Hardware', k: ['teclado mecanico vs membrana', 'teclado mecanico', 'teclado de membrana'], r: ['El **teclado mecánico** usa un interruptor por tecla: tacto preciso, más ruido y más precio, y dura más. El de **membrana** es silencioso y barato, con una goma bajo las teclas, y es el común de oficina.', 'A **mechanical keyboard** has one switch per key: precise feel, more noise and higher price, and it lasts longer. A **membrane** one is quiet and cheap, with rubber under the keys, and it is the office standard.'] },
    { c: 'Hardware', k: ['que es el dpi del mouse', 'dpi mouse', 'dpi alto o bajo'], r: ['El **DPI** del mouse es su sensibilidad: cuántos puntos se mueve el cursor por cada pulgada que mueves el mouse. DPI alto = cursor muy rápido; en juegos se usa bajo con alfombrilla grande para apuntar con precisión.', '**Mouse DPI** is its sensitivity: how many points the cursor moves per inch you move the mouse. High DPI means a very fast cursor; gamers use low DPI with a big pad for precise aiming.'] },
    { c: 'Hardware', k: ['monitor ips tn va', 'panel ips vs tn vs va', 'que panel de monitor'], r: ['Los **paneles de monitor**: **IPS** (mejores colores y ángulos, lo común para todo), **TN** (más rápido y barato, colores peores, para e-sports) y **VA** (mejor contraste y negros, bueno para películas). Elige según uses color, velocidad o cine.', '**Monitor panels**: **IPS** (best colors and angles, the all-rounder), **TN** (fastest and cheapest, worse colors, for e-sports) and **VA** (best contrast and blacks, good for movies). Pick by whether you need color, speed or cinema.'] },
    { c: 'Hardware', k: ['que es hdr', 'hdr monitor', 'hdr que significa'], r: ['El **HDR** (alto rango dinámico) muestra a la vez zonas muy brillantes y muy oscuras con detalle: el sol no se quema en blanco ni la sombra se vuelve negra total. Necesitas contenido HDR y un monitor que lo soporte de verdad.', '**HDR** (high dynamic range) shows very bright and very dark areas together with detail: the sun does not blow out to white nor shadows to pure black. You need HDR content and a monitor that truly supports it.'] },
    { c: 'Hardware', k: ['hdmi displayport vga', 'hdmi o displayport', 'diferencia hdmi displayport'], r: ['**HDMI** es el conector universal de video y audio (TV y monitores), **DisplayPort** es el de PC para altas tasas de refresco y varias pantallas, y **VGA** es el viejo analógico, ya sin audio ni alta definición.', '**HDMI** is the universal video-and-audio connector (TVs and monitors), **DisplayPort** is the PC one for high refresh rates and multiple screens, and **VGA** is the old analog one, with no audio and no high definition.'] },
    { c: 'Hardware', k: ['que es usb-c', 'usb-c thunderbolt', 'usb tipo c'], r: ['El **USB-C** es el conector ovalado reversible que hoy usan celulares, portátiles y discos: carga, datos y video por el mismo cable. **Thunderbolt** usa ese mismo conector pero con mucha más velocidad, en equipos compatibles.', '**USB-C** is the reversible oval connector used today by phones, laptops and drives: charging, data and video over one cable. **Thunderbolt** uses the same connector but with far more speed, on compatible machines.'] },
    { c: 'Hardware', k: ['pila cmos post', 'que es cmos', 'que es el post arranque'], r: ['La **pila CMOS** mantiene la hora y la configuración de la placa cuando el PC está apagado. El **POST** es la autoprueba al encender: si algo falla, la placa pita o muestra un código antes de arrancar el sistema.', 'The **CMOS battery** keeps the board\u2019s clock and settings while the PC is off. **POST** is the self-test at power-on: if something fails, the board beeps or shows a code before booting the system.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['que es uefi', 'bios vs uefi', 'uefi que es'], r: ['La **UEFI** es la sucesora moderna de la BIOS: arranca más rápido, soporta discos de más de 2 TB y mouse en su menú, y trae Secure Boot. La BIOS vieja (Legacy) quedó para equipos antiguos.', '**UEFI** is the modern successor to BIOS: faster boot, support for disks over 2 TB and mouse in its menu, plus Secure Boot. The old Legacy BIOS remains only for ancient machines.'], href: 'hardware.html#componentes' },
    { c: 'Redes', k: ['que es el modelo osi', 'modelo osi 7 capas', 'capas osi'], r: ['El **modelo OSI** describe la comunicación en 7 capas: física, enlace, red, transporte, sesión, presentación y aplicación. Sirve para ubicar dónde falla algo: ¿es el cable (física), la MAC (enlace), la IP (red) o el programa (aplicación)?', 'The **OSI model** describes communication in 7 layers: physical, link, network, transport, session, presentation and application. It locates failures: is it the cable (physical), the MAC (link), the IP (network) or the program (application)?'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['modelo tcp ip', 'modelo tcp ip 4 capas', 'tcp ip capas'], r: ['El **modelo TCP/IP** es el que usa internet de verdad, con 4 capas: acceso a la red, internet (IP), transporte (TCP/UDP) y aplicación (HTTP, DNS, correo). Es la versión práctica del modelo OSI.', 'The **TCP/IP model** is the one the real internet uses, with 4 layers: network access, internet (IP), transport (TCP/UDP) and application (HTTP, DNS, mail). It is OSI\u2019s practical version.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['puertos tcp udp', 'puertos 80 443', 'que son los puertos de red'], r: ['Los **puertos** son números que dicen a qué servicio va un paquete dentro de un equipo: **80** (web HTTP), **443** (web segura HTTPS), **53** (DNS) y **22** (SSH). La IP llega al equipo; el puerto, al programa.', '**Ports** are numbers telling which service a packet goes to inside a machine: **80** (HTTP web), **443** (secure HTTPS web), **53** (DNS) and **22** (SSH). The IP reaches the machine; the port reaches the program.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['http vs https', 'diferencia http https', 'https que es'], r: ['**HTTP** es el protocolo de la web sin cifrar: cualquiera en el camino puede leerlo. **HTTPS** es el mismo, pero cifrado con TLS (el candado del navegador): protege contraseñas y datos. Hoy casi toda la web usa HTTPS.', '**HTTP** is the web protocol, unencrypted: anyone in the middle can read it. **HTTPS** is the same, but encrypted with TLS (the browser padlock): it protects passwords and data. Today nearly the whole web uses HTTPS.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['que es ftp', 'ftp para que sirve', 'protocolo ftp'], r: ['El **FTP** es el protocolo clásico para transferir archivos entre un equipo y un servidor: subir una web o bajar archivos grandes. Hoy se prefiere su versión segura, SFTP, porque el FTP original viaja sin cifrar.', '**FTP** is the classic protocol for moving files between a machine and a server: uploading a website or downloading big files. Today its secure version, SFTP, is preferred, because original FTP travels unencrypted.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['que es ssh', 'ssh para que sirve', 'conexion ssh'], r: ['El **SSH** es el protocolo para administrar otro equipo por terminal de forma segura y cifrada: entras con usuario y clave (o llave) y ejecutas comandos como si estuvieras frente a él. Es el estándar para servidores.', '**SSH** is the protocol for managing another machine by terminal, securely and encrypted: you log in with user and password (or key) and run commands as if sitting in front of it. It is the server standard.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['que es un proxy', 'proxy que es', 'servidor proxy'], r: ['Un **proxy** es un intermediario: tus peticiones salen desde él, no desde tu equipo. Sirve para filtrar contenido, guardar caché o esconder tu IP, pero ve todo tu tráfico: solo usa proxies de confianza.', 'A **proxy** is a middleman: your requests leave from it, not from your machine. It filters content, caches or hides your IP, but it sees all your traffic: only use trusted proxies.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['que es una vpn', 'vpn para que sirve', 'vpn que significa'], r: ['Una **VPN** crea un túnel cifrado entre tu equipo y otro punto de internet: tu tráfico sale desde ahí, protegido de curiosos en redes públicas. No te hace anónimo total, pero sí mucho más seguro en WiFi abiertas.', 'A **VPN** builds an encrypted tunnel between your machine and another point on the internet: your traffic exits from there, shielded from snoopers on public networks. It does not make you fully anonymous, but far safer on open WiFi.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['que es un firewall', 'firewall que es', 'cortafuegos'], r: ['El **firewall** (cortafuegos) es el guardián que decide qué tráfico entra o sale según reglas: bloquea conexiones no pedidas y deja pasar las legítimas. Lo tienen tu sistema, tu módem y las empresas en equipos dedicados.', 'A **firewall** is the guard deciding which traffic enters or leaves by rules: it blocks unsolicited connections and lets legitimate ones through. Your system, your modem and companies (on dedicated boxes) all have one.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['que es nat', 'nat router', 'nat que significa'], r: ['El **NAT** es lo que hace tu router: todos tus equipos comparten una sola IP pública hacia internet, y el router recuerda a quién devolver cada respuesta. Por eso tu red local usa IPs privadas (192.168.x.x).', '**NAT** is what your router does: all your devices share one public IP toward the internet, and the router remembers who gets each reply. That is why your local network uses private IPs (192.168.x.x).'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['que es dhcp', 'dhcp que significa', 'dhcp servidor'], r: ['El **DHCP** es el servicio (normalmente del router) que reparte IPs automáticamente a cada equipo que se conecta: IP, máscara, puerta de enlace y DNS. Sin él, tendrías que configurar la IP de cada equipo a mano.', '**DHCP** is the service (usually on the router) that hands out IPs automatically to each connecting device: IP, mask, gateway and DNS. Without it, you would configure every device\u2019s IP by hand.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['ip publica vs privada', 'ip privada publica diferencia', 'ip publica que es'], r: ['Tu **IP privada** (192.168.x.x) solo vale dentro de tu red; tu **IP pública** es la que ve internet y la que te da tu proveedor. El router traduce entre ambas con NAT.', 'Your **private IP** (192.168.x.x) only works inside your network; your **public IP** is what the internet sees, given by your provider. The router translates between them with NAT.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['ip dinamica vs estatica', 'ip fija o dinamica', 'ip estatica que es'], r: ['Una **IP dinámica** cambia cada cierto tiempo (la da el DHCP) y una **estática** siempre es la misma. En casa casi todo es dinámico; los servidores usan estática para que siempre se les encuentre en la misma dirección.', 'A **dynamic IP** changes from time to time (DHCP gives it) and a **static** one is always the same. At home nearly everything is dynamic; servers use static IPs so they are always found at the same address.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['mascara de subred', 'que es cidr', 'mascara 255.255.255.0'], r: ['La **máscara de subred** (ej. 255.255.255.0 o /24) dice qué parte de la IP es la red y qué parte es el equipo. Con /24, los primeros 24 bits son la red y quedan 254 direcciones para equipos.', 'The **subnet mask** (e.g. 255.255.255.0 or /24) says which part of the IP is the network and which part is the device. With /24, the first 24 bits are the network, leaving 254 addresses for devices.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['que es la puerta de enlace', 'gateway que es', 'puerta de enlace red'], r: ['La **puerta de enlace** (gateway) es la IP de tu router dentro de tu red (normalmente 192.168.1.1): es la salida hacia internet. Si no la tienes bien configurada, hay red local pero no internet.', 'The **gateway** is your router\u2019s IP inside your network (usually 192.168.1.1): it is the exit to the internet. If it is misconfigured, you get local network but no internet.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['que es un dominio', 'dominio web', 'dominio .com'], r: ['Un **dominio** (ej. nvision.social) es el nombre fácil de recordar de un sitio: el DNS lo traduce a la IP del servidor. Los .com, .org o .co son solo terminaciones; el nombre lo eliges tú y se paga por año.', 'A **domain** (e.g. nvision.social) is a site\u2019s easy name: DNS translates it to the server\u2019s IP. Endings like .com, .org or .co are just suffixes; you pick the name and pay yearly.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['que es hosting', 'hosting web', 'alojamiento web'], r: ['El **hosting** es el alquiler del servidor donde vive tu página: guarda los archivos y los sirve cuando alguien entra a tu dominio. Sin hosting, tu web no está en internet.', '**Hosting** is renting the server where your page lives: it stores the files and serves them when someone visits your domain. Without hosting, your website is not on the internet.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['que es un servidor web', 'servidor web que hace', 'apache nginx'], r: ['Un **servidor web** es un programa (Apache, Nginx) que responde peticiones HTTP: cuando entras a una página, él te entrega sus archivos. Vive en un equipo siempre encendido, conectado a internet.', 'A **web server** is a program (Apache, Nginx) answering HTTP requests: when you visit a page, it hands you its files. It lives on a machine that is always on, connected to the internet.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['que es jitter', 'jitter red', 'jitter que significa'], r: ['El **jitter** es la variación del tiempo que tardan los paquetes en llegar: si unos llegan rápido y otros tarde, las llamadas y los juegos se entrecortan aunque la velocidad sea buena. Una red estable tiene jitter bajo.', '**Jitter** is the variation in how long packets take to arrive: if some arrive fast and others late, calls and games stutter even when speed is good. A stable network has low jitter.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['perdida de paquetes', 'packet loss', 'paquetes perdidos'], r: ['La **pérdida de paquetes** es el porcentaje de paquetes que nunca llega: con 0-1 % todo va bien; con más del 5 % hay cortes, voz robotizada y juegos con tirones. Se mide con ping y suele ser señal de cable, WiFi o proveedor con problemas.', '**Packet loss** is the percentage of packets that never arrive: at 0-1 % everything is fine; above 5 % you get drops, robotic voice and game stutter. It is measured with ping and usually signals cable, WiFi or provider trouble.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['que es qos', 'qos router', 'calidad de servicio qos'], r: ['El **QoS** (calidad de servicio) es la regla del router que prioriza tráfico importante (llamadas, juegos) sobre el resto (descargas): así una descarga no arruina tu partida ni tu clase en vivo.', '**QoS** (quality of service) is the router rule prioritizing important traffic (calls, games) over the rest (downloads): so a download does not ruin your match or live class.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['fibra optica vs cobre', 'fibra optica que es', 'fibra o cobre internet'], r: ['La **fibra óptica** lleva internet con pulsos de luz por hilos de vidrio: es mucho más rápida y estable que el cobre (ADSL o coaxial) y no sufre interferencias eléctricas. Por eso los planes rápidos de hoy son de fibra.', '**Fiber optics** carries internet as light pulses through glass strands: it is far faster and steadier than copper (ADSL or coaxial) and immune to electrical interference. That is why today\u2019s fast plans are fiber.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['cat5e cat6 cat6a', 'categorias cable ethernet', 'cable cat6'], r: ['Las **categorías de cable** marcan su velocidad: **Cat5e** llega a 1 Gbps, **Cat6** a 10 Gbps en tramos cortos y **Cat6a** a 10 Gbps en 100 m. Para una casa, Cat6 sobra; lo importante es que el cable no sea el más barato y falso.', '**Cable categories** mark their speed: **Cat5e** reaches 1 Gbps, **Cat6** 10 Gbps over short runs and **Cat6a** 10 Gbps over 100 m. For a home, Cat6 is plenty; what matters is not buying the cheapest fake cable.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['broadcast unicast multicast', 'broadcast que es', 'unicast multicast diferencia'], r: ['**Unicast** es un mensaje de uno a uno, **broadcast** es de uno a todos en la red (como un anuncio) y **multicast** es de uno a un grupo que lo pidió (como un stream en vivo). El switch aprende con unicast y el broadcast lo inunda a todos.', '**Unicast** is one-to-one, **broadcast** is one-to-all on the network (like an announcement) and **multicast** is one-to-a-group that asked for it (like a live stream). The switch learns with unicast and floods broadcast to everyone.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['que es stp', 'spanning tree', 'stp switch bucles'], r: ['El **STP** (Spanning Tree) es el protocolo que evita **bucles** cuando hay dos caminos entre switches: bloquea uno de ellos para que las tramas no den vueltas infinitas y tumben la red. En redes con un solo switch no se nota.', '**STP** (Spanning Tree) is the protocol preventing **loops** when two paths join switches: it blocks one so frames do not circle forever and crash the network. Single-switch networks never notice it.'], href: 'redes.html#switch-3d' },
    { c: 'Redes', k: ['que es trunk', 'trunk vlan', 'enlace troncal vlan'], r: ['Un **trunk** (enlace troncal) es un cable entre switches que lleva varias VLAN a la vez, marcando cada trama con su VLAN. Sin trunk, cada VLAN necesitaría su propio cable entre switches.', 'A **trunk** is a link between switches carrying several VLANs at once, tagging each frame with its VLAN. Without trunks, each VLAN would need its own cable between switches.'], href: 'redes.html#switch-3d' },
    { c: 'Redes', k: ['half duplex full duplex', 'half duplex que es', 'full duplex que es'], r: ['En **half-duplex** un equipo habla o escucha, no las dos cosas a la vez (como un walkie-talkie); en **full-duplex** habla y escucha a la vez (como una llamada). Las redes modernas con switch usan full-duplex y por eso no hay colisiones.', 'In **half-duplex** a device talks or listens, not both at once (like a walkie-talkie); in **full-duplex** it talks and listens simultaneously (like a phone call). Modern switched networks use full-duplex, which is why there are no collisions.'], href: 'redes.html#switch-3d' },
    { c: 'Redes', k: ['filtrado mac', 'filtrado mac sirve', 'filtrar por mac wifi'], r: ['El **filtrado MAC** deja entrar a la WiFi solo a equipos con MAC autorizada. Suena seguro, pero la MAC se falsifica fácil: sirve como un candado extra, no como tu única protección. Lo que protege de verdad es una contraseña WPA2/WPA3 fuerte.', '**MAC filtering** lets only authorized MACs onto WiFi. It sounds secure, but MACs are easily faked: it works as an extra lock, not your only protection. What truly protects you is a strong WPA2/WPA3 password.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['ocultar ssid sirve', 'ssid oculto', 'ocultar nombre wifi'], r: ['**Ocultar el SSID** hace que tu WiFi no aparezca en la lista, pero cualquiera con una herramienta la ve igual: no es seguridad real. Lo que protege es una contraseña fuerte y WPA2/WPA3; ocultar el nombre solo incomoda a tus visitas.', '**Hiding the SSID** keeps your WiFi off the list, but anyone with a tool sees it anyway: it is not real security. What protects you is a strong password and WPA2/WPA3; hiding the name only inconveniences your guests.'], href: 'wifi.html#instalar-modem' },
    { c: 'Redes', k: ['que es wpa3', 'wpa3 vs wpa2', 'wpa3 seguridad wifi'], r: ['El **WPA3** es la seguridad WiFi actual: reemplaza a WPA2 con cifrado más fuerte por equipo y mejor protección contra adivinar contraseñas. Si tu módem y tus equipos lo soportan, úsalo; si no, WPA2 con clave larga sigue siendo seguro.', '**WPA3** is current WiFi security: it replaces WPA2 with stronger per-device encryption and better protection against password guessing. If your modem and devices support it, use it; otherwise WPA2 with a long password stays secure.'], href: 'wifi.html#instalar-modem' },
    { c: 'Redes', k: ['que es un troyano', 'troyano informatico', 'virus troyano'], r: ['Un **troyano** es malware disfrazado de programa legítimo: lo instalas creyendo que es un juego o un "optimizador" y por dentro abre la puerta a ladrones de datos. Por eso solo se descarga desde sitios oficiales.', 'A **trojan** is malware disguised as a legit program: you install it thinking it is a game or an "optimizer" and inside it opens the door to data thieves. That is why you only download from official sites.'], href: 'mantenimiento-software.html#tareas' },
    { c: 'Redes', k: ['que es un gusano informatico', 'gusano worm', 'worm malware'], r: ['Un **gusano (worm)** es malware que se copia solo de equipo en equipo por la red, sin que nadie lo instale. A diferencia del virus, no necesita un archivo huésped: se propaga aprovechando agujeros sin parchear, por eso importan las actualizaciones.', 'A **worm** is malware that copies itself from machine to machine over the network, with nobody installing it. Unlike a virus, it needs no host file: it spreads through unpatched holes, which is why updates matter.'], href: 'mantenimiento-software.html#tareas' },
{ c: 'WiFi', k: ['banda 6 ghz wifi', 'wifi 6 ghz', 'que es 6 ghz'], r: ['La **banda de 6 GHz** es la nueva autopista del WiFi 6E/7: más canales libres y menos vecinos que en 2.4 y 5 GHz, así que va más rápido y estable. Necesitas módem y equipos compatibles, y su alcance es menor que 5 GHz.', 'The **6 GHz band** is the new WiFi 6E/7 highway: more free channels and fewer neighbors than 2.4 and 5 GHz, so it runs faster and steadier. It needs compatible modem and devices, and its range is shorter than 5 GHz.'], href: 'wifi.html#instalar-modem' },
    { c: 'WiFi', k: ['wifi 5 6 6e 7', 'generaciones wifi', 'wifi 5 vs 6 vs 7'], r: ['Las **generaciones WiFi**: **WiFi 5** (802.11ac, solo 5 GHz), **WiFi 6** (802.11ax, 2.4 y 5 GHz, mejor con muchos equipos), **WiFi 6E** (añade 6 GHz) y **WiFi 7** (802.11be, más velocidad y menos latencia). Cada generación pide equipos compatibles para notarse.', '**WiFi generations**: **WiFi 5** (802.11ac, 5 GHz only), **WiFi 6** (802.11ax, 2.4 and 5 GHz, better with many devices), **WiFi 6E** (adds 6 GHz) and **WiFi 7** (802.11be, more speed and less latency). Each needs compatible gear to be noticed.'], href: 'wifi.html#instalar-modem' },
    { c: 'WiFi', k: ['que es mu-mimo', 'mu-mimo wifi', 'mu mimo que significa'], r: ['El **MU-MIMO** deja que el módem hable con varios equipos a la vez, en vez de turnarlos uno por uno. En casas con muchos celulares y TVs se nota: menos esperas cuando todos usan la red al mismo tiempo.', '**MU-MIMO** lets the modem talk to several devices at once instead of taking turns one by one. In homes with many phones and TVs it shows: less waiting when everyone uses the network simultaneously.'], href: 'wifi.html#instalar-modem' },
    { c: 'WiFi', k: ['roaming wifi', 'roaming wifi que es', 'cambiar de punto wifi'], r: ['El **roaming WiFi** es el cambio automático de tu equipo entre puntos de acceso (o nodos mesh) cuando te mueves por la casa: si funciona bien, no notas el salto; si falla, se cae la llamada al cambiar de punto.', '**WiFi roaming** is your device\u2019s automatic hop between access points (or mesh nodes) as you move around the house: when it works, you never notice; when it fails, the call drops mid-hop.'], href: 'wifi.html#instalar-modem' },
    { c: 'WiFi', k: ['red mesh vs repetidor', 'mesh o repetidor', 'malla wifi vs repetidor'], r: ['Una **red mesh** usa varios nodos que hablan entre sí y te pasan de uno a otro sin cortes; un **repetidor** solo reemite la señal y pierde velocidad. Para casas grandes, mesh es mejor; para un cuarto muerto, un repetidor basta.', 'A **mesh network** uses several nodes that talk to each other and hand you over without drops; a **repeater** just re-broadcasts the signal and loses speed. For big homes, mesh wins; for one dead room, a repeater is enough.'], href: 'wifi.html#instalar-modem' },
    { c: 'WiFi', k: ['que es wifi direct', 'wifi direct para que sirve', 'wifi directo'], r: ['El **WiFi Direct** conecta dos equipos sin módem ni router de por medio: sirve para mandar archivos del celular a la TV o a la impresora directo, como un Bluetooth pero más rápido.', '**WiFi Direct** connects two devices with no modem or router between: it sends files from phone to TV or printer directly, like Bluetooth but faster.'], href: 'wifi.html#instalar-modem' },
    { c: 'WiFi', k: ['hotspot celular', 'compartir internet celular', 'zona wifi celular'], r: ['El **hotspot del celular** comparte sus datos móviles como una WiFi para otros equipos: útil cuando no hay internet en casa, pero gasta batería y datos rápido, y la velocidad depende de tu señal móvil.', 'A **phone hotspot** shares its mobile data as WiFi for other devices: handy with no home internet, but it drains battery and data fast, and speed depends on your mobile signal.'], href: 'wifi.html#instalar-modem' },
    { c: 'WiFi', k: ['velocidad subida vs bajada', 'subida y bajada internet', 'upload download'], r: ['La **bajada (download)** es la velocidad para recibir (ver videos, descargar) y la **subida (upload)** para enviar (videollamadas, subir archivos). Los planes suelen dar más bajada que subida; para clases y streaming en vivo, la subida importa mucho.', '**Download** is the speed for receiving (watching videos, downloading) and **upload** for sending (video calls, uploading files). Plans usually give more download than upload; for live classes and streaming, upload matters a lot.'], href: 'wifi.html#instalar-modem' },
    { c: 'WiFi', k: ['test de velocidad', 'como medir mi internet', 'speed test'], r: ['Un **test de velocidad** mide bajada, subida y ping de tu conexión en ese momento. Hazlo por cable y cerca del módem para ver lo real; por WiFi lejos del módem, el número baja y eso no es culpa del proveedor.', 'A **speed test** measures your connection\u2019s download, upload and ping right now. Run it wired and near the modem for the real number; over WiFi far from the modem the number drops, and that is not the provider\u2019s fault.'], href: 'wifi.html#instalar-modem' },
    { c: 'WiFi', k: ['que es cgnat', 'doble nat', 'cgnat que es'], r: ['El **CGNAT** es cuando tu proveedor comparte una IP pública entre varios clientes: tu router ya hace NAT y el proveedor otro NAT encima (**doble NAT**). Por eso a veces no puedes abrir puertos ni jugar en línea con NAT abierta.', '**CGNAT** is when your provider shares one public IP among several customers: your router already NATs and the provider NATs again on top (**double NAT**). That is why sometimes you cannot open ports or get open NAT in online games.'], href: 'wifi.html#instalar-modem' },
    { c: 'Otro', k: ['que es el kernel', 'kernel sistema operativo', 'nucleo del sistema'], r: ['El **kernel** es el núcleo del sistema operativo: habla directo con el hardware y decide quién usa CPU, memoria y disco. Todo lo demás (programas, ventanas) le pide permiso a él.', 'The **kernel** is the operating system\u2019s core: it talks directly to hardware and decides who uses CPU, memory and disk. Everything else (programs, windows) asks it for permission.'] },
    { c: 'Otro', k: ['administrador de tareas', 'task manager', 'ver procesos windows'], r: ['El **Administrador de tareas** (Ctrl + Shift + Esc en Windows) muestra qué programas y procesos consumen CPU, RAM y disco en vivo: sirve para encontrar al culpable cuando el equipo va lento y para cerrar lo trabado.', 'The **Task Manager** (Ctrl + Shift + Esc on Windows) shows which programs and processes eat CPU, RAM and disk live: it finds the culprit when the machine drags and kills frozen apps.'] },
    { c: 'Otro', k: ['que es un proceso', 'proceso y servicio', 'proceso vs servicio'], r: ['Un **proceso** es un programa en ejecución; un **servicio** es un proceso de fondo sin ventana (actualizaciones, antivirus, red) que trabaja aunque no lo veas. Muchos servicios son del sistema y no deben cerrarse.', 'A **process** is a running program; a **service** is a background process with no window (updates, antivirus, network) working unseen. Many services belong to the system and must not be closed.'] },
    { c: 'Otro', k: ['que es firmware', 'firmware que es', 'actualizar firmware'], r: ['El **firmware** es el software grabado dentro de un equipo (módem, impresora, placa, control): le dice cómo funcionar. Actualizarlo corrige fallos y seguridad, igual que actualizar un programa, pero con más cuidado: no se debe apagar a mitad.', '**Firmware** is software baked into a device (modem, printer, board, controller) telling it how to work. Updating it fixes bugs and security, like updating a program, but with more care: never power off mid-update.'] },
    { c: 'Otro', k: ['que es arranque dual', 'dual boot', 'dos sistemas operativos'], r: ['El **arranque dual (dual boot)** es tener dos sistemas (ej. Windows y Linux) en el mismo equipo y elegir cuál arrancar al encender. Cada uno vive en su partición y no se mezclan.', '**Dual boot** means having two systems (e.g. Windows and Linux) on one machine and choosing which boots at power-on. Each lives in its own partition and they do not mix.'] },
    { c: 'Otro', k: ['que es una maquina virtual', 'maquina virtual que es', 'virtualbox vmware'], r: ['Una **máquina virtual** es un computador simulado dentro de tu computador: corre otro sistema en una ventana, aislado del tuyo. Sirve para probar programas o sistemas sin tocar tu equipo real.', 'A **virtual machine** is a simulated computer inside your computer: it runs another system in a window, isolated from yours. It tests programs or systems without touching your real machine.'] },
    { c: 'Otro', k: ['software libre vs propietario', 'codigo abierto que es', 'software libre que significa'], r: ['El **software libre y de código abierto** se puede usar, estudiar y modificar (ej. Linux, BleachBit); el **propietario** es de una empresa y no ves su código (ej. Windows, Office). Libre no siempre es gratis, y gratis no siempre es libre.', '**Free and open-source software** can be used, studied and modified (e.g. Linux, BleachBit); **proprietary** software belongs to a company and hides its code (e.g. Windows, Office). Free is not always gratis, and gratis is not always free.'] },
    { c: 'Otro', k: ['por que no usar software pirata', 'software pirata peligro', 'programas pirata riesgo'], r: ['El **software pirata** suele venir con malware escondido (troyanos, mineros, ladrones de claves) y no recibe actualizaciones de seguridad. Además de ilegal, es la forma más común de infectar un equipo "gratis".', '**Pirated software** usually hides malware (trojans, miners, password stealers) and gets no security updates. Besides being illegal, it is the most common way to infect a machine "for free".'], href: 'mantenimiento-software.html#alertas' },
    { c: 'Otro', k: ['que es bloatware', 'bloatware que es', 'programas preinstalados basura'], r: ['El **bloatware** son los programas preinstalados que no pediste (pruebas, juegos, utilidades del fabricante) y que ocupan disco y arranque. Se desinstalan desde el panel oficial del sistema.', '**Bloatware** is preinstalled software you never asked for (trials, games, maker utilities) eating disk and boot time. Uninstall it from the system\u2019s official panel.'], href: 'mantenimiento-software.html#tareas' },
    { c: 'Otro', k: ['que es un programa portable', 'programa portable que es', 'app portable'], r: ['Un **programa portable** corre sin instalarse: lo llevas en un USB y funciona en cualquier PC sin dejar rastros. Ideal para herramientas de diagnóstico y para equipos donde no puedes instalar nada.', 'A **portable program** runs without installing: carry it on a USB and it works on any PC leaving no traces. Perfect for diagnostic tools and machines where you cannot install anything.'] },
    { c: 'Otro', k: ['que es el modo seguro', 'modo seguro windows', 'arrancar en modo seguro'], r: ['El **modo seguro** arranca Windows solo con lo mínimo (sin drivers ni programas extra): sirve para diagnosticar, quitar malware y deshacer un controlador que dejó la pantalla negra. Si en modo seguro todo va bien, el problema es un programa o driver.', '**Safe mode** boots Windows with only the minimum (no extra drivers or programs): it diagnoses, removes malware and undoes a driver that black-screened you. If everything works in safe mode, the problem is a program or driver.'] },
    { c: 'Otro', k: ['que es un punto de restauracion', 'punto de restauracion windows', 'restaurar sistema'], r: ['Un **punto de restauración** es una foto del sistema (configuración y programas) a una fecha: si una actualización o instalación rompe algo, vuelves a ese punto sin perder tus archivos personales.', 'A **restore point** is a snapshot of the system (settings and programs) at a date: if an update or install breaks something, you roll back to it without losing personal files.'], href: 'mantenimiento-software.html#tareas' },
    { c: 'Otro', k: ['reinstalar el sistema operativo', 'reinstalar windows', 'reinstalar el sistema'], r: ['**Reinstalar el sistema** es borrar Windows y ponerlo de nuevo, limpio: arregla problemas graves, pero borra programas y ajustes (no tus archivos si eliges conservarlos). Solo se hace con copia de seguridad hecha antes.', '**Reinstalling the system** wipes Windows and puts it back clean: it fixes severe problems, but removes programs and settings (not your files, if you choose to keep them). Only do it with a backup made beforehand.'], href: 'mantenimiento-software.html#tareas' },
    { c: 'Otro', k: ['que es una imagen del sistema', 'imagen de sistema backup', 'imagen completa del disco'], r: ['Una **imagen del sistema** es una copia exacta de todo el disco (sistema, programas y archivos) en un momento: si el disco muere, restauras la imagen en uno nuevo y quedas como estabas, sin reinstalar nada.', 'A **system image** is an exact copy of the whole disk (system, programs and files) at a moment: if the disk dies, you restore the image onto a new one and you are back as you were, reinstalling nothing.'], href: 'mantenimiento-software.html#tareas' },
    { c: 'Otro', k: ['arranque desde usb', 'boot desde usb', 'iniciar desde usb'], r: ['El **arranque desde USB** es encender el equipo desde una memoria USB en vez del disco: sirve para instalar un sistema, reparar uno dañado o probar Linux sin instalarlo. Se elige en la BIOS/UEFI o con la tecla de arranque.', '**Booting from USB** powers the machine from a USB stick instead of the disk: it installs a system, repairs a broken one or tries Linux without installing. Pick it in BIOS/UEFI or with the boot key.'] },
    { c: 'Otro', k: ['que es secure boot', 'secure boot que es', 'arranque seguro'], r: ['El **Secure Boot** es una función de la UEFI que solo deja arrancar sistemas firmados y de confianza: bloquea rootkits que se cuelan antes de Windows. A veces hay que desactivarlo para instalar ciertos Linux.', '**Secure Boot** is a UEFI feature that only boots signed, trusted systems: it blocks rootkits sneaking in before Windows. Sometimes you must disable it to install certain Linux distros.'] },
    { c: 'Otro', k: ['que es tpm', 'tpm que es', 'chip tpm'], r: ['El **TPM** es un chip de seguridad en la placa que guarda claves y verifica que el arranque no fue alterado: Windows 11 lo exige y es la base de BitLocker y del inicio de sesión seguro.', 'The **TPM** is a security chip on the board storing keys and verifying boot was not tampered with: Windows 11 requires it and it underpins BitLocker and secure sign-in.'] },
    { c: 'Otro', k: ['que es bitlocker', 'bitlocker cifrado', 'cifrar el disco'], r: ['El **BitLocker** cifra todo el disco de Windows: si te roban el equipo, nadie lee tus archivos sin la clave, aunque saquen el disco. Actívalo en portátiles con datos importantes y guarda la clave de recuperación aparte.', '**BitLocker** encrypts the whole Windows disk: if the machine is stolen, nobody reads your files without the key, even pulling the disk out. Turn it on for laptops with important data and keep the recovery key elsewhere.'], href: 'mantenimiento-software.html#tareas' },
    { c: 'Otro', k: ['que es la autenticacion en dos pasos', '2fa que es', 'doble factor autenticacion'], r: ['La **autenticación en dos pasos (2FA)** pide, además de tu clave, un código de tu celular o llave: aunque te roben la contraseña, no entran sin ese segundo factor. Actívala en correo, redes y bancos.', '**Two-factor authentication (2FA)** asks, besides your password, for a code from your phone or key: even with your password stolen, attackers cannot enter without that second factor. Turn it on for mail, social and banks.'], href: 'mantenimiento-software.html#rutina' },
    { c: 'Otro', k: ['gestor de contraseñas', 'que es un gestor de claves', 'administrador de contraseñas'], r: ['Un **gestor de contraseñas** guarda todas tus claves cifradas bajo una sola clave maestra y genera claves largas y únicas por sitio: así no repites la misma en todo ni la anotas en papel.', 'A **password manager** stores all your passwords encrypted under one master password and generates long, unique passwords per site: no more reusing one everywhere or writing them on paper.'], href: 'mantenimiento-software.html#rutina' },
    { c: 'Recursos', k: ['mejor antivirus gratis', 'que antivirus usar', 'microsoft defender', 'mejor programa mantenimiento'], r: ['[[trophy]] **Mejor en general: Microsoft Defender** — ya viene con Windows, se actualiza solo y protege todo el tiempo sin instalar nada ni pagar nada. Para la mayoría de usuarios, es la base correcta.', '[[trophy]] **Best overall: Microsoft Defender** — it already ships with Windows, updates itself and protects all the time with nothing to install or pay. For most users, it is the right base.'], href: 'mantenimiento-software.html#programas' },
    { c: 'Recursos', k: ['programas gratis mantenimiento', 'mantenimiento costo cero', 'mejor costo programas'], r: ['[[coin]] **Mejor costo: BleachBit + Defender** — costo total 0: Defender protege y BleachBit limpia temporales sin publicidad, sin suscripción y sin peso extra. Ideal si no quieres gastar nada.', '[[coin]] **Best value: BleachBit + Defender** — total cost 0: Defender protects and BleachBit cleans temps with no ads, no subscription and no extra weight. Ideal if you do not want to spend anything.'], href: 'mantenimiento-software.html#programas' },
    { c: 'Recursos', k: ['programas mas eficientes', 'winget que es', 'crystaldiskinfo que es'], r: ['[[bolt]] **Más eficientes: Winget + CrystalDiskInfo** — solo trabajan cuando se les pide: Winget actualiza muchos programas a la vez desde Windows y CrystalDiskInfo revisa la salud SMART del disco sin quedarse en segundo plano.', '[[bolt]] **Most efficient: Winget + CrystalDiskInfo** — they only work when asked: Winget updates many programs at once from Windows and CrystalDiskInfo checks disk SMART health without staying in the background.'], href: 'mantenimiento-software.html#programas' },
    { c: 'Recursos', k: ['tabla programas recomendados', 'que programas instalar mantenimiento', 'programas recomendados mantenimiento'], r: ['La tabla recomienda: **Defender** (antivirus), **Malwarebytes Free** (segunda opinión), **Winget** (actualizar todo), **Windows Update** (sistema y drivers), **BleachBit** (limpiar), **CCleaner Free** (limpieza guiada), **CrystalDiskInfo** (salud del disco) y **Copia de Windows / Veeam** (backup). Combo costo 0: Defender + Winget + BleachBit. Descarga todo solo desde su sitio oficial.', 'The table recommends: **Defender** (antivirus), **Malwarebytes Free** (second opinion), **Winget** (update everything), **Windows Update** (system and drivers), **BleachBit** (cleaning), **CCleaner Free** (guided cleaning), **CrystalDiskInfo** (disk health) and **Windows Backup / Veeam** (backup). Zero-cost combo: Defender + Winget + BleachBit. Download everything only from its official site.'], href: 'mantenimiento-software.html#programas' },
    { c: 'Recursos', k: ['que es tracert', 'tracert', 'traceroute que es'], r: ['El **tracert** (traceroute) muestra el camino que sigue un paquete hasta su destino, salto por salto con su tiempo: sirve para ver en qué punto se pierde o se demora la conexión. En Windows se escribe `tracert 8.8.8.8`.', '**Tracert** (traceroute) shows the path a packet takes to its destination, hop by hop with timing: it reveals where the connection is lost or delayed. On Windows you type `tracert 8.8.8.8`.'], href: 'recursos.html#laboratorio' },
    { c: 'Recursos', k: ['que es nslookup', 'nslookup para que sirve', 'nslookup dns'], r: ['El **nslookup** pregunta al DNS qué IP tiene un dominio (o al revés): sirve para comprobar si un sitio no abre por DNS o por otra cosa. Se escribe `nslookup nvision.social`.', '**Nslookup** asks DNS which IP a domain has (or vice versa): it checks whether a site fails because of DNS or something else. You type `nslookup nvision.social`.'], href: 'recursos.html#laboratorio' },
    { c: 'Recursos', k: ['que es netstat', 'netstat para que sirve', 'netstat conexiones'], r: ['El **netstat** lista las conexiones de red activas de tu equipo: qué programas están conectados, a qué IP y por qué puerto. Sirve para cazar programas sospechosos hablando con internet.', '**Netstat** lists your machine\u2019s active network connections: which programs are connected, to which IP and port. It catches suspicious programs talking to the internet.'], href: 'recursos.html#laboratorio' },
    { c: 'Recursos', k: ['que es getmac', 'getmac comando', 'ver mac con getmac'], r: ['El **getmac** muestra la dirección MAC de todas tus tarjetas de red en una lista rápida, sin abrir configuraciones. Es el código para ver tu MAC sin rodeos.', '**Getmac** shows the MAC address of all your network cards in a quick list, without opening settings. It is the no-nonsense code for seeing your MAC.'], href: 'recursos.html#laboratorio' },
    { c: 'Recursos', k: ['que es systeminfo', 'systeminfo comando', 'systeminfo para que sirve'], r: ['El **systeminfo** vuelca toda la ficha de tu equipo en la terminal: sistema, procesador, RAM, fecha de instalación y actualizaciones. Es el "Detecta mi equipo" pero por código.', '**Systeminfo** dumps your whole machine profile in the terminal: system, processor, RAM, install date and updates. It is "Detect my machine" but as code.'], href: 'recursos.html#laboratorio' },
    { c: 'Recursos', k: ['que es chkdsk', 'chkdsk para que sirve', 'chkdsk disco'], r: ['El **chkdsk** revisa el disco buscando errores del sistema de archivos y sectores dañados, y los repara si le pides (`chkdsk C: /f`). Si el disco tiene errores, es el primer código que se corre.', '**Chkdsk** scans the disk for file-system errors and bad sectors, and repairs them if asked (`chkdsk C: /f`). If the disk has errors, it is the first code to run.'], href: 'recursos.html#laboratorio' },
    { c: 'Recursos', k: ['que es sfc scannow', 'sfc scannow para que sirve', 'sfc reparar windows'], r: ['El **sfc /scannow** revisa los archivos del sistema de Windows y repara los dañados con copias buenas: sirve cuando Windows falla raro tras un virus o un apagón. Se corre en la terminal como administrador.', '**SFC /scannow** checks Windows system files and repairs damaged ones with good copies: it helps when Windows acts strange after a virus or blackout. Run it in the terminal as administrator.'], href: 'recursos.html#laboratorio' },
    { c: 'Recursos', k: ['ipconfig flushdns', 'flushdns para que sirve', 'limpiar cache dns'], r: ['El **ipconfig /flushdns** borra la caché de DNS de tu equipo: sirve cuando un sitio cambió de servidor y tu PC sigue yendo al viejo, o cuando el DNS quedó con basura. Después vuelve a preguntar desde cero.', '**ipconfig /flushdns** clears your machine\u2019s DNS cache: it helps when a site moved servers and your PC keeps going to the old one, or when DNS cache went stale. Afterwards it asks fresh.'], href: 'recursos.html#laboratorio' },
    { c: 'Recursos', k: ['netsh winsock reset', 'netsh winsock', 'resetear red windows'], r: ['El **netsh winsock reset** reinicia el catálogo de red de Windows: sirve cuando internet falla sin razón clara tras un virus o un programa que tocó la red. Después hay que reiniciar el equipo.', '**netsh winsock reset** resets Windows\u2019 network catalog: it helps when the internet fails for no clear reason after a virus or a program that touched the network. You must restart afterwards.'], href: 'recursos.html#laboratorio' },
    { c: 'Recursos', k: ['cmd vs powershell', 'diferencia cmd powershell', 'cmd o powershell'], r: ['El **CMD** es la consola clásica de Windows, simple y compatible con códigos viejos; **PowerShell** es su sucesor moderno, mucho más potente para administrar el sistema y automatizar tareas. Los códigos del laboratorio usan PowerShell donde hace falta potencia.', '**CMD** is classic Windows console, simple and compatible with old codes; **PowerShell** is its modern successor, far more powerful for managing the system and automating tasks. The lab codes use PowerShell where power is needed.'], href: 'recursos.html#laboratorio' },
    { c: 'Otro', k: ['que es un buscador', 'buscador google', 'buscador vs navegador'], r: ['Un **buscador** (Google, Bing) es la página que busca en la web y te da resultados; el **navegador** (Chrome, Firefox) es el programa donde abres esa página. Sin navegador no llegas al buscador, y sin buscador te tocaría escribir cada dirección a mano.', 'A **search engine** (Google, Bing) is the page that searches the web and gives results; the **browser** (Chrome, Firefox) is the program where you open that page. Without a browser you never reach the engine, and without an engine you would type every address by hand.'] },
    { c: 'Otro', k: ['que es streaming', 'streaming que es', 'ver streaming'], r: ['El **streaming** es ver o escuchar contenido por internet sin descargarlo: el video llega en pedazos mientras lo ves (Netflix, YouTube, Twitch). Necesita buena bajada y poco jitter para no pausarse.', '**Streaming** is watching or listening online without downloading: video arrives in pieces as you watch (Netflix, YouTube, Twitch). It needs good download speed and low jitter to avoid buffering.'] },
    { c: 'Otro', k: ['que es una red social', 'redes sociales que son', 'red social que significa'], r: ['Una **red social** (Instagram, TikTok, X) es una plataforma para publicar, seguir gente y conversar: su negocio es tu atención y tus datos. Cuida lo que publicas: una vez en internet, casi nunca se borra del todo.', 'A **social network** (Instagram, TikTok, X) is a platform to post, follow people and chat: its business is your attention and data. Mind what you post: once online, it almost never fully disappears.'] },
    { c: 'Otro', k: ['que es spam', 'spam correo', 'correo spam que es'], r: ['El **spam** es el correo o mensaje masivo no pedido (publicidad, estafas, cadenas): molesta y a veces esconde phishing. No respondas ni abras sus enlaces: márcalo como spam y el filtro aprenderá.', '**Spam** is unsolicited bulk mail or messages (ads, scams, chains): annoying and sometimes hiding phishing. Do not reply or open its links: mark it as spam and the filter will learn.'] },
    { c: 'Otro', k: ['que es la inteligencia artificial', 'inteligencia artificial que es', 'que es ia'], r: ['La **inteligencia artificial (IA)** es software que aprende de muchos ejemplos para hacer tareas que antes pedían personas: reconocer imágenes, traducir, conversar o predecir. No "piensa" como tú: calcula probabilidades con lo que aprendió.', '**Artificial intelligence (AI)** is software that learns from many examples to do tasks that once needed people: recognizing images, translating, chatting or predicting. It does not "think" like you: it computes probabilities from what it learned.'] },
    { c: 'Otro', k: ['que es un chatbot', 'chatbot que es', 'chatbot de reglas'], r: ['Un **chatbot** es un programa que conversa con texto: este asistente de NVISION es un chatbot de **reglas**, entrenado con fichas sobre el sitio (no una IA generativa): entiende tu pregunta, busca la ficha que mejor calza y responde con ella.', 'A **chatbot** is a program that chats in text: this NVISION assistant is a **rule-based** chatbot, trained on cards about the site (not a generative AI): it understands your question, finds the best-matching card and answers with it.'] },
    { c: 'Otro', k: ['que es una criptomoneda', 'criptomoneda que es', 'blockchain que es'], r: ['Una **criptomoneda** (Bitcoin, Ethereum) es dinero digital sin banco central, guardado en una **blockchain**: un registro público compartido que nadie puede borrar a escondidas. Su precio sube y baja muchísimo, y perder tu clave es perder tus monedas.', 'A **cryptocurrency** (Bitcoin, Ethereum) is digital money with no central bank, kept on a **blockchain**: a shared public ledger nobody can secretly erase. Its price swings wildly, and losing your key means losing your coins.'] },
{ c: 'Recursos', k: ['que es el mantenimiento por software', 'mantenimiento por software', 'mantenimiento preventivo por software', 'software maintenance'], r: ['Es el cuidado que se hace **sin abrir el computador**: actualizar, proteger, limpiar, respaldar y revisar el sistema antes de que falle. Bien hecho, evita virus, lentitud, errores y pérdida de archivos.', 'It is the care done **without opening the computer**: updating, protecting, cleaning, backing up and checking the system before it fails. Done well, it prevents viruses, slowness, errors and lost files.'], href: 'mantenimiento-software.html#que-es' },
    { c: 'Recursos', k: ['regla de oro mantenimiento', 'primero la copia de seguridad', 'antes de actualizar copia', 'golden rule backup'], r: ['**Regla de oro: primero la copia de seguridad, después cualquier cambio.** Antes de actualizar o limpiar algo importante, guarda tus archivos: si algo sale mal, vuelves atrás sin perder nada.', '**Golden rule: backup first, changes second.** Before updating or cleaning anything important, save your files: if something goes wrong, you roll back without losing anything.'], href: 'mantenimiento-software.html#paso-a-paso' },
    { c: 'Recursos', k: ['beneficios del mantenimiento', 'para que sirve el mantenimiento preventivo', 'ventajas mantenimiento software'], r: ['Tres beneficios: **menos fallos y pantallazos** (actualizaciones y drivers corrigen errores), **más velocidad y espacio** (limpiar temporales libera disco y arranque) y **más seguridad** (antivirus, contraseñas y copias contra virus y ransomware).', 'Three benefits: **fewer crashes and blue screens** (updates and drivers fix bugs), **more speed and space** (cleaning temp files frees disk and boot time) and **more security** (antivirus, passwords and backups against viruses and ransomware).'], href: 'mantenimiento-software.html#que-es' },
    { c: 'Recursos', k: ['actualizar sistema y aplicaciones', 'tarea actualizar', 'actualizaciones automaticas'], r: ['Las actualizaciones **cierran agujeros de seguridad** y corrigen errores: un programa viejo es una puerta abierta. Activa las automáticas del sistema, actualiza navegador y ofimática **desde sus sitios oficiales** y reinicia para que se apliquen bien.', 'Updates **close security holes** and fix bugs: an old program is an open door. Turn on automatic system updates, update browser and office apps **from their official sites** and restart so changes apply properly.'], href: 'mantenimiento-software.html#tareas' },
    { c: 'Recursos', k: ['controladores al dia', 'drivers al dia', 'actualizar drivers', 'que es un driver', 'que es un controlador driver'], r: ['El **controlador (driver)** es el traductor entre el sistema y cada pieza: video, red, sonido y chipset. Si falla: pantallas negras, Wi-Fi inestable o sonido perdido. Descárgalos **solo del fabricante**; si algo empeora tras actualizar, vuelve al controlador anterior.', 'A **driver** is the translator between the system and each part: video, network, sound and chipset. If it fails: black screens, unstable Wi-Fi or lost sound. Download only **from the manufacturer**; if something gets worse after updating, roll back to the previous driver.'], href: 'mantenimiento-software.html#tareas' },
    { c: 'Recursos', k: ['antivirus y antimalware', 'tarea antivirus', 'analisis antivirus', 'cuantos antivirus'], r: ['**Un solo antivirus activo y actualizado, nunca dos a la vez**: se pelean entre sí y dejan huecos. Análisis rápido semanal y completo mensual. No abras adjuntos ni enlaces sospechosos, aunque parezcan de un conocido.', '**One active, updated antivirus, never two at once**: they fight each other and leave gaps. Quick scan weekly, full scan monthly. Do not open suspicious attachments or links, even if they look like they come from someone you know.'], href: 'mantenimiento-software.html#tareas' },
    { c: 'Recursos', k: ['limpieza digital', 'limpieza y orden digital', 'archivos temporales ocupan disco', 'borrar temporales'], r: ['Temporales, descargas viejas y programas sin uso ocupan disco y hacen más lento el arranque. Borra temporales y papelera, desinstala desde el panel oficial del sistema y desactiva los programas innecesarios que inician con el equipo. Frecuencia: mensual.', 'Temp files, old downloads and unused programs eat disk and slow boot. Delete temps and trash, uninstall from the system\u2019s official panel and disable unneeded startup programs. Frequency: monthly.'], href: 'mantenimiento-software.html#tareas' },
    { c: 'Recursos', k: ['copias de seguridad', 'regla 3-2-1', 'como hacer copia de seguridad', 'backup 3-2-1'], r: ['La copia es el seguro de tus archivos. **Regla 3-2-1: 3 copias, en 2 medios distintos, 1 fuera de casa o en la nube.** Automatízala para no depender de acordarte y comprueba alguna vez que de verdad se puede abrir y restaurar.', 'A backup is your files\u2019 insurance. **3-2-1 rule: 3 copies, on 2 different media, 1 offsite or in the cloud.** Automate it so you do not rely on remembering, and test sometime that it really opens and restores.'], href: 'mantenimiento-software.html#tareas' },
    { c: 'Recursos', k: ['optimizacion del sistema', 'salud del sistema', 'salud smart', 'espacio libre disco'], r: ['Mantén al menos **15–20 % del disco libre**, revisa la salud **SMART** del disco y la temperatura. Si va lento, revisa primero: inicio, disco lleno y programas en segundo plano. Frecuencia: mensual; salud del disco, trimestral.', 'Keep at least **15–20 % of the disk free**, check the disk\u2019s **SMART** health and temperature. If it runs slow, check first: startup, full disk and background programs. Frequency: monthly; disk health, quarterly.'], href: 'mantenimiento-software.html#tareas' },
    { c: 'Recursos', k: ['rutina semanal mantenimiento', 'que hacer cada semana pc', 'mantenimiento semanal', 'que hago cada semana'], r: ['Cada **semana**: actualizar sistema y programas, análisis antivirus rápido y verificar que la copia automática corrió. Es la defensa básica contra virus y errores nuevos.', 'Every **week**: update system and programs, quick antivirus scan and verify the automatic backup ran. It is the basic defense against new viruses and bugs.'], href: 'mantenimiento-software.html#rutina' },
    { c: 'Recursos', k: ['rutina mensual mantenimiento', 'que hacer cada mes pc', 'mantenimiento mensual', 'que hago cada mes'], r: ['Cada **mes**: limpieza de temporales y descargas, desinstalar lo que no usas, análisis antivirus completo y revisar inicio y espacio libre. Recupera velocidad y evita que el disco se llene.', 'Every **month**: clean temps and downloads, uninstall what you do not use, full antivirus scan and check startup and free space. It recovers speed and keeps the disk from filling up.'], href: 'mantenimiento-software.html#rutina' },
    { c: 'Recursos', k: ['rutina trimestral mantenimiento', 'cada tres meses pc', 'mantenimiento trimestral', 'que hago cada trimestre'], r: ['Cada **trimestre**: revisar controladores, salud SMART del disco, probar que una copia se puede restaurar y revisar contraseñas importantes. Detecta desgaste y fallos antes de que pierdas datos.', 'Every **quarter**: check drivers, disk SMART health, test that a backup can be restored and review important passwords. It catches wear and failures before you lose data.'], href: 'mantenimiento-software.html#rutina' },
    { c: 'Recursos', k: ['rutina semestral mantenimiento', 'cada seis meses pc', 'revision completa equipo', 'que hago cada seis meses'], r: ['Cada **semestre**: revisión completa (sistema, seguridad, copias, espacio y programas) y cambiar contraseñas débiles o repetidas. Deja el equipo como nuevo, sin reinstalar por gusto.', 'Every **six months**: full review (system, security, backups, space and programs) and change weak or repeated passwords. It leaves the machine like new, without reinstalling for fun.'], href: 'mantenimiento-software.html#rutina' },
    { c: 'Recursos', k: ['orden seguro 6 pasos', 'media hora mantenimiento', 'en que orden limpiar mi pc', 'paso a paso mantenimiento'], r: ['Si solo tienes media hora, sigue este orden: **1)** copia antes de tocar nada, **2)** actualiza, **3)** pasa el antivirus, **4)** limpia temporales y programas, **5)** revisa inicio y espacio, **6)** reinicia y comprueba. Protege primero, limpia después.', 'If you only have half an hour, follow this order: **1)** backup before touching anything, **2)** update, **3)** run the antivirus, **4)** clean temps and programs, **5)** check startup and space, **6)** restart and verify. Protect first, clean second.'], href: 'mantenimiento-software.html#paso-a-paso' },
    { c: 'Recursos', k: ['ventanas solas anuncios', 'navegador cambio buscador', 'anuncios solos', 'popups solos'], r: ['Ventanas o anuncios que aparecen solos, o el navegador que cambia de buscador: señal de **malware**. Pasa el antivirus completo, revisa las extensiones del navegador y no instales "optimizadores" de sitios pirata.', 'Popups or ads appearing on their own, or a browser that changes search engine: a **malware** sign. Run a full antivirus scan, check browser extensions and never install "optimizers" from pirate sites.'], href: 'mantenimiento-software.html#alertas' },
    { c: 'Recursos', k: ['se calienta mucho', 'equipo muy caliente', 'sobrecalentamiento', 'temperatura alta equipo'], r: ['Si se calienta, se apaga solo o tarda mucho más que antes: revisa ventilación y polvo (limpieza de PC3D), temperatura y salud del disco. Si hay olor a quemado o ruido eléctrico, deja de usarlo y consulta servicio técnico.', 'If it overheats, shuts down alone or takes much longer than before: check ventilation and dust (PC3D cleaning), temperature and disk health. If there is a burning smell or electrical noise, stop using it and consult a technician.'], href: 'mantenimiento-software.html#alertas' },
    { c: 'Recursos', k: ['archivos desaparecen', 'archivos piden rescate', 'ransomware', 'archivos cambian de nombre'], r: ['Archivos que desaparecen, cambian de nombre o **piden rescate para abrirlos**: señal de ransomware o virus. No pagues: desconecta el equipo, pasa el antivirus y restaura desde tu copia (por eso existe la regla 3-2-1).', 'Files disappearing, changing names or **demanding ransom to open**: a ransomware or virus sign. Do not pay: disconnect the machine, run the antivirus and restore from your backup (that is why the 3-2-1 rule exists).'], href: 'mantenimiento-software.html#alertas' },
    { c: 'Recursos', k: ['disco siempre lleno', 'disco al 100 por ciento', 'disco lleno sin razon'], r: ['Disco siempre lleno o al 100 % sin razón: limpia temporales y descargas, desinstala lo que no usas y deja libre al menos 15–20 %. Si sigue al 100 %, revisa salud SMART y qué programa está escribiendo sin parar.', 'Disk always full or at 100 % for no reason: clean temps and downloads, uninstall what you do not use and keep at least 15–20 % free. If it stays at 100 %, check SMART health and which program keeps writing nonstop.'], href: 'mantenimiento-software.html#alertas' },
    { c: 'Recursos', k: ['que no hacer nunca mantenimiento', 'errores mantenimiento', 'no instalar dos antivirus', 'no descargar pirata'], r: ['Qué **no hacer nunca**: dos antivirus a la vez, descargar programas, drivers u "optimizadores" de sitios pirata, borrar archivos del sistema o del registro sin saber qué hacen, e ignorar las copias: un equipo sin copia es un archivo perdido esperando su momento.', 'What **never to do**: two antiviruses at once, downloading programs, drivers or "optimizers" from pirate sites, deleting system or registry files without knowing what they do, and ignoring backups: a machine without a backup is a lost file waiting to happen.'], href: 'mantenimiento-software.html#alertas' },
    { c: 'Recursos', k: ['contraseñas fuertes', 'cambiar contraseñas', 'contraseñas debiles repetidas', 'passwords', 'como deben ser mis contraseñas'], r: ['Contraseñas **fuertes y distintas por servicio**; revisa las importantes cada trimestre y cambia las débiles o repetidas cada semestre. Son parte del mantenimiento: un antivirus no te protege si tu clave es "123456".', '**Strong, different passwords per service**; review the important ones quarterly and change weak or repeated ones every six months. They are part of maintenance: no antivirus protects you if your password is "123456".'], href: 'mantenimiento-software.html#rutina' },
    { c: 'Recursos', k: ['quienes hicieron el eniac', 'creadores del eniac', 'mauchly eckert', 'quien invento el eniac'], r: ['**John Mauchly** (físico, diseñador conceptual: vio que los circuitos con válvulas podían calcular a velocidades impensables) y **J. Presper Eckert** (ingeniero eléctrico jefe: diseñó los circuitos para que miles de tubos no fallaran sin parar).', '**John Mauchly** (physicist, conceptual designer: he saw vacuum-tube circuits could compute at inconceivable speeds) and **J. Presper Eckert** (chief electrical engineer: he designed the circuits so thousands of tubes would not fail nonstop).'], href: 'hardware.html#historia' },
    { c: 'Recursos', k: ['programadoras del eniac', 'mujeres eniac', 'quienes programaron el eniac', 'las 6 programadoras'], r: ['Las **6 programadoras pioneras**: Kay McNulty, Betty Jennings, Betty Snyder, Marlyn Wescoff, Ruth Lichterman y Frances Bilas. Programaban **sin lenguajes ni sistema operativo**: cables, paneles de conmutación y diagramas lógicos a mano para las trayectorias balísticas.', 'The **6 pioneer programmers**: Kay McNulty, Betty Jennings, Betty Snyder, Marlyn Wescoff, Ruth Lichterman and Frances Bilas. They programmed **without languages or an operating system**: patch cables, switch panels and logic diagrams by hand for the ballistic trajectories.'], href: 'hardware.html#historia' },
    { c: 'Recursos', k: ['von neumann', 'arquitectura von neumann', 'programa almacenado'], r: ['**John von Neumann**, consultor matemático del proyecto, formuló en 1945 el concepto de **programa almacenado** (Arquitectura Von Neumann): guardar programa y datos en la misma memoria. Casi todas las computadoras modernas siguen esa idea.', '**John von Neumann**, the project\u2019s mathematical consultant, formalized in 1945 the **stored-program** concept (Von Neumann Architecture): keeping program and data in the same memory. Almost every modern computer still follows that idea.'], href: 'hardware.html#historia' },
    { c: 'Recursos', k: ['por que nacio el eniac', 'para que se creo el eniac', 'project px', 'tablas balisticas'], r: ['En la Segunda Guerra Mundial el ejército de EE. UU. necesitaba **tablas balísticas** para artillería pesada con rapidez y precisión. En 1943 el Laboratorio de Investigación Balística financió en secreto el proyecto en la Universidad de Pensilvania bajo el nombre clave **Project PX**.', 'In World War II the U.S. Army needed **ballistic tables** for heavy artillery, fast and precise. In 1943 the Ballistic Research Laboratory secretly funded the project at the University of Pennsylvania under the code name **Project PX**.'], href: 'hardware.html#historia' },
    { c: 'Recursos', k: ['legado del eniac', 'impacto del eniac', 'que logro el eniac', '20 horas 30 segundos'], r: ['El ENIAC demostró que el cálculo electrónico a gran escala era viable: bajó cálculos de balística de **20 horas a 30 segundos**. No guardaba el programa en memoria como hoy (se recableaba a mano por tarea), pero abrió la era digital moderna.', 'ENIAC proved large-scale electronic computing was viable: it cut ballistic calculations from **20 hours to 30 seconds**. It did not store the program in memory like today (it was rewired by hand per task), but it opened the modern digital age.'], href: 'hardware.html#historia' },
    { c: 'Recursos', k: ['altair 8800', 'primer microcomputador comercial', 'intel 8080'], r: ['El **Altair 8800** fue el primer microcomputador comercial, basado en el procesador **Intel 8080**. Dio origen al software de microcomputadoras y al inicio de la informática personal.', 'The **Altair 8800** was the first commercial microcomputer, powered by the **Intel 8080** processor. It gave birth to microcomputer software and the dawn of personal computing.'], href: 'hardware.html#historia' },
    { c: 'Recursos', k: ['apple ii', 'apple 2', 'primer computador personal masivo'], r: ['El **Apple II** fue uno de los primeros microcomputadores producidos en masa: teclado integrado, gráficos a color y ranuras de expansión.', 'The **Apple II** was one of the first mass-produced microcomputers: integrated keyboard, color graphics and expansion slots.'], href: 'hardware.html#historia' },
    { c: 'Recursos', k: ['ibm 7090', 'transistores mainframe', 'sistema central transistorizado'], r: ['El **IBM 7090** reemplazó las válvulas de vacío por **transistores**: multiplicó por 6 la velocidad de cálculo y redujo el consumo eléctrico. Es el salto de los tubos al transistor.', 'The **IBM 7090** replaced vacuum tubes with **transistors**: it multiplied computing speed by 6 and cut power use. It is the leap from tubes to transistors.'], href: 'hardware.html#historia' },
    { c: 'Recursos', k: ['linea de tiempo computacion', 'timeline historia', 'historia completa computadores'], r: ['La línea de tiempo del sitio recorre: **ENIAC** y sus pioneros, el salto al transistor (**IBM 7090**), el primer microcomputador comercial (**Altair 8800**) y la informática personal (**Apple II**). Está en Hardware, sección Historia.', 'The site\u2019s timeline covers: **ENIAC** and its pioneers, the transistor leap (**IBM 7090**), the first commercial microcomputer (**Altair 8800**) and personal computing (**Apple II**). It lives in Hardware, History section.'], href: 'hardware.html#historia' },
    { c: 'Redes', k: ['ventajas desventajas estrella', 'pros contras estrella', 'estrella punto unico de fallo'], r: ['Estrella: **pro** — fácil de diagnosticar y agregar nodos sin detener la red; **contra** — punto único de fallo: si el switch central cae, toda la red cae.', 'Star: **pro** — easy to troubleshoot and add nodes without stopping the network; **con** — single point of failure: if the central switch dies, the whole network dies.'], href: 'redes.html#topologias' },
    { c: 'Redes', k: ['ventajas desventajas bus', 'pros contras bus'], r: ['Bus: **pro** — bajo costo y poco cableado; **contra** — una rotura del troncal deja inoperativa toda la red y hay alta probabilidad de colisiones.', 'Bus: **pro** — low cost and little cabling; **con** — a break in the backbone kills the whole network and collisions are highly likely.'], href: 'redes.html#topologias' },
    { c: 'Redes', k: ['ventajas desventajas anillo', 'pros contras anillo'], r: ['Anillo: **pro** — sin colisiones y rendimiento regular y predecible con mucho tráfico; **contra** — si un equipo falla o se desconecta, se interrumpe todo el ciclo.', 'Ring: **pro** — no collisions and steady, predictable performance under heavy traffic; **con** — if one device fails or disconnects, the whole cycle breaks.'], href: 'redes.html#topologias' },
    { c: 'Redes', k: ['ventajas desventajas malla', 'pros contras malla'], r: ['Malla: **pro** — máxima tolerancia a fallos, el tráfico se redirige al instante; **contra** — elevado costo de cableado, interfaces y complejidad de ruteo.', 'Mesh: **pro** — maximum fault tolerance, traffic reroutes instantly; **con** — high cost of cabling, interfaces and routing complexity.'], href: 'redes.html#topologias' },
    { c: 'Redes', k: ['ventajas desventajas arbol', 'pros contras arbol'], r: ['Árbol: **pro** — gran escalabilidad y fácil aislamiento de subredes por departamentos; **contra** — si el nodo raíz falla, las ramas pierden conectividad entre sí.', 'Tree: **pro** — highly scalable and easy to isolate subnets per department; **con** — if the root node fails, the branches lose connectivity with each other.'], href: 'redes.html#topologias' },
    { c: 'Redes', k: ['ventajas desventajas hibrida', 'pros contras hibrida'], r: ['Híbrida: **pro** — máxima flexibilidad, aprovecha lo mejor de cada topología por área; **contra** — diseño y mantenimiento complejos, requiere equipos de interconexión avanzados.', 'Hybrid: **pro** — maximum flexibility, takes the best of each topology per area; **con** — complex design and maintenance, needs advanced interconnection gear.'], href: 'redes.html#topologias' },
    { c: 'Redes', k: ['tabla comparativa redes', 'comparar redes tabla', 'tabla de alcances', 'tabla ban pan lan'], r: ['En la sección de tipos de red hay una **tabla comparativa**: cada red con su nombre, cobertura y caso de uso — BAN (<1 m), PAN (1-10 m), LAN (~100 m), CAN (1-5 km), MAN (hasta 50 km), WAN (países) y GAN (planetaria).', 'The network types section has a **comparison table**: each network with its name, coverage and use case — BAN (<1 m), PAN (1-10 m), LAN (~100 m), CAN (1-5 km), MAN (up to 50 km), WAN (countries) and GAN (planetary).'], href: 'redes.html#alcance-redes' },
    { c: 'Recursos', k: ['simulacion torre 3d', 'modelo 3d torre', 'three.js torre'], r: ['En Recursos hay un módulo opcional: la **simulación de torre 3D**, un espacio reservado para integrar Three.js/WebGL y rotar y desarmar una torre virtual. El visor 3D que sí funciona hoy está en PC3D.', 'Resources has an optional module: the **3D tower simulation**, a reserved space to integrate Three.js/WebGL and rotate and disassemble a virtual tower. The 3D viewer that works today is in PC3D.'], href: 'recursos.html#laboratorio' },
    { c: 'Recursos', k: ['bateria del detector', 'que muestra la bateria', 'detecta bateria'], r: ['El detector también muestra la **batería**: nivel y si está **cargando**. Es uno de los 7 datos que el navegador puede ver sin instalar nada.', 'The detector also shows the **battery**: level and whether it is **charging**. It is one of the 7 facts the browser can see with no installs.'], href: 'recursos.html#laboratorio' },
    { c: 'Otro', k: ['inicio de nvision', 'pagina principal nvision', 'que hay en el inicio', 'portada nvision'], r: ['La página principal presenta el sitio — **Arquitectura y Evolución de los Computadores** — y cuatro entradas: Hardware y Evolución, Redes y Simulación, Recursos de Aprendizaje y Mantenimiento por software.', 'The home page introduces the site — **Computer Architecture and Evolution** — and four entries: Hardware and Evolution, Networks and Simulation, Learning Resources and Software Maintenance.'] },
    { c: 'Redes', k: ['del hardware a la red', 'como se enlaza el equipo a la red', 'capa de enlace'], r: ['La sección **Del Hardware a la Red** explica cómo el equipo físico se enlaza a una LAN: la MAC de la NIC (capa de enlace), los puertos RJ-45 y Wi-Fi por PCIe, y el flujo de datos RAM [[arrow_right]] CPU [[arrow_right]] NIC [[arrow_right]] medio físico.', 'The **From Hardware to Network** section explains how physical hardware joins a LAN: the NIC\u2019s MAC (link layer), RJ-45 and Wi-Fi ports over PCIe, and the data flow RAM [[arrow_right]] CPU [[arrow_right]] NIC [[arrow_right]] physical medium.'], href: 'redes.html#redes' },
    { c: 'Otro', k: ['que es un sistema operativo', 'sistema operativo', 'que es windows', 'que es linux', 'que es el os'], r: ['El **sistema operativo** (Windows, Linux, macOS) es el programa base que administra hardware y programas: memoria, archivos, pantalla y red. Sin él, el PC no sabe qué hacer con sus piezas.', 'The **operating system** (Windows, Linux, macOS) is the base program that manages hardware and programs: memory, files, screen and network. Without it, the PC would not know what to do with its parts.'] },
    { c: 'Otro', k: ['que es un programa', 'que es una aplicacion', 'que es una app', 'que es el software de aplicacion'], r: ['Un **programa o app** es software que hace una tarea: navegador, ofimática, juegos. Corre sobre el sistema operativo y usa CPU, RAM y almacenamiento.', 'A **program or app** is software that performs a task: browser, office suite, games. It runs on the operating system and uses CPU, RAM and storage.'] },
    { c: 'Otro', k: ['que es un virus', 'que es malware', 'virus spyware ransomware', 'diferencia virus malware'], r: ['**Malware** es el término general para software dañino: **virus** (se replica), **spyware** (espía y roba datos) y **ransomware** (secuestra archivos pidiendo rescate). Contra todos: un antivirus actualizado y copias de seguridad.', '**Malware** is the general term for harmful software: **virus** (it replicates), **spyware** (it spies and steals data) and **ransomware** (it hijacks files demanding ransom). Against all of them: an updated antivirus and backups.'], href: 'mantenimiento-software.html#tareas' },
    { c: 'Otro', k: ['que es la nube', 'nube que es', 'cloud que significa', 'guardar en la nube'], r: ['La **nube** son servidores de otros (internet) donde guardas archivos y usas programas sin tenerlos en tu disco. Sirve para copias de seguridad: es el "1 fuera de casa" de la regla 3-2-1.', 'The **cloud** is other people\u2019s servers (on the internet) where you store files and run programs without keeping them on your disk. It works for backups: it is the "1 offsite" of the 3-2-1 rule.'], href: 'mantenimiento-software.html#tareas' },
    { c: 'Otro', k: ['que es un navegador', 'navegador web', 'chrome firefox edge'], r: ['El **navegador** (Chrome, Firefox, Edge, Brave) es el programa para ver páginas web: pide la página al servidor por HTTP/DNS y la dibuja. No es lo mismo que el buscador ni que internet.', 'The **browser** (Chrome, Firefox, Edge, Brave) is the program for viewing web pages: it requests the page from the server over HTTP/DNS and draws it. It is not the same as the search engine or the internet.'] },
    { c: 'Otro', k: ['que es un archivo', 'que es una carpeta', 'archivos y carpetas'], r: ['Un **archivo** es un conjunto de datos con nombre (documento, foto, programa); una **carpeta** los organiza. Viven en el almacenamiento y se copian, mueven y respaldan como unidades.', 'A **file** is a named set of data (document, photo, program); a **folder** organizes them. They live in storage and are copied, moved and backed up as units.'] },
    { c: 'Otro', k: ['que es usb', 'usb para que sirve', 'memoria usb'], r: ['**USB** es el conector universal para periféricos y memorias: teclados, mouse, discos externos y celulares. Sirve para pasar archivos y para copias de seguridad en un medio distinto.', '**USB** is the universal connector for peripherals and drives: keyboards, mice, external disks and phones. It moves files and works for backups on a different medium.'] },
    { c: 'Otro', k: ['que es el correo electronico', 'email que es', 'correo electronico'], r: ['El **correo electrónico** es el servicio para enviar mensajes y archivos entre cuentas (ej. usuario@dominio.com) a través de servidores de correo. Ojo: los adjuntos sospechosos son la puerta favorita del malware.', '**Email** is the service for sending messages and files between accounts (e.g. user@domain.com) through mail servers. Watch out: suspicious attachments are malware\u2019s favorite door.'] },
    { c: 'Otro', k: ['contraseña segura', 'clave segura', 'como crear contraseña segura'], r: ['Una contraseña segura es **larga (más de 12 caracteres), única por servicio** y mezcla letras, números y símbolos. Nunca repitas la misma en todo: si filtran una, caen todas.', 'A secure password is **long (over 12 characters), unique per service** and mixes letters, numbers and symbols. Never reuse the same one everywhere: if one leaks, they all fall.'], href: 'mantenimiento-software.html#rutina' },
    { c: 'Otro', k: ['que es phishing', 'phishing', 'correo falso estafa', 'suplantacion'], r: ['**Phishing** es el engaño que se hace pasar por un conocido o una empresa (correo, mensaje o página falsa) para robarte claves o datos. Señales: urgencia, remitente raro y enlaces sospechosos. No abras adjuntos ni enlaces dudosos.', '**Phishing** is the trick that pretends to be someone you know or a company (fake email, message or page) to steal your passwords or data. Signs: urgency, odd sender and suspicious links. Do not open dubious attachments or links.'] },
    { c: 'Otro', k: ['archivos temporales que son', 'temporales windows', 'limpiar temporales'], r: ['Los **archivos temporales** son restos que programas y sistema dejan al trabajar: cachés, instaladores viejos, papelera. Borrarlos cada mes libera disco y no rompe nada (nunca toques carpetas del sistema que no reconozcas).', '**Temporary files** are leftovers programs and the system leave while working: caches, old installers, trash. Deleting them monthly frees disk and breaks nothing (never touch system folders you do not recognize).'], href: 'mantenimiento-software.html#tareas' },
    { c: 'Otro', k: ['que es formatear', 'formatear disco', 'formatear pc'], r: ['**Formatear** es borrar por completo un disco o USB y dejarlo como nuevo, listo para guardar. Borra TODO: solo se hace con copia de seguridad hecha antes.', '**Formatting** means completely erasing a disk or USB and leaving it like new, ready to store. It erases EVERYTHING: only do it with a backup made beforehand.'] },
    { c: 'Otro', k: ['que es una actualizacion', 'para que sirven las actualizaciones', 'actualizaciones para que'], r: ['Una **actualización** es una versión nueva de un programa o del sistema que corrige errores y **cierra agujeros de seguridad**. Por eso el mantenimiento pide activar las automáticas y reiniciar después.', 'An **update** is a new version of a program or the system that fixes bugs and **closes security holes**. That is why maintenance asks you to turn on automatic updates and restart after.'], href: 'mantenimiento-software.html#tareas' },
    { c: 'Otro', k: ['internet o web', 'diferencia internet web', 'web que es'], r: ['**Internet** es la red física de redes; la **web** son las páginas y servicios que corren sobre ella (HTTP). Puedes tener internet sin web (correo, juegos en línea), pero no web sin internet.', '**Internet** is the physical network of networks; the **web** is the pages and services that run on it (HTTP). You can have internet without the web (email, online games) but not the web without the internet.'], href: 'redes.html#alcance-redes' },
    { c: 'Otro', k: ['que es un bit', 'que es un byte', 'bits y bytes', 'mb gb'], r: ['**Bit** es la unidad mínima (0 o 1); **byte** son 8 bits. El ancho de banda se mide en bits por segundo (bps) y el almacenamiento en bytes (KB, MB, GB, TB).', '**Bit** is the smallest unit (0 or 1); **byte** is 8 bits. Bandwidth is measured in bits per second (bps) and storage in bytes (KB, MB, GB, TB).'] },
    { c: 'Otro', k: ['wifi 6', 'que es wifi 6', '802.11ax'], r: ['**WiFi 6 (802.11ax)** es la generación actual de WiFi que usa la LAN de la página de Redes: más velocidad y mejor manejo de muchos equipos a la vez en la misma red.', '**WiFi 6 (802.11ax)** is the current WiFi generation used by the Networks page LAN: more speed and better handling of many devices at once on the same network.'], href: 'redes.html#alcance-redes' },
    { c: 'Redes Challenge', k: ['redes challenge', 'el juego', 'juego de topologias', 'jugar redes challenge', 'donde esta el juego', 'como entro al juego'], r: ['**Redes Challenge** es el minijuego de NVISION para practicar topologías de red. Puedes entrar desde el menú **Redes [[arrow_right]] [[gamepad]] Redes Challenge** (está en todas las páginas), desde la sección «Redes Challenge» en la página de Redes, o desde Recursos. Es gratis, corre en el navegador y tiene español e inglés.', '**Redes Challenge** is the NVISION mini-game for practicing network topologies. You can enter from the **Redes [[arrow_right]] [[gamepad]] Redes Challenge** menu (on every page), from the "Redes Challenge" section on the Networks page, or from Recursos. It is free, runs in the browser and has Spanish and English.'], href: 'redes_challenge/index.html' },
    { c: 'Redes Challenge', k: ['reglas del juego', 'como se juega', 'cuantas preguntas', 'como funcionan las vidas', 'puntos del juego'], r: ['Reglas de **Redes Challenge**: son **10 preguntas** de opción múltiple; cada acierto suma **10 puntos** (máximo **100**). Empiezas con **3 vidas [[heart]][[heart]][[heart]]** y pierdes una por cada error; el juego termina si te quedas sin vidas o al responder las 10 preguntas. Cada respuesta incluye una explicación corta de por qué es correcta.', '**Redes Challenge** rules: there are **10 multiple-choice questions**; each correct answer adds **10 points** (max **100**). You start with **3 lives [[heart]][[heart]][[heart]]** and lose one per mistake; the game ends if you run out of lives or finish all 10 questions. Every answer includes a short explanation of why it is correct.'], href: 'redes_challenge/index.html' },
    { c: 'Redes Challenge', k: ['puntuacion del juego', 'cuanto es buena puntuacion', 'resultado final', 'que pasa si pierdo', 'volver a jugar'], r: ['Al terminar el juego: con **80 puntos o más** recibes «[[trophy]] ¡Excelente trabajo!», con **50 o más** «[[medal]] ¡Buen intento!», y con menos «[[book]] ¡Sigue practicando!». Si te quedas sin vidas puedes reiniciar con el botón **[[refresh]] Volver a jugar** y empezar de cero con las preguntas reordenadas.', 'At the end: **80 points or more** gives you «[[trophy]] Excellent work!», **50 or more** «[[medal]] Good try!», and below that «[[book]] Keep practicing!». If you run out of lives you can restart with the **[[refresh]] Play again** button and start fresh with shuffled questions.'], href: 'redes_challenge/index.html' },
    { c: 'Redes Challenge', k: ['que topologias aparecen', 'topologias del juego', 'temas del juego', 'que aprendo en el juego'], r: ['El juego evalúa las **5 topologías** vistas en la página de Redes: **Estrella, Bus, Anillo, Malla y Árbol**. Primero te pregunta por el diagrama (identificar la estructura que dibuja) y luego por conceptos (¿cuál usa un switch central?, ¿cuál tiene caminos alternativos?, etc.).', 'The game tests the **5 topologies** covered on the Networks page: **Star, Bus, Ring, Mesh and Tree**. It first asks about the diagram (identify the drawn structure) and then about concepts (which one uses a central switch? which one has alternative paths?, etc.).'], href: 'redes.html#topologias' },
    { c: 'Redes Challenge', k: ['estrella en el juego', 'switch central', 'cual usa un switch'], r: ['La **estrella** es la topología con un **dispositivo central** (un **SW/switch**) al que se conectan todas las PC con enlaces propios. Pista del juego: «todos los equipos se conectan a un dispositivo central». Es la estándar de las LAN modernas.', '**Star** is the topology with a **central device** (an **SW/switch**) that every PC connects to with its own link. Game hint: "all devices connect to one central device". It is the standard for modern LANs.'], href: 'redes.html#topologias' },
    { c: 'Redes Challenge', k: ['bus en el juego', 'cable troncal', 'cable compartido'], r: ['La **bus** usa un **cable principal (troncal) compartido** al que se cuelgan todos los equipos en línea recta. Pista del juego: «todos los equipos comparten un cable principal». Hoy sobrevive en buses industriales como CAN.', '**Bus** uses a **shared backbone cable** where all devices hang in a straight line. Game hint: "all devices share one main cable". Today it survives in industrial buses like CAN.'], href: 'redes.html#topologias' },
    { c: 'Redes Challenge', k: ['anillo en el juego', 'circuito cerrado', 'los equipos forman un ciclo'], r: ['El **anillo** conecta cada equipo con sus vecinos formando un **circuito cerrado** (PC1[[arrow_right]]PC2[[arrow_right]]PC3[[arrow_right]]PC4[[arrow_right]]PC1). Pista del juego: «los equipos forman un circuito cerrado».', '**Ring** connects each device to its neighbors forming a **closed loop** (PC1[[arrow_right]]PC2[[arrow_right]]PC3[[arrow_right]]PC4[[arrow_right]]PC1). Game hint: "devices form a closed circuit".'], href: 'redes.html#topologias' },
    { c: 'Redes Challenge', k: ['malla en el juego', 'caminos alternativos', 'enlaces multiples', 'redundancia'], r: ['La **malla** tiene **múltiples enlaces entre los dispositivos**: cada nodo se conecta con todos los demás, así hay **rutas redundantes** si un enlace falla. Pista del juego: «existen múltiples enlaces entre los dispositivos».', '**Mesh** has **multiple links between devices**: every node connects to all the others, so there are **redundant paths** if one link fails. Game hint: "there are multiple links between devices".'], href: 'redes.html#topologias' },
    { c: 'Redes Challenge', k: ['arbol en el juego', 'jerarquia de niveles', 'estructura jerarquica', 'ramas de una organizacion'], r: ['El **árbol** organiza los dispositivos en **niveles jerárquicos**: un switch raíz (SW1) conecta switches secundarios (SW2, SW3) y estos a las PC. Se parece a las ramas de una organización. Pista del juego: «los dispositivos se organizan en niveles jerárquicos».', '**Tree** organizes devices in **hierarchical levels**: a root switch (SW1) connects secondary switches (SW2, SW3), and those connect the PCs. It looks like the branches of an organization. Game hint: "devices are organized in hierarchical levels".'], href: 'redes.html#topologias' },
    { c: 'Redes Challenge', k: ['diagramas del juego', 'glosario y simulador', 'que mas ofrece el juego', 'idioma del juego'], r: ['Extras de **Redes Challenge**: los diagramas de topología son **SVG con efecto 3D** (se inclinan al mover el cursor), la barra superior muestra **puntos [[star]], pregunta [[question]] y vidas [[heart]]**, y desde su menú lateral puedes saltar al **Glosario** de términos o al **Simulador Ping**. Funciona en **español e inglés** y también en el celular.', '**Redes Challenge** extras: the topology diagrams are **SVG with a 3D effect** (they tilt as you move the cursor), the top bar shows **points [[star]], question [[question]] and lives [[heart]]**, and its side menu links to the **Glossary** and the **Ping Simulator**. It works in **Spanish and English** and on mobile too.'], href: 'redes_challenge/index.html' },
    { c: 'Otro', k: ['mi pc no enciende', 'no prende el computador', 'no arranca el pc', 'pantalla negra no enciende'], r: ['Si **no enciende**: revisa en orden — cable y toma de corriente, botón de la fuente (atrás), monitor encendido y bien conectado, y si hay pitidos o luces. Si huele a quemado o no da señales, no insistas: servicio técnico.', 'If it **will not turn on**: check in order — power cable and outlet, the PSU switch (at the back), monitor on and well connected, and whether there are beeps or lights. If it smells burnt or shows no signs, do not insist: get a technician.'] },
    { c: 'Otro', k: ['pantalla negra', 'pantalla en negro con cursor', 'monitor negro'], r: ['Pantalla negra con el equipo encendido: revisa cable del monitor y fuente de video, prueba otro puerto, y si empezó tras actualizar, sospecha del **controlador de video** (vuelve al anterior). Si no hay imagen ni en el arranque, puede ser RAM o GPU.', 'Black screen with the machine on: check the monitor cable and video source, try another port, and if it started after an update, suspect the **video driver** (roll back). If there is no image even at boot, it may be RAM or GPU.'] },
    { c: 'Otro', k: ['no tengo sonido', 'sin sonido pc', 'no suena el computador'], r: ['Sin sonido: revisa volumen y salida correcta (parlantes/auriculares), que el dispositivo no esté silenciado, y el **controlador de audio** (actualízalo desde el fabricante). Si empezó de repente, vuelve al controlador anterior.', 'No sound: check volume and the right output (speakers/headphones), that the device is not muted, and the **audio driver** (update it from the manufacturer). If it started suddenly, roll back to the previous driver.'] },
    { c: 'Otro', k: ['wifi inestable', 'wifi se cae', 'wifi se desconecta solo', 'wifi intermitente'], r: ['WiFi que se cae: acerca el equipo al módem o revisa su ubicación, cambia el canal en 2.4 GHz (1, 6 u 11) y actualiza el **controlador de red** desde el fabricante. Si solo falla un equipo, el problema es ese equipo, no la red.', 'WiFi dropping out: move closer to the modem or check its placement, change the 2.4 GHz channel (1, 6 or 11) and update the **network driver** from the manufacturer. If only one device fails, the problem is that device, not the network.'], href: 'wifi.html#instalar-modem' },
    { c: 'Otro', k: ['ventiladores hacen mucho ruido', 'ruido fuerte pc', 'suena mucho el computador'], r: ['Ruido fuerte: casi siempre son **ventiladores con polvo o trabajando al máximo por calor**. Limpia filtros y ventiladores con aire comprimido (sujetándolos) y revisa temperaturas; si el ruido es eléctrico o hay olor a quemado, apaga y consulta técnico.', 'Loud noise: almost always **fans full of dust or running at max because of heat**. Clean filters and fans with compressed air (holding them) and check temperatures; if the noise is electrical or there is a burning smell, power off and consult a technician.'], href: 'pc3d.html#mantenimiento' },
    { c: 'Otro', k: ['no carga la bateria', 'bateria no carga', 'portatil no carga'], r: ['Si no carga: prueba otro toma y otro cargador compatible, revisa que el conector no esté flojo o sucio y observa la salud de la batería. Si está **hinchada**, no la cargues ni la pinches: servicio técnico.', 'If it will not charge: try another outlet and another compatible charger, check the connector is not loose or dirty and watch battery health. If it is **swollen**, do not charge or puncture it: get a technician.'] },
    { c: 'Otro', k: ['hola', 'buenas', 'buenos dias', 'hey', 'saludos', 'hello', 'hi'], r: ['¡Hola! Soy el asistente de **NVISION** [[robot]]. Pregúntame de hardware, redes, el switch, el WiFi o del juego **Redes Challenge** [[gamepad]]. Toca una sugerencia o escribe tu duda.', 'Hi! I am the **NVISION** assistant [[robot]]. Ask me about hardware, networks, the switch, WiFi or the **Redes Challenge** game [[gamepad]]. Tap a suggestion or type your question.'] },
    { c: 'Otro', k: ['quien eres', 'que eres', 'que haces', 'para que sirves', 'ayuda', 'help', 'who are you', 'what can you do'], r: ['Soy un asistente **entrenado con el contenido de NVISION**: respondo desde una base de conocimiento guardada en la página, sin internet y sin IA externa. Si algo no lo sé, puedes **enseñármelo** en la pestaña «Entrenar» y lo aprendo en este navegador.', 'I am an assistant **trained on NVISION content**: I answer from a knowledge base stored in the page, no internet and no external AI. If I miss something, you can **teach me** in the "Train" tab and I learn it in this browser.'], },
    { c: 'Hardware', k: ['que es la cpu', 'procesador', 'cpu', 'cerebro del computador', 'what is the cpu', 'processor'], r: ['La **CPU** es el cerebro del PC: ejecuta las instrucciones de los programas. Se mide en núcleos e hilos (procesadores lógicos) y en GHz. En el detector del laboratorio puedes ver cuántos hilos tiene tu equipo.', 'The **CPU** is the brain of the PC: it runs program instructions. It is measured in cores and threads (logical processors) and in GHz. In the lab detector you can see how many threads your machine has.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['que es la ram', 'memoria ram', 'ram', 'para que sirve la ram', 'what is ram'], r: ['La **RAM** es la memoria de trabajo: guarda lo que el PC está usando ahora mismo y se borra al apagar. Más RAM = más programas abiertos sin que el equipo se ponga lento.', '**RAM** is the working memory: it holds what the PC is using right now and it clears when you shut down. More RAM = more open programs without slowdowns.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['tarjeta grafica', 'gpu', 'tarjeta de video', 'graphics card'], r: ['La **GPU** (tarjeta gráfica) dibuja todo lo que ves: pantalla, videos y juegos. Puede venir integrada en el procesador o ser una tarjeta dedicada con su propia memoria.', 'The **GPU** (graphics card) draws everything you see: screen, videos and games. It can be integrated into the processor or be a dedicated card with its own memory.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['placa madre', 'motherboard', 'mainboard', 'tarjeta madre'], r: ['La **placa madre** es la tarjeta principal donde se conecta TODO: procesador, RAM, almacenamiento y tarjetas. Es como el sistema nervioso del PC.', 'The **motherboard** is the main board where EVERYTHING connects: processor, RAM, storage and cards. It is like the nervous system of the PC.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['ssd', 'hdd', 'disco duro', 'almacenamiento', 'nvme', 'storage', 'hard drive'], r: ['El **almacenamiento** guarda tus archivos de forma permanente. El **SSD** (y su versión rápida NVMe) no tiene partes móviles y es mucho más veloz que el viejo disco duro **HDD**.', '**Storage** keeps your files permanently. The **SSD** (and its fast NVMe version) has no moving parts and is much faster than the old **HDD** hard drive.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['tarjeta de red', 'nic', 'tarjeta ethernet', 'network card'], r: ['La **NIC** es la tarjeta de red: el puente físico y lógico entre el PC y el cable (o la antena WiFi). Cada NIC tiene su dirección **MAC** única.', 'The **NIC** is the network card: the physical and logical bridge between the PC and the cable (or the WiFi antenna). Every NIC has its own unique **MAC** address.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['fuente de poder', 'psu', 'fuente de alimentacion', 'power supply'], r: ['La **fuente de poder (PSU)** convierte la corriente del enchufe en la energía que cada pieza necesita. Si es de mala calidad o queda corta de vatios, el PC se apaga o falla.', 'The **power supply (PSU)** turns wall power into the energy each part needs. A weak or low-quality one makes the PC shut down or fail.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['refrigeracion', 'refrigeracion liquida', 'cooler', 'ventilador', 'se calienta', 'cooling', 'overheating'], r: ['La **refrigeración** saca el calor del procesador: por aire (ventilador) o **líquida AIO** (bloque, mangueras y radiador). Sin ella, el PC baja su rendimiento para no quemarse.', '**Cooling** removes heat from the processor: by air (fan) or **liquid AIO** (block, tubes and radiator). Without it, the PC slows itself down to avoid burning up.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['unidad optica', 'lector de cd', 'dvd', 'bluray', 'optical drive'], r: ['La **unidad de disco óptico (ODD)** lee y graba CD, DVD y Blu-ray con un láser. Hoy es poco común porque casi todo llega por internet o USB.', 'The **optical disc drive (ODD)** reads and burns CDs, DVDs and Blu-ray with a laser. It is rare today because almost everything arrives over the internet or USB.'], href: 'hardware.html#componentes' },
    { c: 'Recursos', k: ['eniac', 'historia del computador', 'primer computador', 'pioneros', 'history of computers'], r: ['El **ENIAC** (1945) fue uno de los primeros computadores electrónicos: ocupaba una habitación y trabajaba con tubos de vacío. En la sección de historia ves la evolución hasta el PC actual.', 'The **ENIAC** (1945) was one of the first electronic computers: it filled a room and ran on vacuum tubes. In the history section you can see the evolution up to today\u2019s PC.'], href: 'hardware.html#historia' },
    { c: 'Redes', k: ['tipos de red', 'pan lan wan', 'clasificacion de redes', 'alcance de redes', 'que es una lan', 'que es una wan', 'network types', 'network scopes'], r: ['Las redes se clasifican por **alcance**: **PAN** (personal, unos metros), **LAN** (local, una casa u oficina), **MAN** (una ciudad) y **WAN** (países; internet es la WAN más grande). También están BAN, WLAN, CAN y GAN.', 'Networks are classified by **scope**: **PAN** (personal, a few meters), **LAN** (local, a home or office), **MAN** (a city) and **WAN** (countries; the internet is the biggest WAN). There are also BAN, WLAN, CAN and GAN.'], href: 'redes.html#alcance-redes' },
    { c: 'Redes', k: ['topologias', 'topologia estrella', 'bus', 'anillo', 'malla', 'topologies', 'star topology'], r: ['La **topología** es la forma en que se conectan los equipos: **estrella** (todos a un switch central, la más usada), **bus** (un solo cable), **anillo** (un círculo) y **malla** (todos con todos, muy resistente).', 'A **topology** is the shape of the connections: **star** (everyone to a central switch, the most common), **bus** (one single cable), **ring** (a circle) and **mesh** (everyone to everyone, very resilient).'], href: 'redes.html#topologias' },
    { c: 'Redes', k: ['como funciona un switch', 'switch', 'tabla mac', 'flooding', 'como aprende el switch', 'conmutador', 'how does a switch work'], r: ['El **switch** aprende en qué puerto está la MAC de cada equipo y anota eso en su **tabla MAC**. Cuando llega una trama, la reenvía **solo por el puerto correcto**. Si aún no conoce el destino, la envía por todos los puertos (**flooding**) y aprende con la respuesta. ¡Pruébalo en el laboratorio del switch!', 'The **switch** learns which port each MAC address lives on and writes it in its **MAC table**. When a frame arrives, it forwards it **only through the right port**. If it does not know the destination yet, it sends it through all ports (**flooding**) and learns from the reply. Try it in the switch lab!'], href: 'redes.html#switch-3d' },
    { c: 'Redes', k: ['hub', 'diferencia hub switch', 'hub vs switch', 'concentrador'], r: ['El **hub** es el antepasado tonto del switch: **no aprende nada** y repite cada trama por **todos** los puertos, siempre. El switch, en cambio, aprende las MAC y entrega cada trama solo a su destino: menos tráfico y más privacidad.', 'The **hub** is the switch\u2019s dumb ancestor: it **learns nothing** and repeats every frame through **all** ports, always. The switch instead learns MAC addresses and delivers each frame only to its destination: less traffic and more privacy.'], href: 'redes.html#switch-3d' },
    { c: 'Redes', k: ['simulador ping', 'ping', 'icmp', 'como hacer ping', 'ping simulator'], r: ['El **ping** envía paquetes **ICMP** a otro equipo y mide si responde y cuánto tarda: es la primera prueba para saber si hay conexión. En el simulador de Redes ves el paquete viajar paso a paso.', '**Ping** sends **ICMP** packets to another device and measures whether it answers and how long it takes: it is the first test to check a connection. In the Networks simulator you watch the packet travel step by step.'], href: 'redes.html#simulador-red' },
    { c: 'Recursos', k: ['ver mi ip', 'mi mac', 'ipconfig', 'como saber mi ip', 'direccion fisica', 'my ip address', 'my mac'], r: ['Con el código **ipconfig /all** en PowerShell ves la **IP** de tu equipo y su **dirección física (MAC)**. Está en el Laboratorio de Códigos, con botón para copiarlo.', 'With the code **ipconfig /all** in PowerShell you see your computer\u2019s **IP** and its **physical address (MAC)**. It lives in the Code Lab, with a copy button.'], href: 'recursos.html#laboratorio' },
    { c: 'Recursos', k: ['quien esta en mi red', 'arp', 'dispositivos de mi red', 'who is on my network'], r: ['El código **arp -a** lista los dispositivos que tu equipo conoce en la red local, con su IP y su MAC. Está en el Laboratorio de Códigos.', 'The code **arp -a** lists the devices your computer knows on the local network, with their IP and MAC. It lives in the Code Lab.'], href: 'recursos.html#laboratorio' },
    { c: 'Recursos', k: ['renovar ip', 'ipconfig renew', 'internet se puso raro', 'sin internet', 'renew ip', 'no internet'], r: ['Si el internet se pone raro, el código **ipconfig /release** + **ipconfig /renew** suelta tu IP y pide una nueva al router. Es el arreglo clásico; está en el Laboratorio de Códigos (PowerShell como administrador).', 'If the internet acts weird, the code **ipconfig /release** + **ipconfig /renew** drops your IP and asks the router for a new one. The classic fix; it lives in the Code Lab (PowerShell as administrator).'], href: 'recursos.html#laboratorio' },
    { c: 'Recursos', k: ['detectar mi equipo', 'datos de mi pc', 'especificaciones de mi pc', 'detect my device', 'my specs'], r: ['En el Laboratorio hay una tarjeta **«Detecta mi equipo»**: sin instalar nada muestra lo que el navegador puede ver: sistema, navegador, procesadores lógicos, RAM aproximada, gráfica, pantalla y batería. Son 7 datos; el modelo exacto del procesador solo sale con el código de PowerShell.', 'In the Lab there is a **"Detect my device"** card: with no installs it shows what the browser can see: system, browser, logical processors, approximate RAM, graphics, screen and battery. That is 7 items; the exact processor model only comes from the PowerShell code.'], href: 'recursos.html#laboratorio' },
    { c: 'Recursos', k: ['que es throughput', 'throughput', 'rendimiento de red'], r: ['**Throughput**: volumen real de datos que sí logran pasar entre dos puntos en un tiempo dado. Es lo que de verdad recibes, no lo que promete el papel.', '**Throughput**: the real volume of data that actually gets through between two points in a given time. It is what you truly receive, not what the paper promises.'], href: 'recursos.html#glosario' },
    { c: 'Recursos', k: ['que es bandwidth', 'bandwidth', 'ancho de banda', 'what is bandwidth'], r: ['**Bandwidth** (ancho de banda): capacidad máxima teórica de un canal, en bps. Una cosa es el ancho de la tubería y otra el agua que de verdad pasa (**throughput**).', '**Bandwidth**: the maximum theoretical capacity of a channel, in bps. One thing is the width of the pipe and another the water that actually flows (**throughput**).'], href: 'recursos.html#glosario' },
    { c: 'Recursos', k: ['que es un paquete', 'packet', 'paquete de datos', 'what is a packet'], r: ['Un **paquete** es la unidad de datos que viaja por la red: lleva encabezados con origen y destino, y la carga útil (tus datos). Todo en internet viaja en paquetes.', 'A **packet** is the unit of data that travels the network: it carries headers with source and destination, plus the payload (your data). Everything on the internet travels in packets.'], href: 'recursos.html#glosario' },
    { c: 'Hardware', k: ['limpiar mi pc', 'mantenimiento', 'polvo', 'pasta termica', 'cada cuanto limpiar', 'clean my pc', 'maintenance'], r: ['El **mantenimiento** básico: soplar el polvo con **aire comprimido**, trabajar con **manilla antiestática** y cambiar la **pasta térmica** de vez en cuando. En PC3D tienes la guía con las herramientas y sus fotos.', 'Basic **maintenance**: blow dust out with **compressed air**, work with an **anti-static wrist strap** and replace the **thermal paste** from time to time. In PC3D you have the guide with the tools and their photos.'], href: 'pc3d.html#mantenimiento' },
    { c: 'Hardware', k: ['herramientas', 'manilla antiestatica', 'aire comprimido', 'destornillador', 'tools', 'anti static wrist strap'], r: ['Las **herramientas indispensables** del mantenimiento: destornillador de precisión, manilla antiestática, aire comprimido en lata, brocha suave y bridas para ordenar cables. Están en la sección de herramientas de PC3D.', 'The essential **maintenance tools**: precision screwdriver, anti-static wrist strap, canned compressed air, soft brush and cable ties. They are in the PC3D tools section.'], href: 'pc3d.html#mantenimiento' },
    { c: 'Hardware', k: ['explorador 3d', 'visor 3d', 'torre 3d', 'ver el pc por dentro', 'pc3d', '3d explorer'], r: ['El **explorador 3D** de PC3D te deja recorrer la torre por capas y reconocer cada pieza: placa, CPU, RAM, GPU, almacenamiento, fuente, red y hasta la unidad óptica.', 'The PC3D **3D explorer** lets you walk through the tower layer by layer and recognize each part: board, CPU, RAM, GPU, storage, PSU, networking and even the optical drive.'], href: 'pc3d.html#visor-3d' },
    { c: 'WiFi', k: ['instalar modem', 'configurar router', 'movistar', 'entrar al router', '192.168.1.1', 'install modem', 'router setup'], r: ['Para **instalar el módem/router**: conecta el cable del proveedor, enciende y espera las luces fijas; luego entra al panel en **192.168.1.1** con los datos de la etiqueta y cambia SSID, contraseña y seguridad WPA2/WPA3. La guía completa está en WiFi Avanzado.', 'To **install the modem/router**: plug the provider cable, power on and wait for solid lights; then open the panel at **192.168.1.1** with the label credentials and change SSID, password and WPA2/WPA3 security. The full guide is in Advanced WiFi.'], href: 'wifi.html#instalar-modem' },
    { c: 'WiFi', k: ['repetidor', 'extensor', 'no llega el wifi', 'ampliar cobertura', 'wps', 'repeater', 'wifi coverage'], r: ['Un **repetidor** recibe el WiFi y lo reemite: ponlo a **mitad de camino**, donde aún llegue buena señal. Se enlaza por **WPS** (botón en ambos equipos) o a mano desde su panel. Si lo pones donde no hay señal, no tiene nada que repetir.', 'A **repeater** picks up WiFi and rebroadcasts it: place it **halfway**, where signal is still good. Link it by **WPS** (button on both devices) or manually from its panel. If you place it where there is no signal, it has nothing to repeat.'], href: 'wifi.html#instalar-modem' },
    { c: 'WiFi', k: ['cambiar clave wifi', 'contraseña del router', 'seguridad wifi', 'wpa2 wpa3', 'change wifi password'], r: ['Cambia la clave del WiFi desde el panel del router (**192.168.1.1**): contraseña nueva de más de 12 caracteres y seguridad **WPA2 o WPA3**. Y nunca dejes el usuario admin de fábrica del panel.', 'Change the WiFi password from the router panel (**192.168.1.1**): a new password over 12 characters and **WPA2 or WPA3** security. And never keep the panel factory admin user.'], href: 'wifi.html#instalar-modem' },
    { c: 'WiFi', k: ['2.4 o 5 ghz', 'banda wifi', 'wifi lento', 'canal wifi', 'wifi slow', 'wifi band'], r: ['**2.4 GHz** llega más lejos y cruza paredes, pero es más lenta; **5 GHz** es mucho más rápida cerca del módem. Si el WiFi va lento en un edificio lleno de redes, cambia el canal (1, 6 u 11 en 2.4 GHz).', '**2.4 GHz** reaches farther and crosses walls, but it is slower; **5 GHz** is much faster near the modem. If WiFi is slow in a building full of networks, change the channel (1, 6 or 11 on 2.4 GHz).'], href: 'wifi.html#instalar-modem' },
    { c: 'Otro', k: ['por donde empiezo', 'ruta de aprendizaje', 'que ver primero', 'como usar el sitio', 'donde empiezo', 'learning path', 'where do i start'], r: ['Ruta sugerida: **1)** Historia y componentes en Hardware, **2)** el explorador 3D de PC3D, **3)** tipos de red y topologías en Redes, **4)** el laboratorio del switch y el simulador ping, **5)** los códigos y el glosario en Recursos, y **6)** la guía WiFi. En ese orden todo encaja.', 'Suggested path: **1)** History and components in Hardware, **2)** the PC3D 3D explorer, **3)** network types and topologies in Networks, **4)** the switch lab and the ping simulator, **5)** the codes and glossary in Resources, and **6)** the WiFi guide. In that order everything clicks.'] },
    { c: 'Otro', k: ['gracias', 'muchas gracias', 'te agradezco', 'thanks', 'thank you'], r: ['¡Con gusto! [[heart_green]] Si te queda otra duda del sitio, pregúntame; y si alguna vez no sé algo, puedes enseñármelo en la pestaña «Entrenar».', 'You are welcome! [[heart_green]] If you have another question about the site, ask me; and if I ever miss something, you can teach me in the "Train" tab.'] },
    { c: 'Otro', k: ['chao', 'adios', 'hasta luego', 'nos vemos', 'bye', 'see you'], r: ['¡Hasta pronto! [[wave]] Recuerda: el switch aprende solo si le envías tramas… y yo también aprendo si me enseñas.', 'See you soon! [[wave]] Remember: the switch only learns if you send it frames… and I learn too if you teach me.'] },
{ c: 'Hardware', k: ['diferencia entre ram y disco', 'ram vs ssd', 'ram o almacenamiento', 'memoria ram o disco duro', 'ram vs storage'], r: ['No es lo mismo: la **RAM** es el escritorio de trabajo (rápida, temporal, se vacía al apagar) y el **almacenamiento** es el archivador (permanente). Un PC necesita los dos: sin RAM no trabaja y sin disco no guarda nada.', '**RAM** is the work desk (fast, temporary, cleared at shutdown) and **storage** is the filing cabinet (permanent). A PC needs both: without RAM it cannot work and without a drive it cannot keep anything.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['que son los nucleos', 'nucleos e hilos', 'cuantos nucleos necesito', 'hilos del procesador', 'cores and threads', 'what are cores'], r: ['Cada **núcleo** es un cerebro independiente dentro de la CPU; los **hilos** (procesadores lógicos) son las tareas que cada núcleo puede turnarse. Más núcleos = más tareas a la vez: para estudiar y navegar bastan 4; para editar video o jugar ayudan 6-8.', 'Each **core** is an independent brain inside the CPU; **threads** (logical processors) are the tasks each core can juggle. More cores = more tasks at once: 4 is enough for study and browsing; 6-8 help for video editing or gaming.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['intel o amd', 'intel core o ryzen', 'que procesador es mejor', 'amd ryzen', 'intel vs amd', 'ryzen vs intel'], r: ['Las dos grandes marcas de CPU para PC son **Intel Core** y **AMD Ryzen** (y **ARM** domina en celulares). Ninguna gana siempre: se compite modelo contra modelo según precio y uso. En PC3D ves los tipos y qué mirar antes de elegir.', 'The two big PC CPU brands are **Intel Core** and **AMD Ryzen** (and **ARM** rules phones). Neither always wins: compare model against model by price and use. In PC3D you can see the types and what to check before choosing.'], href: 'pc3d.html#componentes-3d' },
    { c: 'Hardware', k: ['que es arm', 'arquitectura arm', 'x86 x64', 'arquitectura del procesador', 'what is arm'], r: ['**x86/x64** es la arquitectura clásica de los PC (Intel/AMD); **ARM** es la de celulares y tablets: gasta menos energía y hoy también vive en portátiles. El software debe estar hecho para la arquitectura de tu equipo.', '**x86/x64** is the classic PC architecture (Intel/AMD); **ARM** is the phone and tablet one: it uses less power and now lives in laptops too. Software must be built for your machine\u2019s architecture.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['ddr3 ddr4 ddr5', 'tipos de memoria ram', 'que ram usa mi pc', 'dimm sodimm', 'diferencia ddr4 ddr5', 'ram types'], r: ['La RAM viene en generaciones **DDR3, DDR4 y DDR5**: cada una es más rápida, pero **no son compatibles entre sí** (la ranura cambia). **DIMM** es el módulo de escritorio y **SO-DIMM** el de portátil.', 'RAM comes in **DDR3, DDR4 and DDR5** generations: each is faster, but they are **not compatible with each other** (the slot changes). **DIMM** is the desktop module and **SO-DIMM** the laptop one.'], href: 'pc3d.html#componentes-3d' },
    { c: 'Hardware', k: ['cuanta ram necesito', '8 o 16 gb', 'cuanta memoria ram', 'ram para estudiar', 'how much ram'], r: ['Guía rápida: **8 GB** para tareas básicas y estudiar, **16 GB** para jugar y multitarea cómoda, **32 GB** para edición de video, diseño 3D o máquinas virtuales. Si dudas entre 8 y 16, elige 16: es lo que más se nota en el día a día.', 'Quick guide: **8 GB** for basic tasks and study, **16 GB** for gaming and comfortable multitasking, **32 GB** for video editing, 3D design or virtual machines. If you doubt between 8 and 16, pick 16: it is what you notice most day to day.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['grafica integrada o dedicada', 'integrada vs dedicada', 'que es vram', 'cuanta vram', 'integrated vs dedicated gpu'], r: ['La GPU **integrada** vive dentro del procesador y comparte la RAM: sirve para estudiar, video y juegos ligeros. La **dedicada** es una tarjeta propia con su memoria **VRAM**: es la que necesitas para juegos exigentes, 3D e IA.', 'An **integrated** GPU lives inside the processor and shares RAM: fine for study, video and light games. A **dedicated** one is its own card with its own **VRAM** memory: what you need for demanding games, 3D and AI.'], href: 'pc3d.html#componentes-3d' },
    { c: 'Hardware', k: ['hdd ssd sata nvme', 'sata o nvme', 'que es m.2', 'tipos de almacenamiento', 'diferencia ssd hdd', 'ssd vs hdd'], r: ['**HDD**: disco mecánico, barato y lento. **SSD SATA**: rápido, formato clásico. **SSD NVMe (M.2)**: se conecta directo por PCIe y es el más veloz. Para revivir un PC viejo, cambiar el HDD por un SSD es la mejora número uno.', '**HDD**: mechanical drive, cheap and slow. **SATA SSD**: fast, classic format. **NVMe SSD (M.2)**: plugs straight into PCIe and is the fastest. To revive an old PC, swapping the HDD for an SSD is the number one upgrade.'], href: 'pc3d.html#componentes-3d' },
    { c: 'Hardware', k: ['certificacion 80 plus', 'fuente bronze gold', 'cuantos watts necesito', 'vatios de la fuente', '80 plus', 'psu wattage'], r: ['La certificación **80 Plus** (Bronze, Silver, Gold, Platinum, Titanium) dice qué tan eficiente es la fuente. En vatios: un PC básico vive con 400-500 W; uno con GPU dedicada pide 550-750 W según la tarjeta.', 'The **80 Plus** certification (Bronze, Silver, Gold, Platinum, Titanium) tells how efficient the PSU is. In watts: a basic PC lives on 400-500 W; one with a dedicated GPU asks for 550-750 W depending on the card.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['aire o liquida', 'disipador o aio', 'tipos de refrigeracion', 'custom loop', 'air vs liquid cooling'], r: ['Tres niveles: **disipador de aire** (simple y confiable), **líquida AIO** (bloque + radiador, silenciosa) y **custom loop** (circuito hecho a mano, para entusiastas). Para la mayoría, un buen disipador de aire basta.', 'Three levels: **air cooler** (simple and reliable), **liquid AIO** (block + radiator, quiet) and **custom loop** (hand-built circuit, for enthusiasts). For most people, a good air cooler is enough.'], href: 'pc3d.html#componentes-3d' },
    { c: 'Hardware', k: ['mi pc se apaga solo', 'se apaga jugando', 'el pc se reinicia solo', 'pc se apaga', 'computer shuts down'], r: ['Si el PC **se apaga solo**, sospecha en este orden: **temperatura** (polvo, pasta térmica seca), **fuente de poder** corta o fallando, y drivers. Empieza por la limpieza de PC3D y revisa que los ventiladores giren.', 'If the PC **shuts down by itself**, suspect in this order: **temperature** (dust, dry thermal paste), a weak or failing **power supply**, and drivers. Start with the PC3D cleaning and check that the fans spin.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['mi pc se congela', 'pantallazo azul', 'se traba el computador', 'pc se queda pegado', 'computer freezes'], r: ['Congelamientos y pantallazos suelen venir de **RAM** inestable, disco con errores o drivers. Revisa el estado **SMART** del almacenamiento, actualiza controladores desde fuentes oficiales y, si empezó tras instalar algo, desinstálalo.', 'Freezes and blue screens usually come from unstable **RAM**, a failing drive or drivers. Check the storage **SMART** status, update drivers from official sources and, if it started after installing something, uninstall it.'], href: 'pc3d.html#mantenimiento' },
    { c: 'Hardware', k: ['que es un computador', 'que es una computadora', 'que es un pc', 'what is a computer'], r: ['Un **computador** es una máquina que procesa datos: recibe información, la trabaja con programas y entrega resultados. Por dentro es la suma de sus componentes: placa madre, CPU, RAM, almacenamiento, fuente y conexión de red.', 'A **computer** is a machine that processes data: it takes information in, works on it with programs and delivers results. Inside, it is the sum of its parts: motherboard, CPU, RAM, storage, power supply and network connection.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['que es hardware', 'que es software', 'diferencia hardware software', 'what is hardware'], r: ['**Hardware** es lo físico (lo que puedes tocar: CPU, RAM, pantalla). **Software** son los programas (lo que no se toca: sistema operativo, apps). Uno sin el otro no sirve: el hardware ejecuta lo que el software ordena.', '**Hardware** is the physical part (what you can touch: CPU, RAM, screen). **Software** is the programs (what you cannot touch: operating system, apps). Neither works alone: hardware runs what software commands.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['perifericos', 'teclado mouse monitor', 'dispositivos de entrada y salida', 'peripherals'], r: ['Los **periféricos** conectan al PC con el mundo: de **entrada** (teclado, mouse, micrófono) y de **salida** (monitor, parlantes, impresora). Se enchufan por USB, Bluetooth o a la placa madre.', '**Peripherals** connect the PC to the world: **input** (keyboard, mouse, microphone) and **output** (monitor, speakers, printer). They plug in via USB, Bluetooth or the motherboard.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['que es la bios', 'bios uefi', 'firmware del pc', 'what is bios'], r: ['La **BIOS/UEFI** es el programa mínimo grabado en la placa madre que despierta el hardware al encender y le pasa el control al sistema operativo. Desde ahí también se ajusta el orden de arranque.', 'The **BIOS/UEFI** is the tiny program stored on the motherboard that wakes the hardware at power-on and hands control to the operating system. Boot order is also set there.'], href: 'hardware.html#componentes' },
    { c: 'Recursos', k: ['evolucion de los computadores', 'historia de la computacion', 'generaciones de computadores', 'history of computing'], r: ['La ruta: tubos de vacío (ENIAC) [[arrow_right]] transistores [[arrow_right]] circuitos integrados [[arrow_right]] microprocesador [[arrow_right]] el PC de hoy. Cada salto hizo los equipos más pequeños, baratos y potentes. La sección de Historia lo recorre con sus pioneros.', 'The path: vacuum tubes (ENIAC) [[arrow_right]] transistors [[arrow_right]] integrated circuits [[arrow_right]] microprocessor [[arrow_right]] today\u2019s PC. Each leap made machines smaller, cheaper and more powerful. The History section walks it with its pioneers.'], href: 'hardware.html#historia' },
    { c: 'Redes', k: ['que es una ban', 'red corporal', 'body area network', 'red de area corporal', 'sensores en el cuerpo'], r: ['Una **BAN** es la red más pequeña: menos de 1 metro alrededor del cuerpo. Conecta biosensores y wearables de salud: marcapasos inteligentes, monitores de glucosa o de ritmo cardíaco (estándar IEEE 802.15.6).', 'A **BAN** is the smallest network: under 1 meter around the body. It connects health biosensors and wearables: smart pacemakers, glucose or heart-rate monitors (IEEE 802.15.6 standard).'], href: 'redes.html#alcance-redes' },
    { c: 'Redes', k: ['que es una pan', 'red personal', 'personal area network', 'red de area personal'], r: ['Una **PAN** cubre de 1 a 10 metros alrededor de una persona: enlaza su celular, reloj y audífonos por **Bluetooth**, NFC o Zigbee, con muy bajo consumo.', 'A **PAN** covers 1 to 10 meters around a person: it links their phone, watch and earbuds over **Bluetooth**, NFC or Zigbee, with very low power use.'], href: 'redes.html#alcance-redes' },
    { c: 'Redes', k: ['que es wlan', 'lan o wlan', 'red local inalambrica', 'wireless lan'], r: ['**LAN** es la red local por cable y **WLAN** es la misma red local pero inalámbrica (Wi-Fi). Cubren una casa u oficina, hasta unos 100 m por segmento de cable.', '**LAN** is the wired local network and **WLAN** is the same local network but wireless (Wi-Fi). They cover a home or office, up to about 100 m per cable segment.'], href: 'redes.html#alcance-redes' },
    { c: 'Redes', k: ['que es una can', 'red de campus', 'campus area network', 'red universitaria'], r: ['Una **CAN** une los edificios de un campus (universidad, hospital, parque industrial) en un radio de 1 a 5 km, con troncales de fibra óptica de alta velocidad.', 'A **CAN** links the buildings of a campus (university, hospital, industrial park) within 1 to 5 km, with high-speed fiber-optic backbones.'], href: 'redes.html#alcance-redes' },
    { c: 'Redes', k: ['que es una man', 'red metropolitana', 'metropolitan area network', 'red de una ciudad'], r: ['Una **MAN** cubre una ciudad completa (hasta ~50 km) con anillos de fibra óptica: redes municipales, cámaras urbanas o TV por cable.', 'A **MAN** covers a whole city (up to ~50 km) with fiber-optic rings: municipal networks, city cameras or cable TV.'], href: 'redes.html#alcance-redes' },
    { c: 'Redes', k: ['que es una gan', 'red global', 'global area network', 'red planetaria', 'starlink que red es'], r: ['Una **GAN** es planetaria: une redes terrestres y espaciales sin fronteras. Ejemplos: constelaciones de satélites como **Starlink**, el GPS y los cables submarinos transoceánicos.', 'A **GAN** is planetary: it joins land and space networks without borders. Examples: satellite constellations like **Starlink**, GPS and transoceanic submarine cables.'], href: 'redes.html#alcance-redes' },
    { c: 'Redes', k: ['topologia anillo', 'red en anillo', 'token ring', 'ring topology', 'testigo token'], r: ['En la topología **anillo** cada equipo se conecta a dos vecinos formando un círculo y los datos viajan en un solo sentido pasando un **testigo (token)**: sin colisiones, pero si un equipo se desconecta, el ciclo se rompe.', 'In a **ring** topology each device connects to two neighbors forming a circle and data travels one way passing a **token**: no collisions, but if one device disconnects, the cycle breaks.'], href: 'redes.html#topologias' },
    { c: 'Redes', k: ['topologia malla', 'red en malla', 'mesh topology', 'wifi mesh', 'red mesh'], r: ['En la topología **malla** cada nodo se conecta con varios o todos los demás: hay muchas rutas y si un enlace cae, el tráfico se redirige al instante. Es la base del backbone de internet y de los Wi-Fi Mesh.', 'In a **mesh** topology each node connects to several or all others: there are many routes and if a link fails, traffic reroutes instantly. It is the basis of the internet backbone and of Wi-Fi Mesh systems.'], href: 'redes.html#topologias' },
    { c: 'Redes', k: ['topologia arbol', 'topologia hibrida', 'tree topology', 'red jerarquica'], r: ['La topología **árbol** organiza la red en niveles (núcleo, distribución y acceso) como varias estrellas unidas; la **híbrida** mezcla dos o más topologías según la zona. Son las de campus y grandes empresas.', 'The **tree** topology organizes the network in levels (core, distribution, access) like several joined stars; the **hybrid** mixes two or more topologies per area. They are the campus and big-company choices.'], href: 'redes.html#topologias' },
    { c: 'Redes', k: ['que es la mac', 'direccion mac', 'mac address', 'mac de 48 bits', 'what is a mac address'], r: ['La **dirección MAC** es el identificador físico único de cada tarjeta de red: **48 bits** grabados de fábrica en su memoria (ej. 00:1A:2B:3C:4D:01). Con ella trabaja el switch en la capa 2. La ves con el código ipconfig /all.', 'The **MAC address** is the unique physical ID of each network card: **48 bits** burned in at the factory (e.g. 00:1A:2B:3C:4D:01). The switch works with it at layer 2. You can see yours with the ipconfig /all code.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['que es una ip', 'direccion ip', 'ip address', 'que es la ip', 'what is an ip address'], r: ['La **dirección IP** es el número lógico que identifica a tu equipo dentro de una red (ej. 192.168.1.10 en casa). A diferencia de la MAC, la IP **cambia** según la red a la que te conectes; la asigna el router.', 'The **IP address** is the logical number that identifies your device on a network (e.g. 192.168.1.10 at home). Unlike the MAC, the IP **changes** with each network you join; the router assigns it.'] },
    { c: 'Redes', k: ['diferencia entre ip y mac', 'ip o mac', 'ip vs mac'], r: ['**MAC** = identidad física de la tarjeta de red, nunca cambia. **IP** = la dirección de donde estás conectado hoy, cambia por red. El switch usa la MAC (capa 2); el router usa la IP (capa 3).', '**MAC** = the network card\u2019s physical identity, it never changes. **IP** = the address of where you are connected today, it changes per network. The switch uses the MAC (layer 2); the router uses the IP (layer 3).'] },
    { c: 'Redes', k: ['que es un router', 'que es el gateway', 'puerta de enlace', 'router gateway', 'what is a router'], r: ['El **router** conecta tu red local con otras redes (internet) usando direcciones IP: es la **puerta de enlace (gateway)**, en casa suele ser 192.168.1.1. En el simulador ves cómo enruta entre la LAN y el servidor web.', 'The **router** connects your local network to other networks (the internet) using IP addresses: it is the **gateway**, at home usually 192.168.1.1. In the simulator you watch it route between the LAN and the web server.'], href: 'redes.html#simulador-red' },
    { c: 'Redes', k: ['diferencia switch y router', 'switch o router', 'switch vs router', 'capa 2 y capa 3'], r: ['**Switch**: mueve tramas dentro de tu red local usando MAC (capa 2). **Router**: mueve paquetes entre redes distintas usando IP (capa 3). En casa ambos viven dentro del mismo equipo del proveedor.', '**Switch**: moves frames inside your local network using MAC (layer 2). **Router**: moves packets between different networks using IP (layer 3). At home both live inside the same provider box.'], href: 'redes.html#simulador-red' },
    { c: 'Redes', k: ['trama o paquete', 'diferencia trama paquete', 'que es una trama', 'frame vs packet'], r: ['La **trama** es la unidad de la capa 2 (lleva MAC origen y destino) y el **paquete** la de la capa 3 (lleva IP origen y destino). El paquete viaja dentro de la trama cuando cruza tu red local.', 'The **frame** is the layer 2 unit (it carries source and destination MAC) and the **packet** is the layer 3 unit (source and destination IP). The packet travels inside the frame across your local network.'], href: 'redes.html#simulador-red' },
    { c: 'Redes', k: ['que es una vlan', 'vlan', 'red virtual', 'virtual lan'], r: ['Una **VLAN** divide un mismo switch en varias redes lógicas separadas, como si fueran switches distintos: orden y seguridad sin comprar más equipos. En el simulador la LAN trabaja en la VLAN 10.', 'A **VLAN** splits one switch into several separate logical networks, as if they were different switches: order and security without buying more gear. In the simulator the LAN runs on VLAN 10.'], href: 'redes.html#simulador-red' },
    { c: 'Redes', k: ['que es ethernet', 'puerto rj45', 'cable de red', 'cable ethernet', 'categorias de cable', 'cat6 cat5e'], r: ['**Ethernet** es la tecnología de red por cable: se conecta por puertos **RJ-45** con cable de par trenzado (categorías como Cat5e o Cat6). En la página de Redes ves el puerto y cómo la NIC lo enlaza por el bus PCIe.', '**Ethernet** is the wired networking technology: it connects through **RJ-45** ports with twisted-pair cable (categories like Cat5e or Cat6). On the Networks page you can see the port and how the NIC links it over the PCIe bus.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['que es internet', 'como funciona internet', 'la red de redes', 'what is the internet'], r: ['**Internet** es la WAN más grande del planeta: millones de redes (LAN, MAN, de proveedores) unidas por routers y protocolos comunes. Tu casa se conecta a ella a través de tu proveedor.', 'The **internet** is the biggest WAN on the planet: millions of networks (LANs, MANs, providers) joined by routers and common protocols. Your home connects to it through your provider.'], href: 'redes.html#alcance-redes' },
    { c: 'Redes', k: ['que es bluetooth', 'bluetooth', 'como funciona bluetooth'], r: ['**Bluetooth** es la tecnología inalámbrica de corto alcance (1-10 m) con la que se forma una PAN: audífonos, relojes y celulares se enlazan con muy bajo consumo (versión 5.3 en equipos recientes).', '**Bluetooth** is the short-range wireless technology (1-10 m) that forms a PAN: earbuds, watches and phones link with very low power use (version 5.3 on recent gear).'], href: 'redes.html#alcance-redes' },
    { c: 'Redes', k: ['como viajan los datos', 'flujo de datos en el host', 'de la ram al cable'], r: ['Dentro de tu equipo el viaje es: los datos salen de la **RAM**, la **CPU** los procesa y los entrega a la **NIC**, que los convierte en señales para el cable o el aire. Por eso la tarjeta de red también es hardware clave.', 'Inside your machine the trip is: data leaves the **RAM**, the **CPU** processes it and hands it to the **NIC**, which turns it into signals for the cable or the air. That is why the network card is key hardware too.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['como uso el simulador', 'simulador de redes', 'wireshark'], r: ['En el **simulador de Redes**: elige host de origen (PC1 o PC2) y destino (el servidor web o la otra PC), pulsa «Enviar Ping ICMP» y mira el monitor de tráfico: verás la trama (capa 2), el paquete (capa 3), el TTL y el RTT.', 'In the **Networks simulator**: pick a source host (PC1 or PC2) and a destination (the web server or the other PC), press "Send ICMP Ping" and watch the traffic monitor: you will see the frame (layer 2), the packet (layer 3), TTL and RTT.'], href: 'redes.html#simulador-red' },
    { c: 'Recursos', k: ['codigo de diagnostico', 'get-computerinfo', 'ver componentes con powershell', 'diagnostico de hardware codigo', 'modelo exacto de mi procesador'], r: ['El código **Get-ComputerInfo | Select-Object CsManufacturer, CsModel, CsProcessors, CsTotalPhysicalMemory** en PowerShell muestra fabricante, modelo, procesador exacto y RAM total de tu equipo. Es el diagnóstico completo que el detector del navegador no puede dar.', 'The code **Get-ComputerInfo | Select-Object CsManufacturer, CsModel, CsProcessors, CsTotalPhysicalMemory** in PowerShell shows your machine\u2019s maker, model, exact processor and total RAM. It is the full diagnosis the browser detector cannot give.'], href: 'recursos.html#laboratorio' },
    { c: 'Recursos', k: ['que es powershell', 'como abro powershell', 'como usar powershell', 'powershell'], r: ['**PowerShell** es la consola de códigos de Windows: allí pegas los códigos del Laboratorio. Ábrela desde el menú Inicio buscando «PowerShell»; para el código de renovar IP, ejecútala **como administrador** (clic derecho).', '**PowerShell** is the Windows code console: that is where you paste the Lab codes. Open it from the Start menu by searching "PowerShell"; for the renew-IP code, run it **as administrator** (right click).'], href: 'recursos.html#laboratorio' },
    { c: 'Recursos', k: ['codigo ping', 'ping 8.8.8.8', 'probar conexion con codigo', 'hay conexion codigo'], r: ['El código **ping 8.8.8.8** envía paquetes al servidor de Google: si responde, tu internet funciona; si todo se pierde, el problema está en tu red local. Está en el Laboratorio de Códigos, listo para copiar.', 'The code **ping 8.8.8.8** sends packets to Google\u2019s server: if it answers, your internet works; if everything is lost, the problem is in your local network. It lives in the Code Lab, ready to copy.'], href: 'recursos.html#laboratorio' },
    { c: 'Recursos', k: ['que es dns', 'dns', 'servidor dns', 'domain name system'], r: ['El **DNS** es la agenda telefónica de internet: traduce nombres como nvision.social a la dirección IP del servidor. Si el DNS falla, parece que «no hay internet» aunque la conexión esté perfecta.', '**DNS** is the internet\u2019s phone book: it translates names like nvision.social into the server\u2019s IP address. If DNS fails, it looks like "no internet" even when the connection is perfect.'] },
    { c: 'Recursos', k: ['que es la latencia', 'latencia', 'lag', 'ping alto'], r: ['La **latencia** es el tiempo que tarda un dato en ir y volver (el ping, en milisegundos). Para jugar y videollamadas importa más que la velocidad bruta: menos de 50 ms va sobrado; más de 150 ms se siente como «lag».', '**Latency** is how long data takes to go and come back (the ping, in milliseconds). For gaming and video calls it matters more than raw speed: under 50 ms is plenty; over 150 ms feels like "lag".'] },
    { c: 'Recursos', k: ['que es un protocolo', 'protocolos de red', 'network protocol'], r: ['Un **protocolo** es el acuerdo de cómo se comunican los equipos: idioma, formato y turnos. Ejemplos: **ICMP** (el del ping), **HTTP** (web) y la familia TCP/IP que mueve internet.', 'A **protocol** is the agreement on how devices communicate: language, format and turns. Examples: **ICMP** (the ping one), **HTTP** (web) and the TCP/IP family that moves the internet.'] },
    { c: 'Recursos', k: ['que es un servidor', 'que es un host', 'servidor web', 'server host'], r: ['Un **host** es cualquier equipo conectado a la red. Un **servidor** es un host que ofrece servicios a otros: el del simulador, por ejemplo, es un servidor web (10.0.0.80) que responde por HTTP y DNS.', 'A **host** is any device connected to the network. A **server** is a host that offers services to others: the one in the simulator, for example, is a web server (10.0.0.80) answering over HTTP and DNS.'] },
    { c: 'Recursos', k: ['por que el detector no muestra mi procesador', 'detector no sale grafica', 'grafica oculta brave', 'limitaciones del detector'], r: ['El detector solo ve lo que el navegador permite: por privacidad, navegadores como **Brave** ocultan la gráfica real, y ningún navegador revela el modelo exacto del procesador. Para eso está el código de PowerShell del propio laboratorio.', 'The detector only sees what the browser allows: for privacy, browsers like **Brave** hide the real graphics card, and no browser reveals the exact processor model. That is what the lab\u2019s own PowerShell code is for.'], href: 'recursos.html#laboratorio' },
    { c: 'Recursos', k: ['como copio un codigo', 'boton copiar codigo', 'como uso el laboratorio'], r: ['En cada tarjeta del Laboratorio pulsa **«Copiar»**, abre PowerShell en tu equipo, pega con clic derecho o Ctrl+V y presiona Enter. Los códigos son de consulta: muestran información sin cambiar nada (salvo Renovar IP, que pide una IP nueva).', 'On each Lab card press **"Copy"**, open PowerShell on your computer, paste with right click or Ctrl+V and press Enter. The codes are read-only: they show information without changing anything (except Renew IP, which asks for a new IP).'], href: 'recursos.html#laboratorio' },
    { c: 'Recursos', k: ['diferencia throughput bandwidth', 'throughput vs bandwidth', 'throughput o bandwidth'], r: ['**Bandwidth** es el máximo teórico del canal; **throughput** es lo que de verdad logra pasar. Analogía: el bandwidth es el ancho de la tubería y el throughput, el agua que realmente sale por el grifo.', '**Bandwidth** is the channel\u2019s theoretical maximum; **throughput** is what actually gets through. Analogy: bandwidth is the width of the pipe and throughput is the water that really comes out of the tap.'], href: 'recursos.html#glosario' },
    { c: 'Hardware', k: ['limpieza exterior', 'limpiar por fuera', 'limpiar filtros del pc', 'polvo por fuera'], r: ['Limpieza **exterior**: equipo apagado y desconectado, mantén el botón de encendido unos segundos para descargar, sopla filtros, rejillas y ventiladores con aire comprimido en ráfagas cortas y pasa un paño de microfibra apenas húmedo. Nunca rocíes líquido directo.', '**External** cleaning: PC off and unplugged, hold the power button a few seconds to discharge, blow filters, grilles and fans with short bursts of compressed air and wipe with a barely damp microfiber cloth. Never spray liquid directly.'], href: 'pc3d.html#mantenimiento' },
    { c: 'Hardware', k: ['limpieza interior', 'limpieza profunda', 'abrir la torre', 'polvo dentro del pc', 'capacitores hinchados'], r: ['Limpieza **interior**: abre el panel lateral, **sujeta los ventiladores** para que el aire no los haga girar, retira el polvo de disipadores, GPU y fuente de adentro hacia afuera, y revisa cables flojos, capacitores hinchados o corrosión.', '**Internal** cleaning: open the side panel, **hold the fans** so the air does not spin them, remove dust from heatsinks, GPU and PSU from the inside out, and check for loose cables, swollen capacitors or corrosion.'], href: 'pc3d.html#mantenimiento' },
    { c: 'Hardware', k: ['electricidad estatica', 'descarga estatica', 'por que usar manilla', 'esd'], r: ['Tu cuerpo acumula **electricidad estática** y una descarga invisible puede quemar RAM, CPU o placa. Por eso se trabaja desconectado y con **manilla antiestática**: ella descarga tu cuerpo antes de que toques los circuitos.', 'Your body builds up **static electricity** and an invisible discharge can fry RAM, CPU or board. That is why you work unplugged and with an **anti-static wrist strap**: it discharges your body before you touch the circuits.'], href: 'pc3d.html#mantenimiento' },
    { c: 'Hardware', k: ['destornillador de precision', 'destornilladores', 'torx', 'herramienta para tornillos'], r: ['Los **destornilladores de precisión** (Phillips, plano y Torx) retiran tapas, discos, ventiladores y tornillos de la placa sin dañarlos. Son la herramienta base de todo el kit de PC3D.', '**Precision screwdrivers** (Phillips, flat and Torx) remove covers, drives, fans and board screws without damaging them. They are the base tool of the whole PC3D kit.'], href: 'pc3d.html#mantenimiento' },
    { c: 'Hardware', k: ['brocha antiestatica', 'pano de microfibra', 'bridas y velcro', 'ordenar los cables'], r: ['La **brocha antiestática** afloja el polvo de ranuras sin rayar, el **paño de microfibra** limpia gabinete y vidrio sin pelusas, y las **bridas y el velcro** ordenan el cableado para no bloquear el flujo de aire.', 'The **anti-static brush** loosens dust from slots without scratching, the **microfiber cloth** cleans case and glass lint-free, and **ties and velcro** tidy the cabling so airflow is not blocked.'], href: 'pc3d.html#mantenimiento' },
    { c: 'Hardware', k: ['como usar aire comprimido', 'aire comprimido ventiladores', 'soplar el pc'], r: ['Con el **aire comprimido**: ráfagas cortas, lata en vertical y **sujetando los ventiladores** con un dedo para que no giren libremente (girar forzados puede dañarlos). Es la forma segura de sacar el polvo de disipadores y filtros.', 'With **compressed air**: short bursts, can upright and **holding the fans** with a finger so they do not spin freely (forced spinning can damage them). It is the safe way to clear dust from heatsinks and filters.'], href: 'pc3d.html#mantenimiento' },
    { c: 'Hardware', k: ['mi pc esta lento', 'computador lento', 'pc lento que hago', 'equipo lento', 'slow computer'], r: ['PC lento: revisa en orden — **1)** espacio libre del SSD, **2)** programas que no usas, **3)** polvo y temperaturas (limpieza de PC3D), **4)** si aún usa HDD, un **SSD** lo revive, y **5)** más **RAM** si abres muchas cosas a la vez.', 'Slow PC: check in order — **1)** free SSD space, **2)** programs you do not use, **3)** dust and temperatures (PC3D cleaning), **4)** if it still has an HDD, an **SSD** revives it, and **5)** more **RAM** if you open many things at once.'], href: 'pc3d.html#mantenimiento' },
    { c: 'WiFi', k: ['192.168.1.1 no abre', 'no abre el panel del router', 'no entra a 192', 'pagina del router no carga', '192.168.0.1'], r: ['Si **192.168.1.1 no abre**: confirma que estás conectado a ESE módem (por cable o a su WiFi), prueba también **192.168.0.1**, y en el celular **desactiva los datos móviles** mientras configuras, porque el teléfono puede estarse yendo por la red móvil y nunca toca el panel.', 'If **192.168.1.1 does not open**: make sure you are connected to THAT modem (cable or its WiFi), also try **192.168.0.1**, and on your phone **turn off mobile data** while setting up, because the phone may be escaping through the mobile network and never reaching the panel.'], href: 'wifi.html#instalar-modem' },
    { c: 'WiFi', k: ['wps es seguro', 'wps pin', 'desactivar wps', 'seguridad wps'], r: ['El **botón físico WPS** es práctico para enlazar el repetidor, pero el **WPS por código PIN es vulnerable**: si tu panel lo permite, desactiva el WPS por PIN y deja solo el botón.', 'The physical **WPS button** is handy for linking the repeater, but **WPS by PIN code is vulnerable**: if your panel allows it, disable PIN WPS and keep only the button.'], href: 'wifi.html#instalar-modem' },
    { c: 'WiFi', k: ['donde pongo el modem', 'poner el modem', 'colocar el modem', 'ubicacion del modem', 'modem en el piso', 'mejorar senal wifi', 'donde ubicar el router'], r: ['Ubicación que sí funciona: punto **central y elevado**, nunca en el piso ni dentro de un mueble cerrado; lejos de microondas, bases de teléfono inalámbrico y metal grande. Un muro grueso o una pecera en el camino debilitan la señal: a veces moverlo un metro lo arregla todo.', 'A placement that works: **central and high**, never on the floor or inside a closed cabinet; away from microwaves, cordless phone bases and big metal objects. A thick wall or a fish tank in the way weakens the signal: sometimes moving it one meter fixes everything.'], href: 'wifi.html#instalar-modem' },
    { c: 'WiFi', k: ['que es ssid', 'nombre de la red wifi', 'cambiar el nombre del wifi', 'ssid'], r: ['El **SSID** es el nombre de tu red WiFi, el que ves en la lista al conectarte. Al instalar, cámbialo por uno reconocible pero **sin datos personales** (nada de apellidos ni direcciones).', 'The **SSID** is your WiFi network\u2019s name, the one you see in the list when connecting. When installing, change it to something recognizable but with **no personal data** (no surnames or addresses).'], href: 'wifi.html#instalar-modem' },
    { c: 'WiFi', k: ['actualizar firmware modem', 'firmware del router', 'actualizar el modem'], r: ['El **firmware** es el sistema interno del módem: mantenerlo **actualizado** cierra huecos de seguridad y arregla fallos. Se actualiza desde el propio panel (192.168.1.1); es uno de los puntos de la lista de verificación final de la guía.', 'The **firmware** is the modem\u2019s internal system: keeping it **updated** closes security holes and fixes bugs. Update it from the panel itself (192.168.1.1); it is one of the items on the guide\u2019s final checklist.'], href: 'wifi.html#instalar-modem' },
    { c: 'WiFi', k: ['red de invitados', 'wifi para visitas', 'guest network', 'red para invitados'], r: ['La **red de invitados** es un WiFi aparte para las visitas: navegan sin entrar a tu red principal ni ver tus equipos. Actívala en el panel; es parte de la lista de verificación final de la guía WiFi.', 'The **guest network** is a separate WiFi for visitors: they browse without entering your main network or seeing your devices. Enable it in the panel; it is part of the WiFi guide\u2019s final checklist.'], href: 'wifi.html#instalar-modem' },
    { c: 'WiFi', k: ['lista de verificacion', 'checklist wifi', 'que revisar al instalar wifi', 'verificacion final wifi'], r: ['La **lista final** de la guía: luces fijas, SSID cambiado y clave nueva guardada, seguridad WPA2/WPA3, firmware actualizado, red de invitados activa, señal probada en todos los cuartos, repetidor donde aún hay buena señal y foto de la etiqueta del módem en el celular.', 'The guide\u2019s **final checklist**: solid lights, SSID changed and new password saved, WPA2/WPA3 security, firmware updated, guest network on, signal tested in every room, repeater where signal is still good and a photo of the modem label on your phone.'], href: 'wifi.html#instalar-modem' },
    { c: 'WiFi', k: ['luces del modem', 'luz roja del modem', 'luces fijas', 'que significan las luces'], r: ['Al instalar, espera unos 2 minutos: las luces de **encendido e internet deben quedar fijas**. Si la de internet parpadea sin parar o está roja, el problema viene del cable del proveedor o de la línea, no de tu configuración.', 'When installing, wait about 2 minutes: the **power and internet lights should stay solid**. If the internet one blinks forever or is red, the problem comes from the provider cable or the line, not from your settings.'], href: 'wifi.html#instalar-modem' },
    { c: 'WiFi', k: ['diferencia modem y router', 'modem o router', 'modem vs router', 'que es un modem'], r: ['El **módem** traduce la señal del proveedor (fibra, coaxial, DSL) a red; el **router** reparte esa conexión entre tus equipos y crea tu red local. En casa el proveedor suele dar un solo equipo que hace las dos cosas.', 'The **modem** translates the provider signal (fiber, coax, DSL) into a network; the **router** shares that connection among your devices and creates your local network. At home the provider usually gives one box that does both.'] },
    { c: 'WiFi', k: ['que es la ont', 'fibra optica', 'cable coaxial', 'como llega el internet a casa'], r: ['La señal llega según tu servicio: **fibra óptica** (con su ONT), **cable coaxial** o **DSL** por la línea telefónica. Ese cable va al puerto de entrada del módem: es el paso 1 de la guía de instalación.', 'The signal arrives depending on your service: **fiber optic** (with its ONT), **coaxial cable** or **DSL** over the phone line. That cable goes into the modem\u2019s input port: it is step 1 of the installation guide.'], href: 'wifi.html#instalar-modem' },
    { c: 'WiFi', k: ['interferencias wifi', 'el microondas afecta el wifi', 'muchas redes vecinas', 'wifi se corta'], r: ['Enemigos de la señal: **microondas**, bases de teléfonos inalámbricos, metal grande, muros gruesos y las redes de los vecinos. En 2.4 GHz cambia al canal **1, 6 u 11** (los que no se pisan) y ubica el módem en alto y al centro.', 'Signal enemies: **microwaves**, cordless phone bases, big metal, thick walls and the neighbors\u2019 networks. On 2.4 GHz switch to channel **1, 6 or 11** (the non-overlapping ones) and place the modem high and central.'], href: 'wifi.html#instalar-modem' },
    { c: 'WiFi', k: ['que es el wifi', 'que es wifi', 'wifi', 'wi-fi'], r: ['**WiFi** es la forma inalámbrica de conectar tus equipos a la red local (una WLAN): en vez de cable, viaja por radio en las bandas de 2.4 y 5 GHz. La guía WiFi Avanzado te lleva de la caja a una red rápida y segura.', '**WiFi** is the wireless way to connect your devices to the local network (a WLAN): instead of a cable, it travels by radio on the 2.4 and 5 GHz bands. The Advanced WiFi guide takes you from the box to a fast, secure network.'], href: 'wifi.html' },
    { c: 'Otro', k: ['que es nvision', 'de que trata este sitio', 'de que es esta pagina', 'about nvision', 'what is nvision'], r: ['**NVISION** es un sitio para aprender tecnología haciendo: hardware y componentes, redes con laboratorios interactivos (switch y ping), códigos reales para tu PC y una guía WiFi paso a paso. Todo con ejemplos que puedes tocar.', '**NVISION** is a site to learn technology by doing: hardware and components, networks with interactive labs (switch and ping), real codes for your PC and a step-by-step WiFi guide. Everything with examples you can touch.'] },
    { c: 'Otro', k: ['modo oscuro', 'cambiar el tema', 'tema oscuro', 'dark mode'], r: ['El sitio tiene **botón de tema** en la barra superior (el ícono de sol/luna): púlsalo para alternar entre modo claro y oscuro. Tu elección se guarda para la próxima visita.', 'The site has a **theme button** in the top bar (the sun/moon icon): tap it to switch between light and dark mode. Your choice is saved for your next visit.'] },
    { c: 'Otro', k: ['cambiar idioma', 'poner en ingles', 'poner en espanol', 'change language', 'idioma del sitio'], r: ['Arriba, junto al botón **ES**, está el selector de idioma: cambia todo el sitio entre **español e inglés** al instante.', 'At the top, next to the **ES** button, is the language selector: it switches the whole site between **Spanish and English** instantly.'] },
    { c: 'Otro', k: ['que secciones tiene', 'que paginas hay', 'contenido del sitio', 'que puedo aprender', 'temas del sitio'], r: ['El sitio tiene 6 zonas: **Hardware** (historia y componentes), **PC3D** (explorador 3D, tipos y mantenimiento), **Redes** (tipos, topologías, simulador ping y laboratorio del switch), **Recursos** (glosario y Laboratorio de Códigos), **WiFi Avanzado** (instalación y repetidores) y **Mantenimiento por software** (actualizaciones, antivirus, limpieza, copias y rutina).', 'The site has 6 areas: **Hardware** (history and components), **PC3D** (3D explorer, types and maintenance), **Networks** (types, topologies, ping simulator and switch lab), **Resources** (glossary and Code Lab), **Advanced WiFi** (installation and repeaters) and **Software Maintenance** (updates, antivirus, cleaning, backups and routine).'] },
    { c: 'Otro', k: ['quien hizo el sitio', 'quien creo nvision', 'autor del sitio', 'creador de nvision'], r: ['NVISION es un **proyecto educativo** hecho para aprender y enseñar tecnología con práctica real. Más que el autor, importa el recorrido: cada página tiene algo para probar, no solo para leer.', 'NVISION is an **educational project** made to learn and teach technology with real practice. More than the author, what matters is the journey: every page has something to try, not just to read.'] },
    { c: 'Otro', k: ['no tengo internet que hago', 'se cayo el internet', 'wifi no funciona', 'sin wifi en casa'], r: ['Sin internet, en orden: **1)** mira las luces del módem (deben estar fijas), **2)** reinícialo y espera 2 minutos, **3)** prueba el código **ping 8.8.8.8** del Laboratorio para saber si el fallo es local, y **4)** renueva tu IP con ipconfig /release y /renew.', 'No internet, in order: **1)** check the modem lights (they should be solid), **2)** restart it and wait 2 minutes, **3)** try the Lab\u2019s **ping 8.8.8.8** code to learn if the fault is local, and **4)** renew your IP with ipconfig /release and /renew.'], href: 'wifi.html#instalar-modem' },
    { c: 'Otro', k: ['que computador compro', 'recomiendas un pc', 'que pc me conviene', 'comprar computador'], r: ['No vendo equipos, pero el sitio te enseña a elegir: en **PC3D** ves qué hace cada componente y sus tipos, y en **Hardware** los comparas. Con eso podrás juzgar cualquier oferta tú mismo: CPU, RAM, SSD y fuente primero.', 'I do not sell computers, but the site teaches you to choose: in **PC3D** you see what each component does and its types, and in **Hardware** you compare them. With that you can judge any deal yourself: CPU, RAM, SSD and PSU first.'], href: 'pc3d.html#componentes-3d' },
    { c: 'Hardware', k: ['que es la vram', 'vram gpu', 'memoria de video'], r: ['La **VRAM** es la memoria de la tarjeta gráfica: ahí se guardan texturas, modelos y el framebuffer de la pantalla. Más VRAM permite resoluciones y juegos más exigentes; para 1080p suele bastar con 8 GB.', '**VRAM** is the graphics card memory: textures, models and the screen framebuffer live there. More VRAM handles higher resolutions and heavier games; for 1080p, 8 GB is usually enough.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['que es el bios', 'bios y uefi', 'entrar al bios'], r: ['El **BIOS/UEFI** es el firmware que arranca tu PC antes del sistema operativo: detecta el hardware y carga Windows o Linux. Desde él controlas orden de arranque, XMP de la RAM y overclock; se entra con Supr o F2 al encender.', '**BIOS/UEFI** is the firmware that starts your PC before the operating system: it detects hardware and loads Windows or Linux. From it you control boot order, RAM XMP and overclock; press Del or F2 while powering on.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['que son los drivers', 'drivers que son', 'controladores de dispositivo'], r: ['Los **drivers** (controladores) son programas que le enseñan al sistema operativo a usar cada componente: GPU, sonido, red, impresora. Sin el driver correcto, el hardware funciona mal o no funciona; instálalos siempre del sitio oficial del fabricante.', '**Drivers** are programs that teach the operating system to use each component: GPU, sound, network, printer. With the wrong driver, hardware misbehaves or fails; always install them from the manufacturer\u2019s official site.'], href: 'mantenimiento-software.html#tareas' },
    { c: 'Hardware', k: ['que es pcie', 'ranura pcie', 'pcie x16'], r: ['**PCIe** es el bus de expansión de la placa base: ahí van GPU, tarjetas de red y capturadoras. Se mide por generaciones (3.0, 4.0, 5.0, cada una el doble de rápido) y por carriles: una ranura **x16** tiene 16 carriles y es la que usan las gráficas.', '**PCIe** is the motherboard expansion bus: GPUs, network cards and capture cards plug into it. It is measured by generation (3.0, 4.0, 5.0, each doubling speed) and lanes: an **x16** slot has 16 lanes and is the one graphics cards use.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['que es raid', 'discos en raid', 'raid 0 raid 1'], r: ['**RAID** combina varios discos en uno lógico: **RAID 0** los une para ir más rápido (pierdes todo si uno falla) y **RAID 1** los espeja para tolerar fallos. Ojo: RAID no reemplaza la copia de seguridad, solo la complementa.', '**RAID** combines several disks into one logical unit: **RAID 0** stripes them for speed (one failure loses everything) and **RAID 1** mirrors them for fault tolerance. Remember: RAID does not replace backups, it complements them.'], href: 'pc3d.html#mantenimiento' },
    { c: 'Hardware', k: ['versiones de usb', 'usb 2.0 3.0', 'tipos de usb', 'usb-c'], r: ['USB por velocidad: **2.0** (480 Mbps) y **3.x** (5-20 Gbps, conector azul o marcado SS). Por conector: el clásico tipo A, el tipo B de impresoras y el **USB-C** reversible, que además carga y transmite video. Conecta tus discos rápidos siempre a un puerto 3.x.', 'USB by speed: **2.0** (480 Mbps) and **3.x** (5-20 Gbps, blue or SS-marked port). By connector: classic type A, printer type B and reversible **USB-C**, which also charges and carries video. Plug fast drives into 3.x ports only.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['overclock de gpu', 'curva de ventiladores gpu', 'msi afterburner'], r: ['El **overclock de GPU** sube la frecuencia de la tarjeta con herramientas como MSI Afterburner: subes núcleo y memoria poco a poco y pruebas estabilidad. Vigila el límite de potencia y la temperatura; si aparecen artefactos en pantalla, retrocede.', '**GPU overclocking** raises the card frequency with tools like MSI Afterburner: raise core and memory step by step and test stability. Watch the power limit and temperature; if screen artifacts appear, back off.'], href: 'hardware.html#componentes' },
    { c: 'Redes', k: ['que es el dns', 'dns que significa', 'no resuelve paginas'], r: ['El **DNS** traduce nombres (google.com) a direcciones IP: es la "agenda" de internet. Si navegas por IP pero no por nombre, tu DNS falló: prueba 8.8.8.8 (Google) o 1.1.1.1 (Cloudflare) en tu configuración de red.', '**DNS** translates names (google.com) into IP addresses: it is the internet\u2019s phone book. If you can browse by IP but not by name, your DNS failed: try 8.8.8.8 (Google) or 1.1.1.1 (Cloudflare) in your network settings.'], href: 'recursos.html#laboratorio' },
    { c: 'Redes', k: ['que es el nat', 'nat que es', 'traduccion de direcciones'], r: ['**NAT** (Network Address Translation) permite que muchos equipos de tu red salgan a internet compartiendo una sola IP pública: el router traduce qué equipo pidió qué. Por eso tu IP local (192.168.x.x) es distinta de la que ve una web.', '**NAT** (Network Address Translation) lets many devices on your network share one public IP: the router tracks which device asked for what. That is why your local IP (192.168.x.x) differs from the one websites see.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['que es ipv6', 'ipv6 vs ipv4', 'diferencia ipv4 ipv6'], r: ['**IPv4** usa direcciones de 32 bits (192.168.1.1): solo hay ~4.300 millones y ya se agotaron. **IPv6** usa 128 bits (2001:db8::1): direcciones casi infinitas, configuración automática y sin NAT obligatorio. Ambos conviven hoy en día.', '**IPv4** uses 32-bit addresses (192.168.1.1): only ~4.3 billion exist and they ran out. **IPv6** uses 128 bits (2001:db8::1): nearly infinite addresses, auto-configuration and no mandatory NAT. Both coexist today.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['que es el firewall', 'cortafuegos que es', 'firewall para que sirve'], r: ['El **firewall (cortafuegos)** filtra el tráfico que entra y sale según reglas: bloquea conexiones no solicitadas y puede impedir que un programa se comunique. Windows trae el suyo; úsalo junto al antivirus y no lo desactives para "que vaya más rápido".', 'A **firewall** filters incoming and outgoing traffic by rules: it blocks unsolicited connections and can stop a program from communicating. Windows has one built in; use it next to your antivirus and do not disable it "for speed".'], href: 'mantenimiento-software.html#tareas' },
    { c: 'Redes', k: ['que es traceroute', 'tracert comando', 'ruta de los paquetes'], r: ['**tracert** (Windows) o **traceroute** (Linux/Mac) muestra cada salto que dan tus paquetes hasta un destino, con su tiempo. Sirve para ver dónde se cae o se ralentiza una conexión: el último salto que responde te dice hasta dónde llega bien.', '**tracert** (Windows) or **traceroute** (Linux/Mac) shows every hop your packets take to a destination, with timing. It reveals where a connection breaks or slows down: the last answering hop tells you how far traffic flows fine.'], href: 'recursos.html#laboratorio' },
    { c: 'Redes', k: ['cable ethernet cat5 cat6', 'categorias de cable de red', 'cable rj45'], r: ['Cables de red por categoría: **Cat5e** hasta 1 Gbps, **Cat6** hasta 10 Gbps en distancias cortas, **Cat6a/Cat7** para 10 Gbps estables. El conector es el **RJ45** (8 hilos). Un cable viejo o doblado puede limitar toda tu conexión aunque el plan sea rápido.', 'Network cables by category: **Cat5e** up to 1 Gbps, **Cat6** up to 10 Gbps over short runs, **Cat6a/Cat7** for stable 10 Gbps. The connector is **RJ45** (8 wires). An old or pinched cable can bottleneck your whole connection even with a fast plan.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['que es arp', 'protocolo arp', 'tabla arp'], r: ['**ARP** resuelve "quién tiene esta IP": pregunta en la red local y el equipo dueño responde con su dirección MAC, formando la tabla ARP. Compruébala con `arp -a`; si ves IPs desconocidas, hay dispositivos extraños en tu red.', '**ARP** answers "who has this IP": it asks on the local network and the owner replies with its MAC address, building the ARP table. Check it with `arp -a`; unknown IPs there mean strange devices on your network.'], href: 'recursos.html#glosario' },
    { c: 'Redes', k: ['que es icmp', 'icmp y ping', 'mensaje de error de red'], r: ['**ICMP** es el protocolo de mensajes de control de IP: ping y traceroute viajan sobre él, y también los errores "host unreachable" o "time exceeded". Los firewalls a veces lo bloquean, y entonces un ping falla aunque la web sí funcione.', '**ICMP** is IP\u2019s control-message protocol: ping and traceroute ride on it, and so do errors like "host unreachable" or "time exceeded". Firewalls sometimes block it, so a ping may fail while the website still works.'], href: 'recursos.html#glosario' },
    { c: 'WiFi', k: ['que es wpa2 wpa3', 'seguridad wifi wpa', 'wep o wpa'], r: ['**WPA** es el cifrado de tu WiFi: **WEP** está roto (no lo uses), **WPA2** es el mínimo aceptable y **WPA3** el más seguro actual. Revísalo en la configuración del router; si tu red sigue en WEP o abierta, cámbialo hoy mismo.', '**WPA** is your WiFi encryption: **WEP** is broken (never use it), **WPA2** is the acceptable minimum and **WPA3** is the current strongest. Check it in the router settings; if your network is still WEP or open, change it today.'], href: 'wifi.html#instalar-modem' },
    { c: 'WiFi', k: ['que es una red mesh', 'sistema mesh', 'malla wifi'], r: ['Una red **mesh** son varios nodos que se comunican entre sí para cubrir toda la casa con una sola red: tu equipo salta al nodo más cercano sin cortes. Es la alternativa moderna a los repetidores en casas grandes o de varios pisos.', 'A **mesh** network is several nodes that talk to each other to cover the whole house with a single network: your device hops to the nearest node without drops. It is the modern alternative to repeaters in large or multi-story homes.'], href: 'wifi.html#instalar-modem' },
    { c: 'Recursos', k: ['ipconfig comando', 'como uso ipconfig', 'ipconfig all'], r: ['**ipconfig** muestra tu configuración de red en Windows: `ipconfig` da IP y gateway; `ipconfig /all` añade MAC y DNS; `/release` y `/renew` renuevan tu IP; `/flushdns` limpia la caché de nombres. Pruébalo en el Laboratorio de Códigos.', '**ipconfig** shows your Windows network configuration: `ipconfig` gives IP and gateway; `ipconfig /all` adds MAC and DNS; `/release` and `/renew` renew your IP; `/flushdns` clears the name cache. Try it in the Code Lab.'], href: 'recursos.html#laboratorio' },
    { c: 'Recursos', k: ['sfc scannow', 'reparar archivos de sistema', 'comprobador de archivos'], r: ['**sfc /scannow** (en CMD como administrador) revisa los archivos de Windows y repara los dañados usando una copia interna. Úsalo cuando el sistema falla sin motivo, con pantallazos azules o errores raros; tarda minutos y no borra tus datos.', '**sfc /scannow** (in CMD as administrator) checks Windows system files and repairs damaged ones from an internal copy. Use it when the system fails without reason, with blue screens or odd errors; it takes minutes and deletes none of your data.'], href: 'mantenimiento-software.html#tareas' },
    { c: 'Recursos', k: ['chkdsk comando', 'revisar el disco', 'chkdsk f r'], r: ['**chkdsk** revisa el disco en busca de errores: `chkdsk C: /f` corrige errores del sistema de archivos y `chkdsk C: /r` busca sectores dañados (tarda más). Si el disco tarda en abrir carpetas o se traba, es buena señal de usarlo.', '**chkdsk** scans the disk for errors: `chkdsk C: /f` fixes file-system errors and `chkdsk C: /r` looks for bad sectors (takes longer). If folders take long to open or the system stalls, it is a good sign to run it.'], href: 'mantenimiento-software.html#tareas' },
    { c: 'Recursos', k: ['modo seguro', 'safe mode', 'entrar en modo seguro'], r: ['El **modo seguro** arranca Windows con lo mínimo imprescindible: sin programas de inicio ni drivers extras. Sirve para quitar virus tozudos o desinstalar lo que falla. Se llega desde Configuración > Recuperación > Arranque avanzado, o forzando 3 veces el apagado.', '**Safe mode** starts Windows with only the essentials: no startup programs or extra drivers. It helps remove stubborn viruses or uninstall whatever fails. Reach it via Settings > Recovery > Advanced startup, or force shutdown 3 times.'], href: 'mantenimiento-software.html#paso-a-paso' },
    { c: 'Recursos', k: ['limpieza de disco', 'liberar espacio', 'borrar archivos temporales'], r: ['Para liberar espacio: **Liberador de espacio en disco** o Configuración > Sistema > Almacenamiento. Borra temporales, la papelera y versiones viejas de Windows. No toques "Archivos de programa" a mano; usa la herramienta y revisa Descargas tú mismo.', 'To free space: **Disk Cleanup** or Settings > System > Storage. Delete temp files, the recycle bin and old Windows versions. Do not touch "Program Files" by hand; use the tool and review Downloads yourself.'], href: 'mantenimiento-software.html#tareas' },
    { c: 'Hardware', k: ['dual channel', 'canales de memoria', 'dos modulos de ram'], r: ['**Dual channel** es usar dos módulos de RAM iguales en las ranuras correctas para duplicar el ancho de banda de memoria. Se nota en juegos y edición: 2×8 GB rinden mejor que 1×16 GB. Mira el manual de tu placa para las ranuras pareadas.', '**Dual channel** means using two identical RAM sticks in the correct slots to double memory bandwidth. It shows in games and editing: 2×8 GB performs better than 1×16 GB. Check your board manual for the paired slots.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['memoria ecc', 'ram ecc', 'correccion de errores'], r: ['La RAM **ECC** detecta y corrige errores de memoria en tiempo real. Es estándar en servidores y estaciones de trabajo donde un error es costoso; para un PC de casa no es necesaria y suele ser más cara, además de requerir placa y CPU compatibles.', '**ECC** RAM detects and corrects memory errors in real time. It is standard on servers and workstations where an error is costly; for a home PC it is unnecessary and pricier, and it needs a compatible board and CPU.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['gabinete del pc', 'torre del pc', 'case del computador'], r: ['El **gabinete (case)** no es solo la caja: define el flujo de aire, el ruido y qué componentes caben. Buen gabinete: ventilación frontal con filtro, gestión de cables y espacio para el disipador y la GPU. Un case cerrado y sin airflow eleva temperaturas.', 'The **case** is not just a box: it defines airflow, noise and which components fit. A good case: front intake with dust filter, cable management and room for the cooler and GPU. A closed case with no airflow raises temperatures.'], href: 'pc3d.html#componentes-3d' },
    { c: 'Hardware', k: ['ventiladores pwm', 'ventilador del gabinete', 'flujo de aire del pc'], r: ['Los ventiladores **PWM** ajustan su velocidad según la temperatura, así son más silenciosos. Regla de flujo: más aire **entra** por el frente que sale por arriba/atrás (presión positiva) para evitar polvo. Conecta los fans a la placa, no directo a la fuente.', '**PWM** fans adjust their speed with temperature, so they run quieter. Airflow rule: more air **in** through the front than out the top/back (positive pressure) to keep dust away. Connect fans to the motherboard, not straight to the PSU.'], href: 'pc3d.html#mantenimiento' },
    { c: 'Hardware', k: ['tarjeta de sonido', 'audio del pc', 'sonido integrado'], r: ['La **tarjeta de sonido** convierte los datos en audio; hoy casi todas las placas traen audio integrado suficiente para la mayoría. Una tarjeta dedicada o un DAC externo se justifica si haces música o usas audífonos exigentes y notas ruido eléctrico.', 'A **sound card** turns data into audio; today almost every board has integrated audio good enough for most people. A dedicated card or external DAC makes sense if you make music or use demanding headphones and hear electrical noise.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['capturadora', 'grabar la pantalla del pc', 'captura de videojuegos'], r: ['Una **capturadora** graba o transmite el video de otra fuente (consola, otro PC). Para grabar tus propios juegos casi no hace falta: **OBS Studio** (gratis) lo hace por software. Capturadora externa (como Elgato) es útil para consolas o grabar sin perder FPS.', 'A **capture card** records or streams video from another source (console, another PC). For recording your own games you usually do not need one: **OBS Studio** (free) does it in software. An external card (like Elgato) is useful for consoles or recording without losing FPS.'], href: 'recursos.html#laboratorio' },
    { c: 'Hardware', k: ['hub usb', 'puertos usb insuficientes', 'multiplicar puertos usb'], r: ['Un **hub USB** divide un puerto en varios; sirve para teclado, mouse y pendrives, pero no para discos rápidos o cargar varios equipos a la vez (comparten energía y ancho de banda). Para dispositivos exigentes, mejor una placa PCIe USB o un hub con fuente propia.', 'A **USB hub** splits one port into many; fine for keyboard, mouse and pendrives, but not for fast drives or charging several devices at once (they share power and bandwidth). For demanding devices, use a PCIe USB card or a powered hub.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['procesador de 64 bits', 'sistemas de 32 y 64 bits', 'bits del procesador'], r: ['Un CPU de **64 bits** maneja más memoria y datos por ciclo que uno de 32 bits. Windows 64 bits es el estándar hoy: un sistema de 32 solo usa ~4 GB de RAM. Todos los procesadores recientes son de 64 bits; lo antiguo es el software de 32, que aún corre por compatibilidad.', 'A **64-bit** CPU handles more memory and data per cycle than a 32-bit one. 64-bit Windows is today\u2019s standard: a 32-bit system only uses ~4 GB of RAM. All recent CPUs are 64-bit; the legacy part is 32-bit software, which still runs for compatibility.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['cuello de botella', 'bottleneck del pc', 'el pc va lento por'], r: ['El **cuello de botella** es el componente que limita a los demás: una GPU potente con CPU flojo, o un SSD rápido en un PC con 4 GB de RAM. Identifícalo mirando el Administrador de tareas durante el uso pesado: lo que llega al 100% primero es tu freno.', 'The **bottleneck** is the component holding the others back: a strong GPU with a weak CPU, or a fast SSD in a PC with 4 GB of RAM. Spot it in Task Manager during heavy use: whatever hits 100% first is your brake.'], href: 'pc3d.html#componentes-3d' },
    { c: 'Hardware', k: ['undervolt', 'bajar voltaje al cpu', 'menos temperatura sin perder rendimiento'], r: ['El **undervolt** baja el voltaje del CPU/GPU manteniendo la frecuencia: menos calor y consumo con el mismo rendimiento. Se hace en BIOS o con herramientas del fabricante, bajando de a poco y probando estabilidad cada paso. Si se cuelga, sube el voltaje otra vez.', '**Undervolting** lowers CPU/GPU voltage while keeping frequency: less heat and power with the same performance. Do it in BIOS or vendor tools, lowering step by step and testing stability each time. If it crashes, raise the voltage back.'], href: 'pc3d.html#mantenimiento' },
    { c: 'Hardware', k: ['que es un benchmark', 'probar el rendimiento', 'medir el rendimiento del pc'], r: ['Un **benchmark** es una prueba estandarizada que mide el rendimiento y da una puntuación comparable: Cinebench para CPU, 3DMark para GPU, CrystalDiskMark para discos. Sirve para saber si tu upgrade realmente funcionó y comparar con equipos parecidos.', 'A **benchmark** is a standardized test that measures performance and gives a comparable score: Cinebench for CPU, 3DMark for GPU, CrystalDiskMark for drives. It tells you whether your upgrade really worked and lets you compare with similar machines.'], href: 'pc3d.html#componentes-3d' },
    { c: 'Hardware', k: ['tasa de refresco', 'pantallas de 60hz 144hz', 'hz del monitor'], r: ['La **tasa de refresco** es cuántas veces por segundo redibuja la pantalla: **60 Hz** estándar, **144 Hz** o más para juegos (imagen más fluida). Verifica en Configuración > Pantalla > Avanzado que Windows esté usando los Hz reales del monitor, no 60 por defecto.', 'The **refresh rate** is how many times per second the screen redraws: **60 Hz** standard, **144 Hz** or more for gaming (smoother motion). Check in Settings > Display > Advanced that Windows is actually using the monitor\u2019s real Hz, not a default 60.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['gpu integrada', 'graficos integrados', 'procesador con graficos'], r: ['Los **gráficos integrados** vienen dentro del CPU: consumen menos y ahorran dinero, pero comparten tu RAM y rinden menos. Sirven perfecto para oficina, video y juegos ligeros; para gaming serio o render 3D, GPU dedicada.', '**Integrated graphics** come inside the CPU: they use less power and save money, but share your RAM and perform less. They are perfect for office work, video and light games; for serious gaming or 3D rendering, a dedicated GPU.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['temperatura normal del cpu', 'temperatura del procesador', 'mi pc se calienta mucho'], r: ['CPU normal: **30-50 °C** en reposo y hasta **80-90 °C** a full (límite razonable). GPU similar. Si pasas de 90 °C o el PC se apaga solo: revisa pasta térmica, polvo en disipadores y ventiladores, y airflow del gabinete. Mide con HWMonitor o Core Temp.', 'Normal CPU: **30-50 °C** idle and up to **80-90 °C** at full load (reasonable limit). GPU is similar. Above 90 °C or sudden shutdowns: check thermal paste, dust in heatsinks and fans, and case airflow. Monitor with HWMonitor or Core Temp.'], href: 'pc3d.html#mantenimiento' },
    { c: 'Hardware', k: ['sintomas de fuente dañada', 'la fuente esta mala', 'pc se apaga solo'], r: ['Síntomas de fuente en falla: apagones aleatorios, reinicios al abrir juegos, olor a quemado, ventilador de la fuente que no gira o zumbidos. No abras la fuente (guarda carga letal aunque desenchufada): prueba cambiándola por una conocida buena antes de culpar a otra pieza.', 'Failing PSU symptoms: random shutdowns, reboots when launching games, burning smell, PSU fan not spinning or buzzing. Never open the PSU (it holds lethal charge even unplugged): test by swapping a known-good one before blaming other parts.'], href: 'hardware.html#componentes' },
    { c: 'Redes', k: ['mbps y mb', 'megabits o megabytes', 'diferencia mbps mb'], r: ['Cuidado con las letras: **Mb = megabits**, **MB = megabytes** (8 bits cada uno). Tu plan de "100 Mbps" descarga como máximo 12,5 **MB** por segundo real. Los proveedores anuncian en bits porque suena más grande; las velocidades de descarga se ven en bytes.', 'Watch the letters: **Mb = megabits**, **MB = megabytes** (8 bits each). Your "100 Mbps" plan downloads at most 12.5 **MB** per real second. Providers advertise in bits because it sounds bigger; download speeds show in bytes.'], href: 'recursos.html#glosario' },
    { c: 'Redes', k: ['ip publica y privada', 'mi ip en internet', 'diferencia ip publica privada'], r: ['Tu IP **privada** (192.168.x.x) solo vale dentro de tu casa y la asigna el router; la **pública** te la da el proveedor y es la que ven las páginas web. Búscalas: privada con ipconfig, pública escribiendo "cuál es mi IP" en el buscador.', 'Your **private** IP (192.168.x.x) only works inside your home and the router assigns it; the **public** one comes from your provider and is what websites see. Find them: private with ipconfig, public by typing "what is my IP" in a search engine.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['ip estatica o dinamica', 'ip fija', 'ip fija para servidor'], r: ['Una IP **dinámica** cambia con el tiempo (la reparte el DHCP del router); una **estática** es fija. En casa casi siempre conviene la dinámica; si necesitas fija para un servidor o cámara, reserva la IP en el router para ese equipo (reserva DHCP), no la configures a mano.', 'A **dynamic** IP changes over time (handed out by the router DHCP); a **static** one is fixed. At home dynamic is almost always right; if you need a fixed IP for a server or camera, reserve it in the router for that device (DHCP reservation), do not set it by hand.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['que es tcp', 'protocolo tcp', 'tcp que significa'], r: ['**TCP** es el protocolo que entrega datos de forma confiable: numera los paquetes, confirma la recepción y repite los perdidos. Lo usan la web, el correo y las descargas. Es ligeramente más lento que UDP, pero no pierde nada.', '**TCP** is the protocol that delivers data reliably: it numbers packets, confirms reception and retransmits lost ones. The web, email and downloads use it. It is slightly slower than UDP, but nothing gets lost.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['que es udp', 'protocolo udp', 'udp para que sirve'], r: ['**UDP** envía paquetes sin confirmación ni reenvío: rapidísimo y liviano, aunque si un paquete se pierde, se perdió. Lo usan los juegos en línea, las videollamadas y el streaming en vivo, donde es mejor un cuadro perdido que esperar.', '**UDP** sends packets with no confirmation or resend: lightning fast and light, but a lost packet stays lost. Online games, video calls and live streaming use it, where a dropped frame beats waiting around.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['que es un puerto de red', 'puertos de red', 'puerto 80 443'], r: ['Los **puertos** son numeraciones sobre una IP que separan servicios: 80 y 443 para web (HTTP/HTTPS), 25 correo, 22 SSH, 3389 escritorio remoto. Como los apartamentos de un edificio: una dirección (IP), muchos destinos (puertos). Escanéalos con cuidado y solo en redes tuyas.', '**Ports** are numbers layered on an IP that separate services: 80 and 443 for web (HTTP/HTTPS), 25 email, 22 SSH, 3389 remote desktop. Like apartments in a building: one address (IP), many destinations (ports). Scan carefully and only on your own networks.'], href: 'recursos.html#glosario' },
    { c: 'Redes', k: ['modelo osi', 'capas de red', 'osi que es'], r: ['El modelo **OSI** organiza la red en 7 capas: 1 física (el cable), 2 enlace (MAC, switches), 3 red (IP, routers), 4 transporte (TCP/UDP), 5-7 sesión, presentación y aplicación (HTTP). Sirve para ubicar problemas: si la capa 1 falla (cable suelto), nada de arriba funciona.', 'The **OSI** model organizes networks in 7 layers: 1 physical (the cable), 2 data link (MAC, switches), 3 network (IP, routers), 4 transport (TCP/UDP), 5-7 session, presentation and application (HTTP). It helps locate problems: if layer 1 fails (loose cable), nothing above works.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['que es la dmz', 'zona desmilitarizada', 'dmz router'], r: ['La **DMZ** de un router expone un equipo de tu red directamente a internet, sin la protección del firewall del router. Solo para servidores con su propia seguridad, nunca para tu PC personal. Si un juego o cámara "no conecta", primero prueba abrir solo los puertos necesarios.', 'A router **DMZ** exposes one device on your network straight to the internet, bypassing the router firewall. For servers with their own security only, never for your personal PC. If a game or camera "will not connect", first try forwarding just the needed ports.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['que es ddns', 'dns dinamico', 'acceder a mi pc desde fuera'], r: ['**DDNS** da un nombre fijo (micasa.ddns.net) a tu IP pública aunque cambie: así accedes a tu red desde fuera sin adivinar la IP. Muchos routers lo traen integrado. Combínalo con reglas de firewall estrictas: exponer tu red también expone riesgos.', '**DDNS** gives a fixed name (myhouse.ddns.net) to your changing public IP: you reach your network from outside without guessing the address. Many routers include it. Pair it with strict firewall rules: exposing your network also exposes risks.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['que es p2p', 'peer to peer', 'red punto a punto'], r: ['En **P2P** (peer to peer) cada equipo se conecta directo a los demás, sin servidor central: así funcionan torrents, algunas videollamadas y las redes antiguas de Windows por grupos de trabajo. Es eficiente para compartir, pero cada nodo depende de los otros.', 'In **P2P** (peer to peer) every device connects directly to the others, with no central server: torrents, some video calls and old Windows workgroups work this way. It is efficient for sharing, but each node depends on the others.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['cable directo o cruzado', 'cable cruzado de red', 't568'], r: ['Antes se usaba cable **directo** para conectar equipos distintos (PC-switch) y **cruzado** para iguales (PC-PC). Hoy no te preocupes: los puertos modernos tienen **Auto-MDIX** y detectan el tipo solos. Lo que sí importa: el orden T568B de los 8 hilos al crimpear.', 'Historically, **straight-through** cable connected different devices (PC-switch) and **crossover** connected equals (PC-PC). Do not worry today: modern ports have **Auto-MDIX** and detect the type themselves. What still matters is the T568B order of the 8 wires when crimping.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['que es el loopback', '127.0.0.1', 'localhost que es'], r: ['**127.0.0.1 (localhost)** es tu propio equipo: el tráfico a esa IP nunca sale a la red. Sirve para probar servidores y aplicaciones localmente y para verificar la pila TCP/IP: si `ping 127.0.0.1` falla, el problema está dentro de tu sistema, no en la red.', '**127.0.0.1 (localhost)** is your own machine: traffic to that IP never leaves to the network. Use it to test servers and apps locally and to verify the TCP/IP stack: if `ping 127.0.0.1` fails, the problem is inside your system, not the network.'], href: 'recursos.html#laboratorio' },
    { c: 'Redes', k: ['que es el 5g', 'redes moviles 5g', 'quinta generacion movil'], r: ['**5G** es la quinta generación de redes móviles: más velocidad, menos latencia (importante para juegos y realidad virtual) y más dispositivos por antena. No confundir con el WiFi de **5 GHz**: son tecnologías distintas que solo coinciden en el número.', '**5G** is the fifth mobile network generation: more speed, lower latency (key for gaming and VR) and more devices per antenna. Do not confuse it with **5 GHz** WiFi: they are different technologies that only share the number.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['que es iot', 'internet de las cosas', 'dispositivos smart'], r: ['El **IoT** (Internet de las Things) son dispositivos cotidianos conectados a la red: bombillas, cámaras, TV, parlantes inteligentes. Ojo con la seguridad: cambian la contraseña de fábrica, van en la red de invitados y se actualizan; un dispositivo descuidado abre la puerta a toda tu red.', '**IoT** (Internet of Things) are everyday devices on your network: bulbs, cameras, TVs, smart speakers. Mind security: change factory passwords, put them on the guest network and keep them updated; one careless device opens the door to your whole network.'], href: 'wifi.html#instalar-modem' },
    { c: 'WiFi', k: ['wifi de 6 ghz', 'wifi 6e', 'banda de 6ghz'], r: ['La banda de **6 GHz** (WiFi 6E/7) es la más rápida y con menos interferencias, porque casi nadie la usa todavía. Su contra: menos alcance y peor atraviesa muros. Ideal cuando el equipo está cerca del router; los dispositivos viejos no la ven.', 'The **6 GHz** band (WiFi 6E/7) is the fastest and cleanest, because almost nobody uses it yet. The downside: shorter range and worse wall penetration. Ideal when the device is near the router; older devices cannot even see it.'], href: 'wifi.html#instalar-modem' },
    { c: 'WiFi', k: ['hotspot', 'compartir internet del celular', 'punto de acceso movil'], r: ['Un **hotspot** es compartir el dato móvil de tu teléfono como WiFi. Cuidado: consume tu plan rápido y calienta el teléfono; ponle contraseña WPA2, revisa cuántos equipos conectas y desactívalo al terminar. Para PCs sin WiFi sirve como red de emergencia.', 'A **hotspot** shares your phone\u2019s mobile data as WiFi. Warning: it burns through your data plan and heats the phone; set a WPA2 password, watch how many devices connect and turn it off when done. For PCs without WiFi it works as an emergency network.'], href: 'wifi.html' },
    { c: 'WiFi', k: ['medir senal wifi', 'cuanto mide mi senal', 'dbm wifi'], r: ['La señal WiFi se mide en **dBm** (negativo, más cerca de 0 es mejor): -50 excelente, -60 bien, -70 regular, -80 casi inutilizable. Apps como WiFi Analyzer te la muestran por cuarto. Con -70 o peor, reubica el router o agrega repetidor/mesh.', 'WiFi signal is measured in **dBm** (negative, closer to 0 is better): -50 excellent, -60 good, -70 fair, -80 nearly unusable. Apps like WiFi Analyzer show it room by room. At -70 or worse, relocate the router or add a repeater/mesh node.'], href: 'wifi.html#instalar-modem' },
    { c: 'Recursos', k: ['taskkill comando', 'cerrar programa que no responde', 'forzar cierre de aplicacion'], r: ['Para cerrar un programa trabado: `taskkill /IM nombre.exe /F` (el /F fuerza). Primero mira el nombre exacto en el Administrador de tareas, pestaña Detalles. Alternativa clásica: Ctrl+Shift+Esc, clic derecho al proceso, Finalizar tarea.', 'To close a stuck program: `taskkill /IM name.exe /F` (/F forces it). First check the exact name in Task Manager, Details tab. The classic alternative: Ctrl+Shift+Esc, right-click the process, End task.'], href: 'recursos.html#laboratorio' },
    { c: 'Recursos', k: ['que es winget', 'winget install', 'instalar programas por comando'], r: ['**winget** es el gestor de paquetes de Windows: instala y actualiza programas desde CMD sin buscar instaladores. `winget install vlc` instala VLC; `winget upgrade` lista todo lo desactualizado y `winget upgrade --all` lo actualiza todo. Más seguro que descargar de webs raras.', '**winget** is Windows\u2019 package manager: it installs and updates programs from CMD without hunting installers. `winget install vlc` installs VLC; `winget upgrade` lists everything outdated and `winget upgrade --all` updates it all. Safer than downloading from sketchy sites.'], href: 'mantenimiento-software.html#programas' },
    { c: 'Recursos', k: ['windows update', 'actualizar windows', 'actualizaciones del sistema'], r: ['**Windows Update** trae parches de seguridad y mejoras: actívalo automático y reinicia cuando lo pida (las actualizaciones se completan al reiniciar). Si una actualización daña algo, Configuración > Windows Update > Historial > Desinstalar actualizaciones te devuelve atrás.', '**Windows Update** ships security patches and improvements: keep it automatic and reboot when asked (updates finish while restarting). If one update breaks something, Settings > Windows Update > History > Uninstall updates takes you back.'], href: 'mantenimiento-software.html#tareas' },
    { c: 'Recursos', k: ['gb y tb', 'cuanta capacidad de almacenamiento', 'gigabytes terabytes'], r: ['Unidades de almacenamiento: 1 **GB** ≈ 1.000 MB (una película en buena calidad), 1 **TB** = 1.000 GB. Guía rápida: 256 GB para uso básico, 512 GB-1 TB para juegos y trabajo. Ojo: los discos anuncian GB decimales y Windows muestra GiB binarios, por eso un "1 TB" aparece como ~931 GB.', 'Storage units: 1 **GB** ≈ 1,000 MB (a good-quality movie), 1 **TB** = 1,000 GB. Quick guide: 256 GB for basic use, 512 GB-1 TB for games and work. Note: drives advertise decimal GB and Windows shows binary GiB, which is why a "1 TB" shows as ~931 GB.'], href: 'hardware.html#componentes' },
    { c: 'Recursos', k: ['extensiones de archivo', 'tipos de archivos', 'que es un exe'], r: ['La **extensión** es lo que va después del punto: .exe ejecuta, .docx es Word, .pdf documento, .jpg imagen, .mp4 video, .zip comprimido. Activa "Mostrar extensiones" en el Explorador para detectar trampas: "foto.jpg.exe" es un programa, no una foto.', 'The **extension** is what comes after the dot: .exe runs, .docx is Word, .pdf document, .jpg image, .mp4 video, .zip archive. Turn on "Show extensions" in File Explorer to spot traps: "photo.jpg.exe" is a program, not a photo.'], href: 'mantenimiento-software.html#tareas' },
    { c: 'Recursos', k: ['atajos de teclado', 'combinaciones utiles', 'atajos de windows'], r: ['Atajos que valen oro: **Win+V** historial del portapapeles, **Win+Mayús+S** captura de pantalla, **Win+L** bloquear sesión, **Alt+Tab** cambiar ventana, **Win+R** ejecutar comandos, **Ctrl+Mayús+Esc** Administrador de tareas. Practica de a tres por día y los incorporas solos.', 'Gold-star shortcuts: **Win+V** clipboard history, **Win+Shift+S** screenshot, **Win+L** lock session, **Alt+Tab** switch windows, **Win+R** run commands, **Ctrl+Shift+Esc** Task Manager. Practice three a day and they stick on their own.'], href: 'mantenimiento-software.html#tareas' },
    { c: 'Recursos', k: ['histórico de archivos', 'versiones anteriores de un archivo', 'recuperar archivo borrado'], r: ['Si borraste algo: primero la **Papelera**. Para versiones anteriores de un archivo, clic derecho > "Versiones anteriores" (si el Historial de archivos está activo). Herramientas como Recuva pueden recuperar lo ya borrado de la papelera, pero mientras menos uses el disco, más chances hay.', 'If you deleted something: check the **Recycle Bin** first. For previous versions of a file, right-click > "Previous versions" (if File History is on). Tools like Recuva can recover bin-emptied files, but the less you use the disk meanwhile, the better the odds.'], href: 'pc3d.html#mantenimiento' },
    { c: 'Recursos', k: ['que es un pdf', 'archivos pdf', 'por que el pdf no se edita'], r: ['El **PDF** es un formato de documento que se ve igual en cualquier equipo: congela fuentes, imágenes y diseño. Por eso se usa para contratos y CVs. Editarlo es posible con herramientas dedicadas, pero su gracia es justamente no cambiarse.', 'A **PDF** is a document format that looks the same on every computer: it freezes fonts, images and layout. That is why contracts and CVs use it. Editing is possible with dedicated tools, but its whole point is not changing.'], href: 'mantenimiento-software.html#tareas' },
    { c: 'Recursos', k: ['7zip y winrar', 'que es un archivo zip', 'comprimir archivos'], r: ['Un **.zip/.rar** agrupa varios archivos en uno más pequeño (compresión). **7-Zip** es gratis y abre ambos; Windows ya abre .zip nativo. Para mandar carpetas completas por correo o subir varias cosas a la vez, comprimir es el camino.', 'A **.zip/.rar** packs several files into one smaller file (compression). **7-Zip** is free and opens both; Windows opens .zip natively. To send whole folders by email or upload many things at once, compressing is the way.'], href: 'mantenimiento-software.html#tareas' },
    { c: 'Recursos', k: ['winver', 'que version de windows tengo', 'ver la version de windows'], r: ['Para saber tu versión de Windows: **Win+R**, escribe `winver` y Enter. Ahí ves edición (Home/Pro) y compilación. Útil antes de instalar programas o buscar soluciones, porque los pasos cambian entre Windows 10 y 11.', 'To find your Windows version: **Win+R**, type `winver` and Enter. It shows the edition (Home/Pro) and build. Useful before installing software or looking for fixes, because steps differ between Windows 10 and 11.'], href: 'recursos.html#laboratorio' },
    { c: 'Redes', k: ['que es un modem router combinado', 'equipo todo en uno', 'el equipo del proveedor'], r: ['El equipo que da tu proveedor suele ser **módem + router + WiFi** en una caja. Está bien para empezar, pero en casas grandes conviene apagar su WiFi y usar tu propio router o mesh mejor ubicado. Accede a su panel (192.168.1.1) para cambiar claves y canales.', 'The box your provider gives you is usually **modem + router + WiFi** in one. It is fine to start, but in large homes it is better to turn off its WiFi and use your own router or mesh placed well. Reach its panel (192.168.1.1) to change passwords and channels.'], href: 'wifi.html#instalar-modem' },
    { c: 'Hardware', k: ['que es el bus de datos', 'bus del pc', 'canales de datos'], r: ['El **bus** es el "camino" por donde viajan los datos entre CPU, RAM y demás: entre más ancho y rápido, más datos por ciclo. Hay buses de memoria, de datos y de expansión (PCIe es uno de ellos).', 'The **bus** is the "road" data travels between CPU, RAM and the rest: the wider and faster, the more data per cycle. There are memory, data and expansion buses (PCIe is one of them).'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['que es xmp', 'perfil xmp de la ram', 'ram corre lenta'], r: ['**XMP** es el perfil de velocidad oficial de tu RAM: sin activarlo, la memoria corre a velocidad básica aunque sea de 3200 MHz. Se activa en el BIOS/UEFI en un clic: es el "upgrade gratis" más olvidado.', '**XMP** is your RAM’s official speed profile: without enabling it, memory runs at base speed even if it is 3200 MHz. Turn it on in BIOS/UEFI in one click: it is the most forgotten "free upgrade".'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['pila del bios', 'se borra la fecha del pc', 'cmos que es'], r: ['Si tu PC pierde la **hora y fecha** al desenchufarlo, la **pila CMOS** (tipo moneda CR2032 en la placa) se agotó: cuesta poco y se cambia en minutos. Sin ella el BIOS olvida su configuración en cada apagón.', 'If your PC loses the **time and date** when unplugged, the **CMOS battery** (a CR2032 coin cell on the board) is dead: it costs little and swaps in minutes. Without it, the BIOS forgets its settings on every power cut.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['egpu', 'tarjeta grafica externa para laptop', 'gpu externa'], r: ['Una **eGPU** es una tarjeta gráfica en caja externa que se conecta por Thunderbolt/USB4 a una laptop: le da poder de gaming o render sin abrir el equipo. Es cara y pierde algo de rendimiento por el cable, pero resucita portátiles ligeros.', 'An **eGPU** is a graphics card in an external box connected by Thunderbolt/USB4 to a laptop: it adds gaming or render power without opening the machine. It is pricey and loses some performance over the cable, but it revives light laptops.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['dpi del mouse', 'sensibilidad del mouse', 'que es dpi'], r: ['El **DPI** del mouse es cuántos pasos registra por pulgada de movimiento: más DPI = cursor más rápido con el mismo gesto. Para oficina 800-1200 basta; en juegos se juega mejor con DPI bajo y movimientos de brazo, no con el número más alto.', 'Mouse **DPI** is how many steps it registers per inch of movement: more DPI = faster cursor for the same hand motion. For office work 800-1200 is plenty; in games lower DPI with arm aiming usually beats the highest number.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['jack de 3.5', 'puertos de audio', 'conectar audifonos al pc'], r: ['Los puertos de audio **jack 3.5** tienen código de color: verde para audífonos, rosa para micrófono, azul para entrada de línea. En el frente del gabinete suelen estar conectados a la placa: si no suenan, revisa el conector HD Audio dentro del case.', '**3.5 mm** audio jacks are color-coded: green for headphones, pink for mic, blue line-in. Front case ports connect to the motherboard: if they are silent, check the HD Audio header inside the case.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['vida util del ssd', 'tbw del ssd', 'el ssd se desgasta'], r: ['Un **SSD** se desgasta por escrituras, pero no te alarmes: un disco moderno aguanta cientos de TB escritos, años de uso normal. Evita llenarlo al 100% (necesita espacio libre para trabajar) y deja que TRIM haga su trabajo: no necesitas "desfragmentar" un SSD jamás.', 'An **SSD** wears out with writes, but do not panic: modern drives endure hundreds of TB written, years of normal use. Avoid filling it to 100% (it needs free space to work) and let TRIM do its job: never defragment an SSD.'], href: 'hardware.html#componentes' },
    { c: 'Redes', k: ['ancho de canal wifi', 'canal 20 40 80', 'configurar canal del router'], r: ['El **ancho de canal** es cuánto espectro usa tu WiFi: 20 MHz estable en zonas saturadas, 40/80 MHz más rápido pero más propenso a interferencia. En edificios con muchas redes vecinas, 20 MHz en 2.4 GHz suele ir más fluido que canales anchos.', '**Channel width** is how much spectrum your WiFi uses: 20 MHz stays stable in crowded areas, 40/80 MHz is faster but more interference-prone. In buildings full of neighbor networks, 20 MHz on 2.4 GHz often flows better than wide channels.'], href: 'wifi.html#instalar-modem' },
    { c: 'Redes', k: ['que es un cable utp', 'cable utp', 'cable de red sin blindar'], r: ['**UTP** (Unshielded Twisted Pair) es el cable de red típico: 8 hilos trenzados en pares sin blindaje. El trenzado cancela interferencias; el blindaje (STP) solo se justifica cerca de motores o industrial. Para casa, UTP Cat5e/Cat6 es el estándar.', '**UTP** (Unshielded Twisted Pair) is the typical network cable: 8 wires twisted in pairs with no shield. Twisting cancels interference; shielding (STP) only makes sense near motors or in industrial settings. For home, UTP Cat5e/Cat6 is the standard.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['que es https', 'candado del navegador', 'http y https diferencia'], r: ['El candado del navegador significa **HTTPS**: la conexión con la web viaja cifrada, nadie en el camino lee tus claves ni lo que escribes. **HTTP** plano va en texto claro: evita escribir contraseñas en sitios sin candado. El candado no garantiza que el sitio sea honesto, solo que va cifrado.', 'The browser padlock means **HTTPS**: traffic to the site is encrypted, nobody along the way reads your passwords. Plain **HTTP** travels in clear text: never type credentials on a site without the padlock. The lock does not guarantee honesty, only encryption.'], href: 'recursos.html#glosario' },
    { c: 'Redes', k: ['que es un certificado ssl', 'certificado de seguridad', 'sitio no seguro'], r: ['El **certificado** detrás del candado HTTPS lo emite una autoridad que verifica que el dominio es de quien dice ser. Si el navegador dice "no seguro" o "certificado inválido", puede ser expiración, mala configuración… o alguien interceptando: no ingreses claves ahí.', 'The **certificate** behind the HTTPS padlock is issued by an authority verifying the domain belongs to who it claims. If the browser says "not secure" or "invalid certificate", it may be expiry, misconfiguration… or someone intercepting: do not enter credentials there.'], href: 'recursos.html#glosario' },
    { c: 'WiFi', k: ['repetidor donde colocarlo', 'ubicar repetidor wifi', 'repetidor no llega lejos'], r: ['Regla del repetidor: colócalo donde **todavía** haya buena señal del router (mitad del camino), no donde ya no llega nada. Un repetidor en zona muerta solo repite una señal mala. La luz de su señal te guía: verde bien, ámbar regular, rojo reubicar.', 'Repeater rule: place it where the router signal is **still** good (halfway), not where nothing arrives. A repeater in a dead zone just repeats a bad signal. Its signal light guides you: green good, amber fair, red relocate.'], href: 'wifi.html#instalar-modem' },
    { c: 'WiFi', k: ['conectar impresora por wifi', 'impresora inalambrica', 'la impresora no aparece'], r: ['Para una impresora WiFi: conéctala a la **misma red** que tu PC (desde su panel o botón WPS) y agrégala en Windows desde Configuración > Bluetooth y dispositivos > Impresoras. Si "no aparece", revisa que no esté en la red de invitados: eso la aísla de tu PC.', 'For a WiFi printer: connect it to the **same network** as your PC (from its panel or WPS button) and add it in Windows via Settings > Bluetooth & devices > Printers. If it "does not appear", check it is not on the guest network: that isolates it from your PC.'], href: 'wifi.html' },
    { c: 'WiFi', k: ['llamadas wifi', 'wifi calling', 'llamar sin senal movil'], r: ['**WiFi Calling** hace llamadas por tu red WiFi cuando la señal móvil es mala: se activa en Ajustes del teléfono (Móvil > Llamadas WiFi) y usa tu número normal, sin apps. Ideal en interiores con poca cobertura.', '**WiFi Calling** makes calls over your WiFi when mobile signal is weak: enable it in phone settings (Mobile > WiFi Calling) and it uses your normal number, no apps needed. Great indoors with poor coverage.'], href: 'wifi.html' },
    { c: 'WiFi', k: ['placa de red wifi', 'tarjeta inalambrica', 'el pc no tiene wifi'], r: ['El **adaptador WiFi** (integrado en la placa o USB) es la "antena" de tu PC. Un PC de escritorio viejo sin WiFi se resuelve con un adaptador USB de 10 dólares o una tarjeta PCIe para mejor antena. Si el WiFi va lento solo en ese PC, revisa el driver antes de culpar a la red.', 'The **WiFi adapter** (onboard or USB) is your PC’s "antenna". An old desktop without WiFi is fixed with a $10 USB adapter or a PCIe card with better antennas. If WiFi is slow only on that PC, check the driver before blaming the network.'], href: 'wifi.html' },
    { c: 'Recursos', k: ['captura de pantalla', 'como tomo una captura', 'screenshot windows'], r: ['Capturas en Windows: **Win+Mayús+S** recorta lo que quieras (la mejor), **Impr Pant** copia toda la pantalla, **Alt+Impr Pant** solo la ventana activa. La captura queda en el portapapeles o en Imágenes/Capturas de pantalla.', 'Screenshots on Windows: **Win+Shift+S** crops what you want (the best one), **PrtScn** copies the whole screen, **Alt+PrtScn** just the active window. The shot lands in the clipboard or Pictures/Screenshots.'], href: 'mantenimiento-software.html#tareas' },
    { c: 'Recursos', k: ['explorador de archivos', 'file explorer', 'carpetas de windows'], r: ['El **Explorador de archivos** (Win+E) es tu ventana a todo lo guardado: usa la barra de ruta para escribir direcciones, Ctrl+Mayús+N para carpetas nuevas y la vista "Detalles" con fechas para encontrar lo reciente. Atajos: F2 renombrar, Ctrl+Mayús+Esc… no, ese es el otro atajo.', '**File Explorer** (Win+E) is your window into everything stored: use the path bar to type addresses, Ctrl+Shift+N for new folders and the "Details" view with dates to find recent files. Shortcuts: F2 renames, Ctrl+Shift+Esc… no, that one is Task Manager.'], href: 'mantenimiento-software.html#tareas' },
    { c: 'Recursos', k: ['disco c y disco d', 'particiones del disco', 'por que tengo c y d'], r: ['**C:** es donde vive Windows; **D:** suele ser otra partición del mismo disco o un disco aparte. Truco útil: instala programas y guarda documentos en C:, y usa D: para juegos y archivos grandes; si reinstalas Windows, D: sobrevive.', '**C:** is where Windows lives; **D:** is usually another partition of the same disk or a separate drive. Handy trick: keep programs and documents on C: and use D: for games and big files; if you reinstall Windows, D: survives.'], href: 'mantenimiento-software.html#paso-a-paso' },
    { c: 'Recursos', k: ['renombrar varios archivos', 'renombrar en lote', 'cambiar nombre a muchas fotos'], r: ['Selecciona varios archivos (Ctrl o Mayús), pulsa **F2** y escribe el nuevo nombre: Windows los numera solo (foto(1), foto(2)…). Para patrones más finos (fechas, contadores), PowerToys **PowerRename** es gratis y hace magia.', 'Select several files (Ctrl or Shift), hit **F2** and type the new name: Windows numbers them automatically (photo(1), photo(2)…). For finer patterns (dates, counters), PowerToys **PowerRename** is free and works like magic.'], href: 'mantenimiento-software.html#tareas' },
    { c: 'Recursos', k: ['que es un acceso directo', 'shortcut en el escritorio', 'accesos directos de windows'], r: ['Un **acceso directo** es un puntero a un programa o archivo, no el programa en sí: borrarlo no desinstala nada (el icono tiene una flechita). Se crea con clic derecho > Enviar a > Escritorio, o arrastrando con Alt desde el menú Inicio.', 'A **shortcut** is a pointer to a program or file, not the program itself: deleting one uninstalls nothing (the icon has a tiny arrow). Create them with right-click > Send to > Desktop, or drag from the Start menu while holding Alt.'], href: 'mantenimiento-software.html#tareas' },
    { c: 'Recursos', k: ['instalar programas seguros', 'descargar programas sin virus', 'de donde descargar programas'], r: ['Regla: descarga **solo** del sitio oficial del programa o de la tienda de Windows/Microsoft Store. Evita "portables" y webs de terceros: son la vía #1 de virus. Al instalar, lee el asistente y desmarca barras de herramientas que vienen "de regalo".', 'Rule: download **only** from the program’s official site or the Windows/Microsoft Store. Avoid "portables" and third-party sites: they are the #1 virus vector. While installing, read the wizard and uncheck bonus toolbars that sneak in.'], href: 'mantenimiento-software.html#programas' },
    { c: 'Recursos', k: ['limpiar cache del navegador', 'la pagina no carga bien', 'borrar cache'], r: ['Si una página se ve mal o no actualiza, limpia la **caché del navegador**: Ctrl+Mayús+Supr, elige "imágenes y archivos en caché" y borra. No borres contraseñas ni historial salvo que quieras. Resuelve el 80% de las páginas "roto".', 'If a page looks broken or will not refresh, clear the **browser cache**: Ctrl+Shift+Del, choose "cached images and files", clear. Do not delete passwords or history unless you mean to. It fixes 80% of "broken page" cases.'], href: 'mantenimiento-software.html#tareas' },
    { c: 'Recursos', k: ['modo incognito', 'navegacion privada', 'ventana incognito'], r: ['La ventana **incógnito/privada** no guarda historial, cookies ni relleno de formularios en ese equipo. Ojo: no te hace anónimo en internet (tu proveedor y la web te ven igual), y no evade filtros del trabajo o el colegio. Sirve para usar un equipo ajeno sin dejar rastro local.', 'The **incognito/private** window stores no history, cookies or form data on that machine. Careful: it does not make you anonymous online (your provider and the site still see you), and it does not bypass school or work filters. It is for using someone else’s computer without local traces.'], href: 'mantenimiento-software.html#tareas' },
    { c: 'Recursos', k: ['hacer copia con robocopy', 'robocopy comando', 'copiar carpetas grandes'], r: ['**robocopy** es la copia profesional de Windows: `robocopy "C:\Documentos" "D:\Backup" /E /MIR` copia todo incluyendo subcarpetas y solo transfiere lo cambiado en la próxima vez. Mucho más confiable que arrastrar y soltar para respaldos.', '**robocopy** is Windows’ pro-grade copy: `robocopy "C:\Documents" "D:\Backup" /E /MIR` copies everything including subfolders and only transfers changes next time. Far more reliable than drag-and-drop for backups.'], href: 'recursos.html#laboratorio' },
    { c: 'Hardware', k: ['ventajas del ssd', 'cambiar hdd por ssd', 'ssd o disco duro'], r: ['Cambiar un disco mecánico por un **SSD** es la mejora que más se siente: Windows arranca en segundos, los programas abren al instante y el PC "renace". Un HDD sirve hoy como disco secundario para archivos y respaldos, no como disco de sistema.', 'Swapping a mechanical drive for an **SSD** is the upgrade you feel the most: Windows boots in seconds, programs open instantly and the PC "comes back to life". An HDD today works as secondary storage for files and backups, not as the system drive.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['que es la placa de video', 'tarjeta grafica que hace', 'gpu que es'], r: ['La **GPU (tarjeta gráfica)** dibuja todo lo que ves: juegos, video, efectos. Su potencia se mide por chip, VRAM y refrigeración. Para juegos, es el componente que más define el rendimiento; para oficina, la integrada basta.', 'The **GPU (graphics card)** draws everything you see: games, video, effects. Its power comes from the chip, VRAM and cooling. For gaming, it is the component that defines performance most; for office work, integrated graphics suffice.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['nucleos e hilos del procesador', 'nucleos del cpu', 'que es un hilo'], r: ['Los **núcleos** son los "cerebros" del CPU; los **hilos** (threads) dejan que cada núcleo atienda dos tareas a la vez. Editar video y renderizar usan muchos núcleos; los juegos valoran pocos núcleos muy rápidos. Más núcleos no siempre significa más velocidad.', '**Cores** are the CPU’s "brains"; **threads** let each core handle two tasks at once. Video editing and rendering love many cores; games favor fewer, faster cores. More cores does not always mean more speed.'], href: 'hardware.html#componentes' },
    { c: 'Redes', k: ['topologia bus', 'bus en redes', 'topologia lineal'], r: ['En la topología **bus**, todos los equipos comparten un solo cable con terminadores en los extremos. Era común con cable coaxial: barata, pero un corte en el cable cae toda la red y hay colisiones. Hoy quedó reemplazada por la estrella con switch.', 'In a **bus** topology, every device shares one cable with terminators at the ends. It was common with coaxial cable: cheap, but one cut brought the whole network down and collisions happened. Today star-with-switch replaced it.'], href: 'redes.html#topologias' },
    { c: 'Recursos', k: ['que es el cmd', 'terminal de windows', 'linea de comandos'], r: ['El **CMD/terminal** es la forma de dar órdenes escribiendo: más rápida y repetible que clics. Abre con Win+R y `cmd`. En este sitio el Laboratorio de Códigos te enseña ping, ipconfig y más con explicación de cada línea.', 'The **CMD/terminal** is how you give orders by typing: faster and repeatable compared to clicking. Open it with Win+R and `cmd`. This site’s Code Lab teaches you ping, ipconfig and more with a line-by-line explanation.'], href: 'recursos.html#laboratorio' },
    { c: 'Hardware', k: ['que es el bluetooth', 'bluetooth del pc', 'parear dispositivos'], r: ['**Bluetooth** conecta dispositivos cercanos sin cable: audífonos, teclados, impresoras. Alcance ~10 metros y menos velocidad que WiFi. Si el audio se entrecorta, el problema suele ser interferencia o distancia; en PC de escritorio viejo, un adaptador USB lo agrega.', '**Bluetooth** connects nearby devices without a cable: headphones, keyboards, printers. About 10 meters of range and less speed than WiFi. If audio stutters, interference or distance is usually the cause; on old desktops, a USB adapter adds it.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['que es nfc', 'nfc para que sirve', 'pagos por nfc'], r: ['**NFC** es comunicación de campo cercano: funciona a pocos centímetros. Es lo que usan los pagos con tarjeta o teléfono y el emparejamiento rápido de dispositivos. En PC apenas se usa; en el teléfono es el motor del pago sin contacto.', '**NFC** is near-field communication: it works within a few centimeters. It powers contactless card and phone payments and quick device pairing. PCs barely use it; on phones it is the engine of tap-to-pay.'], href: 'hardware.html#componentes' },
    { c: 'Redes', k: ['escritorio remoto', 'acceso remoto al pc', 'controlar mi pc desde fuera'], r: ['El **escritorio remoto** muestra y controla tu PC desde otro equipo: RDP (Windows Pro), o herramientas como Chrome Remote Desktop / AnyDesk. Deja el equipo encendido, usa contraseña fuerte y 2FA; abrir el escritorio a internet sin protección es invitar a desconocidos.', '**Remote desktop** shows and controls your PC from another machine: RDP (Windows Pro), or tools like Chrome Remote Desktop / AnyDesk. Keep the PC on, use a strong password and 2FA; exposing your desktop to the internet unprotected is inviting strangers in.'], href: 'redes.html#redes' },
    { c: 'Recursos', k: ['compartir archivos en red', 'carpeta compartida windows', 'compartir carpeta en lan'], r: ['Para compartir archivos entre PCs de casa: clic derecho a la carpeta > **Propiedades > Compartir**. Ambos equipos deben estar en la misma red y con perfil "Privado". Windows guarda las credenciales de acceso; si pide usuario, usa los datos del equipo dueño.', 'To share files between home PCs: right-click the folder > **Properties > Share**. Both computers must be on the same network with the "Private" profile. Windows stores access credentials; if it asks for a user, use the owner machine’s login.'], href: 'redes.html#redes' },
    {"c":"Hardware","k":["lineas pcie x16 x8 segundo slot","que pasa si uso el segundo slot pcie","pcie lanes x16 x8 second slot","reparto de lineas pcie placa"],"r":["Cuando una placa reparte sus líneas entre dos slots, el principal puede bajar de **x16** a x8: el chipset y la CPU tienen un número fijo de líneas PCIe (por ejemplo, 16 para la gráfica en muchas plataformas) y al poblar el segundo slot se dividen 8+8. En juegos la pérdida típica al pasar una GPU moderna de x16 a x8 Gen4 es de solo un 1-3 %, porque x8 Gen4 equivale en ancho de banda a x16 Gen3. Revisa el manual: ahí indica el reparto exacto según los slots y los M.2 ocupados.","When a board shares its lanes between two slots, the main one can drop from **x16** to x8: the chipset and CPU have a fixed number of PCIe lanes (for example, 16 for graphics on many platforms) and populating the second slot splits them 8+8. In games, the typical loss moving a modern GPU from x16 to x8 Gen4 is only 1-3%, because x8 Gen4 matches x16 Gen3 in bandwidth. Check the manual: it states the exact sharing per slot and occupied M.2."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["resizable bar que es","como activar resizable bar","resizable bar what is it","rebar rendimiento gpu"],"r":["**Resizable BAR** permite a la CPU acceder de una vez a toda la memoria de la GPU, en vez de hacerlo por una ventana fija de 256 MB: así los juegos cargan texturas y recursos con menos pasos. Para activarlo necesitas UEFI puro sin CSM, Above 4G Decoding activado, una GPU y un driver compatibles, y a veces una vBIOS actualizada. La ganancia típica es de un 0-10 % según el juego; alguno incluso pierde un poco, por eso el driver mantiene una lista de títulos verificados.","**Resizable BAR** lets the CPU access all of the GPU's memory at once, instead of through a fixed 256 MB window: games then load textures and assets with fewer steps. To enable it you need pure UEFI without CSM, Above 4G Decoding on, a compatible GPU and driver, and sometimes an updated vBIOS. The typical gain is 0-10% depending on the game; a few even lose slightly, which is why the driver keeps a list of verified titles."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["ihs procesador que es","que es el ihs de la cpu","cpu ihs meaning","tapa metalica del procesador"],"r":["El **IHS** (Integrated Heat Spreader) es la tapa metálica niquelada que ves sobre el procesador: protege el die de silicio y reparte el calor a una superficie mayor para que el disipador lo extraiga. Entre el die y el IHS hay soldadura metálica o pasta térmica según el modelo; por eso quitarlo (delid) baja temperaturas pero anula la garantía y puede destruir la CPU. Al montar el disipador, la pasta va sobre el IHS: una cantidad del tamaño de un guisante en el centro basta.","The **IHS** (Integrated Heat Spreader) is the nickel-plated metal lid you see on top of the processor: it protects the silicon die and spreads heat over a larger surface so the cooler can remove it. Between die and IHS there is metal solder or thermal paste depending on the model; that is why removing it (delidding) lowers temperatures but voids the warranty and can destroy the CPU. When mounting the cooler, paste goes on the IHS: a pea-sized amount in the center is enough."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["pl1 pl2 intel que son","limites de potencia pl1 pl2","intel pl1 pl2 power limits","tau procesador intel"],"r":["En Intel, **PL1** es el límite de potencia sostenida en vatios (parecido al TDP) y **PL2** es el límite de ráfaga corta, que la CPU puede mantener solo durante un tiempo definido por Tau, típicamente 28-56 segundos. Si tu placa pone PL1=PL2=4095 W, el procesador consumirá hasta que la temperatura mande: más rendimiento en renders largos, pero mucho más calor. Para un uso equilibrado, fija PL1 al TDP oficial y PL2 un 25-30 % por encima, y comprueba temperaturas con HWiNFO.","On Intel, **PL1** is the sustained power limit in watts (similar to TDP) and **PL2** is the short burst limit, which the CPU can hold only for a time defined by Tau, typically 28-56 seconds. If your board sets PL1=PL2=4095 W, the processor will draw power until temperature takes over: more performance in long renders, but far more heat. For balanced use, set PL1 to the official TDP and PL2 about 25-30% higher, and check temperatures with HWiNFO."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["precision boost overdrive pbo","curve optimizer que es","amd pbo curve optimizer","pbo limites ppt tdc edc"],"r":["En AMD, **Precision Boost Overdrive (PBO)** amplía los límites PPT (potencia), TDC y EDC (corriente) para que Ryzen boostee más tiempo, y **Curve Optimizer** aplica un undervolt por núcleo desplazando la curva voltaje-frecuencia, típicamente de -10 a -30 pasos. Valores negativos agresivos dan más frecuencia con menos calor, pero pueden provocar reinicios en reposo o errores en un solo núcleo. Ajusta de 5 en 5, prueba estabilidad con CoreCycler y guarda el último perfil estable antes de seguir bajando.","On AMD, **Precision Boost Overdrive (PBO)** raises the PPT (power), TDC and EDC (current) limits so Ryzen boosts longer, and **Curve Optimizer** applies a per-core undervolt by shifting the voltage-frequency curve, typically from -10 to -30 steps. Aggressive negative values give more frequency with less heat, but can cause idle reboots or errors on a single core. Adjust in steps of 5, test stability with CoreCycler, and save the last stable profile before going lower."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["fases vrm temperatura","que son las fases vrm","vrm phases temperature","vrm se calienta mucho"],"r":["Las **fases VRM** convierten los 12 V de la fuente en el voltaje exacto que pide la CPU (alrededor de 1,0-1,4 V) repartiendo la corriente entre varias etapas: más fases reales significan menos amperios y menos calor por fase. Un VRM sano trabaja por debajo de 90-100 °C; por encima de 110 °C la placa puede bajar frecuencias (throttling) aunque la CPU esté fría. Se mide con el sensor VRM de HWiNFO o con termómetro infrarrojo, y mejora con flujo de aire directo sobre sus disipadores.","The **VRM phases** convert the PSU's 12 V into the exact voltage the CPU requests (around 1.0-1.4 V), sharing current across several stages: more real phases mean fewer amps and less heat per phase. A healthy VRM runs below 90-100 °C; above 110 °C the board may cut frequencies (throttling) even if the CPU is cool. Measure it with HWiNFO's VRM sensor or an infrared thermometer, and improve it with direct airflow over its heatsinks."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["coil whine que es","ruido electrico grafica coil whine","gpu coil whine meaning","zumbido bobinas fuente"],"r":["El **coil whine** es un zumbido agudo que producen las bobinas (inductores) del VRM de la gráfica o la fuente al vibrar con la corriente: no es una avería, es vibración mecánica audible. Empeora con FPS muy altos (menús a cientos de frames) porque la frecuencia de trabajo entra en el rango audible. Mitígalo limitando los FPS a la tasa del monitor, activando V-Sync o probando otra fuente; cambiar la carga a veces desplaza el ruido fuera del oído. Si aparece junto a fallos o reinicios, ya es otra cosa.","**Coil whine** is a high-pitched whine produced by the coils (inductors) of the GPU or PSU VRM vibrating with the current: it is not a failure, it is audible mechanical vibration. It gets worse at very high FPS (menus at hundreds of frames) because the working frequency enters the audible range. Mitigate it by capping FPS to the monitor's refresh rate, enabling V-Sync, or trying another PSU; changing the load sometimes moves the noise out of hearing. If it appears together with crashes or reboots, that is a different problem."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["gpu sag soporte grafica","la grafica se dobla sag","gpu sag support bracket","tarjeta grafica hundida peso"],"r":["El **GPU sag** es la caída del extremo de una gráfica larga y pesada (las de triple ventilador superan 1,5 kg) por su propio peso: fuerza el slot PCIe y, con los años, puede agrietar soldaduras o el conector. Solución: un soporte vertical regulable bajo la esquina lejana, un bracket atornillado a las bahías, o pasar los cables de alimentación por arriba para que sujeten en vez de tirar. Al instalarla, aprieta ambos tornillos de la chapa y comprueba que la tarjeta queda horizontal con un nivel o a simple vista.","**GPU sag** is the droop of a long, heavy graphics card's far end (triple-fan models exceed 1.5 kg) under its own weight: it stresses the PCIe slot and, over years, can crack solder joints or the connector. Fix: an adjustable vertical support under the far corner, a bracket screwed to the expansion bays, or routing the power cables from above so they hold instead of pull. When installing, tighten both bracket screws and check the card sits level, with a level tool or by eye."],"href":"pc3d.html#mantenimiento"},
    {"c":"Hardware","k":["hotspot gpu vs borde","temperatura hotspot grafica","gpu hotspot temperature meaning","diferencia hotspot junction"],"r":["La GPU reporta dos temperaturas: la del **borde** (media del die, la que muestran la mayoría de programas) y la del **hotspot** o junction, el punto más caliente del chip. Una diferencia normal es de 10-20 °C; si el hotspot supera en más de 30 °C al borde o pasa de 105-110 °C, suele haber pasta reseca, una almohadilla mal asentada o presión desigual del disipador. Revisa con HWiNFO el sensor GPU Hot Spot: es el primer aviso antes de que aparezca throttling o apagados en juegos exigentes.","The GPU reports two temperatures: the **edge** temperature (die average, what most tools show) and the **hotspot** or junction, the hottest point of the chip. A normal gap is 10-20 °C; if the hotspot exceeds the edge by more than 30 °C or goes past 105-110 °C, there is usually dried paste, a badly seated pad, or uneven cooler pressure. Check the GPU Hot Spot sensor in HWiNFO: it is the first warning before throttling or shutdowns appear in demanding games."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["hbm vs gddr diferencia","que es memoria hbm","hbm vs gddr bandwidth","memoria apilada hbm"],"r":["La **HBM** apila chips de memoria en 3D junto a la GPU y se conecta por un bus enorme (1.024-8.192 bits según generación) a baja frecuencia, logrando un ancho de banda de 1 a más de 3 TB/s con menos consumo por bit. La **GDDR**, en cambio, coloca chips alrededor de la GPU con buses de 32 bits por chip y frecuencias altísimas. Por coste, HBM queda para aceleradores de IA y gama profesional; las gráficas de juego usan GDDR porque es mucho más barata de producir.","**HBM** stacks memory chips in 3D next to the GPU and connects through a huge bus (1,024-8,192 bits depending on generation) at low clock speeds, reaching 1 to over 3 TB/s of bandwidth with lower power per bit. **GDDR**, instead, places chips around the GPU with 32-bit buses per chip and very high clocks. Because of cost, HBM stays in AI accelerators and professional cards; gaming cards use GDDR because it is far cheaper to produce."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["gddr6 vs gddr6x vs gddr7","diferencia gddr6 gddr6x gddr7","gddr7 vs gddr6x speed","tipos de memoria grafica"],"r":["La evolución GDDR se mide en gigabits por segundo por pin: **GDDR6** llega a 16-20 Gbps con señalización NRZ, **GDDR6X** usa PAM4 (dos bits por símbolo) para alcanzar 21-24 Gbps, y **GDDR7** pasa a PAM3 y sube a 28-32 Gbps o más. Con el mismo bus de 256 bits, eso significa pasar de unos 512 GB/s a cerca de 1 TB/s. Más velocidad ayuda sobre todo en 4K y trazado de rayos; en 1080p la diferencia práctica puede ser pequeña si el juego no satura la memoria.","GDDR evolution is measured in gigabits per second per pin: **GDDR6** reaches 16-20 Gbps with NRZ signaling, **GDDR6X** uses PAM4 (two bits per symbol) to hit 21-24 Gbps, and **GDDR7** moves to PAM3 and climbs to 28-32 Gbps or more. With the same 256-bit bus, that means going from about 512 GB/s to close to 1 TB/s. More speed helps mainly at 4K and in ray tracing; at 1080p the practical difference can be small if the game does not saturate memory."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["bus memoria gpu bits","ancho de banda memoria grafica calculo","gpu memory bus bandwidth formula","192 bits vs 256 bits"],"r":["El ancho de banda de una GPU se calcula multiplicando: **bus en bits dividido entre 8, por la velocidad efectiva en Gbps**. Ejemplo: 256 bits × 20 Gbps ÷ 8 = 640 GB/s. Un bus más estrecho (128 o 192 bits) puede compensarse con memoria más rápida o con una caché L2 grande en el chip, como hacen las generaciones recientes. Por eso no compares solo los bits entre generaciones distintas: compara los GB/s finales y el tamaño de caché, que es lo que alimenta de verdad a los núcleos.","A GPU's bandwidth is calculated by multiplying: **bus width in bits divided by 8, times the effective speed in Gbps**. Example: 256 bits × 20 Gbps ÷ 8 = 640 GB/s. A narrower bus (128 or 192 bits) can be offset by faster memory or a large on-chip L2 cache, as recent generations do. So do not compare bits alone across different generations: compare the final GB/s and cache size, which is what actually feeds the cores."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["nvenc codificacion av1","que es nvenc obs","nvenc av1 encoding","codificador hardware nvidia"],"r":["**NVENC** es el bloque de codificación por hardware de las GPU NVIDIA: graba y transmite sin cargar la CPU, usando chips dedicados. Las RTX 40 y 50 añaden codificación **AV1**, que ofrece la misma calidad que H.264 con un 25-30 % menos de bitrate, ideal si la plataforma lo acepta. En OBS selecciona NVENC AV1 (o HEVC como alternativa), calidad CQP 18-22 para grabar y 6.000-8.000 kbps en H.264 para directo a 1080p60. Las RTX 50 traen doble codificador, útil para grabar y transmitir a la vez.","**NVENC** is the hardware encoding block in NVIDIA GPUs: it records and streams without loading the CPU, using dedicated chips. RTX 40 and 50 cards add **AV1** encoding, which delivers the same quality as H.264 at 25-30% less bitrate, ideal if the platform accepts it. In OBS pick NVENC AV1 (or HEVC as an alternative), CQP quality 18-22 for recording, and 6,000-8,000 kbps in H.264 for 1080p60 streaming. RTX 50 cards carry dual encoders, useful for recording and streaming at once."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["nvidia reflex que es","como activar nvidia reflex","nvidia reflex latency","reflex on + boost diferencia"],"r":["**NVIDIA Reflex** reduce la latencia del sistema sincronizando CPU y GPU para que la CPU no genere frames con mucha antelación que luego esperen en cola: en juegos compatibles baja el retardo total en un 25-50 %. Actívalo dentro del juego en Activado o Activado+Boost (Boost mantiene la GPU a frecuencias altas, a costa de más consumo en menús). Funciona mejor con la GPU al límite; si tu cuello de botella es la CPU, la mejora será menor. Requiere GPU GTX 900 o superior.","**NVIDIA Reflex** cuts system latency by synchronizing CPU and GPU so the CPU does not render frames far ahead that then wait in a queue: in supported games it lowers total delay by 25-50%. Enable it in-game as On or On+Boost (Boost keeps the GPU at high clocks, at the cost of more power draw in menus). It works best when the GPU is the limit; if your bottleneck is the CPU, the gain will be smaller. It requires a GTX 900 GPU or newer."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["g sync vs freesync diferencia","que es mejor gsync o freesync","g-sync vs freesync explained","sincronizacion adaptativa monitor"],"r":["**G-Sync** y **FreeSync** son sincronización adaptiva: el monitor ajusta su refresco a los FPS de la GPU para eliminar tearing sin el retardo del V-Sync. G-Sync original usa un módulo de hardware de NVIDIA y valida rangos completos (por ejemplo 1-360 Hz); FreeSync es un estándar abierto sobre DisplayPort/HDMI y su calidad depende del modelo. La etiqueta G-Sync Compatible indica un monitor FreeSync validado por NVIDIA. En la práctica, en monitores buenos la experiencia es casi idéntica; revisa que el rango cubra tus FPS habituales.","**G-Sync** and **FreeSync** are adaptive sync: the monitor matches its refresh rate to the GPU's FPS to remove tearing without V-Sync's added delay. Original G-Sync uses an NVIDIA hardware module and validates full ranges (for example 1-360 Hz); FreeSync is an open standard over DisplayPort/HDMI and its quality depends on the model. The G-Sync Compatible label marks a FreeSync monitor validated by NVIDIA. In practice, on good monitors the experience is nearly identical; check that the range covers your usual FPS."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["vrr que es variable refresh","variable refresh rate vrr tv","what is vrr gaming","vrr hdmi 2.1 consola"],"r":["El **VRR** (Variable Refresh Rate) es el nombre genérico de HDMI para la sincronización adaptiva: la pantalla refresca cuando la GPU termina cada frame, en un rango típico de 48-120 Hz en televisores. En consolas evita el tearing y el judder cuando el juego oscila entre 40 y 60 FPS, y algunos títulos usan modos de 40 FPS con VRR. Actívalo en TV y consola, usa el puerto HDMI marcado como 2.1 y ten en cuenta que en algunos paneles OLED el VRR puede provocar un leve parpadeo en negros.","**VRR** (Variable Refresh Rate) is HDMI's generic name for adaptive sync: the display refreshes when the GPU finishes each frame, in a typical 48-120 Hz range on TVs. On consoles it prevents tearing and judder when a game swings between 40 and 60 FPS, and some titles use 40 FPS VRR modes. Enable it on TV and console, use the port labeled HDMI 2.1, and note that on some OLED panels VRR can cause slight near-black flicker."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["input lag monitor que es","cuanto input lag es bueno","monitor input lag meaning","retardo entrada pantalla"],"r":["El **input lag** es el tiempo entre que la GPU envía la imagen (o tú mueves el ratón) y el cambio aparece en pantalla: suma el procesado del monitor, el refresco y el render. Un monitor gaming bueno está por debajo de 5 ms a su refresco nativo; los televisores en modo juego rondan 5-10 ms, pero fuera de ese modo pueden superar 50-100 ms. Mídelo o consúltalo en análisis con equipo dedicado: las marcas casi nunca publican esta cifra, que no hay que confundir con el tiempo de respuesta del píxel.","**Input lag** is the time between the GPU sending the image (or you moving the mouse) and the change appearing on screen: it adds up the monitor's processing, refresh, and rendering. A good gaming monitor stays under 5 ms at its native refresh; TVs in game mode run about 5-10 ms, but outside that mode they can exceed 50-100 ms. Measure it or check reviews with dedicated equipment: brands almost never publish this figure, which should not be confused with pixel response time."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["tiempo respuesta gtg monitor","que significa 1ms gtg","gtg vs mprt response time","grey to grey explained"],"r":["El **GtG** (grey-to-grey) mide cuánto tarda un píxel en pasar de un tono de gris a otro, y los famosos «1 ms» se miden con overdrive al máximo, un ajuste que a menudo crea estelas inversas (overshoot, halos claros tras objetos en movimiento). Un valor realista bueno es 3-5 ms GtG con overdrive medio. El MPRT, en cambio, mide la nitidez en movimiento con inserción de luz de fondo. Para 144 Hz, el frame dura 6,9 ms: si el píxel tarda más, habrá algo de desenfoque aunque la caja diga 1 ms.","**GtG** (grey-to-grey) measures how long a pixel takes to go from one gray shade to another, and the famous '1 ms' figures are measured with overdrive at maximum, a setting that often creates inverse ghosting (overshoot, bright halos behind moving objects). A realistic good value is 3-5 ms GtG with medium overdrive. MPRT, instead, measures motion clarity with backlight strobing. At 144 Hz a frame lasts 6.9 ms: if the pixel takes longer, there will be some blur even if the box says 1 ms."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["panel 8 bits vs 10 bits frc","que es frc 8+2 bits","8 bit vs 10 bit panel","profundidad color monitor"],"r":["Un panel de **8 bits** muestra 16,7 millones de colores y uno de **10 bits**, 1.070 millones: la diferencia se nota en degradados suaves (cielos, sombras), donde 8 bits sin más puede producir bandas (banding). Muchos monitores «10 bits» son en realidad 8 bits + **FRC**, que alterna dos tonos por frame para simular el intermedio: resultado casi idéntico para uso normal. Ojo: 10 bits reales exigen cadena completa (GPU, cable DisplayPort, contenido y programa compatibles); en Windows la mayoría de juegos sigue trabajando en 8 bits.","An **8-bit** panel shows 16.7 million colors and a **10-bit** one, 1.07 billion: the difference shows in smooth gradients (skies, shadows), where plain 8-bit can produce banding. Many '10-bit' monitors are actually 8-bit + **FRC**, which alternates two shades per frame to simulate the in-between one: a nearly identical result for normal use. Note: real 10-bit needs a complete chain (GPU, DisplayPort cable, compatible content and software); on Windows most games still work in 8-bit."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["cobertura srgb vs dci p3","que es dci p3 gamut","srgb vs dci-p3 coverage","espacio de color monitor porcentaje"],"r":["La **cobertura** indica qué parte de un espacio de color puede mostrar el panel: sRGB es el estándar de web y Windows, y **DCI-P3** es un 25 % más amplio, usado en cine y en HDR. Un monitor con 95-99 % DCI-P3 mostrará colores más saturados, pero si ves contenido sRGB en un panel amplio sin modo sRGB, todo se verá sobresaturado (rojos y verdes exagerados). Para edición fotográfica busca 100 % sRGB y un modo sRGB con bloqueo de controles; para cine y HDR, prioriza DCI-P3 alto.","**Coverage** states how much of a color space the panel can display: sRGB is the web and Windows standard, and **DCI-P3** is about 25% wider, used in cinema and HDR. A monitor with 95-99% DCI-P3 will show more saturated colors, but if you view sRGB content on a wide panel without an sRGB mode, everything looks oversaturated (exaggerated reds and greens). For photo editing look for 100% sRGB and an sRGB mode with control lock; for cinema and HDR, prioritize high DCI-P3."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["perfil icc calibrar monitor","como usar perfil icc","icc profile calibration windows","perfil color fabricante monitor"],"r":["Un **perfil ICC** describe los colores reales de tu monitor concreto para que Windows y los programas con gestión de color compensen sus desviaciones. Instala el del fabricante desde su web (Configuración de pantalla no basta: se asigna en Administración de color) o crea uno propio con un colorímetro tipo Calibrite, que es la opción precisa. El perfil no cambia la pantalla por sí solo: solo funciona en aplicaciones que lo respetan; los juegos suelen ignorarlo. Recalibrar cada 2-3 meses compensa el envejecimiento de la retroiluminación.","An **ICC profile** describes the actual colors of your specific monitor so Windows and color-managed programs can compensate for its deviations. Install the manufacturer's profile from its website (Display settings are not enough: it is assigned in Color Management) or create your own with a colorimeter such as a Calibrite, which is the accurate option. The profile does not change the screen by itself: it only works in applications that respect it; games usually ignore it. Recalibrating every 2-3 months offsets backlight aging."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["ecc on die ddr5 pmic","que es pmic ddr5","ddr5 on-die ecc meaning","regulador voltaje modulo ddr5"],"r":["En DDR5, el **ECC on-die** corrige errores de un bit dentro de cada chip de memoria para mantener la integridad con celdas tan densas: ojo, no equivale al ECC de módulos servidor, porque no protege el bus ni lo reporta igual al sistema. La otra novedad es el **PMIC**, un chip en el propio módulo que regula su voltaje (1,1 V) en vez de hacerlo la placa; por eso módulos con PMIC de mala calidad limitaron el overclock en los primeros lotes de DDR5.","In DDR5, **on-die ECC** corrects single-bit errors inside each memory chip to keep integrity with such dense cells: note, it is not equivalent to server-module ECC, because it does not protect the bus or report to the system the same way. The other novelty is the **PMIC**, a chip on the module itself that regulates its voltage (1.1 V) instead of the board doing it; that is why modules with poor-quality PMICs limited overclocking in the first DDR5 batches."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["single rank vs dual rank ram","que es dual rank memoria","ram ranks performance difference","como saber ranks de mi ram"],"r":["El **rank** es un grupo de chips de RAM que comparte bus de 64 bits y responde como una unidad: un módulo puede ser single rank (1Rx8) o dual rank (2Rx8). Dos ranks permiten intercalar operaciones y suelen rendir un 3-8 % más en CPU dependiente de memoria, pero cargan más el controlador y a veces limitan la frecuencia. Ojo: 2 módulos dual rank equivalen eléctricamente a 4 ranks, configuración exigente. Consulta los ranks en CPU-Z (pestaña SPD) o en la etiqueta del módulo antes de mezclar kits.","A **rank** is a group of RAM chips sharing a 64-bit bus that responds as one unit: a module can be single rank (1Rx8) or dual rank (2Rx8). Two ranks allow interleaved operations and usually perform 3-8% better when the CPU is memory-dependent, but they load the controller more and sometimes limit frequency. Note: 2 dual-rank modules are electrically like 4 ranks, a demanding configuration. Check ranks in CPU-Z (SPD tab) or on the module label before mixing kits."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["infinity fabric 1 1 gear 2","ratio fclk mclk ryzen","infinity fabric gear 2 ddr5","fclk 2000 ddr5 6000"],"r":["En Ryzen, el **Infinity Fabric (FCLK)** debería ir sincronizado con el controlador de memoria (UCLK) y la RAM: en DDR4 el ideal 1:1 era, por ejemplo, FCLK 1800 con DDR4-3600. En DDR5 la relación práctica es UCLK=MCLK con FCLK desacoplado (auto 2000 MHz) y el punto dulce está en DDR5-6000/6400. Forzar divisores tipo **Gear 2** (UCLK a la mitad) sube frecuencia bruta pero añade latencia: solo compensa con kits muy rápidos. Comprueba la relación real en ZenTimings o HWiNFO tras activar el perfil.","On Ryzen, the **Infinity Fabric (FCLK)** should stay in sync with the memory controller (UCLK) and the RAM: on DDR4 the ideal 1:1 was, for example, FCLK 1800 with DDR4-3600. On DDR5 the practical setup is UCLK=MCLK with FCLK decoupled (auto 2000 MHz) and the sweet spot is DDR5-6000/6400. Forcing dividers like **Gear 2** (UCLK at half rate) raises raw frequency but adds latency: it only pays off with very fast kits. Verify the real ratio in ZenTimings or HWiNFO after enabling the profile."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["xmp inestable que hacer pasos","xmp da pantallazos azules","xmp unstable troubleshooting steps","activar xmp y falla el pc"],"r":["Si **XMP** da errores o pantallazos, sigue este orden: 1) actualiza la BIOS, que mejora la compatibilidad de memoria; 2) confirma que los módulos están en A2/B2; 3) baja un escalón de frecuencia (de 6000 a 5600 MT/s) manteniendo timings; 4) sube el voltaje DRAM en pasos de 0,01-0,02 V sin pasar de 1,35-1,40 V; 5) prueba un solo módulo cada vez. Verifica cada cambio con TestMem5 u OCCT Memoria durante al menos 30-60 minutos: un solo error ya invalida el perfil.","If **XMP** gives errors or blue screens, follow this order: 1) update the BIOS, which improves memory compatibility; 2) confirm the modules are in A2/B2; 3) drop one frequency step (from 6000 to 5600 MT/s) keeping the timings; 4) raise DRAM voltage in 0.01-0.02 V steps, not exceeding 1.35-1.40 V; 5) test one module at a time. Verify each change with TestMem5 or OCCT Memory for at least 30-60 minutes: a single error already invalidates the profile."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["entrenamiento memoria ddr5 arranque lento","memory training que es","ddr5 slow boot training","pc tarda en arrancar tras xmp"],"r":["El **entrenamiento de memoria** es la calibración que la placa hace al arrancar: ajusta tiempos internos entre controlador y módulos probando hasta encontrar valores estables, y en DDR5 con perfiles altos puede tardar 30-90 segundos con la pantalla en negro y el LED DRAM encendido. No es una avería si después arranca normal. Si tu BIOS tiene Memory Context Restore (AMD) o similar, actívalo para reutilizar los valores y arrancar en segundos; si aparece inestabilidad tras hacerlo, desactívalo y deja que entrene en cada arranque.","**Memory training** is the calibration the board runs at boot: it tunes internal timings between controller and modules, testing until it finds stable values, and on DDR5 with high profiles it can take 30-90 seconds with a black screen and the DRAM LED lit. It is not a fault if the PC then boots normally. If your BIOS has Memory Context Restore (AMD) or similar, enable it to reuse the values and boot in seconds; if instability appears afterwards, disable it and let it train on every boot."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["ssd sin dram hmb","que es hmb host memory buffer","dramless ssd performance","ssd dramless vale la pena"],"r":["Un SSD **DRAM-less** ahorra el chip DRAM donde el controlador guarda el mapa de direcciones (qué bloque físico guarda cada dato) y en su lugar usa **HMB**: reserva unos 64 MB de la RAM del sistema por NVMe. En uso normal la diferencia es pequeña, pero en escrituras aleatorias sostenidas o con el disco casi lleno puede rendir menos que un modelo con DRAM. Para el disco del sistema operativo y juegos exigentes, prefiere uno con DRAM; para almacenamiento secundario, un DRAM-less bueno es perfectamente válido.","A **DRAM-less** SSD saves the DRAM chip where the controller keeps the address map (which physical block holds each piece of data) and instead uses **HMB**: it reserves about 64 MB of system RAM over NVMe. In normal use the difference is small, but under sustained random writes or with the drive nearly full it can perform worse than a DRAM model. For the OS drive and demanding games, prefer one with DRAM; for secondary storage, a good DRAM-less drive is perfectly fine."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["cache slc ssd caida velocidad","que es cache slc dinamica","ssd slow after cache full copy","copia larga ssd se hace lenta"],"r":["Muchos SSD escriben al principio en modo **caché SLC**: usan celdas TLC/QLC como si fueran de un bit, mucho más rápidas, y luego reescriben en segundo plano. Cuando copias decenas de GB seguidos, la caché (típicamente 10-40 GB según modelo y espacio libre) se agota y la velocidad cae a la nativa de la NAND: de más de 3.000 MB/s a 400-100 MB/s en un QLC. Es comportamiento normal, no avería. Dejar un 15-20 % del disco libre ayuda a que la caché sea mayor y se recupere antes.","Many SSDs initially write in **SLC cache** mode: they use TLC/QLC cells as if they were single-bit, much faster, and rewrite in the background later. When you copy tens of GB in a row, the cache (typically 10-40 GB depending on model and free space) runs out and speed drops to the NAND's native rate: from over 3,000 MB/s to 400-100 MB/s on a QLC. This is normal behavior, not a fault. Keeping 15-20% of the drive free helps the cache stay larger and recover sooner."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["nand tlc vs qlc diferencia","que es mejor tlc o qlc","tlc vs qlc endurance ssd","celdas nand slc mlc tlc qlc"],"r":["La diferencia está en los bits por celda: **TLC** guarda 3 bits y **QLC**, 4 bits en el mismo espacio, lo que abarata el GB pero hace las escrituras más lentas y reduce la resistencia. Un SSD TLC de 1 TB suele declarar 600 TBW (terabytes escritos) frente a unos 200-400 TBW de un QLC equivalente. Para sistema operativo, edición o descargas intensivas, elige TLC; el QLC tiene sentido en discos grandes de biblioteca de juegos o copias donde casi todo es lectura. Revisa siempre la ficha del modelo concreto.","The difference is bits per cell: **TLC** stores 3 bits and **QLC** stores 4 bits in the same space, which makes each GB cheaper but writes slower and endurance lower. A 1 TB TLC SSD typically rates 600 TBW (terabytes written) versus about 200-400 TBW for an equivalent QLC. For the OS, editing, or heavy downloading, choose TLC; QLC makes sense in large game-library or backup drives where almost everything is reads. Always check the specific model's spec sheet."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["disipador nvme throttling ssd","ssd se calienta baja velocidad","nvme heatsink thermal throttling","temperatura maxima ssd nvme"],"r":["Un NVMe rápido convierte su velocidad en calor: el controlador suele empezar a hacer **throttling** entre 70 y 80 °C, bajando la transferencia a veces a la mitad para protegerse. Un disipador sencillo (el que traen muchas placas, con su pad térmico bien apoyado) suele mantenerlo 10-20 °C más fresco que al aire. Comprueba la temperatura en CrystalDiskInfo o HWiNFO durante una copia larga; si nunca pasa de 65 °C, no necesitas más. En portátiles, un pad que contacte con el chasis hace la misma función.","A fast NVMe turns its speed into heat: the controller usually starts **throttling** between 70 and 80 °C, cutting transfers sometimes in half to protect itself. A simple heatsink (the one many boards include, with its thermal pad properly pressed) usually keeps it 10-20 °C cooler than bare. Check temperature in CrystalDiskInfo or HWiNFO during a long copy; if it never passes 65 °C, you need nothing more. In laptops, a pad contacting the chassis does the same job."],"href":"pc3d.html#mantenimiento"},
    {"c":"Hardware","k":["pcie gen3 gen4 gen5 ssd uso real","diferencia real nvme gen4 gen5","pcie gen5 ssd worth it games","velocidad ssd juegos carga"],"r":["En secuencial las cifras impresionan (Gen3 ~3.500 MB/s, Gen4 ~7.000 y Gen5 ~12.000-14.000), pero en **uso real** casi todo son lecturas aleatorias pequeñas y tiempos de acceso, donde las tres generaciones quedan muy cerca: cargar un juego o Windows difiere en apenas unos segundos. Gen5 además se calienta tanto que muchos modelos llevan disipador con ventilador. Compra Gen4 como estándar equilibrado; Gen5 solo compensa en trabajos con archivos enormes (edición 8K, datasets) o si el precio ya casi iguala a Gen4.","In sequential terms the numbers impress (Gen3 ~3,500 MB/s, Gen4 ~7,000 and Gen5 ~12,000-14,000), but in **real use** almost everything is small random reads and access times, where all three generations are very close: loading a game or Windows differs by barely a few seconds. Gen5 also runs so hot that many models ship with fan heatsinks. Buy Gen4 as the balanced standard; Gen5 only pays off in workloads with huge files (8K editing, datasets) or if its price nearly matches Gen4."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["atributos smart vigilar valores","smart ssd salud porcentaje","smart attributes warning values","crystaldiskinfo smart que mirar","atributos smart ssd","smart del ssd"],"r":["En **SMART** vigila sobre todo: porcentaje de vida usada (en SSD, 'Percentage Used'; al pasar del 80-90 % planifica el cambio), temperatura sostenida por encima de 70 °C, sectores reasignados o pendientes en HDD (cualquier valor creciente es malo), y errores de interfaz (UDMA CRC) que suelen indicar cable SATA defectuoso. En NVMe revisa también 'Media and Data Integrity Errors' y 'Critical Warning': deben estar a 0 siempre. CrystalDiskInfo marca en amarillo o rojo los parámetros que se salen de lo normal; ante un rojo, haz copia de seguridad antes de seguir diagnosticando.","In **SMART**, watch mainly: used-life percentage (on SSDs, 'Percentage Used'; past 80-90%, plan the replacement), sustained temperature above 70 °C, reallocated or pending sectors on HDDs (any rising value is bad), and interface errors (UDMA CRC), which usually indicate a faulty SATA cable. On NVMe also check 'Media and Data Integrity Errors' and 'Critical Warning': they must always be 0. CrystalDiskInfo flags out-of-range parameters in yellow or red; if you see red, back up before diagnosing further."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["raid 5 vs raid 10 diferencia","que raid elegir 5 o 10","raid 5 vs raid 10 explained","raid paridad vs espejo"],"r":["**RAID 5** reparte datos y paridad entre 3 o más discos: pierde solo uno de capacidad y sobrevive al fallo de un disco, pero su escritura es lenta y la reconstrucción de un disco grande tarda horas, con riesgo si falla otro. **RAID 10** espeja parejas y las suma (mínimo 4 discos): pierdes la mitad de capacidad, pero rindes más y reconstruyes rápido copiando el espejo. Para un NAS doméstico tranquilo, RAID 5; para bases de datos o máquinas virtuales, RAID 10. Y recuerda: RAID no es una copia de seguridad.","**RAID 5** stripes data and parity across 3 or more drives: it loses only one drive of capacity and survives one failure, but writes are slow and rebuilding a large drive takes hours, with risk if another fails. **RAID 10** mirrors pairs and stripes them (minimum 4 drives): you lose half the capacity, but get more performance and fast rebuilds by copying the mirror. For a quiet home NAS, RAID 5; for databases or virtual machines, RAID 10. And remember: RAID is not a backup."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["protecciones fuente ocp ovp opp scp","que significan ocp ovp opp","psu protections explained","protecciones psu lista"],"r":["Las **protecciones** son los circuitos que apagan la fuente antes de que un fallo queme el equipo: **OCP** corta por exceso de corriente en una línea, **OVP** por sobretensión de salida, **UVP** por tensión demasiado baja, **OPP** por potencia total excedida y **SCP** ante un cortocircuito; **OTP** protege por temperatura. Una fuente de calidad las trae todas, ajustadas y probadas en análisis con equipo de carga. Si una ficha solo anuncia «protecciones completas» sin detallar, desconfía: su ausencia es típica de fuentes baratas que hay que evitar.","**Protections** are the circuits that shut the PSU down before a fault burns the PC: **OCP** cuts on overcurrent on a rail, **OVP** on output overvoltage, **UVP** on voltage too low, **OPP** on total power exceeded, and **SCP** on a short circuit; **OTP** protects against temperature. A quality PSU includes all of them, properly tuned and verified in reviews with load equipment. If a spec sheet only claims 'full protections' without detail, be suspicious: missing protections are typical of cheap PSUs you should avoid."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["atx 3 conector 12v 2x6","que es 12v 2x6 fuente","atx 3.1 psu connector gpu","conector 12vhpwr diferencia"],"r":["El estándar **ATX 3.x** obliga a la fuente a soportar picos de hasta el 200 % de su potencia durante 100 microsegundos por los transitorios de las GPU modernas. Su conector de gráfica, antes 12VHPWR y ahora **12V-2x6** (ATX 3.1), lleva hasta 600 W por un solo cable con 4 pines de sensado que confirman el asiento; la versión 2x6 acorta esos pines para detectar antes un mal contacto. Regla de oro: inserta el conector hasta oír y notar el clic, sin doblar el cable en los primeros 35 mm.","The **ATX 3.x** standard requires the PSU to withstand spikes of up to 200% of its wattage for 100 microseconds, due to modern GPU transients. Its graphics connector, formerly 12VHPWR and now **12V-2x6** (ATX 3.1), carries up to 600 W over a single cable with 4 sense pins that confirm seating; the 2x6 version shortens those pins to detect a bad contact earlier. Golden rule: insert the connector until you hear and feel the click, and do not bend the cable within the first 35 mm."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["picos transitorios consumo gpu","gpu transitorios apaga pc","gpu power spikes psu shutdown","spikes consumo rtx"],"r":["Las GPU modernas generan **picos transitorios**: microráfagas de consumo de 1,5-2 veces su TDP durante milisegundos (una gráfica de 320 W puede pedir más de 500 W por un instante al cambiar de escena o cargar un mapa). Si la fuente no los tolera, su protección OCP/OPP corta y el PC se apaga sin error, como si hubieras tirado del cable. Por eso una gráfica así pide fuente ATX 3.x de 750-850 W de calidad, no solo por los vatios medios, sino por cómo responde a esos picos.","Modern GPUs produce **transient spikes**: micro-bursts drawing 1.5-2 times their TDP for milliseconds (a 320 W card can demand over 500 W for an instant when changing scenes or loading a map). If the PSU cannot tolerate them, its OCP/OPP protection trips and the PC shuts off with no error, as if you had pulled the plug. That is why such a card calls for a quality 750-850 W ATX 3.x PSU, not just for the average watts, but for how it responds to those spikes."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["leds depuracion placa cpu dram vga boot","led rojo dram placa base","motherboard debug leds meaning","ez debug led significado"],"r":["Las placas con **LEDs de depuración** detienen el proceso de arranque en el paso que falla: CPU (procesador no detectado o incompatible), DRAM (memoria en entrenamiento o incompatible), VGA (gráfica) y BOOT (sin unidad de arranque válida). Un LED DRAM fijo en DDR5 puede ser simple entrenamiento el primer arranque: espera 1-2 minutos antes de tocar nada. Si persiste, reseñala la RAM en A2/B2; VGA fijo pide recolocar la gráfica y su alimentación; BOOT fijo suele ser solo que falta sistema operativo o el disco no se detecta.","Boards with **debug LEDs** halt the boot process at the failing step: CPU (processor not detected or incompatible), DRAM (memory training or incompatible), VGA (graphics card), and BOOT (no valid boot device). A steady DRAM LED on DDR5 can be simple training on first boot: wait 1-2 minutes before touching anything. If it persists, reseat the RAM in A2/B2; a steady VGA calls for reseating the card and its power; a steady BOOT usually just means a missing OS or an undetected drive."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["codigos pitidos post bios","pitidos al arrancar pc significado","beep codes post meaning","un pitido largo tres cortos"],"r":["Los **códigos de pitidos** del POST (cuando la placa tiene buzzer) anuncian el fallo antes de que haya imagen: 1 pitido corto, arranque correcto; 1 largo y 2-3 cortos, error de vídeo en BIOS clásicas AMI/Award; pitidos continuos o repetidos, memoria o alimentación. El problema: cada fabricante usa su tabla y muchas placas actuales ni traen zumbador, sustituido por LEDs o pantalla de códigos. Anota el patrón exacto, busca la tabla de TU modelo de placa y contrasta con el LED de depuración antes de comprar recambios.","POST **beep codes** (when the board has a buzzer) announce the fault before there is any picture: 1 short beep, correct boot; 1 long and 2-3 short, video error on classic AMI/Award BIOS; continuous or repeating beeps, memory or power. The problem: each manufacturer uses its own table and many current boards have no buzzer at all, replaced by LEDs or a code display. Note the exact pattern, look up YOUR board model's table, and cross-check with the debug LED before buying replacement parts."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["clear cmos cuando y como","como hacer clear cmos","clear cmos jumper pins steps","borrar cmos tras xmp fallido"],"r":["Haz **Clear CMOS** cuando la BIOS queda inestable o el PC no arranca tras tocar XMP, voltajes o curvas: borra los ajustes y vuelve a valores de fábrica (no borra tus archivos ni el sistema). Cómo: apaga y desenchufa la fuente, espera 30 segundos, y une con un destornillador los dos pines CLR_CMOS durante 5-10 segundos según el manual (o quita la pila CR2032 unos 5 minutos si no hay pines). Después entrarás a la BIOS como la primera vez: revisa fecha, orden de arranque y vuelve a aplicar tus ajustes poco a poco.","Do a **Clear CMOS** when the BIOS becomes unstable or the PC will not boot after touching XMP, voltages, or curves: it erases the settings and returns to factory values (it does not erase your files or the OS). How: switch off and unplug the PSU, wait 30 seconds, and bridge the two CLR_CMOS pins with a screwdriver for 5-10 seconds as the manual states (or remove the CR2032 battery for about 5 minutes if there are no pins). Afterwards you will enter the BIOS like the first time: check date, boot order, and reapply your settings gradually."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["bios flashback sin cpu","que es bios flashback","bios flashback usb steps","actualizar bios sin procesador"],"r":["**BIOS Flashback** permite actualizar la BIOS solo con la fuente conectada, sin CPU ni RAM instaladas: es la salvación cuando una placa con BIOS antigua no reconoce un procesador nuevo. Pasos: en otro PC, formatea un USB en FAT32, copia el archivo renombrado exactamente como pide el fabricante (por ejemplo MSI.ROM o CAP según marca), conéctalo al puerto USB marcado como Flashback, pulsa el botón trasero y espera sin cortar la luz hasta que el LED se apague (5-10 minutos). Interrumpirlo sí puede dejar la placa inservible.","**BIOS Flashback** lets you update the BIOS with only the PSU connected, no CPU or RAM installed: it is the lifesaver when a board with an old BIOS does not recognize a new processor. Steps: on another PC, format a USB stick as FAT32, copy the file renamed exactly as the manufacturer requires (for example MSI.ROM or a CAP file depending on brand), plug it into the USB port marked Flashback, press the rear button, and wait without cutting power until the LED turns off (5-10 minutes). Interrupting it can indeed brick the board."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["actualizar bios cuando si riesgos","vale la pena actualizar bios","bios update risks when to","actualizo bios o no"],"r":["Actualiza la **BIOS** solo con un motivo concreto: compatibilidad con una CPU o RAM nueva, corrección de un fallo que sufres, vulnerabilidad de seguridad o soporte de funciones como Resizable BAR en placas antiguas. Cada versión publica su lista de cambios; si nada te afecta, no ganes un riesgo gratis. Riesgos reales: un corte de luz a mitad del proceso puede inutilizar la placa si no tiene Flashback o doble BIOS. Hazlo con el PC conectado a un SAI si puedes, desde el propio menú de la BIOS (no desde Windows) y sin tormenta eléctrica.","Update the **BIOS** only for a concrete reason: compatibility with a new CPU or RAM, a fix for a fault you actually have, a security vulnerability, or support for features like Resizable BAR on old boards. Each release publishes its changelog; if nothing affects you, do not take a free risk. Real risks: a power cut mid-process can brick the board if it lacks Flashback or dual BIOS. Do it with the PC on a UPS if possible, from the BIOS menu itself (not from Windows), and never during an electrical storm."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["csm legacy vs uefi puro","que es csm bios modo","csm vs uefi pure boot","desactivar csm windows 11"],"r":["El modo **CSM** (Compatibility Support Module) emula la BIOS antigua para arrancar discos y sistemas heredados, mientras que **UEFI puro** arranca directamente con particiones GPT y arranque seguro. Windows 11 exige UEFI: si tu disco está en MBR, con CSM funciona un Windows 10 antiguo pero no podrás activar Resizable BAR ni Secure Boot. Para migrar sin reinstalar, Windows trae la herramienta mbr2gpt que convierte el disco a GPT; haz copia antes. Regla práctica en equipos actuales: UEFI activado, CSM desactivado, y CSM solo como último recurso para hardware muy viejo.","**CSM** (Compatibility Support Module) mode emulates the legacy BIOS to boot old drives and systems, while **pure UEFI** boots directly with GPT partitions and Secure Boot. Windows 11 requires UEFI: if your drive is MBR, an old Windows 10 works with CSM but you cannot enable Resizable BAR or Secure Boot. To migrate without reinstalling, Windows includes the mbr2gpt tool, which converts the drive to GPT; back up first. Practical rule on current PCs: UEFI on, CSM off, and CSM only as a last resort for very old hardware."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["above 4g decoding que es","activar above 4g decoding bios","above 4g decoding meaning","above 4g decoding mineria resizable"],"r":["**Above 4G Decoding** permite al sistema asignar a los dispositivos PCIe (sobre todo GPUs) espacios de direcciones de memoria por encima de los 4 GB del mapa clásico de 32 bits. Sin él, una gráfica con mucha VRAM o varias tarjetas no caben en el mapa y la placa puede ni arrancar. Es además requisito previo de Resizable BAR. Actívalo en la BIOS, en la sección de PCIe/Advanced, cuando uses gráficas modernas o más de una tarjeta; en equipos sin esas necesidades puede quedarse desactivado sin ninguna penalización.","**Above 4G Decoding** lets the system assign PCIe devices (mainly GPUs) memory address spaces above the 4 GB of the classic 32-bit map. Without it, a GPU with lots of VRAM or several cards do not fit in the map and the board may not even boot. It is also a prerequisite for Resizable BAR. Enable it in the BIOS, under the PCIe/Advanced section, when using modern graphics cards or more than one card; on PCs without those needs it can stay off with no penalty."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["ftpm vs tpm discreto","que es ftpm amd intel ptt","ftpm vs discrete tpm difference","tpm windows 11 ftpm sirve"],"r":["El **fTPM** es el módulo TPM 2.0 implementado por firmware dentro de la propia CPU (AMD lo llama fTPM e Intel, PTT): cumple los requisitos de Windows 11 y de BitLocker sin comprar nada. Un **TPM discreto** es un chip físico soldado o en un pin de la placa, con su propio almacenamiento sellado: se prefiere en empresas por gestión y políticas de seguridad. Para un usuario doméstico el fTPM basta de sobra; cuidado al cambiar de CPU o hacer Clear CMOS: las claves ligadas al TPM pueden invalidarse, así que suspende BitLocker y guarda su clave de recuperación antes.","**fTPM** is the TPM 2.0 module implemented by firmware inside the CPU itself (AMD calls it fTPM, Intel PTT): it meets Windows 11 and BitLocker requirements at no extra cost. A **discrete TPM** is a physical chip soldered or on a board header, with its own sealed storage: preferred in companies for management and security policies. For a home user fTPM is more than enough; be careful when swapping CPU or doing a Clear CMOS: TPM-bound keys can be invalidated, so suspend BitLocker and save its recovery key first."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["slots ram a2 b2 dos modulos","donde poner 2 modulos ram","ram slots a2 b2 why","segundo y cuarto slot ram"],"r":["Con 2 módulos, van casi siempre en **A2 y B2**: el segundo y el cuarto slot contando desde la CPU. No es un capricho: la topología de pistas en cadena (daisy chain) de la mayoría de placas está optimizada para que el último slot de cada canal reciba la señal más limpia, y usar A1/B1 puede impedir activar XMP o bajar la frecuencia máxima. La serigrafía de la placa suele marcarlos y muchas los distinguen por color o una pestaña distinta. Consulta el manual de TU placa: en modelos con otra topología puede variar.","With 2 modules, they almost always go in **A2 and B2**: the second and fourth slots counting from the CPU. It is not arbitrary: the daisy-chain trace layout of most boards is optimized so the last slot of each channel receives the cleanest signal, and using A1/B1 can prevent enabling XMP or lower the maximum frequency. The board's silkscreen usually marks them and many distinguish them by color or a different tab. Check YOUR board's manual: on models with a different topology it can vary."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["pc no reconoce ram nueva diagnostico","instale ram nueva no arranca","new ram not detected steps","ram nueva pantalla negra"],"r":["Diagnóstico ordenado si el PC no reconoce la **RAM nueva**: 1) apaga, desenchufa y reseña cada módulo hasta oír el clic de ambas pestañas; 2) prueba un solo módulo en A2, primero el nuevo y luego el viejo, para aislar el defectuoso; 3) haz Clear CMOS, porque un perfil XMP anterior puede bloquear el arranque; 4) confirma en la lista QVL y en las especificaciones que la placa acepta esa capacidad y tipo (DDR4 y DDR5 no son intercambiables ni encajan en la misma ranura); 5) si arranca con uno, añade el segundo y deja que entrene.","Ordered diagnosis if the PC does not recognize the **new RAM**: 1) switch off, unplug, and reseat each module until both tabs click; 2) test a single module in A2, first the new one then the old, to isolate the faulty one; 3) do a Clear CMOS, because a previous XMP profile can block booting; 4) confirm on the QVL list and specs that the board accepts that capacity and type (DDR4 and DDR5 are not interchangeable nor fit the same slot); 5) if it boots with one, add the second and let it train."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["memtest86 detectar ram defectuosa","como usar memtest86 usb","memtest86 errors meaning","cuantas pasadas memtest"],"r":["**MemTest86** se ejecuta desde un USB arrancable, fuera de Windows, y escribe patrones en toda la RAM buscando bits que se corrompen: es la prueba de referencia para memoria defectuosa. Crea el USB con su instalador, arranca desde él y deja completar al menos 4 pasadas (puede tardar 1-3 horas según capacidad y velocidad). El resultado válido es cero errores: un solo error ya justifica probar módulo a módulo para identificar el malo y tramitar garantía. Si falla solo con XMP y pasa a velocidad JEDEC, el problema es estabilidad del perfil, no la memoria.","**MemTest86** runs from a bootable USB stick, outside Windows, and writes patterns across all RAM looking for corrupted bits: it is the reference test for faulty memory. Create the USB with its installer, boot from it, and let at least 4 passes complete (it can take 1-3 hours depending on capacity and speed). The valid result is zero errors: a single error already justifies testing module by module to identify the bad one and claim warranty. If it fails only under XMP and passes at JEDEC speed, the problem is profile stability, not the memory."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["prueba estres cpu prime95 interpretacion","prime95 small fft blend diferencia","cpu stress test prime95 temps","prime95 error hardware failure"],"r":["**Prime95** estresa la CPU con transformadas de Fourier: el modo Small FFTs carga al máximo núcleos y caché (peor caso de calor y consumo, ideal para probar refrigeración y VRM), Blend mezcla RAM, y Large FFTs es intermedio. Interprétalo así: error o 'hardware failure' en un worker en minutos indica inestabilidad (overclock, undervolt o RAM), no sigas; temperaturas de 90-100 °C en Small FFTs son normales en CPUs modernas con boost y no representan juegos, donde verás 15-25 °C menos. Para un equipo de diario, 30-60 minutos sin errores es una señal razonable.","**Prime95** stresses the CPU with Fourier transforms: Small FFTs mode loads cores and cache to the maximum (worst case for heat and power draw, ideal for testing cooling and VRM), Blend mixes in RAM, and Large FFTs is in between. Read it this way: an error or 'hardware failure' in a worker within minutes indicates instability (overclock, undervolt, or RAM), so stop there; 90-100 °C in Small FFTs is normal on modern boosting CPUs and does not represent gaming, where you will see 15-25 °C less. For an everyday PC, 30-60 minutes with no errors is a reasonable signal."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["furmark uso precaucion","furmark puede danar grafica","furmark stress test gpu safe","furmark quema graficas mito"],"r":["**FurMark** dibuja una escena diseñada para disparar el consumo de la GPU al máximo teórico, más que cualquier juego: es útil 5-10 minutos para comprobar temperaturas, ruido y si la fuente aguanta, pero no como tortura de horas. Las GPUs modernas se autoprotegen con límites de potencia y temperatura, así que el riesgo real es bajo en tarjetas sanas con buena ventilación; el peligro aparece en gráficas con VRM débil, fuentes justas o pasta reseca. Si sale artefacto o se apaga con FurMark, apaga también la prueba: ya tienes el diagnóstico, no insistas.","**FurMark** renders a scene designed to push GPU power draw to its theoretical maximum, more than any game: it is useful for 5-10 minutes to check temperatures, noise, and whether the PSU holds up, but not as an hours-long torture. Modern GPUs protect themselves with power and temperature limits, so the real risk is low on healthy cards with good airflow; danger appears on cards with weak VRM, borderline PSUs, or dried paste. If artifacts show or it shuts down under FurMark, stop the test too: you already have the diagnosis, do not insist."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["artefactos visuales gpu fallando","cuadros colores pantalla artefactos","gpu artifacts dying signs","artefactos grafica vram"],"r":["Los **artefactos visuales** (cuadros de colores, píxeles que parpadean, texturas corruptas o líneas) suelen apuntar a la VRAM o al núcleo de la GPU fallando, sobre todo si aparecen también en la BIOS o en el escritorio, fuera de cualquier juego. Antes de condenarla, descarta lo barato: prueba otro cable y otro monitor, baja cualquier overclock de memoria de la GPU a valores de fábrica y reinstala el driver limpio con DDU. Si los artefactos siguen en frío y sin carga en otro PC, la tarjeta está muriendo; haz copia de lo importante y piensa en la garantía.","**Visual artifacts** (colored squares, flickering pixels, corrupted textures, or lines) usually point to failing VRAM or GPU core, especially if they also appear in the BIOS or on the desktop, outside any game. Before condemning it, rule out the cheap things: try another cable and another monitor, drop any GPU memory overclock back to stock, and clean-reinstall the driver with DDU. If artifacts persist cold and idle on another PC, the card is dying; back up what matters and think about the warranty."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["screen tearing vs stuttering diferencia","que es tearing y stuttering","screen tearing vs stutter explained","imagen partida vs tirones"],"r":["El **screen tearing** es una imagen partida: la pantalla muestra la mitad de un frame y la mitad del siguiente porque la GPU entrega frames sin sincronizar con el refresco; se cura con V-Sync o sincronización adaptiva (G-Sync/FreeSync). El **stuttering** son tirones: frames que llegan a intervalos irregulares (uno a 16 ms, el siguiente a 45 ms) aunque los FPS medios parezcan buenos; sus causas son frametimes inestables, shaders compilando o un cuello de botella. Son problemas distintos con soluciones distintas: identifica primero cuál ves, porque activar lo equivocado no lo arregla.","**Screen tearing** is a split image: the display shows half of one frame and half of the next because the GPU delivers frames unsynchronized with the refresh; it is cured by V-Sync or adaptive sync (G-Sync/FreeSync). **Stuttering** is hitching: frames arriving at irregular intervals (one at 16 ms, the next at 45 ms) even though average FPS look good; its causes are unstable frametimes, shader compilation, or a bottleneck. They are different problems with different fixes: first identify which one you see, because enabling the wrong thing will not fix it."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["frametime minimos 1 0.1 lows","que son 1 percent lows","frametime vs fps fluidity","0.1 lows stutter meaning"],"r":["Los FPS medios engañan: lo que decide la fluidez percibida es el **frametime** (milisegundos entre frames) y los mínimos **1 % y 0,1 % lows**, el promedio de los frames más lentos. Un juego a 90 FPS medios con un 1 % de 30 FPS se sentirá a tirones, porque esos frames tardan más de 33 ms. Mídelo con CapFrameX o el overlay de RTSS tras 5-10 minutos de partida real. Objetivo sano: que el 1 % esté al menos al 60-70 % de la media; si no, busca picos de CPU, RAM al límite o shaders en compilación.","Average FPS deceive: what decides perceived smoothness is **frametime** (milliseconds between frames) and the **1% and 0.1% lows**, the average of the slowest frames. A game at 90 average FPS with a 1% of 30 FPS will feel hitchy, because those frames take over 33 ms. Measure it with CapFrameX or the RTSS overlay after 5-10 minutes of real gameplay. Healthy target: the 1% at least at 60-70% of the average; if not, look for CPU spikes, RAM at its limit, or shader compilation."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["path tracing vs ray tracing diferencia","que es path tracing","path tracing vs ray tracing cost","trazado de caminos juegos"],"r":["El **ray tracing** de los juegos actuales es híbrido: rasteriza la escena y lanza pocos rayos (1-2 por píxel, con denoiser) para reflejos, sombras o iluminación concretos. El **path tracing** simula el recorrido completo de la luz con múltiples rebotes por píxel, generando la imagen entera por física, con un coste de 3 a 10 veces mayor: por eso solo unos pocos juegos lo ofrecen como modo especial y piden DLSS/FSR con generación de frames. Visualmente, el path tracing da rebotes de luz y sombras de contacto mucho más coherentes, a cambio de necesitar una GPU de gama alta.","Current games' **ray tracing** is hybrid: it rasterizes the scene and shoots few rays (1-2 per pixel, with a denoiser) for specific reflections, shadows, or lighting. **Path tracing** simulates the full path of light with multiple bounces per pixel, generating the whole image from physics, at 3 to 10 times the cost: that is why only a few games offer it as a special mode and require DLSS/FSR with frame generation. Visually, path tracing gives far more coherent light bounces and contact shadows, in exchange for needing a high-end GPU."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["hdmi 2.0 vs 2.1 4k 120hz","hdmi 2.0 no llega 4k 120","hdmi 2.1 bandwidth 48 gbps","cable hdmi ultra high speed"],"r":["Para 4K a 120 Hz necesitas **HDMI 2.1**: su ancho de banda de 48 Gbps admite 4K@120 en 10 bits sin compresión, mientras **HDMI 2.0** llega a 18 Gbps y se queda en 4K@60 (o 4K@120 solo con chroma 4:2:0, perdiendo nitidez en texto). El cable importa: busca la certificación Ultra High Speed; un cable 2.0 antiguo puede dar pantalla negra o bajar el refresco sin avisar. DisplayPort 1.4 también logra 4K@120 con DSC. Comprueba además que el puerto concreto de la TV o monitor sea el 2.1, porque a menudo solo uno o dos lo son.","For 4K at 120 Hz you need **HDMI 2.1**: its 48 Gbps bandwidth supports 4K@120 in 10-bit without compression, while **HDMI 2.0** tops out at 18 Gbps and stays at 4K@60 (or 4K@120 only with 4:2:0 chroma, losing text sharpness). The cable matters: look for Ultra High Speed certification; an old 2.0 cable can cause a black screen or silently drop the refresh rate. DisplayPort 1.4 also achieves 4K@120 with DSC. Also check that the specific port on the TV or monitor is the 2.1 one, since often only one or two are."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["dsc compresion displayport que es","display stream compression dsc","dsc lossy or lossless visually","4k 240hz dsc necesario"],"r":["**DSC** (Display Stream Compression) comprime el vídeo en tiempo real para que quepa por el cable: es compresión con pérdida matemáticamente, pero visualmente sin pérdida (visually lossless), diseñada para que ni en pruebas ciegas se distinga del original a las tasas usadas (hasta 3:1). Gracias a DSC, DisplayPort 1.4 alcanza 4K@240 Hz o 8K@60, resoluciones imposibles con sus 32,4 Gbps en crudo. Actívalo en la GPU y el monitor cuando el modo que buscas lo exija; algún monitor antiguo con DSC puede tardar más en recuperar señal al cambiar de ventana, es un efecto conocido.","**DSC** (Display Stream Compression) compresses video in real time so it fits through the cable: it is mathematically lossy compression, but visually lossless, designed so that even in blind tests it is indistinguishable from the original at the ratios used (up to 3:1). Thanks to DSC, DisplayPort 1.4 reaches 4K@240 Hz or 8K@60, resolutions impossible with its raw 32.4 Gbps. Enable it on GPU and monitor when the mode you want requires it; some older DSC monitors may take longer to recover signal when alt-tabbing, a known effect."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["thunderbolt 4 vs usb4 diferencia","usb4 vs thunderbolt 4 que cambia","thunderbolt 4 mandatory specs","puerto usb4 es thunderbolt"],"r":["**USB4** es el estándar abierto (hasta 40 Gbps, tuneliza DisplayPort y PCIe) pero con mínimos opcionales según el equipo; **Thunderbolt 4** es la certificación de Intel sobre USB4 que hace obligatorios esos mínimos: siempre 40 Gbps, siempre vídeo hasta dos pantallas 4K o una 8K, datos PCIe de 32 Gbps y carga de hasta 100 W disponible en el puerto. En la práctica, un puerto Thunderbolt 4 garantiza la experiencia completa con docks, y un USB4 puede quedarse corto según el fabricante. El conector es el mismo USB-C en ambos.","**USB4** is the open standard (up to 40 Gbps, tunnels DisplayPort and PCIe) but with optional minimums depending on the device; **Thunderbolt 4** is Intel's certification on top of USB4 that makes those minimums mandatory: always 40 Gbps, always video up to two 4K displays or one 8K, 32 Gbps PCIe data, and up to 100 W charging available at the port. In practice, a Thunderbolt 4 port guarantees the full dock experience, while a USB4 port may fall short depending on the manufacturer. The connector is the same USB-C on both."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["displayport alt mode usb c","usb c salida video alt mode","displayport alt mode meaning","mi usb c no da video por que"],"r":["El **DisplayPort Alt Mode** permite que un puerto USB-C envíe señal de vídeo DisplayPort por los pines del conector, usando hasta 4 carriles para imagen (y dejando USB reducido a 2.0 si se usan todos) o 2 carriles compartiendo con datos USB 3.x. No todos los USB-C lo tienen: es opcional y suele anunciarse con el logo de DisplayPort o un icono de rayo/pantalla junto al puerto. Si tu portátil no lo soporta, un adaptador pasivo no servirá; necesitarás una dock con chip propio (DisplayLink) o el puerto HDMI del equipo.","**DisplayPort Alt Mode** lets a USB-C port send DisplayPort video signal over the connector's pins, using up to 4 lanes for video (leaving USB reduced to 2.0 if all are used) or 2 lanes shared with USB 3.x data. Not every USB-C port has it: it is optional and is usually advertised with the DisplayPort logo or a bolt/display icon next to the port. If your laptop does not support it, a passive adapter will not work; you will need a dock with its own chip (DisplayLink) or the machine's HDMI port."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["usb power delivery vatios perfiles","que es usb pd perfiles voltaje","usb pd 240w epr profiles","cargador usb pd watts laptop"],"r":["**USB Power Delivery** negocia voltaje y corriente entre cargador y equipo: los perfiles clásicos son 5 V, 9 V, 15 V y 20 V, con topes de 15, 27, 45, 60 y 100 W según amperios (máximo 5 A con cables con chip e-marker). La revisión EPR eleva el máximo a 240 W con 28, 36 y 48 V para portátiles gaming. Reglas prácticas: el equipo solo toma lo que pide, un cargador mayor no daña, pero un cable básico limita a 60 W aunque el cargador sea de 100 W; para más de 60 W usa cable certificado con e-marker.","**USB Power Delivery** negotiates voltage and current between charger and device: the classic profiles are 5 V, 9 V, 15 V, and 20 V, with caps of 15, 27, 45, 60, and 100 W depending on amps (maximum 5 A with e-marker cables). The EPR revision raises the maximum to 240 W with 28, 36, and 48 V for gaming laptops. Practical rules: the device only takes what it requests, a bigger charger does no harm, but a basic cable caps at 60 W even if the charger is 100 W; above 60 W use a certified e-marker cable."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["ciclos carga salud bateria portatil","cuantos ciclos dura bateria laptop","laptop battery cycles health","limitar carga 80 por ciento bateria"],"r":["Una batería de portátil se mide en **ciclos de carga**: un ciclo es gastar el 100 % acumulado (dos veces el 50 % también suman uno), y lo típico es conservar el 80 % de capacidad tras 300-500 ciclos en modelos normales. El calor y vivir al 100 % enchufada aceleran la degradación tanto como los ciclos. Si tu equipo tiene opción de limitar la carga al 80 % en la BIOS o en su software, actívala para uso de escritorio; cárgala al 100 % solo antes de viajar. Consulta los ciclos acumulados con powercfg /batteryreport en Windows.","A laptop battery is measured in **charge cycles**: one cycle is using 100% accumulated (twice 50% also adds up to one), and typically 80% capacity remains after 300-500 cycles on normal models. Heat and living plugged in at 100% accelerate degradation as much as cycles do. If your machine has an option to limit charging to 80% in the BIOS or its software, enable it for desk use; charge to 100% only before traveling. Check accumulated cycles with powercfg /batteryreport on Windows."],"href":"pc3d.html#mantenimiento"},
    {"c":"Hardware","k":["bateria hinchada que hacer que no","bateria portatil hinchada peligro","swollen battery what to do","spicy pillow bateria movil"],"r":["Una **batería hinchada** (tapa que se levanta, touchpad abombado o pantalla que no cierra) significa gases acumulados en la celda: es un riesgo real de incendio si se perfora o se sigue cargando. Qué hacer: apaga el equipo, desenchúfalo, deja de usarlo y no lo cargues más; llévala a un servicio técnico o punto limpio para extraerla y reciclarla. Qué no hacer: nunca pincharla ni presionarla para «desinflarla», no meterla en agua ni a la basura doméstica, y no seguir usándola por muy bien que aun encienda. No es reparable: se sustituye.","A **swollen battery** (a lifting lid, a bulging touchpad, or a screen that no longer closes) means gas built up inside the cell: it is a real fire risk if punctured or kept charging. What to do: shut the device down, unplug it, stop using it, and do not charge it again; take it to a service center or recycling point to be removed and recycled. What not to do: never puncture it or press it to 'deflate' it, do not put it in water or household trash, and do not keep using it no matter how well it still turns on. It cannot be repaired: it must be replaced."],"href":"pc3d.html#mantenimiento"},
    {"c":"Redes","k":["que es la mtu y la fragmentacion","mtu 1500 fragmentacion ip","por que se fragmenta un paquete","what is mtu fragmentation","mtu size explained"],"r":["La **MTU** de Ethernet es 1500 bytes: es el payload máximo por trama. Si un paquete IP de 1600 bytes debe salir por esa interfaz y lleva activo el bit DF (no fragmentar), el router lo descarta y responde ICMP tipo 3 código 4 indicando la MTU del salto. Sin DF, el paquete se fragmenta: cada fragmento lleva cabecera IP propia de 20 bytes, comparte el mismo ID de fragmentación y solo el primero transporta la cabecera TCP o UDP, lo que complica a firewalls y NAT.","The Ethernet **MTU** is 1500 bytes: the maximum payload per frame. If a 1600-byte IP packet must leave through that interface with the DF (do not fragment) bit set, the router drops it and replies ICMP type 3 code 4 stating the hop MTU. Without DF, the packet is fragmented: each fragment carries its own 20-byte IP header, shares the same fragmentation ID, and only the first one carries the TCP or UDP header, which complicates firewalls and NAT."],"href":"redes.html#redes"},
    {"c":"Redes","k":["que son los jumbo frames","jumbo frames 9000 para que sirven","mtu 9000 en una lan","what are jumbo frames"],"r":["Los **jumbo frames** elevan la MTU de 1500 a 9000 bytes, típica en LAN, SAN y enlaces entre servidores. Con paquetes de 9000, la sobrecarga de cabeceras baja del 3,8 % aproximado al 0,6 % y la CPU procesa unas 6 veces menos paquetes por gigabyte movido. La condición es estricta: todos los equipos del camino (NIC, switch y router) deben soportar y tener configurada la misma MTU; si un salto sigue en 1500, habrá fragmentación o descartes silenciosos que se notan como cuelgues raros en copias grandes.","**Jumbo frames** raise the MTU from 1500 to 9000 bytes, typical on LANs, SANs and server-to-server links. With 9000-byte packets, header overhead drops from roughly 3.8% to 0.6% and the CPU processes about 6 times fewer packets per gigabyte moved. The condition is strict: every device on the path (NIC, switch and router) must support and be configured with the same MTU; if one hop stays at 1500, you get fragmentation or silent drops that show up as weird stalls on large copies."],"href":"redes.html#redes"},
    {"c":"Redes","k":["como probar la mtu con ping","ping -f -l buscar mtu maxima","comando para saber mi mtu real","how to test mtu with ping"],"r":["Para encontrar la MTU real del camino usa ping con **DF** activado y tamaño exacto: en Windows, ping -f -l 1472 -n 4 8.8.8.8. Los 1472 bytes de datos más 28 de cabeceras IP e ICMP suman 1500. Si responde, el camino admite 1500; si dice que el paquete debe fragmentarse, baja de 10 en 10 (1464, 1452…) hasta que pase. En Linux el equivalente es ping -M do -s 1472. La MTU útil será el mayor tamaño que responde, más 28.","To find the real path MTU, ping with **DF** set and an exact size: on Windows, ping -f -l 1472 -n 4 8.8.8.8. The 1472 data bytes plus 28 bytes of IP and ICMP headers add up to 1500. If it replies, the path supports 1500; if it says the packet needs fragmentation, step down by 10 (1464, 1452…) until it passes. On Linux the equivalent is ping -M do -s 1472. The usable MTU is the largest size that replies, plus 28."],"href":"redes.html#simulador-red"},
    {"c":"Redes","k":["como interpretar tracert","asteriscos en tracert que significan","latencia por salto en traceroute","how to read tracert output","traceroute asterisks meaning"],"r":["**tracert** (traceroute en Linux) envía paquetes con TTL creciente: 1, 2, 3… y cada router que lo reduce a cero responde con un ICMP tiempo excedido, revelando el salto. Los asteriscos de una línea no siempre son un corte: muchos routers limitan o bloquean esas respuestas, y si el salto siguiente responde, el camino sigue vivo. La latencia que importa es la del destino final: un salto intermedio puede tardar 120 ms por priorizar mal el ICMP y aun así reenviar el tráfico a 15 ms.","**tracert** (traceroute on Linux) sends packets with increasing TTL: 1, 2, 3… and each router that decrements it to zero replies with an ICMP time exceeded, revealing the hop. Asterisks on one line are not always a cut: many routers rate-limit or block those replies, and if the next hop answers, the path is still alive. The latency that matters is the final destination's: an intermediate hop may take 120 ms because it deprioritizes ICMP while still forwarding your traffic at 15 ms."],"href":"redes.html#simulador-red"},
    {"c":"Redes","k":["winmtr perdida en un salto intermedio","perdida de paquetes en winmtr es real","como leer los resultados de winmtr","winmtr packet loss intermediate hop"],"r":["**WinMTR** combina ping y tracert enviando paquetes continuos a cada salto y calculando pérdida y latencia media, peor y última. La regla de oro: la pérdida real es la del destino final. Si el salto 4 muestra 40 % de pérdida pero el destino y los saltos posteriores muestran 0 %, ese router simplemente descarta parte del ICMP de control, no tu tráfico. En cambio, si la pérdida nace en un salto y se mantiene igual o crece hasta el final, el problema está en ese tramo o en su enlace de salida.","**WinMTR** combines ping and tracert by sending continuous packets to every hop and computing loss plus average, worst and last latency. The golden rule: real loss is the final destination's loss. If hop 4 shows 40% loss but the destination and later hops show 0%, that router is simply dropping some control ICMP, not your traffic. However, if loss starts at one hop and stays the same or grows all the way to the end, the problem is on that segment or its outgoing link."],"href":"redes.html#simulador-red"},
    {"c":"Redes","k":["que es el bufferbloat","bufferbloat como solucionarlo con sqm","latencia alta cuando subo archivos","what is bufferbloat and sqm"],"r":["El **bufferbloat** aparece cuando el router acumula colas enormes al saturar la subida o la bajada: el ancho de banda parece bueno, pero la latencia bajo carga pasa de 15 ms a 400 ms y las videollamadas se congelan. Se diagnostica con un test de latencia bajo carga (por ejemplo el de Waveform). La solución es SQM con cake o fq_codel, disponible en muchos routers: actívalo y fija el límite al 85-90 % de tu velocidad real; si tu plan es 100/20, prueba 90/18 y mide de nuevo.","**Bufferbloat** appears when the router builds up huge queues as upload or download saturates: bandwidth looks fine, but latency under load jumps from 15 ms to 400 ms and video calls freeze. Diagnose it with a latency-under-load test (for example Waveform's). The fix is SQM with cake or fq_codel, available on many routers: enable it and cap the limit at 85-90% of your real speed; if your plan is 100/20, try 90/18 and measure again."],"href":"redes.html#redes"},
    {"c":"Redes","k":["como detectar doble nat","tengo doble nat en mi red","ip wan privada doble nat","how to detect double nat"],"r":["Hay **doble NAT** cuando tu router recibe en su puerto WAN una IP privada (192.168.x.x, 10.x.x.x o 172.16-31.x.x) en vez de una pública: otro router del ISP ya está traduciendo antes que el tuyo. Se detecta en 1 minuto: mira la IP WAN en el panel de tu router y compárala con la que muestra una web tipo what is my IP; si difieren, hay doble NAT o CGNAT. Consecuencias típicas: puertos imposibles de abrir, NAT estricta en consolas y VPN que no conecta desde fuera.","There is **double NAT** when your router receives a private IP (192.168.x.x, 10.x.x.x or 172.16-31.x.x) on its WAN port instead of a public one: another ISP router is already translating before yours. Detect it in 1 minute: check the WAN IP in your router's panel and compare it with what a what is my IP site shows; if they differ, there is double NAT or CGNAT. Typical consequences: ports you cannot open, strict NAT on consoles and VPNs that will not connect from outside."],"href":"redes.html#redes"},
    {"c":"Redes","k":["como abrir puertos en el router","port forwarding paso a paso","abrir un puerto es peligroso","how to port forward safely","como abro los puertos del router","abro un puerto en el router","abrir los puertos del router"],"r":["El **port forwarding** se configura en el router en 4 pasos: 1) fija la IP del equipo destino con reserva DHCP, por ejemplo 192.168.1.50; 2) crea la regla con puerto externo, puerto interno (pueden coincidir), protocolo TCP, UDP o ambos y esa IP; 3) permite ese puerto en el firewall del propio equipo; 4) prueba desde fuera de tu red, nunca desde dentro. Riesgos: cada puerto abierto es una puerta pública; expón solo servicios actualizados, con contraseña fuerte, y cierra la regla cuando ya no la uses.","**Port forwarding** is set up on the router in 4 steps: 1) pin the target device's IP with a DHCP reservation, for example 192.168.1.50; 2) create the rule with external port, internal port (they may match), protocol TCP, UDP or both, and that IP; 3) allow that port in the device's own firewall; 4) test from outside your network, never from inside. Risks: every open port is a public door; expose only updated services with strong passwords, and delete the rule when you no longer use it."],"href":"redes.html#redes"},
    {"c":"Redes","k":["que es upnp y para que sirve","upnp es seguro dejarlo activado","por que desactivar upnp","should i disable upnp"],"r":["**UPnP** permite que cualquier programa de tu red le pida al router que abra puertos automáticamente, sin contraseña y sin avisar. Es cómodo para consolas y P2P, pero un malware que entre en un PC puede usarlo para exponerse a internet o abrir paso a otros ataques; además, varias implementaciones de UPnP en routers domésticos han tenido fallos graves. Recomendación práctica: desactívalo en el router y, si un juego o servicio lo necesita, crea la regla de puertos manualmente solo para ese equipo y ese puerto.","**UPnP** lets any program on your network ask the router to open ports automatically, with no password and no warning. It is convenient for consoles and P2P, but malware that gets into a PC can use it to expose itself to the internet or pave the way for other attacks; several home-router UPnP implementations have also had serious flaws. Practical advice: disable it on the router and, if a game or service needs it, create the port rule manually only for that device and that port."],"href":"redes.html#redes"},
    {"c":"Redes","k":["nat abierta moderada o estricta en consola","nat estricta como solucionarla","tipos de nat en playstation y xbox","strict nat how to fix","open vs moderate nat"],"r":["La **NAT** de consolas se clasifica por lo fácil que otros te pueden contactar. Abierta (tipo 1 o 2 en PlayStation): puedes crear partidas y hablar con todos. Moderada: juegas, pero no siempre puedes unirte a quien también tenga NAT moderada o estricta, y el chat de voz falla a ratos. Estricta (tipo 3): solo te conectas con NAT abierta y aparecen errores de grupo. Se mejora con IP fija o reserva para la consola, abriendo sus puertos o activando UPnP, y eliminando la doble NAT si existe.","Console **NAT** is classified by how easily others can reach you. Open (type 1 or 2 on PlayStation): you can host games and talk to everyone. Moderate: you can play, but you cannot always join players who also have moderate or strict NAT, and voice chat fails intermittently. Strict (type 3): you can only connect to open NAT players and party errors appear. Improve it with a fixed IP or reservation for the console, opening its ports or enabling UPnP, and removing double NAT if present."],"href":"redes.html#redes"},
    {"c":"Redes","k":["reserva dhcp o ip fija que es mejor","diferencia entre reserva dhcp e ip fija","como asignar siempre la misma ip","dhcp reservation vs static ip"],"r":["Con **reserva DHCP** el router siempre entrega la misma IP a la MAC de un equipo, por ejemplo 192.168.1.50, pero la configuración sigue siendo centralizada y automática. Con IP fija manual en el equipo, la IP se escribe en su configuración y el router no interviene: si pones una IP dentro del rango DHCP sin reservarla, otro equipo puede recibirla y causar un conflicto. Regla práctica: reserva en el router para servidores, impresoras y consolas; deja la IP automática en el resto, y documenta cada reserva.","With a **DHCP reservation**, the router always hands the same IP to a device's MAC, for example 192.168.1.50, while configuration stays centralized and automatic. With a manual static IP on the device, the address is typed into its own settings and the router is not involved: if you pick an IP inside the DHCP pool without reserving it, another device may receive it and cause a conflict. Practical rule: reserve on the router for servers, printers and consoles; leave everything else on automatic IP, and document each reservation."],"href":"redes.html#redes"},
    {"c":"Redes","k":["que es el lease de dhcp","tiempo de concesion dhcp cuanto poner","cada cuanto renueva la ip el dhcp","dhcp lease time explained"],"r":["El **lease** o tiempo de concesión es cuánto dura la IP que el DHCP presta a un equipo: 24 horas es lo típico en casa. Al llegar al 50 % del tiempo, el equipo pide renovar la misma IP; si el servidor no responde, sigue usándola hasta agotar el lease y entonces pide una nueva. Un lease muy corto, de minutos, genera tráfico y cortes innecesarios; uno de días facilita que invitados agoten el rango. En redes domésticas, 12-24 horas es el equilibrio razonable.","The **lease** time is how long the IP that DHCP lends to a device lasts: 24 hours is typical at home. At 50% of the time, the device asks to renew the same IP; if the server does not answer, it keeps using it until the lease expires and then requests a new one. A very short lease, just minutes, creates needless traffic and drops; one lasting days makes it easier for guests to exhaust the pool. On home networks, 12-24 hours is the sensible balance."],"href":"redes.html#redes"},
    {"c":"Redes","k":["conflicto de ip duplicada como resolverlo","dos equipos con la misma ip","windows detecto un conflicto de direccion ip","ip address conflict how to fix"],"r":["Un **conflicto de IP** aparece cuando dos equipos usan la misma dirección, por ejemplo 192.168.1.50: Windows avisa de dirección duplicada y la conexión va y viene porque la tabla ARP del router alterna entre las dos MAC. Se resuelve en orden: localiza qué equipos reclaman esa IP (arp -a y panel del router), deja solo un dueño, cambia la IP manual del intruso o crea la reserva DHCP correspondiente, y renueva con ipconfig /release e ipconfig /renew. Si fue por una IP fija dentro del rango DHCP, muévela fuera de ese rango.","An **IP conflict** appears when two devices use the same address, for example 192.168.1.50: Windows warns about a duplicate address and the connection comes and goes because the router's ARP table alternates between the two MACs. Fix it in order: find which devices claim that IP (arp -a and the router's panel), leave only one owner, change the intruder's manual IP or create the matching DHCP reservation, and renew with ipconfig /release and ipconfig /renew. If it came from a static IP inside the DHCP pool, move it outside that range."],"href":"redes.html#redes"},
    {"c":"Redes","k":["ip 169.254 que significa","mi pc tiene ip 169.254 y no hay internet","que es apipa","169.254 ip address no dhcp"],"r":["Si un equipo queda con una IP **169.254.x.x**, está usando APIPA: no obtuvo respuesta del servidor DHCP y se autoasignó una dirección del rango 169.254.0.0/16, válida solo para hablar con otros equipos igual de perdidos en el mismo cable. Ese equipo no tiene puerta de enlace ni internet. Diagnóstico en orden: cable o Wi-Fi realmente conectado, router encendido, servicio DHCP activo en el router, y prueba con ipconfig /release seguido de ipconfig /renew. Si otro equipo sí recibe IP, el problema es local de ese equipo.","If a device ends up with a **169.254.x.x** IP, it is using APIPA: it got no answer from the DHCP server and self-assigned an address from the 169.254.0.0/16 range, valid only to talk to other equally lost devices on the same cable. That device has no gateway and no internet. Diagnose in order: cable or Wi-Fi actually connected, router powered on, DHCP service enabled on the router, and test with ipconfig /release followed by ipconfig /renew. If another device does get an IP, the problem is local to that one."],"href":"redes.html#redes"},
    {"c":"Redes","k":["doh vs dot diferencia","dns over https o dns over tls","que es doh y dot","doh vs dot explained"],"r":["**DoH** y DoT cifran las consultas DNS para que nadie en la red espíe qué dominios pides ni los manipule. DoT (DNS over TLS) usa un puerto dedicado, el 853, fácil de identificar y de bloquear en un firewall. DoH (DNS over HTTPS) viaja dentro del HTTPS normal por el puerto 443, mezclado con el tráfico web: más difícil de bloquear, y por eso los navegadores lo activan por su cuenta. En rendimiento la diferencia es mínima; en control de red, DoT es más transparente para el administrador.","**DoH** and DoT encrypt DNS queries so nobody on the network can spy on which domains you request or tamper with them. DoT (DNS over TLS) uses a dedicated port, 853, easy to identify and to block in a firewall. DoH (DNS over HTTPS) travels inside normal HTTPS on port 443, mixed with web traffic: harder to block, which is why browsers enable it on their own. In performance the difference is minimal; for network control, DoT is more transparent for the administrator."],"href":"redes.html#redes"},
    {"c":"Redes","k":["cambiar el dns a 1.1.1.1 ayuda","poner dns de google 8.8.8.8 sirve","cuando conviene cambiar los dns","does changing dns make internet faster"],"r":["Cambiar el DNS a **1.1.1.1** (Cloudflare) o 8.8.8.8 (Google) ayuda en casos concretos: si el DNS de tu ISP es lento, se cae o resuelve mal algunos dominios, notarás que las webs empiezan a cargar antes y desaparecen errores de nombre no encontrado. No acelera descargas ni baja el ping del juego, porque cuando la conexión ya existe el DNS ya no interviene. Se cambia en el router, para toda la casa, o solo en un equipo para probar; anota el DNS anterior antes de tocar nada.","Switching DNS to **1.1.1.1** (Cloudflare) or 8.8.8.8 (Google) helps in specific cases: if your ISP's DNS is slow, goes down or mis-resolves some domains, you will notice websites starting to load sooner and name-not-found errors disappearing. It does not speed up downloads or lower in-game ping, because once the connection exists DNS is no longer involved. Change it on the router for the whole home, or on a single device to test; write down the previous DNS before touching anything."],"href":"redes.html#redes"},
    {"c":"Redes","k":["registros dns a aaaa cname mx txt","que es un registro cname","para que sirve el registro mx","dns record types explained"],"r":["Los **registros DNS** de un dominio son sus instrucciones públicas. A apunta el nombre a una IPv4 y AAAA a una IPv6. CNAME crea un alias hacia otro nombre (www puede apuntar al dominio raíz). MX indica qué servidores reciben el correo y con qué prioridad, por ejemplo MX 10 y MX 20 de respaldo. TXT guarda textos de verificación y políticas como SPF y DKIM. Un error típico: crear un CNAME donde hacía falta un A, o tardar horas en ver el cambio por el TTL.","A domain's **DNS records** are its public instructions. A points the name to an IPv4 and AAAA to an IPv6. CNAME creates an alias to another name (www can point to the root domain). MX states which servers receive the mail and with what priority, for example MX 10 and a backup MX 20. TXT stores verification texts and policies such as SPF and DKIM. A typical mistake: creating a CNAME where an A record was needed, or waiting hours to see a change because of the TTL."],"href":"redes.html#redes"},
    {"c":"Redes","k":["que es el ttl del dns","cuanto tarda en propagar un dns","bajar el ttl antes de migrar","dns ttl and propagation time"],"r":["El **TTL** de un registro DNS es, en segundos, cuánto tiempo pueden cachearlo los resolvers: con TTL 3600, un cambio puede tardar hasta 1 hora en verse en todo internet, y con 86400, hasta 24 horas. Por eso, antes de migrar un servidor se baja el TTL a 300 el día anterior, se hace el cambio en la ventana de mínimo impacto y luego se vuelve a subir. Comprueba la propagación con nslookup o dig consultando a 1.1.1.1 y 8.8.8.8: si difieren, aún hay cachés viejas vivas.","A DNS record's **TTL** is, in seconds, how long resolvers may cache it: with TTL 3600, a change can take up to 1 hour to be seen across the internet, and with 86400, up to 24 hours. That is why, before migrating a server, you lower the TTL to 300 the day before, make the change in the lowest-impact window, and raise it again afterwards. Check propagation with nslookup or dig querying 1.1.1.1 and 8.8.8.8: if they differ, old caches are still alive."],"href":"redes.html#redes"},
    {"c":"Redes","k":["cuantos hosts tiene una red /26","calcular hosts de una /26","ejemplo de subred /26","how many hosts in a /26 subnet"],"r":["Una red **/26** tiene 6 bits de host (32 menos 26), así que admite 2 elevado a 6 = 64 direcciones en total. Restando la dirección de red y la de broadcast quedan 62 hosts útiles. Ejemplo con 192.168.1.64/26: red .64, rango útil .65 a .126, broadcast .127, y la siguiente red empieza en .128. Este cálculo rápido sirve para segmentar: cuatro redes /26 caben dentro de una /24, perfectas por ejemplo para invitados, IoT, cámaras y red principal sin desperdiciar direcciones.","A **/26** network has 6 host bits (32 minus 26), so it holds 2 to the power of 6 = 64 addresses in total. Subtracting the network and broadcast addresses leaves 62 usable hosts. Example with 192.168.1.64/26: network .64, usable range .65 to .126, broadcast .127, and the next network starts at .128. This quick math is handy for segmenting: four /26 networks fit inside one /24, perfect for example for guests, IoT, cameras and the main network without wasting addresses."],"href":"redes.html#redes"},
    {"c":"Redes","k":["que es la notacion cidr","cidr /24 y /16 explicado","cuantas ips tiene un /24","what is cidr notation"],"r":["La notación **CIDR** escribe una red como IP seguida de una barra y el número de bits fijos de red: 192.168.1.0/24 significa 24 bits de red (máscara 255.255.255.0) y 8 bits libres, es decir, 256 direcciones y 254 hosts útiles. Un /16, como 172.16.0.0/16, usa máscara 255.255.0.0 y ofrece 65 536 direcciones (65 534 útiles): por eso las LAN caseras suelen ser /24 y las de empresas o campus son /16 subdivididas en muchas /24.","**CIDR** notation writes a network as an IP followed by a slash and the number of fixed network bits: 192.168.1.0/24 means 24 network bits (mask 255.255.255.0) and 8 free bits, that is, 256 addresses and 254 usable hosts. A /16, like 172.16.0.0/16, uses mask 255.255.0.0 and offers 65,536 addresses (65,534 usable): that is why home LANs are usually /24 while company or campus networks are /16 blocks subdivided into many /24s."],"href":"redes.html#redes"},
    {"c":"Redes","k":["partes de la red 192.168.1.0/24","cual es el broadcast de mi red /24","rango util de una red 192.168.1.0","parts of a /24 network gateway broadcast"],"r":["En **192.168.1.0/24** cada parte tiene un papel fijo. La dirección de red es 192.168.1.0 y no se asigna a ningún equipo. La puerta de enlace (gateway) suele ser la primera útil, 192.168.1.1, que es el router. El rango útil para equipos va de .1 a .254, aunque normalmente el router reserva parte para DHCP, por ejemplo .100 a .199, y deja el resto para IPs fijas. La dirección de broadcast es 192.168.1.255: un paquete enviado a ella llega a todos los equipos de la red.","In **192.168.1.0/24** each part has a fixed role. The network address is 192.168.1.0 and is never assigned to a device. The gateway is usually the first usable one, 192.168.1.1, which is the router. The usable range for devices runs from .1 to .254, although the router normally reserves part of it for DHCP, for example .100 to .199, leaving the rest for static IPs. The broadcast address is 192.168.1.255: a packet sent to it reaches every device on the network."],"href":"redes.html#redes"},
    {"c":"Redes","k":["que es la ruta por defecto 0.0.0.0/0","default gateway route que significa","por que no tengo internet pero si red local","what is the default route 0.0.0.0/0"],"r":["La **ruta por defecto**, escrita 0.0.0.0/0, significa literalmente todo lo demás: cualquier destino que no encaje en una ruta más específica sale por ahí, normalmente hacia la puerta de enlace de tu LAN y de ahí a internet. Las rutas más largas ganan: una /24 local se prefiere antes que la /0 para hablar con equipos de tu red. Si la ruta por defecto apunta a una puerta de enlace caída, tendrás red local funcionando pero nada de internet, el clásico síntoma de revisar primero.","The **default route**, written 0.0.0.0/0, literally means everything else: any destination that does not match a more specific route leaves through it, normally towards your LAN gateway and from there to the internet. Longer routes win: a local /24 is preferred over the /0 to talk to devices on your own network. If the default route points to a dead gateway, you get a working local network but no internet at all, the classic symptom to check first."],"href":"redes.html#redes"},
    {"c":"Redes","k":["como ver la tabla de rutas en windows","route print para que sirve","comando para ver las rutas de red","how to view routing table route print"],"r":["En Windows, **route print** muestra la tabla de rutas IPv4 e IPv6: destino, máscara, puerta de enlace, interfaz y métrica. Léela buscando la línea 0.0.0.0 con máscara 0.0.0.0: su puerta de enlace debería ser tu router, por ejemplo 192.168.1.1. Si aparecen dos rutas por defecto, gana la de métrica menor. En Linux el equivalente es ip route, y verás una línea default via 192.168.1.1 dev eth0. Un gateway inesperado, como el de una VPN, explica que todo tu tráfico salga por otro sitio.","On Windows, **route print** shows the IPv4 and IPv6 routing tables: destination, mask, gateway, interface and metric. Read it by finding the 0.0.0.0 line with mask 0.0.0.0: its gateway should be your router, for example 192.168.1.1. If two default routes appear, the one with the lower metric wins. On Linux the equivalent is ip route, and you will see a line like default via 192.168.1.1 dev eth0. An unexpected gateway, such as a VPN's, explains why all your traffic leaves through somewhere else."],"href":"redes.html#redes"},
    {"c":"Redes","k":["wifi y cable conectados a la vez cual usa","metrica de interfaz que es","priorizar cable sobre wifi en windows","interface metric wifi vs ethernet priority"],"r":["Si conectas Wi-Fi y cable a la vez, Windows mantiene dos rutas por defecto y elige por **métrica**: gana la suma menor entre la métrica de la interfaz y la de la ruta. Por defecto el cable suele tener mejor (menor) métrica que el Wi-Fi, así que el tráfico sale por cable aunque ambos estén conectados. Puedes comprobarlo con route print y forzar una preferencia en las propiedades avanzadas del adaptador, desactivando Métrica automática y poniendo, por ejemplo, 10 al cable y 50 al Wi-Fi. Evita duplicar programas de descarga en ambas rutas: cada conexión usa solo una.","If you connect Wi-Fi and cable at the same time, Windows keeps two default routes and chooses by **metric**: the lowest sum of interface metric plus route metric wins. By default the cable usually has a better (lower) metric than Wi-Fi, so traffic leaves by cable even with both connected. Check it with route print and force a preference in the adapter's advanced properties, disabling Automatic metric and setting, for example, 10 for cable and 50 for Wi-Fi. Avoid duplicating download programs across both routes: each connection uses only one."],"href":"redes.html#redes"},
    {"c":"Redes","k":["poner un segundo router como access point","usar otro router como punto de acceso","router viejo como repetidor por cable","second router as access point setup"],"r":["Para usar un segundo router como **access point**: entra en su panel y desactiva su servidor DHCP, ponle una IP fija libre dentro de tu red principal (por ejemplo 192.168.1.2 si el router principal es .1), y conéctalo por un puerto LAN, no por el WAN, al router principal. Déjale el mismo nombre de red (SSID) y contraseña que la red principal, pero en un canal distinto para no estorbarse. Resultado: una sola red, una sola IP para cada equipo y roaming razonable entre zonas de la casa.","To use a second router as an **access point**: open its panel and disable its DHCP server, give it a free static IP inside your main network (for example 192.168.1.2 if the main router is .1), and connect it through a LAN port, not the WAN port, to the main router. Leave it with the same network name (SSID) and password as the main network, but on a different channel so they do not interfere. Result: a single network, one IP per device and reasonable roaming between areas of the house."],"href":"redes.html#redes"},
    {"c":"Redes","k":["que es el modo bridge del modem","poner el modem del isp en bridge","modo puente para quitar doble nat","modem bridge mode explained"],"r":["El **modo bridge** apaga en el módem-router del ISP sus funciones de router, NAT y DHCP, dejándolo como simple conversor: la IP pública pasa directa a tu propio router, que es quien marca la conexión (a veces con PPPoE y las credenciales del ISP). Se pide cuando hay doble NAT y quieres abrir puertos, montar una VPN o usar tu router sin interferencias. Antes de activarlo anota las credenciales y el tipo de conexión: un error te deja sin internet hasta reconfigurar, y tras el cambio quien da Wi-Fi y seguridad es solo tu router.","**Bridge mode** turns off the ISP modem-router's router, NAT and DHCP functions, leaving it as a plain converter: the public IP passes straight to your own router, which is the one that dials the connection (sometimes with PPPoE and the ISP credentials). You want it when there is double NAT and you need to open ports, run a VPN or use your router without interference. Before enabling it, write down the credentials and connection type: one mistake leaves you offline until reconfigured, and after the change your router alone provides Wi-Fi and security."],"href":"redes.html#redes"},
    {"c":"Redes","k":["que es el etiquetado vlan 802.1q","puerto trunk y puerto access diferencia","como funcionan las vlan en un switch","vlan tagging 802.1q trunk vs access"],"r":["El etiquetado **VLAN 802.1Q** inserta una etiqueta de 4 bytes con el ID de VLAN (1 a 4094) en la trama Ethernet. En la práctica: un puerto del switch en modo trunk lleva varias VLAN etiquetadas entre switches o hacia el router, y un puerto en modo access pertenece a una sola VLAN sin etiquetar, para un PC o una cámara. Así, con el mismo cableado físico corren redes lógicamente separadas: la VLAN 10 de oficinas no ve la VLAN 30 de cámaras aunque compartan switch.","**VLAN 802.1Q** tagging inserts a 4-byte tag with the VLAN ID (1 to 4094) into the Ethernet frame. In practice: a switch port in trunk mode carries several tagged VLANs between switches or towards the router, while an access port belongs to a single untagged VLAN, for a PC or a camera. That way, logically separate networks run over the same physical cabling: the office VLAN 10 cannot see the camera VLAN 30 even though they share the switch."],"href":"redes.html#switch-3d"},
    {"c":"Redes","k":["que es port mirroring o span","como capturar trafico con span y wireshark","puerto espejo en un switch para que sirve","port mirroring span explained"],"r":["El **port mirroring** o SPAN copia el tráfico de uno o varios puertos (o de una VLAN) hacia un puerto destino donde conectas un PC con Wireshark. Sirve para diagnosticar sin interrumpir la red: ves ARP, DHCP y retransmisiones tal cual ocurren. Precauciones: el puerto espejo puede saturarse si copias más tráfico del que admite (dos puertos a 1 Gbps hacia uno solo descartan paquetes) y estás viendo tráfico de otros, así que úsalo solo en redes tuyas o autorizadas y desactívalo al terminar.","**Port mirroring** or SPAN copies the traffic of one or more ports (or a VLAN) to a destination port where you plug in a PC running Wireshark. It lets you diagnose without disturbing the network: you see ARP, DHCP and retransmissions exactly as they happen. Cautions: the mirror port can saturate if you copy more traffic than it handles (two 1 Gbps ports into one will drop packets), and you are viewing other people's traffic, so use it only on your own or authorized networks and disable it when done."],"href":"redes.html#switch-3d"},
    {"c":"Redes","k":["que es lacp agregacion de enlaces","unir dos cables para tener 2 gbps","link aggregation como funciona","lacp link aggregation explained"],"r":["**LACP** (802.3ad) agrupa varios cables entre dos equipos, típicamente dos puertos de 1 Gbps entre switches, en un solo enlace lógico de 2 Gbps para la suma de flujos. Ojo: una sola conexión cliente-servidor sigue limitada a 1 Gbps, porque cada flujo se asigna siempre al mismo cable según un hash de direcciones. Su gran ventaja práctica es la redundancia: si un cable se corta, los flujos se reparten entre los que quedan y nadie nota el corte. Ambos extremos deben configurar el mismo grupo.","**LACP** (802.3ad) bundles several cables between two devices, typically two 1 Gbps ports between switches, into a single 2 Gbps logical link for the sum of flows. Note: a single client-server connection is still capped at 1 Gbps, because each flow is always assigned to the same cable by an address hash. Its big practical advantage is redundancy: if one cable is cut, flows are redistributed among the remaining ones and nobody notices. Both ends must configure the same group."],"href":"redes.html#switch-3d"},
    {"c":"Redes","k":["cuantos vatios da poe af at bt","potencia poe 802.3af at bt","que poe necesito para una camara","poe power budget af at bt watts"],"r":["**PoE** lleva datos y alimentación por el mismo cable Ethernet. Los estándares fijan el presupuesto: 802.3af entrega hasta 15,4 W por puerto (12,95 W útiles en el equipo), 802.3at (PoE+) llega a 30 W (25,5 W útiles) y 802.3bt sube a 60 W en tipo 3 y 90 W en tipo 4. Una cámara fija consume 6-8 W, un punto de acceso Wi-Fi 6 puede pedir 20 W y una cámara PTZ con calefactor supera los 30 W: suma todos antes de elegir el switch, cuyo presupuesto total también es limitado.","**PoE** carries data and power over the same Ethernet cable. The standards set the budget: 802.3af delivers up to 15.4 W per port (12.95 W usable at the device), 802.3at (PoE+) reaches 30 W (25.5 W usable) and 802.3bt rises to 60 W in type 3 and 90 W in type 4. A fixed camera draws 6-8 W, a Wi-Fi 6 access point may ask for 20 W and a PTZ camera with heater exceeds 30 W: add them all up before choosing the switch, whose total budget is also limited."],"href":"redes.html#switch-3d"},
    {"c":"Redes","k":["poe pasivo vs poe activo","poe pasivo es peligroso","inyector poe pasivo 24v riesgos","passive poe vs active poe risks"],"r":["El **PoE activo** negocia antes de entregar energía: el switch comprueba la firma del equipo y solo aplica el voltaje correcto si es compatible. El PoE pasivo, en cambio, inyecta un voltaje fijo (12, 24 o 48 V) siempre, negocie o no, usando inyectores baratos propios de algunas marcas. El riesgo es real: conectar un equipo pensado para 24 V pasivo a 48 V, o un puerto pasivo a un equipo que no espera alimentación, puede quemar su electrónica. Regla: verifica voltaje y estándar en la etiqueta de ambos extremos antes de enchufar.","**Active PoE** negotiates before delivering power: the switch checks the device's signature and only applies the correct voltage if it is compatible. Passive PoE, instead, injects a fixed voltage (12, 24 or 48 V) at all times, negotiation or not, using cheap injectors specific to some brands. The risk is real: feeding a device designed for 24 V passive with 48 V, or plugging a passive port into a device that expects no power, can fry its electronics. Rule: verify voltage and standard on the labels at both ends before plugging in."],"href":"redes.html#switch-3d"},
    {"c":"Redes","k":["cable cca vs cobre puro","que es un cable de red cca","cable de aluminio cobreado es malo","cca vs pure copper cable"],"r":["El cable **CCA** tiene conductores de aluminio recubierto de cobre, no cobre puro. Es más barato, pero el aluminio ofrece más resistencia (peor rendimiento en tramos largos y con PoE, donde se calienta más), es más frágil al doblarlo y muchos CCA ni siquiera cumplen la categoría que imprimen en la cubierta. En tiradas cortas y sin PoE puede funcionar, pero para instalaciones fijas, cámaras o puntos de acceso exige cobre puro: míralo en las especificaciones, porque por fuera ambos cables se ven idénticos.","**CCA** cable has copper-clad aluminium conductors, not pure copper. It is cheaper, but aluminium has higher resistance (worse performance on long runs and with PoE, where it heats up more), is more fragile when bent, and many CCA cables do not even meet the category printed on the jacket. On short runs without PoE it may work, but fixed installations, cameras and access points demand pure copper: check the specifications, because from the outside both cables look identical."],"href":"redes.html#redes"},
    {"c":"Redes","k":["t568a o t568b cual usar","diferencia entre t568a y t568b","orden de colores rj45 t568b","t568a vs t568b wiring"],"r":["**T568A** y T568B solo difieren en el orden de los pares verde y naranja en el conector RJ45; eléctricamente son equivalentes y el rendimiento es el mismo. La norma práctica: usa el mismo esquema en ambos extremos del cable (en Europa y en la mayoría de instalaciones modernas, T568B) y obtendrás un cable directo normal. Un cable con A en un extremo y B en el otro es un cable cruzado, útil antiguamente entre equipos iguales; hoy el Auto MDI-X de los puertos modernos lo hace innecesario.","**T568A** and T568B differ only in the order of the green and orange pairs on the RJ45 connector; electrically they are equivalent and performance is the same. The practical rule: use the same scheme at both ends of the cable (in Europe and most modern installations, T568B) and you get a normal straight-through cable. A cable with A on one end and B on the other is a crossover cable, formerly useful between similar devices; today the Auto MDI-X of modern ports makes it unnecessary."],"href":"redes.html#redes"},
    {"c":"Redes","k":["cuando usar cable blindado ftp stp","cable de red blindado para que sirve","utp o ftp que es mejor en casa","shielded ethernet cable when to use"],"r":["El cable blindado (**FTP/STP**) lleva una lámina o malla metálica que protege los pares de interferencias electromagnéticas. Tiene sentido junto a motores, fluorescentes, variadores, ascensores o en bandejas compartidas con cables de potencia, y en enlaces largos entre edificios. Condición clave: el blindaje solo funciona si se conecta a tierra correctamente en los extremos, con conectores también blindados; mal puesto, actúa como antena y puede empeorar las cosas. En una vivienda normal, el UTP sin blindar sobra y es más fácil de instalar bien.","Shielded cable (**FTP/STP**) has a metal foil or braid that protects the pairs from electromagnetic interference. It makes sense near motors, fluorescent lights, variable drives, elevators or in trays shared with power cables, and on long links between buildings. Key condition: the shield only works if it is properly grounded at the ends, with shielded connectors too; done badly, it acts as an antenna and can make things worse. In a normal home, unshielded UTP is plenty and far easier to install correctly."],"href":"redes.html#redes"},
    {"c":"Redes","k":["fibra monomodo vs multimodo diferencia","que fibra usar entre edificios","os2 vs om4 fibra","single mode vs multimode fiber"],"r":["La **fibra monomodo** (OS2) tiene un núcleo de unas 9 micras y usa láser: alcanza kilómetros sin repetir (10, 40 o más según la óptica) y es la elegida entre edificios y por los operadores. La multimodo (OM3/OM4) tiene núcleo de 50 micras, usa LED o VCSEL más baratos y sirve dentro del edificio: con 10 Gbps llega a unos 300-400 metros según el tipo. No son intercambiables: mezclar ópticas y fibras de tipos distintos en un enlace provoca pérdidas y fallos intermitentes.","**Single-mode fiber** (OS2) has a core of about 9 microns and uses lasers: it reaches kilometres without repeating (10, 40 or more depending on the optics) and is the choice between buildings and by carriers. Multimode (OM3/OM4) has a 50-micron core, uses cheaper LEDs or VCSELs and serves inside buildings: at 10 Gbps it reaches about 300-400 metres depending on the type. They are not interchangeable: mixing optics and fibers of different types on one link causes losses and intermittent faults."],"href":"redes.html#redes"},
    {"c":"Redes","k":["que es un modulo sfp y sfp+","conector lc en fibra para que sirve","sfp+ 10gbps diferencia con sfp","sfp vs sfp+ lc connector"],"r":["Los módulos **SFP** son transceptores intercambiables en caliente que convierten el puerto del switch en lo que necesites: fibra o incluso cobre RJ45. SFP llega a 1 Gbps y SFP+ a 10 Gbps, compartiendo el mismo formato físico, aunque un SFP+ en un puerto SFP suele funcionar a 1 Gbps y no al revés. El conector de fibra habitual es el LC dúplex, dos fibras (envío y recepción) en un conector pequeño. Antes de comprar, comprueba compatibilidad: algunos fabricantes bloquean módulos de terceros.","**SFP** modules are hot-swappable transceivers that turn a switch port into whatever you need: fiber or even RJ45 copper. SFP reaches 1 Gbps and SFP+ 10 Gbps, sharing the same physical format, although an SFP+ in an SFP port usually works at 1 Gbps and not the other way round. The usual fiber connector is duplex LC, two fibers (transmit and receive) in one small connector. Before buying, check compatibility: some vendors lock out third-party modules."],"href":"redes.html#redes"},
    {"c":"Redes","k":["radio de curvatura minimo de la fibra","cuanto se puede doblar un cable de fibra","doblar fibra optica se rompe","fiber optic minimum bend radius"],"r":["Cada fibra tiene un **radio de curvatura mínimo**: doblarla más agudo deja escapar luz por la curva (atenuación por macrocurvatura) y puede partir el vidrio. Como referencia, en instalación se respeta unas 10 veces el diámetro de la cubierta sin tensión y 20 veces bajo tensión de tiro; un cable típico de 3 mm pide curvas no menores de unos 30 mm, como el borde de una lata. Por eso la fibra va en bandejas y curvas suaves, nunca grapada ni con bridas apretadas como si fuera cobre.","Every fiber has a **minimum bend radius**: bending it sharper lets light escape through the curve (macrobend attenuation) and can crack the glass. As a reference, during installation you keep about 10 times the jacket diameter with no tension and 20 times under pulling tension; a typical 3 mm cable asks for bends no tighter than about 30 mm, like the rim of a can. That is why fiber runs in trays with gentle curves, never stapled or strapped tight like copper."],"href":"redes.html#redes"},
    {"c":"Redes","k":["que necesito para 2.5gbe en casa","requisitos reales para 10gbe","cat6 sirve para 10 gbps","2.5gbe and 10gbe requirements"],"r":["Para **2.5GbE** necesitas tres piezas a la vez: tarjeta de red 2.5G en el equipo, puerto 2.5G en el switch o router y, si el otro extremo es un NAS, también su puerto a 2.5G; el cable Cat5e de calidad ya sirve en distancias caseras. Para 10GbE el salto es serio: Cat6 admite 10G hasta unos 55 m (Cat6A hasta 100 m), las NIC y switches 10G cuestan y consumen más, y por fibra se usan SFP+ con módulos adecuados. Sin disco rápido en ambos extremos, el cuello será el almacenamiento, no la red.","For **2.5GbE** you need three pieces at once: a 2.5G network card in the device, a 2.5G port on the switch or router and, if the other end is a NAS, its port at 2.5G too; quality Cat5e cabling already works at home distances. For 10GbE the jump is serious: Cat6 supports 10G up to about 55 m (Cat6A up to 100 m), 10G NICs and switches cost and consume more, and over fiber you use SFP+ with suitable modules. Without fast storage at both ends, the bottleneck will be the disks, not the network."],"href":"redes.html#redes"},
    {"c":"Redes","k":["como configurar wake on lan","encender el pc por red wol","wake on lan no funciona como probarlo","wake on lan setup and test"],"r":["**Wake on LAN** enciende un PC apagado enviándole un paquete mágico a su dirección MAC: 6 bytes FF seguidos de la MAC repetida 16 veces, normalmente por UDP al puerto 7 o 9 en broadcast. Para configurarlo: activa Wake on LAN o Power On By PCI-E en la BIOS/UEFI, y en Windows, en las propiedades de la tarjeta de red, permite que reactive el equipo y solo con paquete mágico. Prueba primero desde la misma LAN con una app de WoL; desde internet exige abrir puertos o usar la función WoL de tu router o una VPN, porque el broadcast no cruza de red.","**Wake on LAN** powers on a switched-off PC by sending it a magic packet addressed to its MAC: 6 bytes of FF followed by the MAC repeated 16 times, normally over UDP to port 7 or 9 as a broadcast. To set it up: enable Wake on LAN or Power On By PCI-E in the BIOS/UEFI, and on Windows, in the network card properties, allow it to wake the device and only with a magic packet. Test first from the same LAN with a WoL app; from the internet it requires opening ports or using your router's WoL feature or a VPN, because broadcasts do not cross networks."],"href":"redes.html#redes"},
    {"c":"Redes","k":["que es arp spoofing y como detectarlo","suplantacion arp en mi red","como saber si me hacen arp spoofing","arp spoofing detection"],"r":["En el **ARP spoofing**, un atacante envía respuestas ARP falsas para asociar la IP de la puerta de enlace a su propia MAC; tu equipo le manda entonces todo el tráfico a él. Se detecta comparando: ejecuta arp -a y comprueba que la MAC del gateway coincide con la real impresa en el router o anotada antes; herramientas como arpwatch o XArp avisan si una IP cambia de MAC o si una MAC reclama ser varios equipos. La defensa seria es segmentar, usar DHCP snooping y inspección ARP dinámica en switches gestionables.","In **ARP spoofing**, an attacker sends forged ARP replies to bind the gateway's IP to their own MAC; your device then sends all its traffic to them. Detect it by comparing: run arp -a and check that the gateway's MAC matches the real one printed on the router or noted down earlier; tools like arpwatch or XArp warn you if an IP changes MAC or if one MAC claims to be several devices. The serious defence is segmentation, DHCP snooping and dynamic ARP inspection on managed switches."],"href":"redes.html#redes"},
    {"c":"Redes","k":["que es un servidor dhcp falso","rogue dhcp en mi red como encontrarlo","hay otro router repartiendo ips","rogue dhcp server detection"],"r":["Un **DHCP falso** (rogue DHCP) es un servidor no autorizado repartiendo IPs en tu red: suele ser un segundo router conectado al revés, con su DHCP aún activo. Los equipos que le piden IP reciben su puerta de enlace y su DNS, así que navegan mal o todo su tráfico pasa por él. Se caza buscando en el panel del router o con ipconfig /all qué servidor DHCP te asignó la IP: debe ser solo tu router. Se apaga el DHCP del aparato intruso, y en switches gestionables se activa DHCP snooping.","A **rogue DHCP** server is an unauthorized server handing out IPs on your network: usually a second router plugged in backwards with its DHCP still on. Devices that ask it for an IP receive its gateway and its DNS, so they browse badly or all their traffic passes through it. Hunt it down by checking in the router's panel or with ipconfig /all which DHCP server assigned your IP: it must only be your router. Turn off the intruder's DHCP, and on managed switches enable DHCP snooping."],"href":"redes.html#redes"},
    {"c":"Redes","k":["ataque man in the middle en la lan","que puede ver un mitm en mi red","como protegerme de un mitm local","man in the middle lan attack"],"r":["Un **man-in-the-middle** en la LAN se coloca entre tu equipo y la puerta de enlace, normalmente con ARP spoofing, y reenvía el tráfico leyéndolo por el camino. Lo que consigue: ver todo lo que viaje sin cifrar (HTTP, contraseñas de servicios viejos) y manipularlo. Lo que no puede romper es un HTTPS bien implementado: ahí solo ve destinos y metadatos, y cualquier intento de suplantar el certificado hace saltar el aviso del navegador. Defensas prácticas: no ignores avisos de certificado, usa HTTPS y VPN en redes ajenas, y segmenta tu red.","A **man-in-the-middle** on the LAN places itself between your device and the gateway, usually with ARP spoofing, and forwards the traffic while reading it on the way. What it gets: everything that travels unencrypted (HTTP, passwords of old services) and the ability to manipulate it. What it cannot break is properly implemented HTTPS: there it only sees destinations and metadata, and any attempt to fake the certificate triggers the browser warning. Practical defences: never ignore certificate warnings, use HTTPS and a VPN on other people's networks, and segment your network."],"href":"redes.html#redes"},
    {"c":"Redes","k":["como separar los dispositivos iot de mi red","poner las camaras en otra red vlan","segmentar iot para seguridad","how to segment iot devices network"],"r":["Segmentar el **IoT** significa poner bombillas, cámaras baratas, TV y enchufes en una red o VLAN separada de la principal, con reglas de firewall entre ambas. Configuración típica: la red IoT tiene salida a internet, pero no puede iniciar conexiones hacia la red principal; tu móvil, desde la principal, sí puede alcanzarlos para controlarlos. Así, si una cámara con firmware abandonado cae, el atacante no llega a tu PC ni a tu NAS. Muchos routers lo resuelven fácil con la red de invitados aislada como red IoT.","Segmenting **IoT** means putting bulbs, cheap cameras, TVs and smart plugs on a separate network or VLAN from the main one, with firewall rules between them. Typical setup: the IoT network can reach the internet but cannot initiate connections towards the main network; your phone, from the main network, can still reach them to control them. That way, if a camera with abandoned firmware falls, the attacker cannot reach your PC or your NAS. Many routers solve this easily by using the isolated guest network as the IoT network."],"href":"redes.html#redes"},
    {"c":"Redes","k":["que es split tunneling en vpn","tunel dividido vpn ventajas y riesgos","parte del trafico fuera de la vpn","split tunneling explained"],"r":["El **split tunneling** decide qué tráfico entra en la VPN y cuál sale directo a internet. Con túnel completo, todo (también tus descargas y el streaming) pasa por el servidor VPN: más privado, pero más lento y con su latencia. Con split, solo el rango de la oficina, por ejemplo 10.10.0.0/16, viaja cifrado y el resto sale por tu conexión normal. Es lo práctico para teletrabajar, pero ojo: un equipo en split mal configurado puede ser puente entre internet y la red de la empresa.","**Split tunneling** decides which traffic goes into the VPN and which goes straight to the internet. With a full tunnel, everything (including your downloads and streaming) passes through the VPN server: more private, but slower and with its latency. With split, only the office range, for example 10.10.0.0/16, travels encrypted and the rest leaves over your normal connection. It is the practical choice for remote work, but beware: a badly configured split-tunnel device can become a bridge between the internet and the company network."],"href":"redes.html#redes"},
    {"c":"Redes","k":["wireguard vs openvpn cual es mejor","diferencias entre wireguard y openvpn","que vpn es mas rapida wireguard u openvpn","wireguard vs openvpn comparison"],"r":["**WireGuard** y OpenVPN resuelven lo mismo con filosofías opuestas. WireGuard usa criptografía moderna fija (Curve25519, ChaCha20), tiene un código mínimo y conecta casi al instante; al ser tan simple, rinde más y consume menos batería, pero su diseño sin gestión de usuarios exige añadir claves una a una. OpenVPN es veterano y flexible: certificados, autenticación de usuarios, funciona incluso sobre TCP 443 para saltar redes restrictivas. Para un túnel personal o de oficina pequeña, WireGuard es hoy la opción práctica; OpenVPN sigue fuerte donde ya hay infraestructura y políticas complejas.","**WireGuard** and OpenVPN solve the same problem with opposite philosophies. WireGuard uses fixed modern cryptography (Curve25519, ChaCha20), has minimal code and connects almost instantly; being so simple, it performs better and uses less battery, but its design without user management means adding keys one by one. OpenVPN is the veteran and flexible one: certificates, user authentication, and it even works over TCP 443 to get past restrictive networks. For a personal or small-office tunnel, WireGuard is today's practical choice; OpenVPN stays strong where infrastructure and complex policies already exist."],"href":"redes.html#redes"},
    {"c":"Redes","k":["que es http/3 y quic","http3 por que usa udp","ventajas de quic frente a tcp","http3 quic explained"],"r":["**HTTP/3** abandona TCP y corre sobre QUIC, un transporte cifrado montado sobre UDP que incluye TLS 1.3 en el propio apretón de manos. Ventajas reales: la conexión segura se establece en 1 viaje de ida y vuelta (o 0 en reconexiones), y la pérdida de un paquete ya no bloquea a todos los flujos a la vez, como pasaba con el bloqueo de cabeza de línea de HTTP/2 sobre TCP. En redes móviles, QUIC sobrevive al cambio de Wi-Fi a datos porque la conexión se identifica por un ID, no por la IP.","**HTTP/3** abandons TCP and runs over QUIC, an encrypted transport built on UDP that includes TLS 1.3 in the handshake itself. Real advantages: the secure connection is established in 1 round trip (or 0 on resumptions), and losing one packet no longer blocks all streams at once, as happened with HTTP/2 over TCP head-of-line blocking. On mobile networks, QUIC survives switching from Wi-Fi to cellular data because the connection is identified by an ID, not by the IP."],"href":"redes.html#redes"},
    {"c":"Redes","k":["http/2 vs http/1.1 diferencias","que es la multiplexacion de http/2","por que http/2 es mas rapido","http2 multiplexing vs http1.1"],"r":["En **HTTP/1.1**, el navegador abría unas 6 conexiones TCP por dominio y cada una cargaba los recursos casi en cola. HTTP/2 introduce la multiplexación: una sola conexión TCP transporta muchos flujos binarios a la vez, con las cabeceras comprimidas (HPACK), así que una página con 80 recursos ya no espera turnos por conexión. Su talón de Aquiles seguía siendo TCP: si un paquete se pierde, todos los flujos esperan su retransmisión; justo eso es lo que corrige HTTP/3 al pasar a QUIC. En la práctica, HTTP/2 se nota sobre todo en webs con muchos archivos pequeños.","In **HTTP/1.1**, the browser opened about 6 TCP connections per domain and each one loaded resources almost in a queue. HTTP/2 introduces multiplexing: a single TCP connection carries many binary streams at once, with compressed headers (HPACK), so a page with 80 resources no longer waits for turns per connection. Its Achilles heel was still TCP: if a packet is lost, every stream waits for its retransmission; that is exactly what HTTP/3 fixes by moving to QUIC. In practice, HTTP/2 shows most on websites with many small files."],"href":"redes.html#redes"},
    {"c":"Redes","k":["que es websocket y para que sirve","websocket vs polling diferencia","como funciona una conexion websocket","what problem do websockets solve"],"r":["**WebSocket** resuelve el problema de la comunicación en tiempo real sin trucos. Antes, el navegador simulaba inmediatez preguntando cada pocos segundos (polling) o dejando una petición colgada (long polling), con gasto y retraso. Con WebSocket, tras un apretón de manos HTTP que pide el upgrade, la conexión queda abierta y es bidireccional: el servidor puede empujar datos en cuanto existen, con una cabecera mínima de 2 a 10 bytes por mensaje. Por eso es la base de chats, marcadores en vivo, notificaciones y juegos web sencillos.","**WebSocket** solves real-time communication without tricks. Before, the browser faked immediacy by asking every few seconds (polling) or leaving a request hanging (long polling), with waste and delay. With WebSocket, after an HTTP handshake that requests the upgrade, the connection stays open and is bidirectional: the server can push data as soon as it exists, with a tiny header of 2 to 10 bytes per message. That is why it underpins chats, live scoreboards, notifications and simple web games."],"href":"redes.html#redes"},
    {"c":"Redes","k":["como funciona una cdn por dentro","que es una red de entrega de contenidos","cdn cache como reparte el contenido","how does a cdn work"],"r":["Una **CDN** guarda copias del contenido en servidores repartidos por el mundo (puntos de presencia) y entrega cada visita desde el nodo cercano. Al publicar, el origen sube el contenido una vez; cada nodo lo cachea según los TTL de las cabeceras y lo sirve miles de veces sin tocar el origen. Valida con el origen solo cuando el objeto expira o se purga. Si un nodo falla o se satura, el DNS o Anycast desvía a los visitantes al siguiente. Resultado: menos latencia, menos carga del servidor y mejor aguante ante picos y ataques.","A **CDN** keeps copies of content on servers spread around the world (points of presence) and serves each visit from the nearby node. When publishing, the origin uploads the content once; each node caches it according to the header TTLs and serves it thousands of times without touching the origin. It revalidates with the origin only when the object expires or is purged. If a node fails or saturates, DNS or Anycast shifts visitors to the next one. Result: less latency, less server load and better resilience against spikes and attacks."],"href":"redes.html#redes"},
    {"c":"Redes","k":["que es anycast y como funciona","misma ip en muchos sitios anycast","anycast en dns y cdn","what is anycast routing"],"r":["**Anycast** anuncia la misma IP desde muchos lugares a la vez y el enrutamiento BGP lleva a cada usuario al nodo que la red considera más cercano en saltos, no en kilómetros. Es la técnica de los DNS grandes (1.1.1.1 vive en cientos de ciudades con la misma dirección) y de las CDN. Ventajas: latencia baja sin configurar nada y resistencia natural a caídas y ataques distribuidos, porque el tráfico se reparte entre nodos. Su punto delicado: si las rutas cambian a mitad de una conexión larga, esta puede caer a otro nodo y romperse.","**Anycast** announces the same IP from many places at once and BGP routing takes each user to the node the network considers closest in hops, not in kilometres. It is the technique behind the big DNS services (1.1.1.1 lives in hundreds of cities with the same address) and CDNs. Advantages: low latency with zero configuration and natural resilience to outages and distributed attacks, because traffic spreads across nodes. Its delicate point: if routes change in the middle of a long connection, it can land on another node and break."],"href":"redes.html#redes"},
    {"c":"Redes","k":["que es bgp en palabras simples","por que se cae internet por bgp","bgp explicado facil","bgp explained simply outages"],"r":["**BGP** es el protocolo con el que los grandes bloques de internet (sistemas autónomos, como tu ISP) se anuncian entre sí qué rangos de IP saben alcanzar y por qué camino. No hay un mapa central: cada operador confía en lo que sus vecinos anuncian, y esa confianza es su debilidad. Cuando un operador anuncia por error (o a propósito) rangos ajenos, medio internet puede enviar su tráfico al sitio equivocado: así han caído servicios enormes durante horas por una sola ruta mal publicada.","**BGP** is the protocol with which the big blocks of the internet (autonomous systems, like your ISP) announce to each other which IP ranges they can reach and by what path. There is no central map: each operator trusts what its neighbours announce, and that trust is its weakness. When an operator announces someone else's ranges by mistake (or on purpose), half the internet can send its traffic to the wrong place: that is how huge services have gone down for hours because of a single badly published route."],"href":"redes.html#redes"},
    {"c":"Redes","k":["slaac vs dhcpv6 diferencia","como se asignan ips en ipv6","ipv6 sin servidor dhcp slaac","slaac vs dhcpv6 explained"],"r":["En IPv6, **SLAAC** permite que cada equipo se autoconfigure: escucha el anuncio del router (Router Advertisement) con el prefijo de la red, por ejemplo 2001:db8:1::/64, y se genera su propia dirección, sin servidor que reparta. DHCPv6, en cambio, reparte direcciones y datos de forma controlada, como en IPv4, o solo entrega datos extra (DNS) mientras la dirección sale de SLAAC. Matiz práctico: Android no soporta DHCPv6, así que una red solo con DHCPv6 deja a los móviles Android sin IPv6; por eso casi todas las redes usan SLAAC.","In IPv6, **SLAAC** lets each device configure itself: it listens to the router's advertisement (Router Advertisement) carrying the network prefix, for example 2001:db8:1::/64, and generates its own address, with no server handing them out. DHCPv6, by contrast, assigns addresses and data in a controlled way, as in IPv4, or only supplies extra data (DNS) while the address comes from SLAAC. Practical nuance: Android does not support DHCPv6, so a DHCPv6-only network leaves Android phones without IPv6; that is why almost every network uses SLAAC."],"href":"redes.html#redes"},
    {"c":"Redes","k":["que es una direccion fe80 link local","ipv6 link local para que sirve","fe80:: que significa","ipv6 link local fe80 explained"],"r":["Las direcciones **link-local** IPv6 empiezan por fe80::/10 y existen siempre, en cada interfaz, aunque no haya router ni internet: el equipo las genera solo. Sirven para hablar con los vecinos del mismo enlace, descubrir al router (los anuncios se hacen desde la link-local del router) y configurar el resto de IPv6. No se enrutan: un paquete con destino fe80:: nunca cruza a otra red, y al usarlas hay que indicar la interfaz (zona), como fe80::1%eth0, porque la misma dirección puede existir en cada enlace.","IPv6 **link-local** addresses start with fe80::/10 and always exist on every interface, even with no router and no internet: the device generates them by itself. They are used to talk to neighbours on the same link, discover the router (advertisements are sent from the router's link-local) and set up the rest of IPv6. They are not routed: a packet destined to fe80:: never crosses to another network, and when using them you must specify the interface (zone), like fe80::1%eth0, because the same address can exist on every link."],"href":"redes.html#redes"},
    {"c":"Redes","k":["que es ntp y para que sirve","por que importa la hora exacta en red","sincronizar hora con ntp problemas tls","ntp why accurate time matters"],"r":["**NTP** sincroniza el reloj de los equipos con servidores de hora por el puerto UDP 123, con precisiones de milisegundos en una LAN. La hora exacta no es un capricho: los certificados TLS se validan contra fechas (un reloj desfasado horas hace que el navegador rechace webs válidas), Kerberos solo tolera unos 5 minutos de diferencia, los registros de dos equipos solo se pueden correlacionar para investigar un incidente si sus relojes coinciden, y las copias programadas dependen de ello. En Windows, w32tm /query /status muestra tu fuente de hora actual.","**NTP** synchronizes device clocks with time servers over UDP port 123, with millisecond accuracy on a LAN. Exact time is not a whim: TLS certificates are validated against dates (a clock off by hours makes the browser reject valid websites), Kerberos only tolerates about 5 minutes of difference, logs from two machines can only be correlated to investigate an incident if their clocks agree, and scheduled backups depend on it. On Windows, w32tm /query /status shows your current time source."],"href":"redes.html#redes"},
    {"c":"Redes","k":["por que desactivar smbv1","smbv1 es peligroso wannacry","diferencia smb1 smb2 smb3 seguridad","why disable smbv1"],"r":["Desactiva **SMBv1** porque es un protocolo de 30 años sin cifrado ni protecciones modernas, y fue la puerta de entrada de ataques históricos como WannaCry y NotPetya por el fallo EternalBlue. SMB2 y SMB3 mantienen la misma función (compartir archivos e impresoras en red) añadiendo firmado, cifrado en SMB3 y mejor rendimiento. En Windows se comprueba y desactiva desde Características de Windows o con PowerShell, y en un NAS desde su panel de SMB: si un equipo muy antiguo deja de ver los recursos, ese equipo es el problema a actualizar, no motivo para reactivar SMBv1.","Disable **SMBv1** because it is a 30-year-old protocol with no encryption or modern protections, and it was the entry door for historic attacks like WannaCry and NotPetya via the EternalBlue flaw. SMB2 and SMB3 keep the same function (sharing files and printers over the network) while adding signing, encryption in SMB3 and better performance. On Windows you check and disable it from Windows Features or with PowerShell, and on a NAS from its SMB panel: if a very old device stops seeing the shares, that device is the thing to upgrade, not a reason to re-enable SMBv1."],"href":"redes.html#redes"},
    {"c":"Redes","k":["nfs vs smb cual usar","diferencia entre nfs y smb","compartir archivos linux nfs o smb windows","nfs vs smb file sharing"],"r":["**NFS** y SMB reparten archivos por red con culturas distintas. SMB nació en Windows: integra permisos de usuario tipo Active Directory, bloqueo de archivos pensado para programas que comparten documentos y es el predeterminado en Windows y en muchos NAS. NFS es el clásico de Linux/Unix: exporta carpetas a IPs autorizadas, mapea usuarios por UID y brilla con cargas de máquinas virtuales y servidores Linux. En una red mixta manda quién consume: clientes Windows, SMB; granja Linux, NFS. Rendimiento parecido, problemas distintos: NFS falla por permisos de UID, SMB por credenciales y versiones.","**NFS** and SMB share files over the network with different cultures. SMB was born on Windows: it integrates Active Directory-style user permissions, file locking designed for programs sharing documents, and is the default on Windows and many NAS boxes. NFS is the Linux/Unix classic: it exports folders to authorized IPs, maps users by UID and shines with virtual machine workloads and Linux servers. In a mixed network the consumer rules: Windows clients, SMB; Linux farm, NFS. Similar performance, different problems: NFS fails on UID permissions, SMB on credentials and versions."],"href":"redes.html#redes"},
    {"c":"Redes","k":["que es iscsi y para que sirve","almacenamiento en bloque por red iscsi","iscsi vs carpeta compartida diferencia","iscsi block storage explained"],"r":["**iSCSI** transporta comandos SCSI sobre TCP/IP (puerto 3260) para presentar un disco remoto como si fuera un disco local en bloque, no como carpeta compartida. El iniciador (tu servidor) formatea ese volumen con su propio sistema de archivos, así que es ideal para máquinas virtuales y bases de datos. Su red importa: se recomienda segmento o VLAN propia, MTU 9000 alineada y sin competencia con el tráfico normal. La trampa mortal: montar el mismo volumen en dos servidores sin clúster encima corrompe el sistema de archivos.","**iSCSI** carries SCSI commands over TCP/IP (port 3260) to present a remote disk as if it were a local block disk, not a shared folder. The initiator (your server) formats that volume with its own filesystem, making it ideal for virtual machines and databases. Its network matters: a dedicated segment or VLAN is recommended, with aligned 9000 MTU and no competition from normal traffic. The deadly trap: mounting the same volume on two servers without a cluster layer on top corrupts the filesystem."],"href":"redes.html#redes"},
    {"c":"Redes","k":["que es dscp y el marcado de paquetes","valores dscp ef af41 qos","marcar paquetes para priorizar voz","dscp packet marking qos"],"r":["**DSCP** marca cada paquete IP con un valor de 6 bits en su cabecera (0 a 63) que indica cómo debe tratarlo la red. Los valores con nombre ahorran memorizar números: EF (46) para voz, que pide cola prioritaria y baja latencia; AF41 (34) para video; CS0 (0) para el tráfico normal. Routers y switches con QoS leen la marca y dan prioridad o descartan en ese orden cuando hay congestión. Ojo: al salir a internet, tu operador puede borrar o ignorar tus marcas; el marcado sirve sobre todo dentro de tu red y hacia una WAN gestionada.","**DSCP** marks each IP packet with a 6-bit value in its header (0 to 63) stating how the network should treat it. The named values save memorizing numbers: EF (46) for voice, which asks for a priority queue and low latency; AF41 (34) for video; CS0 (0) for normal traffic. Routers and switches with QoS read the mark and prioritize or drop in that order when congestion hits. Note: when leaving to the internet, your carrier may strip or ignore your marks; marking mainly pays off inside your network and towards a managed WAN."],"href":"redes.html#redes"},
    {"c":"Redes","k":["que es snmp para monitorear la red","snmp v2c vs v3 seguridad","como vigilar switches con snmp","snmp network monitoring basics"],"r":["**SNMP** permite vigilar switches, routers, impresoras y servidores preguntándoles por contadores estructurados (OID) desde un sistema de monitoreo como Zabbix o LibreNMS: tráfico por puerto, errores, CPU, temperatura o tinta. Se consulta por UDP 161 y los avisos (traps) llegan por el 162. Versiones importan: SNMPv2c viaja en claro y su seguridad es solo una clave compartida llamada community; usa SNMPv3, con usuario y cifrado, o al menos v2c solo en lectura y dentro de una VLAN de gestión separada.","**SNMP** lets you watch switches, routers, printers and servers by polling structured counters (OIDs) from a monitoring system like Zabbix or LibreNMS: traffic per port, errors, CPU, temperature or ink. It is polled over UDP 161 and alerts (traps) arrive on 162. Versions matter: SNMPv2c travels in cleartext and its security is just a shared key called a community; use SNMPv3, with users and encryption, or at least v2c read-only and inside a separate management VLAN."],"href":"redes.html#redes"},
    {"c":"Redes","k":["latencia de satelite geo vs leo","ping satelital starlink vs geoestacionario","por que el internet satelital geo es lento","geo vs leo satellite latency"],"r":["Un satélite **GEO** orbita a unos 35 786 km, así que cada señal sube y baja recorriendo más de 70 000 km: el ping mínimo real ronda 550-700 ms y no hay configuración que lo baje, aunque el ancho de banda sea decente. Las constelaciones LEO, como Starlink, orbitan a unos 550 km: la distancia cae más de 60 veces y la latencia típica queda en 25-60 ms, suficiente para jugar y hacer videollamadas. La contrapartida LEO: el satélite se mueve, hay traspasos constantes entre satélites y la cobertura depende de tener cielo despejado hacia ellos.","A **GEO** satellite orbits at about 35,786 km, so each signal travels up and down more than 70,000 km: the real minimum ping sits around 550-700 ms and no setting can lower it, even if bandwidth is decent. LEO constellations, like Starlink, orbit at about 550 km: the distance drops more than 60 times and typical latency lands at 25-60 ms, enough for gaming and video calls. The LEO trade-off: the satellite moves, handovers between satellites are constant and coverage depends on having a clear view of the sky."],"href":"redes.html#redes"},
    {"c":"WiFi","k":["canales dfs radar 5 ghz","dfs wifi radar aeropuerto","por que se va el 5 ghz solo","dfs channels radar 5ghz wifi"],"r":["Los canales **DFS** en 5 GHz (52-64, 100-140, U-NII-2) comparten espectro con radares meteorológicos y militares. Al activarse, el AP escucha 60 segundos —CAC— antes de emitir; si detecta pulsos de radar, debe abandonar el canal en 10 segundos y no volver en 30 minutos. Por eso un AP reinicia 'sin 5 GHz' un rato o salta de canal solo. Ventaja: son canales limpios, sin vecinos. Si hay cortes cerca de un aeropuerto, desactívalos y usa 36-48 o 149-161.","**DFS** channels in 5 GHz (52-64, 100-140, U-NII-2) share spectrum with weather and military radars. When one activates, the AP listens for 60 seconds —the CAC— before transmitting; if it detects radar pulses, it must leave the channel within 10 seconds and stay away for 30 minutes. That is why an AP restarts 'without 5 GHz' for a while or hops channel by itself. Upside: they are clean channels, with no neighbors. If you get drops near an airport, disable them and use 36-48 or 149-161."],"href":"wifi.html"},
    {"c":"WiFi","k":["canales 1 6 11 no solapados","que canal 2.4 ghz elegir","canales que no se solapan","non overlapping channels 1 6 11"],"r":["En 2,4 GHz cada canal ocupa unos 22 MHz pero se separan solo 5 MHz, así que se solapan. Los únicos que no se tocan son **1, 6 y 11**: forman el esquema estándar de reutilización. Usar el 3, 4, 8 o 9 mete tu red en tierra de nadie, recibiendo interferencia parcial de dos redes vecinas que ni siquiera puede coordinar bien con CSMA/CA. Regla práctica: fija 1, 6 u 11, el menos ocupado según el escaneo, con ancho de 20 MHz siempre en esta banda.","In 2.4 GHz each channel takes about 22 MHz but channels sit only 5 MHz apart, so they overlap. The only ones that do not touch are **1, 6 and 11**: they form the standard reuse scheme. Using 3, 4, 8 or 9 puts your network in no man's land, receiving partial interference from two neighboring networks it cannot even coordinate with properly through CSMA/CA. Practical rule: lock in 1, 6 or 11, whichever a scan shows least busy, always with 20 MHz width in this band."],"href":"wifi.html"},
    {"c":"WiFi","k":["interferencia cocanal vs canal adyacente","diferencia interferencia cocanal adyacente","cual interferencia es peor wifi","co-channel vs adjacent channel interference"],"r":["La interferencia **cocanal** ocurre entre redes en el mismo canal: es la menos mala, porque los equipos se 'oyen' y CSMA/CA reparte el tiempo de aire. La de **canal adyacente** es peor: llega de canales solapados (por ejemplo el 4 contra el 6), suena como ruido que no se puede decodificar y corrompe tramas sin que haya coordinación. Resultado: reintentos y caídas de velocidad. Solución: canales no solapados, 20 MHz en 2,4 GHz y bajar potencia antes que subirla.","**Co-channel** interference happens between networks on the same channel: it is the lesser evil, because devices can 'hear' each other and CSMA/CA shares the airtime. **Adjacent-channel** interference is worse: it comes from overlapping channels (say, 4 against 6), sounds like undecodable noise and corrupts frames with no coordination at all. Result: retries and speed drops. Fix: non-overlapping channels, 20 MHz in 2.4 GHz, and lower the power before raising it."],"href":"wifi.html"},
    {"c":"WiFi","k":["rssi dbm interpretar -50 -65 -75","que rssi es bueno wifi","niveles de senal wifi dbm","wifi rssi levels explained dbm"],"r":["El **RSSI** se mide en dBm, en negativo: cuanto más cerca de cero, mejor. -50 dBm es señal excelente, típica junto al router; -65 dBm es buena y sirve para voz y video sin cortes; -75 dBm es el borde útil: navegas, pero con reintentos y velocidad variable. Por debajo de -80 dBm la conexión se cae o negocia tasas mínimas. Ojo: cada fabricante calibra distinto su indicador, así que compara dBm, no 'rayitas', y mide donde de verdad usas el equipo.","**RSSI** is measured in dBm, as a negative number: the closer to zero, the better. -50 dBm is excellent signal, typical next to the router; -65 dBm is good and handles voice and video without drops; -75 dBm is the usable edge: you can browse, but with retries and variable speed. Below -80 dBm the link drops or negotiates minimum rates. Note: every vendor calibrates its indicator differently, so compare dBm, not 'bars', and measure where you actually use the device."],"href":"wifi.html"},
    {"c":"WiFi","k":["snr minima segun uso wifi","que snr necesito wifi","relacion senal ruido wifi db","wifi snr minimum required"],"r":["La **SNR** es la diferencia entre señal y ruido, en dB: RSSI de -65 con ruido de -95 da 30 dB. Mínimos prácticos: 10-15 dB para datos básicos y correo, 20 dB para web y video fluido, 25 dB o más para voz sobre WiFi, videollamadas y las tasas altas de 802.11ac/ax. Con SNR baja el equipo baja de modulación —de 1024-QAM a QPSK, por ejemplo— y cada trama ocupa más tiempo. Si la SNR es mala, acercar el AP o bajar el ruido ayuda más que subir potencia.","**SNR** is the difference between signal and noise, in dB: an RSSI of -65 with noise at -95 gives 30 dB. Practical minimums: 10-15 dB for basic data and email, 20 dB for smooth web and video, 25 dB or more for voice over WiFi, video calls and the high rates of 802.11ac/ax. With low SNR the device drops modulation —from 1024-QAM down to QPSK, for instance— and each frame takes longer. If SNR is poor, moving the AP closer or reducing noise helps more than raising power."],"href":"wifi.html"},
    {"c":"WiFi","k":["velocidad phy vs velocidad real wifi","por que el wifi da la mitad de velocidad","velocidad de enlace vs real","wifi phy rate vs real throughput"],"r":["La velocidad **PHY** es la tasa de enlace negociada —por ejemplo 866 Mbps en 802.11ac 2x2 a 80 MHz—, no lo que descargas. WiFi es half-duplex y compartido: cabeceras, ACK, esperas CSMA/CA, reintentos y el propio protocolo TCP se quedan con un 40-50 %. Por eso un enlace de 866 suele dar 350-450 Mbps reales en buenas condiciones, y menos si hay vecinos o distancia. Para comprobarlo: mira la tasa negociada en el equipo, mide junto al AP con iperf3 y compara; la diferencia es sobrecarga, no engaño.","The **PHY** rate is the negotiated link speed —for example 866 Mbps on 802.11ac 2x2 at 80 MHz—, not what you download. WiFi is half-duplex and shared: headers, ACKs, CSMA/CA waits, retries and TCP itself eat 40-50 %. That is why an 866 link usually delivers 350-450 real Mbps in good conditions, and less with neighbors or distance. To check: look at the negotiated rate on the device, measure next to the AP with iperf3 and compare; the gap is overhead, not a scam."],"href":"wifi.html"},
    {"c":"WiFi","k":["ofdma wifi 6 como funciona","que es ofdma 802.11ax","unidades de recurso ru wifi","ofdma wifi 6 explained"],"r":["**OFDMA**, de WiFi 6 (802.11ax), divide un canal en unidades de recurso (RU) de 26, 52, 106 tonos y más, para atender a varios clientes a la vez dentro del mismo intervalo de transmisión. Antes, con OFDM, un solo cliente ocupaba todo el canal por turno, aunque enviara un paquetito. Resultado: menos latencia y mejor rendimiento con muchos dispositivos de poco tráfico —sensores, móviles, IoT—. No sube mucho la velocidad máxima de un solo equipo; su ganancia es la eficiencia cuando hay decenas conectados.","**OFDMA**, from WiFi 6 (802.11ax), splits a channel into resource units (RUs) of 26, 52, 106 tones and more, to serve several clients at once within the same transmit interval. Before, with OFDM, a single client took the whole channel per turn, even for a tiny packet. Result: lower latency and better performance with many low-traffic devices —sensors, phones, IoT—. It does not raise one device's top speed much; its win is efficiency when dozens are connected."],"href":"wifi.html"},
    {"c":"WiFi","k":["bss coloring wifi 6 que es","color bss reutilizacion espacial","colision de color wifi","bss coloring wifi 6 explained"],"r":["El **BSS Coloring** de WiFi 6 añade un número de 1 a 63 —el 'color'— a las tramas de cada red. Al recibir una trama, el equipo mira el color enseguida: si es de otra red y la señal llega por debajo del umbral OBSS-PD, puede seguir transmitiendo en vez de esperar. Esto se llama reutilización espacial y sube el rendimiento en pisos y oficinas con muchas redes vecinas. Si dos redes cercanas comparten color hay colisión de color y el AP debe cambiarlo.","WiFi 6 **BSS Coloring** adds a number from 1 to 63 —the 'color'— to each network's frames. On receiving a frame, a device checks the color right away: if it belongs to another network and the signal arrives below the OBSS-PD threshold, it may keep transmitting instead of waiting. This is called spatial reuse and boosts performance in apartments and offices full of neighboring networks. If two nearby networks share a color there is a color collision and the AP must change it."],"href":"wifi.html"},
    {"c":"WiFi","k":["target wake time twt wifi 6","que es twt bateria wifi","ahorro bateria 802.11ax twt","target wake time wifi explained"],"r":["**Target Wake Time (TWT)**, de 802.11ax, negocia con cada cliente cuándo despertará para enviar o recibir, por ejemplo cada 100 ms o cada varios segundos. Entre despertares la radio duerme de verdad, así que móviles y sensores a batería gastan mucho menos. También ordena el tráfico: el AP reparte turnos y evita que veinte equipos IoT se despierten y choquen a la vez. Necesita AP y cliente WiFi 6; un cliente antiguo no lo usa, pero tampoco estorba al resto.","**Target Wake Time (TWT)**, from 802.11ax, negotiates with each client when it will wake up to send or receive, say every 100 ms or every few seconds. Between wake-ups the radio truly sleeps, so phones and battery sensors use far less power. It also organizes traffic: the AP hands out turns and stops twenty IoT devices waking and colliding at once. It needs a WiFi 6 AP and client; a legacy client simply does not use it, without hindering the rest."],"href":"wifi.html"},
    {"c":"WiFi","k":["beamforming explicito vs implicito","diferencia beamforming explicito implicito","como funciona beamforming wifi","explicit vs implicit beamforming wifi"],"r":["El **beamforming** enfoca la señal hacia el cliente usando varias antenas y ajustes de fase. El explícito (802.11ac/ax) mide el canal con tramas de sondeo: el cliente devuelve su matriz de canal y el AP calcula con datos reales, por eso funciona mejor. El implícito lo deduce del tráfico recibido, sin ayuda del cliente, y falla si emisor y receptor no están calibrados igual. Ganancia típica: unos dB extra y tasas más estables a media distancia, no cobertura milagrosa a través de paredes.","**Beamforming** focuses the signal toward the client using several antennas and phase adjustments. Explicit beamforming (802.11ac/ax) measures the channel with sounding frames: the client returns its channel matrix and the AP computes from real data, which is why it works better. Implicit beamforming deduces it from received traffic, without the client's help, and fails if transmitter and receiver are not calibrated alike. Typical gain: a few extra dB and steadier rates at mid distance, not miracle coverage through walls."],"href":"wifi.html"},
    {"c":"WiFi","k":["airtime fairness cliente lento frena red","por que un equipo lento baja todo el wifi","equidad tiempo de aire wifi","airtime fairness slow client wifi"],"r":["En WiFi el recurso escaso es el **tiempo de aire**: una trama a 6 Mbps ocupa 100 veces más que la misma a 600 Mbps. Sin equidad, un cliente lejano y lento frena a toda la red porque cada turno suyo dura muchísimo. El airtime fairness del AP reparte tiempo, no velocidad: da turnos proporcionales para que el cliente lento no acapare. En redes 802.11b/g antiguas un solo equipo b puede obligar a activar protecciones que penalizan a todos.","In WiFi the scarce resource is **airtime**: a frame at 6 Mbps occupies the channel 100 times longer than the same frame at 600 Mbps. Without fairness, one distant, slow client drags down the whole network because each of its turns lasts so long. The AP's airtime fairness shares time, not speed: it hands out proportional turns so the slow client cannot hog the channel. In legacy 802.11b/g networks a single b device can force protection mechanisms that penalize everyone."],"href":"wifi.html"},
    {"c":"WiFi","k":["cliente pegajoso sticky client wifi","el movil no cambia de ap roaming","por que se queda en el router lejano","sticky client wifi roaming problem"],"r":["Un **cliente pegajoso** (sticky client) es el móvil o portátil que se aferra a un AP lejano con -80 dBm aunque tenga otro a -55 dBm al lado. La decisión de cambiar es del cliente, no de la red, y muchos esperan demasiado para no perder la conexión. Síntomas: velocidad pésima siempre en el mismo sitio. Remedios: bajar la potencia de los AP, subir la tasa mínima (desactivar 6-12 Mbps), activar 802.11k/v si el equipo lo soporta y, en casos extremos, el AP puede expulsarlo para forzarlo a reasociarse.","A **sticky client** is the phone or laptop that clings to a far AP at -80 dBm even with another one at -55 dBm right beside it. The decision to roam belongs to the client, not the network, and many wait too long to avoid dropping the connection. Symptom: awful speed always in the same spot. Remedies: lower AP power, raise the minimum rate (disable 6-12 Mbps), enable 802.11k/v if the device supports it and, in extreme cases, the AP can kick it to force re-association."],"href":"wifi.html"},
    {"c":"WiFi","k":["802.11r k v roaming que aporta cada uno","diferencia 802.11r 802.11k 802.11v","roaming rapido wifi normas","802.11r k v roaming explained"],"r":["Tres normas distintas que se confunden: **802.11k** deja que el cliente pida a su AP una lista de vecinos con canal y carga, para no escanear a ciegas. **802.11v** permite al AP sugerirle un AP mejor (BSS Transition) y negociar horarios de sueño. **802.11r** (Fast Transition) acelera la reautenticación WPA2/WPA3 al cambiar de AP, de cientos de ms a menos de 50 ms, clave en voz. k y v informan y sugieren; r acelera la seguridad. El cliente decide siempre el salto.","Three different standards that get mixed up: **802.11k** lets the client ask its AP for a neighbor list with channel and load, so it does not scan blindly. **802.11v** lets the AP suggest a better AP (BSS Transition) and negotiate sleep schedules. **802.11r** (Fast Transition) speeds up WPA2/WPA3 re-authentication when changing AP, from hundreds of ms to under 50 ms, key for voice. k and v inform and suggest; r accelerates security. The client always makes the final roaming decision."],"href":"wifi.html"},
    {"c":"WiFi","k":["band steering problemas tipicos","el iot no conecta por band steering","que es band steering wifi","band steering problems iot wifi"],"r":["El **band steering** intenta empujar a los clientes de doble banda hacia 5 GHz, respondiendo solo en esa banda o retrasando la respuesta en 2,4 GHz. Problemas típicos: equipos IoT que solo aceptan 2,4 y tardan minutos en conectar, clientes que interpretan el silencio como red caída, impresoras y cámaras que nunca se asocian, y saltos erráticos entre bandas. Si algo falla justo al instalar un equipo nuevo, prueba a desactivar el steering o crea un SSID separado solo 2,4 GHz para IoT.","**Band steering** tries to push dual-band clients toward 5 GHz, by answering only on that band or delaying answers on 2.4 GHz. Typical problems: IoT gear that only accepts 2.4 GHz taking minutes to connect, clients reading the silence as a dead network, printers and cameras that never associate, and erratic hopping between bands. If something fails right when a new device is installed, try disabling steering or create a separate 2.4 GHz-only SSID for IoT."],"href":"wifi.html"},
    {"c":"WiFi","k":["bajar potencia de emision mejora wifi","por que menos potencia wifi es mejor","potencia dbm router recomendada","lowering wifi transmit power benefits"],"r":["Subir la potencia no crea una red mejor: el AP grita, pero el móvil, que emite con menos potencia, no puede responder desde lejos. Bajar la **potencia de emisión** —por ejemplo a 14-17 dBm en 5 GHz y menos en 2,4 GHz— iguala el enlace en ambos sentidos, reduce el tamaño de cada celda, mejora el roaming, disminuye la interferencia cocanal con vecinos y permite reutilizar canales cerca. Regla: la potencia de 2,4 GHz debería quedar unos 6 dB por debajo de la de 5 GHz.","Raising power does not create a better network: the AP shouts, but the phone, transmitting with less power, cannot answer from far away. Lowering the **transmit power** —say to 14-17 dBm on 5 GHz and less on 2.4 GHz— balances the link both ways, shrinks each cell, improves roaming, reduces co-channel interference with neighbors and allows channel reuse nearby. Rule of thumb: 2.4 GHz power should sit about 6 dB below the 5 GHz power."],"href":"wifi.html"},
    {"c":"WiFi","k":["wmm qos wifi como funciona","que es wmm 802.11e colas","priorizar voz y video wifi","wmm wifi qos explained"],"r":["**WMM** (Wi-Fi Multimedia, de 802.11e) clasifica el tráfico en cuatro colas de acceso: voz (AC_VO), video (AC_VI), best effort (AC_BE) y fondo (AC_BK). Cada cola espera un tiempo distinto antes de transmitir (EDCA): la voz espera microsegundos y casi siempre gana el canal; las descargas esperan más. Sin WMM activo, 802.11n/ac/ax ni siquiera pueden usar sus tasas altas. Para que funcione, la aplicación o el sistema deben marcar el tráfico (DSCP) y el AP mapearlo a la cola correcta.","**WMM** (Wi-Fi Multimedia, from 802.11e) sorts traffic into four access categories: voice (AC_VO), video (AC_VI), best effort (AC_BE) and background (AC_BK). Each category waits a different time before transmitting (EDCA): voice waits microseconds and almost always wins the channel; downloads wait longer. Without WMM enabled, 802.11n/ac/ax cannot even use their high rates. For it to work, the app or OS must mark traffic (DSCP) and the AP must map it to the right category."],"href":"wifi.html"},
    {"c":"WiFi","k":["wpa3 sae modo transicion wpa2 wpa3","que es wpa3 sae dragonfly","diferencia wpa3 y wpa2 seguridad","wpa3 sae transition mode explained"],"r":["**WPA3-SAE** sustituye el intercambio de claves de WPA2 por SAE (Dragonfly): cada intento de adivinar la contraseña exige interactuar con el AP, así que no sirve capturar un handshake y atacar offline con diccionario. Además da secreto hacia adelante: grabar el tráfico hoy no permite descifrarlo si mañana se filtra la clave. El modo de transición WPA2/WPA3 deja entrar equipos antiguos, pero rebaja parte de la protección —un atacante puede forzar el modo WPA2— y algunos equipos viejos ni siquiera ven la red. Si todo tu parque es moderno, WPA3 puro.","**WPA3-SAE** replaces WPA2's key exchange with SAE (Dragonfly): every password guess requires interacting with the AP, so capturing a handshake and attacking it offline with a dictionary no longer works. It also provides forward secrecy: recording traffic today will not let anyone decrypt it if the password leaks tomorrow. The WPA2/WPA3 transition mode lets legacy devices in, but weakens part of the protection —an attacker can force WPA2 mode— and some old devices cannot even see the network. If all your gear is modern, go pure WPA3."],"href":"wifi.html"},
    {"c":"WiFi","k":["pmf 802.11w que es","protected management frames para que sirve","ataque deauth pmf wifi","pmf 802.11w protected management frames"],"r":["**PMF** (Protected Management Frames, 802.11w) firma criptográficamente las tramas de gestión —desautenticación, desasociación y algunas de acción— para que un atacante no pueda expulsarte de la red falsificando un 'deauth' del AP, ataque clásico con herramientas de auditoría. En WPA3 es obligatorio; en WPA2 suele ser opcional o 'capaz'. Problema típico: equipos muy antiguos o IoT baratos que se asocian mal con PMF requerido; en esos casos déjalo en opcional mientras los renuevas, nunca como solución permanente.","**PMF** (Protected Management Frames, 802.11w) cryptographically signs management frames —deauthentication, disassociation and some action frames— so an attacker cannot kick you off the network by spoofing a 'deauth' from the AP, a classic attack with auditing tools. In WPA3 it is mandatory; in WPA2 it is usually optional or 'capable'. Typical problem: very old gear or cheap IoT that associates badly with PMF required; in those cases leave it optional while you replace them, never as a permanent fix."],"href":"wifi.html"},
    {"c":"WiFi","k":["portal cautivo como lo detecta el sistema","por que no abre el portal cautivo","pagina de acceso hotel wifi deteccion","captive portal detection how it works"],"r":["Al conectar a una red con **portal cautivo**, el sistema operativo lo detecta solo: pide una URL HTTP conocida (en Android, generate_204 de Google; en Apple, su página de éxito) y espera una respuesta concreta. Si llega otra cosa —la página del hotel o del aeropuerto—, sabe que hay portal y abre el navegador de acceso. Por eso a veces 'no abre': bloqueadores de DNS privado o una VPN pueden interceptar esa comprobación. Truco si no salta: visita una web HTTP sencilla, nunca HTTPS, para forzarlo.","When you join a network with a **captive portal**, the OS detects it on its own: it requests a known HTTP URL (on Android, Google's generate_204; on Apple, its success page) and expects a specific response. If something else arrives —the hotel or airport page— it knows there is a portal and opens the sign-in browser. That is why it sometimes 'won't open': private DNS blockers or a VPN can intercept that check. Trick if it does not pop up: visit a simple HTTP site, never HTTPS, to force it."],"href":"wifi.html"},
    {"c":"WiFi","k":["mac aleatoria telefono problemas reservas","mac privada wifi rompe dhcp","filtrado mac y mac aleatoria","random mac address phone dhcp reservation problems"],"r":["Los móviles actuales usan **MAC aleatoria** por cada SSID (rotación en iOS y Android recientes) para que no te rastreen entre redes. En casa eso rompe dos cosas clásicas: las reservas DHCP por MAC —la IP fija 'salta' si la MAC cambia— y el filtrado por MAC, que además nunca fue seguridad real. También llena la lista de dispositivos del router con fantasmas. Solución: en tu red de casa desactiva la MAC privada solo para ese SSID en el teléfono y deja las reservas funcionando.","Today's phones use a **randomized MAC** per SSID (with rotation on recent iOS and Android) so you cannot be tracked across networks. At home that breaks two classics: DHCP reservations by MAC —the 'fixed' IP jumps if the MAC changes— and MAC filtering, which was never real security anyway. It also fills the router's device list with ghosts. Fix: on your home network, turn off the private MAC only for that SSID on the phone and let the reservations work."],"href":"wifi.html"},
    {"c":"WiFi","k":["por que 6 ghz llega menos lejos","alcance wifi 6e vs 5 ghz vs 2.4","6 ghz paredes perdida senal","why 6 ghz wifi has less range"],"r":["La banda de **6 GHz** (WiFi 6E/7) llega menos lejos por física: la pérdida en espacio libre crece con la frecuencia —a doble frecuencia, unos 6 dB más de pérdida a igual distancia— y los materiales absorben más: un tabique que en 2,4 GHz resta poco, en 6 GHz resta mucho más. A cambio ofrece canales limpios de 160-320 MHz sin vecinos ni DFS en gran parte del rango. Diseño correcto: 6 GHz para la misma habitación o la contigua; 2,4 GHz sigue siendo la banda de alcance.","The **6 GHz** band (WiFi 6E/7) reaches less far because of physics: free-space loss grows with frequency —double the frequency means about 6 dB more loss at the same distance— and materials absorb more: a partition wall that costs little at 2.4 GHz costs much more at 6 GHz. In exchange it offers clean 160-320 MHz channels with no neighbors and no DFS across much of the range. Correct design: 6 GHz for the same or the next room; 2.4 GHz remains the range band."],"href":"wifi.html"},
    {"c":"WiFi","k":["backhaul dedicado mesh tribanda","que es backhaul dedicado mesh","mesh tribanda tercera banda para que","dedicated backhaul tri-band mesh wifi"],"r":["En un sistema mesh **tribanda** la tercera radio (5 o 6 GHz) se reserva como backhaul: es el enlace entre nodos y no compite con tus equipos. Sin banda dedicada, nodo y clientes comparten el mismo canal y cada salto recorta el rendimiento. Con backhaul dedicado puedes ver cerca del nodo satélite velocidades parecidas a las del router principal, si el enlace entre ellos es bueno (ideal -60 a -70 dBm). La banda dedicada no aparece como SSID para clientes: es infraestructura interna de la mesh.","In a **tri-band** mesh system the third radio (5 or 6 GHz) is reserved as backhaul: it is the link between nodes and does not compete with your devices. Without a dedicated band, node and clients share the same channel and every hop cuts performance. With a dedicated backhaul you can see, near the satellite node, speeds close to the main router's, if the link between them is good (ideally -60 to -70 dBm). The dedicated band does not appear as a client SSID: it is the mesh's internal infrastructure."],"href":"wifi.html"},
    {"c":"WiFi","k":["backhaul por cable mesh ethernet","conectar nodos mesh por cable mejora","backhaul cableado mesh como hacerlo","wired ethernet backhaul mesh benefits"],"r":["Conectar los nodos mesh por **cable Ethernet** (backhaul cableado, 802.3) es la mejor mejora posible: el enlace entre nodos pasa a ser gigabit dedicado, sin ocupar aire ni sufrir paredes, y los clientes recuperan toda la capacidad WiFi del satélite. Detalles que importan: usa el puerto correcto del nodo (WAN/LAN según el fabricante), cable Cat5e o superior bien crimpado y, si hay switch de por medio, que sea gigabit. Muchos sistemas detectan el cable automáticamente y dejan la radio de backhaul libre para clientes.","Connecting mesh nodes by **Ethernet cable** (wired backhaul, 802.3) is the best upgrade there is: the node-to-node link becomes dedicated gigabit, using no airtime and suffering no walls, and clients recover the satellite's full WiFi capacity. Details that matter: use the node's correct port (WAN/LAN depending on the vendor), Cat5e or better cable, properly crimped, and if there is a switch in between, make it gigabit. Many systems detect the cable automatically and free the backhaul radio for clients."],"href":"wifi.html"},
    {"c":"WiFi","k":["repetidor parte la velocidad mitad","por que el repetidor wifi es lento","repetidor half duplex wifi","why wifi repeater halves speed"],"r":["Un repetidor clásico escucha y reenvía por el **mismo canal y la misma radio**, y WiFi es half-duplex: no puede hacer ambas cosas a la vez. Cada trama ocupa el aire dos veces, así que el rendimiento cae a la mitad o menos, y eso antes de contar reintentos si la señal que recibe ya es mala. Repetir una señal de -80 dBm produce una red 'con rayitas' pero lenta. Alternativas: repetidor de doble banda cruzada, mesh con backhaul dedicado o, mejor, cable hasta el punto de acceso.","A classic repeater listens and forwards on the **same channel and the same radio**, and WiFi is half-duplex: it cannot do both at once. Every frame uses the air twice, so throughput drops to half or less, and that is before counting retries if the signal it receives is already weak. Repeating a -80 dBm signal yields a network 'with full bars' but slow. Alternatives: a cross-band dual-band repeater, mesh with a dedicated backhaul or, better, a cable run to the access point."],"href":"wifi.html"},
    {"c":"WiFi","k":["ganancia antena dbi cobertura error","mas dbi no es mas cobertura","antena 8 dbi zonas muertas casa","antenna gain dbi coverage myth"],"r":["La ganancia en **dBi** no crea energía: la concentra. Una antena de 2-3 dBi reparte en casi todas direcciones; una de 8-9 dBi aplana el patrón vertical como un donut: gana alcance en horizontal pero deja zonas muertas arriba y abajo —malo en una casa de dos plantas—. Por eso 'más dBi = más cobertura' es falso en 3D: mejoras en un plano y empeoras en otro. Además la ganancia de fábrica se mide en el mejor ángulo, no en el promedio real de tu casa.","Gain in **dBi** does not create energy: it concentrates it. A 2-3 dBi antenna spreads it in almost all directions; an 8-9 dBi one flattens the vertical pattern like a donut: it gains horizontal reach but leaves dead zones above and below —bad in a two-story house—. That is why 'more dBi = more coverage' is false in 3D: you improve one plane and worsen another. Also, factory gain is measured at the best angle, not at your home's real average."],"href":"wifi.html"},
    {"c":"Otro","k":["gpt vs mbr diferencias limites","disco gpt o mbr arranque uefi","mbr limite 2 tb 4 particiones","gpt vs mbr differences uefi boot"],"r":["**GPT** y MBR son esquemas de particionado. MBR guarda la tabla en el primer sector, admite discos de hasta 2 TB y 4 particiones primarias, y arranca en modo BIOS heredado. GPT usa GUID, admite discos enormes y 128 particiones en Windows, guarda copia de la tabla al final del disco con comprobación CRC y es el requisito para arrancar en UEFI con Secure Boot. Convertir de MBR a GPT sin perder datos exige herramienta específica (mbr2gpt en Windows) y placa en modo UEFI.","**GPT** and MBR are partitioning schemes. MBR stores the table in the first sector, supports disks up to 2 TB and 4 primary partitions, and boots in legacy BIOS mode. GPT uses GUIDs, supports huge disks and 128 partitions on Windows, keeps a backup copy of the table at the end of the disk with CRC checking, and is required to boot in UEFI with Secure Boot. Converting MBR to GPT without data loss needs a specific tool (mbr2gpt on Windows) and a board set to UEFI mode."],"href":"mantenimiento-software.html#tareas"},
    {"c":"Otro","k":["ransomware como entra defensa copias","copias desconectadas ransomware 3-2-1","como se infecta ransomware phishing","ransomware disconnected backups protection"],"r":["El **ransomware** suele entrar por phishing, adjuntos, RDP expuesto o programas pirateados; una vez dentro cifra documentos y también las copias que alcance: unidades de red montadas y nubes sincronizadas se cifran igual. La defensa que funciona es la regla 3-2-1 con al menos una copia **desconectada o inmutable**: un disco externo que solo se enchufa para copiar y se guarda aparte, o copias con bloqueo de objetos. Prueba la restauración cada cierto tiempo: una copia nunca probada es una esperanza, no una copia.","**Ransomware** usually gets in through phishing, attachments, exposed RDP or pirated software; once inside it encrypts documents and also any backups it can reach: mounted network drives and synced clouds get encrypted too. The defense that works is the 3-2-1 rule with at least one **disconnected or immutable** copy: an external drive plugged in only to copy and stored away afterwards, or backups with object lock. Test restoring from time to time: a backup never tested is a hope, not a backup."],"href":"mantenimiento-software.html#tareas"},
    {"c":"Otro","k":["quishing phishing por qr que es","fraude codigo qr pegatina falsa","peligro escanear qr desconocido","quishing qr code phishing scam"],"r":["El **quishing** es phishing con códigos QR: pegatinas falsas sobre parquímetros, cartas suplantando al banco o correos con un QR que lleva a una página de pago clonada. Funciona porque el QR oculta la URL y porque al escanear saltas al móvil, fuera de las protecciones del correo corporativo. Defensa concreta: antes de escribir credenciales, revisa el dominio que muestra la vista previa del escáner; desconfía de QR pegados encima de otros y nunca instales una app desde un QR desconocido.","**Quishing** is phishing with QR codes: fake stickers over parking meters, letters posing as your bank, or emails with a QR leading to a cloned payment page. It works because the QR hides the URL and because scanning moves you to the phone, outside corporate email protections. Concrete defense: before typing any credentials, check the domain shown in the scanner's preview; distrust QR codes pasted over other QR codes and never install an app from an unknown QR."],"href":"mantenimiento-software.html#tareas"},
    {"c":"Otro","k":["sim swapping que es robo numero","me quede sin cobertura sim swapping","duplicado de sim fraude sms","sim swapping attack warning signs"],"r":["El **SIM swapping** consigue que la operadora pase tu número a una SIM del atacante, tras suplantarte con datos filtrados. En minutos deja de sonarte el móvil y él recibe tus SMS: puede resetear contraseñas y saltarse la verificación por SMS de bancos y correo. Señales: pérdida súbita de cobertura sin motivo. Defensa: PIN de SIM y de portabilidad con la operadora, verificación con app autenticadora o passkey en vez de SMS, y actuar en minutos llamando a la operadora si el teléfono se queda 'sin servicio' de golpe.","**SIM swapping** gets the carrier to move your number to the attacker's SIM, after impersonating you with leaked data. Within minutes your phone goes silent and he receives your texts: he can reset passwords and bypass SMS verification for banks and email. Warning sign: sudden loss of coverage for no reason. Defense: SIM and portability PINs with your carrier, verification via authenticator app or passkey instead of SMS, and acting within minutes —call your carrier— if the phone suddenly shows 'no service'."],"href":"mantenimiento-software.html#tareas"},
    {"c":"Otro","k":["passkeys que son como funcionan","passkey vs contrasena phishing","activar passkey fido2 webauthn","passkeys explained fido2 phishing resistant"],"r":["Las **passkeys** son credenciales FIDO2/WebAuthn: un par de claves donde la privada nunca sale de tu dispositivo y se desbloquea con huella, cara o PIN. Al iniciar sesión firmas un desafío único por sitio, así que un clon de la página no puede reutilizar nada: es resistente al phishing por diseño. Se sincronizan con tu cuenta de Apple, Google o un gestor, y conviven con la contraseña como respaldo. Si un servicio ofrece passkey, actívala: elimina el robo de contraseñas y los códigos interceptados.","**Passkeys** are FIDO2/WebAuthn credentials: a key pair where the private key never leaves your device and unlocks with fingerprint, face or PIN. At sign-in you sign a per-site unique challenge, so a cloned page cannot reuse anything: it is phishing-resistant by design. They sync through your Apple or Google account or a password manager, and coexist with your password as a fallback. If a service offers a passkey, enable it: it removes password theft and intercepted codes."],"href":"mantenimiento-software.html#tareas"},
    {"c":"Otro","k":["cifrado de extremo a extremo e2ee que es","e2ee metadatos que no protege","diferencia cifrado en transito y e2ee","end to end encryption e2ee explained"],"r":["En el **cifrado de extremo a extremo (E2EE)** el mensaje se cifra en tu dispositivo con claves que solo tienen emisor y receptor; el servidor transporta texto cifrado que no puede leer. Protocolos como Signal Protocol usan doble ratchet: cada mensaje estrena claves, dando secreto hacia adelante y recuperación tras una brecha. Lo que E2EE no protege: los metadatos (quién habla con quién y cuándo), las copias de seguridad sin cifrar ni un dispositivo ya comprometido. 'Cifrado en tránsito' a secas no es E2EE: ahí el servidor sí puede leer.","With **end-to-end encryption (E2EE)** the message is encrypted on your device with keys held only by sender and receiver; the server carries ciphertext it cannot read. Protocols like the Signal Protocol use a double ratchet: each message gets fresh keys, giving forward secrecy and recovery after a breach. What E2EE does not protect: metadata (who talks to whom, and when), unencrypted backups, or an already-compromised device. Plain 'encryption in transit' is not E2EE: there, the server can read the content."],"href":"redes.html#redes"},
    {"c":"Otro","k":["huella del navegador fingerprinting que es","fingerprinting sin cookies identificacion","como reducir huella navegador","browser fingerprinting explained tracking"],"r":["La **huella del navegador** (fingerprinting) te identifica sin cookies, combinando decenas de señales: resolución, fuentes instaladas, zona horaria, GPU y cómo dibuja un canvas o procesa audio. Juntas forman una combinación casi única por equipo, útil también contra el fraude, por eso bloquearla del todo rompe webs bancarias. Reducirla: navegador actualizado, no instalar fuentes ni extensiones raras, y navegadores con anti-fingerprinting como Firefox con resistFingerprinting o Brave, que normalizan valores en vez de ocultarlos mal.","**Browser fingerprinting** identifies you without cookies, combining dozens of signals: screen resolution, installed fonts, time zone, GPU, and how your browser draws a canvas or processes audio. Together they form a nearly unique combination per device, also useful against fraud, which is why blocking it entirely breaks banking sites. To reduce it: keep the browser updated, do not install odd fonts or extensions, and use browsers with anti-fingerprinting such as Firefox with resistFingerprinting or Brave, which normalize values instead of hiding them badly."],"href":"redes.html#redes"},
    {"c":"Otro","k":["robo de sesion cookies tokens infostealer","me robaron la sesion sin contrasena","malware roba cookies navegador","session hijacking stolen cookies tokens"],"r":["Muchas webs no guardan tu contraseña en el navegador, sino un **token de sesión** (cookie) que equivale a estar dentro. El malware infostealer moderno roba esas cookies y contraseñas guardadas en segundos y las vende; el atacante las importa y entra sin contraseña y, a veces, sin segundo factor, porque la sesión ya estaba verificada. Defensa: navegador y sistema actualizados, no instalar cracks, cerrar sesiones en equipos ajenos y, ante sospecha, 'cerrar todas las sesiones' desde el servicio para invalidar los tokens robados.","Many sites do not store your password in the browser, but a **session token** (cookie) that amounts to being signed in. Modern infostealer malware steals those cookies and saved passwords in seconds and sells them; the attacker imports them and gets in with no password and sometimes no second factor, because the session was already verified. Defense: keep browser and OS updated, install no cracks, sign out on other people's machines and, if suspicious, use the service's 'sign out everywhere' to invalidate stolen tokens."],"href":"mantenimiento-software.html#tareas"},
    {"c":"Otro","k":["spf dkim dmarc que son correo","proteger dominio correo suplantacion dns","dmarc reject spf dkim explicados","spf dkim dmarc email protection explained"],"r":["Tres registros DNS que protegen un dominio de correo. **SPF** lista qué servidores pueden enviar con tu dominio. **DKIM** firma criptográficamente cada correo y el receptor verifica la firma contra una clave publicada en DNS. **DMARC** dice qué hacer si alguno falla —nada, cuarentena o rechazo— y envía informes. Sin DMARC en modo reject, cualquiera puede suplantar tu dominio aunque SPF y DKIM existan. Al montar un dominio: publica los tres, vigila los informes unas semanas y solo después pasa DMARC a reject.","Three DNS records protect an email domain. **SPF** lists which servers may send using your domain. **DKIM** cryptographically signs each message and the receiver verifies the signature against a key published in DNS. **DMARC** says what to do if one fails —nothing, quarantine or reject— and sends reports. Without DMARC in reject mode, anyone can spoof your domain even if SPF and DKIM exist. When setting up a domain: publish all three, watch the reports for a few weeks, and only then move DMARC to reject."],"href":"redes.html#redes"},
    {"c":"Otro","k":["totp app autenticadora vs sms codigos","codigos sms inseguros autenticador mejor","rfc 6238 totp 30 segundos","totp authenticator app vs sms codes"],"r":["Los códigos por SMS viajan por la red telefónica: se interceptan con SIM swapping, desvíos y redes SS7 débiles. Una app autenticadora **TOTP** (RFC 6238) calcula el código localmente a partir de un secreto compartido y la hora, en ventanas de 30 segundos: no hay nada que interceptar en tránsito. Además el código TOTP no depende de cobertura. Migra primero correo y banco: guarda los códigos de recuperación offline y, si cambias de móvil, exporta las cuentas antes de borrar la app antigua.","SMS codes travel over the phone network: they can be intercepted via SIM swapping, forwarding and weak SS7 networks. A **TOTP** authenticator app (RFC 6238) computes the code locally from a shared secret and the time, in 30-second windows: there is nothing to intercept in transit. TOTP codes also do not depend on coverage. Migrate email and banking first: keep recovery codes offline and, if you change phones, export the accounts before deleting the old app."],"href":"mantenimiento-software.html#tareas"},
    {"c":"Otro","k":["contenedores docker vs maquinas virtuales","diferencia docker y vm cuando usar","contenedor comparte kernel hipervisor","docker containers vs virtual machines difference"],"r":["Una **máquina virtual** emula hardware completo: cada VM lleva su propio sistema operativo invitado sobre un hipervisor, arranca en minutos y aísla fuerte, a costa de GB de RAM y disco. Un **contenedor** Docker comparte el kernel del anfitrión y empaqueta solo la aplicación y sus librerías: arranca en segundos y pesa MB, pero el aislamiento es de procesos, no de máquina. Regla práctica: contenedores para desplegar aplicaciones y microservicios; VMs cuando necesitas otro sistema operativo o una frontera de seguridad dura.","A **virtual machine** emulates complete hardware: each VM carries its own guest operating system on a hypervisor, boots in minutes and isolates strongly, at the cost of GBs of RAM and disk. A Docker **container** shares the host kernel and packages only the app and its libraries: it starts in seconds and weighs MBs, but isolation is at process level, not machine level. Practical rule: containers to deploy applications and microservices; VMs when you need a different operating system or a hard security boundary."],"href":"hardware.html#componentes"},
    {"c":"Otro","k":["alucinaciones chatbot ia que son","la ia se inventa respuestas por que","como detectar alucinacion ia","ai chatbot hallucinations explained"],"r":["Un chatbot de IA comete una **alucinación** cuando afirma con total seguridad algo inventado: una ley que no existe, una cita falsa, un comando con parámetros imposibles. Pasa porque el modelo predice texto plausible, no verifica hechos: su objetivo es que suene bien, no que sea verdad. Defensa práctica: pídele fuentes y compruébalas, desconfía de datos muy concretos sin referencia (fechas, cifras, normas) y contrasta lo importante en una segunda fuente. Si te da una referencia, ábrela: muchas veces el enlace no dice lo que afirma.","An AI chatbot commits a **hallucination** when it confidently states something invented: a law that does not exist, a fake quote, a command with impossible parameters. It happens because the model predicts plausible text; it does not verify facts: its goal is to sound right, not to be right. Practical defense: ask it for sources and check them, distrust very specific claims without references (dates, figures, regulations) and cross-check anything important in a second source. If it gives you a reference, open it: often the link does not say what it claims."],"href":"index.html"},
    {"c":"Otro","k":["que es un token en ia ventana de contexto","tokens ia contexto 128k olvida","cuantas palabras es un token","ai tokens and context window explained"],"r":["En IA un **token** es el trozo en que el modelo parte el texto: palabras, sílabas o signos; en español, unas 100 palabras son unos 130-150 tokens. La **ventana de contexto** es cuántos tokens puede 'ver' a la vez el modelo —por ejemplo 128k—: incluye tu pregunta, el historial y su respuesta. Al llenarse, lo antiguo se recorta y el modelo 'olvida' el principio de la conversación. Por eso en chats largos conviene resumir lo importante y repetir los datos clave junto a la nueva petición.","In AI a **token** is the chunk the model splits text into: words, syllables or punctuation; in Spanish, about 100 words make roughly 130-150 tokens. The **context window** is how many tokens the model can 'see' at once —for example 128k—: it includes your question, the history and its answer. When it fills up, the oldest parts get trimmed and the model 'forgets' the start of the conversation. That is why, in long chats, it helps to summarize what matters and repeat key facts with the new request."],"href":"index.html"},
    {"c":"Otro","k":["nube publica vs privada vs hibrida","diferencia tipos de nube cual elegir","cloud publica privada hibrida definicion","public private hybrid cloud differences"],"r":["En la **nube pública** compartes infraestructura de un proveedor (AWS, Azure, Google) pagando por uso: elástica y sin comprar hardware, pero con costes que crecen y datos fuera de casa. La **privada** es infraestructura dedicada, propia o alojada: más control y previsibilidad, más inversión y mantenimiento. La **híbrida** combina ambas: lo sensible y constante en privado; los picos y servicios puntuales en pública, unidos por red privada o VPN. La elección suele decidirla el tipo de carga y la normativa de datos, no la moda.","In the **public cloud** you share a provider's infrastructure (AWS, Azure, Google) paying per use: elastic and with no hardware to buy, but with growing costs and data outside your premises. The **private cloud** is dedicated infrastructure, owned or hosted: more control and predictability, more investment and maintenance. The **hybrid cloud** combines both: sensitive, steady workloads in private; peaks and one-off services in public, joined by a private network or VPN. The choice is usually decided by workload type and data regulations, not fashion."],"href":"redes.html#redes"},
    {"c":"Otro","k":["pin windows hello vs contrasena seguridad","pin ligado al dispositivo tpm","por que el pin es mas seguro windows","windows hello pin vs password security"],"r":["El **PIN de Windows Hello** no es una contraseña corta: está ligado a ese dispositivo concreto y, con TPM, protegido contra ataques por fuerza bruta. La contraseña de la cuenta Microsoft se puede probar desde internet contra otros servicios; el PIN solo funciona físicamente en ese equipo y nunca viaja. Por eso Microsoft lo considera más seguro que la contraseña para iniciar sesión local, y lo combina con huella o rostro. Un PIN de 6 dígitos con TPM y bloqueo tras varios fallos supera en la práctica a una contraseña reutilizada.","The **Windows Hello PIN** is not a short password: it is tied to that specific device and, with a TPM, protected against brute-force attacks. Your Microsoft account password can be tried from the internet against other services; the PIN only works physically on that machine and never travels. That is why Microsoft considers it more secure than the password for local sign-in, and combines it with fingerprint or face. A 6-digit PIN with TPM and lockout after failed attempts beats, in practice, a reused password."],"href":"mantenimiento-software.html#tareas"},
    {"c":"Otro","k":["cuenta local vs cuenta microsoft windows","ventajas cuenta local windows privacidad","que cuenta usar en windows 11","local account vs microsoft account windows"],"r":["Con **cuenta Microsoft**, Windows sincroniza ajustes, claves WiFi y de BitLocker en la nube y facilita recuperar el equipo, pero vincula tu actividad a una identidad online y Windows insiste en ella durante la instalación. Con **cuenta local** todo queda en el equipo: más privacidad y control, pero si olvidas la contraseña y no hay disco de restablecimiento, recuperar el acceso es mucho más duro. En ambos casos crea una segunda cuenta administradora de respaldo y guarda la clave de BitLocker fuera del propio PC.","With a **Microsoft account**, Windows syncs settings, WiFi keys and BitLocker keys to the cloud and makes recovering the machine easier, but it ties your activity to an online identity and Windows pushes it during setup. With a **local account** everything stays on the machine: more privacy and control, but if you forget the password and have no reset disk, regaining access is much harder. In both cases, create a second backup administrator account and store the BitLocker key outside the PC itself."],"href":"mantenimiento-software.html#tareas"},
    {"c":"Otro","k":["minidump error whea pantalla azul causa","whea_uncorrectable_error 0x124 hardware","leer minidump bluescreen causa probable","minidump whea uncorrectable error bsod cause"],"r":["Tras una pantalla azul, Windows guarda un **minidump** en C:\\Windows\\Minidump con el código de parada y el módulo implicado. Si el error es **WHEA_UNCORRECTABLE_ERROR (0x124)**, casi siempre es hardware: CPU, RAM inestable, temperaturas o fuente, no un driver cualquiera. Herramientas como BlueScreenView o WinDbg muestran el parámetro 1 del WHEA: 0 suele apuntar a caché/núcleo de CPU y 4 a PCIe. Plan: anota el código, revisa temperaturas, pasa MemTest86 y deshaz cualquier overclock antes de reinstalar nada.","After a blue screen, Windows saves a **minidump** in C:\\Windows\\Minidump with the stop code and the module involved. If the error is **WHEA_UNCORRECTABLE_ERROR (0x124)**, it is almost always hardware: CPU, unstable RAM, temperatures or power supply, not some random driver. Tools like BlueScreenView or WinDbg show WHEA parameter 1: 0 usually points to CPU cache/core and 4 to PCIe. Plan: note the code, check temperatures, run MemTest86 and undo any overclock before reinstalling anything."],"href":"mantenimiento-software.html#tareas"},
    {"c":"Otro","k":["inicio rapido windows efectos bios dual boot","fast startup windows apagar no es reiniciar","inicio rapido problema linux arranque dual","windows fast startup effects dual boot"],"r":["El **inicio rápido** de Windows (Fast Startup) no apaga del todo: al apagar, cierra tu sesión pero hiberna el kernel en el archivo hiberfil.sys, y al encender lo recarga. Por eso 'apagar y encender' no equivale a reiniciar y algunos problemas sobreviven al apagado pero no al reinicio. Efectos colaterales: entrar en la BIOS se complica porque el arranque vuela, y en arranque dual con Linux, Windows deja el disco NTFS 'sucio' y Linux lo monta solo en lectura. Si algo falla raro, reinicia; no apagues.","Windows **Fast Startup** does not fully shut down: on shutdown it closes your session but hibernates the kernel into the hiberfil.sys file, and reloads it at power-on. That is why 'shut down and turn on' is not a restart, and some problems survive a shutdown but not a restart. Side effects: getting into the BIOS gets tricky because boot flies by, and in a dual boot with Linux, Windows leaves the NTFS disk 'dirty' and Linux mounts it read-only. If something fails oddly, restart; do not shut down."],"href":"mantenimiento-software.html#tareas"},
    {"c":"Otro","k":["suspender vs hibernar vs apagar diferencia","hibernar portatil varios dias consumo","que es hibernar windows hiberfil","suspend vs hibernate vs shutdown difference"],"r":["**Suspender** guarda el trabajo en RAM y mantiene un consumo mínimo: despierta en segundos, pero si se acaba la batería pierdes la sesión. **Hibernar** escribe la RAM entera al disco (hiberfil.sys) y consume cero: despierta más lento y recupera todo tal cual, ideal para portátiles que pasan días sin uso. **Apagar** cierra sistema y programas —con inicio rápido, ni siquiera del todo—. Regla práctica: suspender para pausas cortas del mismo día, hibernar para guardar el portátil varios días, reiniciar cuando algo va mal.","**Suspend** keeps your work in RAM with minimal power draw: it wakes in seconds, but if the battery dies you lose the session. **Hibernate** writes the whole RAM to disk (hiberfil.sys) and uses zero power: it wakes slower and restores everything exactly, ideal for laptops left unused for days. **Shut down** closes the OS and programs —with Fast Startup, not even fully—. Practical rule: suspend for short breaks the same day, hibernate to store the laptop for several days, restart when something goes wrong."],"href":"mantenimiento-software.html#tareas"},
    {"c":"Otro","k":["hipervisor tipo 1 vs tipo 2 diferencia","hipervisor bare metal vs hosted ejemplos","proxmox esxi tipo 1 virtualbox tipo 2","type 1 vs type 2 hypervisor difference"],"r":["Un **hipervisor tipo 1** (bare-metal) se ejecuta directamente sobre el hardware y hospeda las máquinas virtuales sin sistema anfitrión debajo: ESXi, Hyper-V Server o Proxmox. Es el de servidores: menos sobrecarga y mejor aislamiento. El **tipo 2** (hosted) es un programa más sobre tu Windows o Linux —VirtualBox, VMware Workstation—: cómodo para probar sistemas en tu PC, pero añade una capa y compite con tus programas por los recursos. Si la VM es para trabajar en serio todo el día, tipo 1; para experimentar, tipo 2.","A **type 1 hypervisor** (bare-metal) runs directly on the hardware and hosts virtual machines with no host OS underneath: ESXi, Hyper-V Server or Proxmox. It is the server kind: less overhead and better isolation. A **type 2 hypervisor** (hosted) is just another program on your Windows or Linux —VirtualBox, VMware Workstation—: handy for testing systems on your PC, but it adds a layer and competes with your programs for resources. If the VM is for serious all-day work, type 1; to experiment, type 2."],"href":"hardware.html#componentes"},
    {"c":"Recursos","k":["dism restorehealth antes que sfc","orden dism y sfc","reparar imagen de windows","dism restorehealth order before sfc"],"r":["**DISM** repara la imagen de Windows que SFC usa como fuente, por eso va primero. Abre Terminal como administrador y ejecuta `DISM /Online /Cleanup-Image /RestoreHealth`; espera al 100%, aunque parezca detenido en el 20% o el 40%. Después ejecuta `sfc /scannow`. Si DISM falla sin conexión, usa una ISO de la misma versión con `/Source:D:\\sources\\install.wim /LimitAccess`. Reinicia al terminar y, si SFC reparó archivos, repítelo una vez más. No cierres la ventana durante ninguno de los dos procesos.","**DISM** repairs the Windows image that SFC uses as its source, so it goes first. Open Terminal as administrator and run `DISM /Online /Cleanup-Image /RestoreHealth`; wait for 100%, even if it seems stuck at 20% or 40%. Then run `sfc /scannow`. If DISM fails with no connection, use an ISO of the same version with `/Source:D:\\sources\\install.wim /LimitAccess`. Restart when finished and, if SFC repaired files, run it once more. Do not close the window during either process."],"href":"recursos.html#laboratorio"},
    {"c":"Recursos","k":["chkdsk f o r diferencia","chkdsk f repara errores logicos","chkdsk r sectores defectuosos","chkdsk /f vs /r difference"],"r":["La diferencia está en el alcance: `chkdsk C: /f` repara errores **lógicos** del sistema de archivos, como índices dañados o registros inconsistentes, y necesita bloquear la unidad. `chkdsk C: /r` incluye todo lo de `/f` y además busca **sectores defectuosos**, intenta recuperar su información y los marca para no volver a usarlos. Por eso `/r` tarda horas en discos grandes. En el disco del sistema, Windows pedirá reiniciar para ejecutar la comprobación antes de arrancar. Empieza por `/f`; reserva `/r` si hay síntomas físicos: bloqueos, ruidos o errores de lectura.","The difference is scope: `chkdsk C: /f` repairs **logical** file-system errors, such as damaged indexes or inconsistent records, and needs to lock the drive. `chkdsk C: /r` includes everything `/f` does and also scans for **bad sectors**, tries to recover their data and marks them so they are not used again. That is why `/r` takes hours on large disks. On the system drive, Windows will ask to restart to run the check before booting. Start with `/f`; save `/r` for physical symptoms: freezes, noises or read errors."],"href":"mantenimiento-software.html#tareas"},
    {"c":"Recursos","k":["comprobar trim activo ssd","fsutil behavior query disabledeletenotify","optimizar unidades desfragmentar ssd","check if trim is enabled ssd"],"r":["Para comprobar **TRIM** en un SSD, abre Terminal como administrador y ejecuta `fsutil behavior query DisableDeleteNotify`. Si devuelve `DisableDeleteNotify = 0` para NTFS, TRIM está activo; si devuelve 1, está desactivado. Después abre **Optimizar unidades** (`dfrgui`), selecciona el SSD y confirma que el tipo de medio dice «Unidad de estado sólido» y que la optimización programada está activada: en un SSD eso ejecuta retrim, no una desfragmentación clásica. No fuerces desfragmentar un SSD como si fuera un HDD: acorta su vida útil sin mejorar el rendimiento.","To check **TRIM** on an SSD, open Terminal as administrator and run `fsutil behavior query DisableDeleteNotify`. If it returns `DisableDeleteNotify = 0` for NTFS, TRIM is enabled; if it returns 1, it is disabled. Then open **Optimize Drives** (`dfrgui`), select the SSD and confirm the media type says 'Solid state drive' and scheduled optimization is on: on an SSD that runs retrim, not a classic defragmentation. Do not force-defragment an SSD as if it were an HDD: it shortens its lifespan without improving performance."],"href":"mantenimiento-software.html#tareas"},
    {"c":"Recursos","k":["powercfg batteryreport capacidad real","informe de bateria portatil","capacidad de diseno vs capacidad total","battery report design vs full charge capacity"],"r":["`powercfg /batteryreport` genera un informe HTML, normalmente en `C:\\Users\\tu-usuario\\battery-report.html`. Ábrelo y compara dos valores de la primera tabla: **DESIGN CAPACITY**, la capacidad original de fábrica, y **FULL CHARGE CAPACITY**, lo que la batería carga hoy como máximo. Divide el segundo entre el primero: si da 0,80, la batería conserva el 80% de salud. Revisa también «Cycle count» y el historial reciente: una caída brusca entre periodos suele indicar una celda dañada, no solo desgaste. Es un informe de lectura: no modifica nada del sistema.","`powercfg /batteryreport` generates an HTML report, usually at `C:\\Users\\your-user\\battery-report.html`. Open it and compare two values in the first table: **DESIGN CAPACITY**, the original factory capacity, and **FULL CHARGE CAPACITY**, what the battery charges to today at most. Divide the second by the first: if you get 0.80, the battery keeps 80% health. Also check 'Cycle count' and the recent history: a sudden drop between periods usually points to a damaged cell, not just wear. It is a read-only report: it changes nothing in the system."],"href":"recursos.html#laboratorio"},
    {"c":"Recursos","k":["powercfg energy informe energia","diagnostico consumo energia windows","powercfg energy 60 segundos","powercfg energy report errors"],"r":["`powercfg /energy` observa el equipo durante 60 segundos y guarda `energy-report.html` con errores, advertencias e información. Ejecútalo en Terminal como administrador, con el portátil conectado a corriente y sin tocar nada durante el análisis. Lee primero los **errores**: suelen señalar dispositivos USB que impiden suspender, controladores que bloquean el modo de espera o solicitudes que mantienen despierto el procesador. Las advertencias indican ineficiencias menores. Anota el dispositivo o controlador exacto antes de cambiar nada, y contrasta el resultado tras actualizar ese controlador concreto; no desactives dispositivos al azar buscando ahorrar batería.","`powercfg /energy` observes the computer for 60 seconds and saves `energy-report.html` with errors, warnings and information. Run it in Terminal as administrator, with the laptop plugged in and without touching anything during the trace. Read the **errors** first: they usually point to USB devices preventing sleep, drivers blocking standby, or requests keeping the processor awake. Warnings indicate minor inefficiencies. Note the exact device or driver before changing anything, and compare the result after updating that specific driver; do not disable devices at random chasing battery savings."],"href":"recursos.html#laboratorio"},
    {"c":"Recursos","k":["visor de eventos filtrar por id","errores criticos visor eventos id","event viewer filter event id critical"],"r":["En el **Visor de eventos** no se lee el registro entero: se filtra. Ve a Registros de Windows > Sistema o Aplicación, pulsa «Filtrar registro actual» y marca los niveles Crítico y Error. En el campo de **Id. de evento** escribe los códigos que buscas, separados por comas, y limita el intervalo a la hora del fallo. Abre el evento y anota origen, ID y descripción antes de buscar soluciones: el mismo ID con orígenes distintos significa cosas distintas. Guardar el filtro como vista personalizada te ahorra repetirlo en cada revisión.","In **Event Viewer** you do not read the whole log: you filter it. Go to Windows Logs > System or Application, click 'Filter Current Log' and tick the Critical and Error levels. In the **Event ID** field, type the codes you are looking for, separated by commas, and limit the range to the time of the failure. Open the event and note source, ID and description before searching for fixes: the same ID with different sources means different things. Saving the filter as a custom view saves you repeating it on every check."],"href":"mantenimiento-software.html#alertas"},
    {"c":"Recursos","k":["monitor de confiabilidad historial fallos","reliability monitor windows historia","ver historial de fallos y cuelgues","reliability monitor crash history"],"r":["El **Monitor de confiabilidad** resume los fallos del equipo en una línea de tiempo diaria, más legible que el Visor de eventos. Búscalo escribiendo «Ver historial de confiabilidad». Cada día recibe una puntuación de estabilidad de 1 a 10; los iconos rojos marcan fallos de aplicaciones o de Windows, y los amarillos, advertencias. Pulsa un día con bajada brusca y revisa «Ver detalles técnicos»: ahí se conectan cuelgues, instalaciones y actualizaciones. Si la puntuación cae justo tras instalar un programa o controlador concreto, ese es tu primer sospechoso, no el hardware.","The **Reliability Monitor** summarises the computer's failures on a daily timeline, more readable than Event Viewer. Find it by typing 'View reliability history'. Each day gets a stability score from 1 to 10; red icons mark application or Windows failures, and yellow ones warnings. Click a day with a sharp drop and check 'View technical details': that is where crashes, installs and updates connect. If the score falls right after installing a specific program or driver, that is your first suspect, not the hardware."],"href":"mantenimiento-software.html#alertas"},
    {"c":"Recursos","k":["winre opciones recuperacion cual usar","entorno recuperacion windows que elegir","windows recovery environment options"],"r":["**WinRE** es el entorno de recuperación que arranca fuera de Windows. Elige según el caso: «Restaurar sistema» si el fallo empezó tras un cambio reciente y hay un punto de restauración; «Desinstalar actualizaciones» si el problema llegó con la última actualización; «Reparación de inicio» si Windows no arranca pero el disco responde; «Símbolo del sistema» para comandos como `chkdsk` o `bootrec` cuando sabes qué reparar; y «Restablecer este PC» solo como último recurso. Se entra desde Configuración > Recuperación > Inicio avanzado, o forzando dos apagados durante el arranque.","**WinRE** is the recovery environment that starts outside Windows. Choose by case: 'System Restore' if the failure began after a recent change and a restore point exists; 'Uninstall Updates' if the problem arrived with the latest update; 'Startup Repair' if Windows will not boot but the disk responds; 'Command Prompt' for commands like `chkdsk` or `bootrec` when you know what to repair; and 'Reset this PC' only as a last resort. Enter it from Settings > Recovery > Advanced startup, or by forcing two shutdowns during boot."],"href":"mantenimiento-software.html#paso-a-paso"},
    {"c":"Recursos","k":["restablecer pc conservando archivos o instalacion limpia","reset pc keep files vs clean install","cuando restablecer y cuando reinstalar"],"r":["**Restablecer este PC** conservando archivos reinstala Windows, mantiene tus documentos personales, pero elimina programas instalados y restablece la configuración: sirve cuando el sistema está dañado pero el hardware está sano. La **instalación limpia** desde USB borra todo, particiones incluidas si lo eliges, y deja el equipo como de fábrica: es la opción ante malware persistente, cambio de disco o años de errores acumulados. En ambos casos haz copia previa de tus archivos, porque «conservar archivos» no protege ante un disco que falla a mitad del proceso. Ten a mano tus licencias y contraseñas.","**Reset this PC** keeping your files reinstalls Windows, keeps your personal documents, but removes installed programs and resets settings: it suits a damaged system on healthy hardware. A **clean install** from USB erases everything, partitions included if you choose, and leaves the machine factory-fresh: it is the option for persistent malware, a disk swap or years of accumulated errors. In both cases back up your files first, because 'keep my files' does not protect against a disk failing mid-process. Keep your licences and passwords at hand."],"href":"mantenimiento-software.html#paso-a-paso"},
    {"c":"Recursos","k":["arranque limpio clean boot aislar","clean boot msconfig servicios terceros","inicio limpio conflicto programas","clean boot isolate conflicting programs"],"r":["El **arranque limpio** inicia Windows solo con servicios de Microsoft para aislar conflictos. En `msconfig`, pestaña Servicios, marca «Ocultar todos los servicios de Microsoft» y luego «Deshabilitar todos»: ese orden es la precaución clave, así no tocas los del sistema. Después, en el Administrador de tareas > Inicio, deshabilita todo. Reinicia: si el fallo desaparece, un servicio o programa de terceros era el culpable; reactiva por mitades hasta localizarlo. Al terminar, vuelve a `msconfig` y deja «Inicio normal» para no quedarte en modo diagnóstico sin darte cuenta.","A **clean boot** starts Windows with Microsoft services only, to isolate conflicts. In `msconfig`, Services tab, tick 'Hide all Microsoft services' and then 'Disable all': that order is the key precaution, so you never touch system services. Then, in Task Manager > Startup, disable everything. Restart: if the failure disappears, a third-party service or program was the culprit; re-enable in halves until you find it. When done, return to `msconfig` and set 'Normal startup' so you do not stay in diagnostic mode without noticing."],"href":"mantenimiento-software.html#paso-a-paso"},
    {"c":"Recursos","k":["servicio manual o deshabilitado diferencia","poner servicio en manual windows","manual vs disabled service difference"],"r":["Poner un servicio en **Manual** significa que Windows lo arranca solo cuando algo lo necesita; ponerlo en **Deshabilitado** significa que no puede arrancar nunca, ni aunque otro componente lo pida. Por eso, ante la duda, Manual es la opción reversible y segura: si una función falla, el servicio puede levantarse solo. Deshabilitado se reserva para servicios que conoces bien y que rompen dependencias si faltan. Antes de cambiar cualquiera, anota su estado original en una lista: revertir en orden inverso es la forma rápida de deshacer un experimento que salió mal.","Setting a service to **Manual** means Windows starts it only when something needs it; setting it to **Disabled** means it can never start, even if another component requests it. That is why, when in doubt, Manual is the reversible, safe choice: if a function breaks, the service can still come up on its own. Disabled is reserved for services you know well and that break dependencies if missing. Before changing any of them, write down its original state: reverting in reverse order is the fast way to undo an experiment gone wrong."],"href":"mantenimiento-software.html#tareas"},
    {"c":"Recursos","k":["servicios que nunca se desactivan windows","no desactivar rpc dcom plug and play","servicios criticos windows update audio","windows services never disable"],"r":["Hay servicios que no se desactivan nunca porque todo lo demás depende de ellos. **RPC** y el Iniciador de procesos de servidor **DCOM** sostienen la comunicación entre componentes: sin ellos, media Windows deja de responder. **Plug and Play** detecta el hardware; si falta, no se reconocen dispositivos nuevos. **Windows Update** mantiene el sistema parcheado, y el servicio de **audio** de Windows es requisito directo del sonido. Si un equipo va lento, la respuesta no es apagar estos pilares, sino buscar qué proceso concreto consume recursos en el Administrador de tareas.","Some services are never disabled because everything else depends on them. **RPC** and the **DCOM** Server Process Launcher hold communication between components: without them, half of Windows stops responding. **Plug and Play** detects hardware; without it, new devices are not recognised. **Windows Update** keeps the system patched, and the Windows **Audio** service is a direct requirement for sound. If a machine runs slowly, the answer is not switching off these pillars, but finding which specific process is consuming resources in Task Manager."],"href":"mantenimiento-software.html#alertas"},
    {"c":"Recursos","k":["disco al 100 administrador tareas causas","disco 100 por ciento que revisar orden","disk usage 100 percent task manager causes","disco al 100 por ciento en el administrador de tareas","uso del disco al 100 por ciento"],"r":["Disco al **100%** no siempre significa disco dañado: significa que la cola de peticiones está saturada. Revisa en este orden en el Administrador de tareas, pestaña Procesos, ordenando por columna Disco: primero, si **Windows Update** o el instalador de módulos está trabajando, espera a que termine; segundo, el antivirus haciendo un análisis completo; tercero, un HDD viejo intentando seguir el ritmo, síntoma típico si además todo abre lento. Comprueba la salud con CrystalDiskInfo y el espacio libre: con menos del 15% libre, cualquier disco se ahoga. No desactives servicios a ciegas.","Disk at **100%** does not always mean a damaged disk: it means the request queue is saturated. Check in this order in Task Manager, Processes tab, sorting by the Disk column: first, if **Windows Update** or the module installer is working, let it finish; second, the antivirus running a full scan; third, an old HDD struggling to keep up, a typical symptom if everything also opens slowly. Check health with CrystalDiskInfo and free space: with under 15% free, any disk chokes. Do not disable services blindly."],"href":"mantenimiento-software.html#alertas"},
    {"c":"Recursos","k":["signo amarillo administrador dispositivos codigo 28 43","error codigo 28 driver no instalado","error codigo 43 dispositivo detenido","device manager code 28 code 43 yellow mark"],"r":["El signo amarillo en el **Administrador de dispositivos** significa que el dispositivo no funciona bien, y el código lo aclara. **Código 28**: faltan los controladores; entra en Propiedades > Controlador > Actualizar controlador, y si Windows no lo encuentra, instala el paquete del fabricante. **Código 43**: Windows detuvo el dispositivo porque informó de un problema, típico en gráficas y USB; prueba desinstalar el dispositivo marcando eliminar el controlador, reinicia y deja que se reinstale limpio. Anota el código exacto y el modelo antes de descargar nada: cada código pide una solución distinta.","The yellow mark in **Device Manager** means the device is not working properly, and the code explains why. **Code 28**: the drivers are missing; go to Properties > Driver > Update driver, and if Windows cannot find it, install the manufacturer's package. **Code 43**: Windows stopped the device because it reported a problem, typical of graphics cards and USB; try uninstalling the device ticking delete the driver, restart and let it reinstall cleanly. Note the exact code and model before downloading anything: each code calls for a different fix."],"href":"mantenimiento-software.html#alertas"},
    {"c":"Recursos","k":["instalar driver manualmente archivo inf","instalar controlador desde inf administrador dispositivos","install driver manually from inf file"],"r":["Instalar un controlador desde un **INF** sirve cuando el fabricante da un paquete ZIP sin instalador. Descomprímelo en una carpeta conocida. En el Administrador de dispositivos, clic derecho sobre el dispositivo > Actualizar controlador > «Buscar controladores en mi equipo» > «Elegir de una lista» > «Usar disco» y señala el archivo `.inf` de la carpeta, eligiendo la variante de tu arquitectura si hay carpetas x64 y ARM. Acepta solo controladores **firmados** o del fabricante oficial: Windows avisará si la firma no es válida, y ese aviso no se ignora a la ligera.","Installing a driver from an **INF** is useful when the manufacturer provides a ZIP package with no installer. Extract it to a known folder. In Device Manager, right-click the device > Update driver > 'Browse my computer for drivers' > 'Let me pick from a list' > 'Have Disk' and point to the `.inf` file in the folder, choosing your architecture variant if there are x64 and ARM folders. Accept only **signed** drivers or ones from the official manufacturer: Windows will warn if the signature is invalid, and that warning is not ignored lightly."],"href":"mantenimiento-software.html#tareas"},
    {"c":"Recursos","k":["revertir controlador rollback driver","volver al controlador anterior paso a paso","roll back driver previous version"],"r":["Si un fallo empezó justo tras actualizar un controlador, el **rollback** vuelve a la versión anterior sin reinstalar nada. Abre el Administrador de dispositivos, entra en Propiedades del dispositivo > pestaña Controlador > «Revertir al controlador anterior». Windows preguntará el motivo: elige el que encaje, por ejemplo que la versión nueva no funciona. El botón aparece atenuado cuando no hay versión anterior guardada; en ese caso toca desinstalar el dispositivo y poner el controlador viejo del fabricante. Después, pausa esa actualización concreta para que Windows Update no lo reinstale al día siguiente.","If a failure started right after updating a driver, **rollback** returns to the previous version without reinstalling anything. Open Device Manager, go to the device's Properties > Driver tab > 'Roll Back Driver'. Windows will ask why: pick the matching reason, for example that the new version does not work. The button is greyed out when no previous version is stored; in that case you must uninstall the device and install the manufacturer's older driver. Afterwards, pause that specific update so Windows Update does not reinstall it the next day."],"href":"mantenimiento-software.html#tareas"},
    {"c":"Recursos","k":["winget upgrade all actualizar todo","actualizar todos programas winget comando","winget upgrade --all all programs"],"r":["`winget upgrade --all` actualiza de una vez todos los programas que **winget** sabe gestionar. Primero ejecuta `winget upgrade` a secas para ver la lista de pendientes y detectar sorpresas, y después `winget upgrade --all --accept-source-agreements --accept-package-agreements` en Terminal como administrador para no confirmar paquete a paquete. Cierra los programas abiertos antes: el instalador de uno en uso puede fallar o pedir reinicio. Lo que winget no lista —programas portables o muy antiguos— seguirá necesitando actualización manual desde su propia web oficial, no desde páginas de descargas genéricas.","`winget upgrade --all` updates at once every program **winget** knows how to manage. First run plain `winget upgrade` to see the pending list and spot surprises, and then `winget upgrade --all --accept-source-agreements --accept-package-agreements` in Terminal as administrator to avoid confirming package by package. Close open programs first: the installer of one in use may fail or demand a restart. Anything winget does not list — portable or very old programs — will still need manual updating from its own official website, not from generic download pages."],"href":"mantenimiento-software.html#programas"},
    {"c":"Recursos","k":["winget export import lista programas otro pc","exportar programas winget json","winget export import move programs new pc"],"r":["Para llevar tu lista de programas a otro PC, **winget** lo hace en dos comandos. En el equipo viejo: `winget export -o programas.json`, que guarda un archivo con tus aplicaciones y sus fuentes. Cópialo al equipo nuevo y ejecuta `winget import -i programas.json --accept-source-agreements --accept-package-agreements`: winget instalará lo que encuentre en sus repositorios. Revisa el aviso final, porque algunos programas no están en winget o exigen otra versión y quedarán fuera de la lista. El archivo no lleva licencias ni configuraciones, solo la lista de instalación.","To take your program list to another PC, **winget** does it in two commands. On the old machine: `winget export -o programas.json`, which saves a file with your applications and their sources. Copy it to the new machine and run `winget import -i programas.json --accept-source-agreements --accept-package-agreements`: winget will install whatever it finds in its repositories. Read the final notice, because some programs are not in winget or require another version and will be left off the list. The file carries no licences or settings, only the install list."],"href":"mantenimiento-software.html#programas"},
    {"c":"Recursos","k":["programador tareas copia semanal automatica","programar copia automatica task scheduler","task scheduler weekly backup task"],"r":["El **Programador de tareas** puede lanzar tu copia semanal sin que te acuerdes. Crea una tarea básica: desencadenador semanal, elige día y hora con el equipo encendido; acción «Iniciar un programa», por ejemplo `robocopy` con origen y destino, o el ejecutable de tu programa de copias. Marca «Ejecutar con los privilegios más altos» solo si la copia toca carpetas del sistema, y en Condiciones desmarca que dependa de estar inactivo. Pruébala una vez con «Ejecutar» y revisa el Historial: que exista en la lista no garantiza que se lance bien.","**Task Scheduler** can launch your weekly backup without you remembering. Create a basic task: weekly trigger, pick a day and time with the machine on; action 'Start a program', for example `robocopy` with source and destination, or your backup program's executable. Tick 'Run with highest privileges' only if the backup touches system folders, and under Conditions untick dependence on being idle. Test it once with 'Run' and check the History: existing in the list does not guarantee it fires correctly."],"href":"mantenimiento-software.html#rutina"},
    {"c":"Recursos","k":["regla 3 2 1 copias ejemplo concreto","backup 3-2-1 rule explained example","tres copias dos medios uno fuera casa"],"r":["La regla **3-2-1** dice: tres copias de tus datos, en dos medios distintos, con una fuera de casa. Ejemplo concreto con tus trabajos: la copia 1 vive en el SSD del PC; la copia 2 se guarda cada domingo en un disco USB externo, que es otro medio; la copia 3 está en la nube, que cumple el «fuera de casa» ante un robo o un incendio. Si el PC falla, queda el USB; si el USB estaba conectado durante un ransomware, queda la nube. Ninguna copia única, por grande que sea, cumple la regla.","The **3-2-1** rule says: three copies of your data, on two different media, with one off-site. Concrete example with your coursework: copy 1 lives on the PC's SSD; copy 2 is saved every Sunday to an external USB disk, which is another medium; copy 3 is in the cloud, which covers 'off-site' against theft or fire. If the PC fails, the USB remains; if the USB was connected during ransomware, the cloud remains. No single copy, however large, satisfies the rule."],"href":"mantenimiento-software.html#tareas"},
    {"c":"Recursos","k":["probar copia seguridad se puede restaurar","comprobar backup restaura de verdad","test backup restore actually works"],"r":["Una copia no está probada hasta que **restauras** algo de ella. Haz esta prueba trimestral: elige tres archivos de tipos distintos —un documento, una foto y un proyecto— y restáuralos desde la copia a una carpeta temporal distinta, nunca encima de los originales. Ábrelos y comprueba que no están corruptos y que son recientes, no de hace seis meses. Si tu copia es una imagen del sistema, verifica además que el medio de recuperación arranca en el equipo. Anota la fecha de la prueba: la próxima revisión parte de ese resultado, no de una suposición.","A backup is not proven until you **restore** something from it. Run this quarterly test: pick three files of different types — a document, a photo and a project — and restore them from the backup into a separate temporary folder, never over the originals. Open them and check they are not corrupted and that they are recent, not six months old. If your backup is a system image, also verify the recovery media boots on the machine. Write down the test date: the next review starts from that result, not from an assumption."],"href":"mantenimiento-software.html#rutina"},
    {"c":"Recursos","k":["crystaldiskinfo que valores mirar salud","sectores reasignados crystaldiskinfo temperatura","crystaldiskinfo health reallocated sectors temperature"],"r":["En **CrystalDiskInfo** importan cuatro datos. Primero, el **estado de salud**: «Bueno» frente a «Precaución» o «Malo» en amarillo o rojo. Segundo, la **temperatura**: de forma sostenida por encima de 55-60 °C acorta la vida del disco. Tercero, el atributo de **sectores reasignados**: si su valor bruto sube entre revisiones, el disco está apartando zonas dañadas y conviene planear el cambio. Cuarto, en SSD, el porcentaje de vida restante. Un solo valor raro pide vigilancia semanal; salud en «Precaución» más sectores subiendo pide copia inmediata y sustitución cercana.","In **CrystalDiskInfo** four values matter. First, the **health status**: 'Good' versus 'Caution' or 'Bad' in yellow or red. Second, **temperature**: sustained above 55-60 °C it shortens the disk's life. Third, the **reallocated sectors** attribute: if its raw value climbs between checks, the disk is setting aside damaged areas and you should plan its replacement. Fourth, on SSDs, the remaining-life percentage. A single odd value calls for weekly watching; 'Caution' health plus rising sectors calls for an immediate backup and a near replacement."],"href":"mantenimiento-software.html#programas"},
    {"c":"Recursos","k":["ipconfig displaydns cache dns local","ver cache dns windows comando","ipconfig /displaydns local dns cache"],"r":["`ipconfig /displaydns` muestra la **caché DNS local**: los nombres que Windows ya resolvió y su IP guardada, sin preguntar otra vez al servidor DNS. Sirve para diagnosticar: si un sitio abre con la IP antigua tras cambiar de servidor, ahí verás la entrada caducada. Su pareja es `ipconfig /flushdns`, que vacía la caché y fuerza a resolver de nuevo; úsala cuando una web carga en el móvil pero no en el PC. La salida es larga: redirígela con `ipconfig /displaydns > dns.txt` para buscar con calma el dominio que te interesa.","`ipconfig /displaydns` shows the **local DNS cache**: the names Windows has already resolved and their stored IPs, without asking the DNS server again. It helps diagnose: if a site opens with the old IP after a server change, you will see the stale entry there. Its partner is `ipconfig /flushdns`, which empties the cache and forces fresh resolution; use it when a website loads on your phone but not on the PC. The output is long: redirect it with `ipconfig /displaydns > dns.txt` to search calmly for the domain you care about."],"href":"recursos.html#laboratorio"},
    {"c":"Recursos","k":["netstat ano puerto pid proceso","que proceso usa un puerto netstat","netstat -ano find pid process port"],"r":["`netstat -ano` lista las conexiones y puertos en escucha con el **PID** del proceso dueño en la última columna. Para un puerto concreto, filtra: `netstat -ano | findstr :443` y anota el PID. Después crúzalo en Terminal con `tasklist | findstr <PID>` o en el Administrador de tareas > Detalles, ordenando por PID: así sabes qué programa usa ese puerto antes de cerrarlo. Esto resuelve el clásico «puerto ocupado» al arrancar un servidor local. No mates el proceso si es del sistema: identifica primero, decide después, con el programa cerrado de forma normal.","`netstat -ano` lists connections and listening ports with the owning process's **PID** in the last column. For a specific port, filter: `netstat -ano | findstr :443` and note the PID. Then cross it in Terminal with `tasklist | findstr <PID>` or in Task Manager > Details, sorting by PID: that tells you which program uses that port before closing it. This solves the classic 'port already in use' when starting a local server. Do not kill the process if it belongs to the system: identify first, decide later, closing the program normally."],"href":"recursos.html#laboratorio"},
    {"c":"Recursos","k":["ping t continuo estadisticas detener","ping continuo como leer resultados","continuous ping -t read statistics"],"r":["`ping -t 8.8.8.8` envía paquetes sin parar hasta que lo detienes con **Ctrl+C**, y al detenerlo muestra las estadísticas completas: enviados, recibidos, perdidos y tiempos mínimo, máximo y medio. Déjalo corriendo varios minutos mientras usas la conexión: una pérdida del 0% con tiempos estables es una red sana; pérdidas a ráfagas o saltos de 20 ms a 900 ms señalan Wi-Fi saturado o interferencias, no necesariamente un fallo del proveedor. Ctrl+Pausa muestra un resumen parcial sin detenerlo. Guarda la prueba con fecha y hora si vas a reclamar al operador.","`ping -t 8.8.8.8` sends packets non-stop until you stop it with **Ctrl+C**, and on stopping it shows full statistics: sent, received, lost, and minimum, maximum and average times. Leave it running for several minutes while you use the connection: 0% loss with stable times is a healthy network; bursty losses or jumps from 20 ms to 900 ms point to saturated Wi-Fi or interference, not necessarily a provider fault. Ctrl+Break shows a partial summary without stopping it. Save the test with date and time if you plan to complain to your provider."],"href":"recursos.html#laboratorio"},
    {"c":"Recursos","k":["nslookup servidor dns concreto 1.1.1.1","consultar dns especifico nslookup","nslookup query specific dns server 1.1.1.1"],"r":["`nslookup dominio 1.1.1.1` obliga a resolver usando **ese servidor DNS concreto**, en vez del que tengas configurado. Úsalo para comparar: primero `nslookup nvision.social` con tu DNS habitual y después `nslookup nvision.social 1.1.1.1`; si uno responde y el otro no, o devuelven IPs distintas, el problema está en el DNS, no en la web ni en tu conexión. También ayuda tras cambiar los registros de un dominio: el DNS público suele ver el cambio antes que el del operador. Anota servidor, respuesta y hora de cada consulta para comparar con fundamento.","`nslookup domain 1.1.1.1` forces resolution using **that specific DNS server**, instead of the one you have configured. Use it to compare: first `nslookup nvision.social` with your usual DNS and then `nslookup nvision.social 1.1.1.1`; if one answers and the other does not, or they return different IPs, the problem is in the DNS, not in the website or your connection. It also helps after changing a domain's records: public DNS often sees the change before your provider's. Note server, answer and time of each query to compare on solid ground."],"href":"recursos.html#laboratorio"},
    {"c":"Recursos","k":["comando no se reconoce path windows","variables de entorno path editar","command not recognized path environment variable"],"r":["Cuando Windows dice que un comando «no se reconoce», casi siempre es el **PATH**: la lista de carpetas donde el sistema busca ejecutables. Si el programa está instalado pero su carpeta no está en el PATH, la consola no lo encuentra. Revísalo en «Editar las variables de entorno del sistema» > Variables de entorno > Path, y añade solo la carpeta exacta del ejecutable, sin borrar ninguna entrada existente: quitar una ruta del sistema rompe otros programas. Cierra y reabre la Terminal tras el cambio, porque las consolas ya abiertas conservan el PATH antiguo en memoria.","When Windows says a command 'is not recognized', it is almost always the **PATH**: the list of folders where the system looks for executables. If the program is installed but its folder is not in the PATH, the console cannot find it. Check it in 'Edit the system environment variables' > Environment Variables > Path, and add only the executable's exact folder, without deleting any existing entry: removing a system path breaks other programs. Close and reopen Terminal after the change, because already-open consoles keep the old PATH in memory."],"href":"recursos.html#laboratorio"},
    {"c":"Recursos","k":["exportar respaldo registro regedit antes","backup registry export regedit key","respaldar clave registro windows exportar"],"r":["Antes de tocar el **Registro**, exporta un respaldo de lo que vayas a cambiar. Abre `regedit`, localiza la clave exacta, clic derecho > Exportar y guarda el `.reg` con nombre y fecha claros, por ejemplo `respaldo-clave-2026-11-06.reg`. Si algo sale mal, doble clic en ese archivo devuelve la clave a su estado anterior. Para un respaldo completo, exporta desde la raíz «Equipo», aunque ese archivo es grande y su restauración total es más delicada. Regla extra: anota en un texto qué cambiaste y por qué; dentro de un mes, ese papel vale más que la memoria.","Before touching the **Registry**, export a backup of whatever you are going to change. Open `regedit`, locate the exact key, right-click > Export and save the `.reg` with a clear name and date, for example `key-backup-2026-11-06.reg`. If something goes wrong, double-clicking that file returns the key to its previous state. For a full backup, export from the 'Computer' root, although that file is large and fully restoring it is more delicate. Extra rule: write down what you changed and why; in a month, that note is worth more than memory."],"href":"mantenimiento-software.html#paso-a-paso"},
    {"c":"Recursos","k":["windows sandbox probar programas sin riesgo","sandbox windows entorno desechable","windows sandbox test programs safely"],"r":["**Windows Sandbox** abre un Windows limpio y desechable dentro del tuyo: instalas ahí el programa dudoso, lo pruebas, y al cerrar la ventana todo desaparece, sin tocar tu sistema real. Se activa en «Activar o desactivar las características de Windows» marcando «Espacio aislado de Windows», en ediciones Pro, Enterprise o Education; en Home no está disponible. Requiere virtualización activada en la BIOS. Es ideal para abrir un instalador de origen dudoso o probar una herramienta antes de adoptarla. Recuerda su límite: al cerrarlo se pierde todo, así que no trabajes documentos importantes dentro.","**Windows Sandbox** opens a clean, disposable Windows inside yours: you install the doubtful program there, test it, and when you close the window everything disappears, without touching your real system. Enable it in 'Turn Windows features on or off' by ticking 'Windows Sandbox', on Pro, Enterprise or Education editions; it is not available on Home. It requires virtualization enabled in the BIOS. It is ideal for opening an installer of doubtful origin or trying a tool before adopting it. Remember its limit: closing it loses everything, so do not work on important documents inside."],"href":"recursos.html#laboratorio"},
    {"c":"Recursos","k":["wsl2 para que sirve quien conviene","subsistema windows linux wsl2 usos","wsl2 what is it for who should use"],"r":["**WSL2** permite usar un Linux real dentro de Windows, con su terminal y sus herramientas, sin máquinas virtuales pesadas ni doble arranque. Le conviene a quien programa —sobre todo web y servidores—, estudia sistemas o necesita comandos de Linux junto a sus programas de Windows: los archivos se comparten entre ambos lados. Se instala con `wsl --install` en Terminal como administrador y un reinicio. Si solo usas ofimática y juegos, no te aporta nada y ocupará varios gigas. Dentro de WSL, trabaja en su carpeta de Linux: acceder a archivos de Windows desde ahí es notablemente más lento.","**WSL2** lets you use a real Linux inside Windows, with its terminal and tools, without heavy virtual machines or dual boot. It suits people who code — especially web and servers —, study systems, or need Linux commands alongside their Windows programs: files are shared between both sides. Install it with `wsl --install` in Terminal as administrator plus a restart. If you only do office work and gaming, it gives you nothing and will take several gigabytes. Inside WSL, work in its Linux folder: reaching Windows files from there is noticeably slower."],"href":"recursos.html#laboratorio"},
    {"c":"Recursos","k":["desinstalar actualizacion windows numero kb","quitar actualizacion problematica kb","uninstall windows update by kb number"],"r":["Si el fallo empezó tras una actualización concreta, desinstálala por su número **KB**. Ve a Configuración > Windows Update > Historial de actualizaciones > «Desinstalar actualizaciones», localiza la entrada con ese código, por ejemplo KB5034441, y pulsa Desinstalar; reinicia cuando lo pida. Alternativa por comandos, como administrador: `wusa /uninstall /kb:5034441`. Después pausa las actualizaciones una o dos semanas desde Windows Update para que no se reinstale enseguida, y apunta el código: cuando Microsoft publique la versión corregida, ese número es el que compararás antes de reactivarlas.","If the failure started after a specific update, uninstall it by its **KB** number. Go to Settings > Windows Update > Update history > 'Uninstall updates', find the entry with that code, for example KB5034441, and click Uninstall; restart when asked. Command-line alternative, as administrator: `wusa /uninstall /kb:5034441`. Then pause updates for one or two weeks in Windows Update so it does not reinstall right away, and write the code down: when Microsoft publishes the fixed version, that number is what you will compare before re-enabling them."],"href":"mantenimiento-software.html#paso-a-paso"},
    {"c":"Recursos","k":["error windows update secuencia arreglo dism sfc","reparar windows update orden pasos","fix windows update error dism sfc restart services"],"r":["Ante un error de **Windows Update**, sigue esta secuencia y no la saltes. Primero, reinicia el PC y reintenta: muchos errores son temporales. Segundo, repara la base con `DISM /Online /Cleanup-Image /RestoreHealth` y después `sfc /scannow`, en ese orden. Tercero, reinicia los servicios parando `wuauserv` y `bits` con `net stop`, renombrando la carpeta `SoftwareDistribution` a `SoftwareDistribution.old` y arrancándolos otra vez con `net start`: Windows creará una carpeta limpia de descargas. Cuarto, vuelve a buscar actualizaciones. Anota el código de error original antes de empezar: si persiste, ese código manda sobre cualquier consejo genérico.","Faced with a **Windows Update** error, follow this sequence and do not skip it. First, restart the PC and retry: many errors are temporary. Second, repair the base with `DISM /Online /Cleanup-Image /RestoreHealth` and then `sfc /scannow`, in that order. Third, restart the services by stopping `wuauserv` and `bits` with `net stop`, renaming the `SoftwareDistribution` folder to `SoftwareDistribution.old` and starting them again with `net start`: Windows will create a clean download folder. Fourth, check for updates again. Note the original error code before starting: if it persists, that code rules over any generic advice."],"href":"mantenimiento-software.html#alertas"},
    {"c":"Recursos","k":["limpiar winsxs startcomponentcleanup tamano","dism startcomponentcleanup winsxs engana explorador","clean winsxs component store size"],"r":["`DISM /Online /Cleanup-Image /StartComponentCleanup` limpia **WinSxS**, el almacén de componentes, retirando versiones antiguas sustituidas que ya no se pueden desinstalar después. Ejecútalo como administrador y déjalo terminar sin prisa. El Explorador engaña sobre su tamaño porque muchos archivos de WinSxS son enlaces duros a archivos que también cuentan en otras carpetas: el espacio real ocupado es menor que el que suma Propiedades. Mide el tamaño verdadero con `DISM /Online /Cleanup-Image /AnalyzeComponentStore`, que además dice si recomienda la limpieza. Nunca borres la carpeta WinSxS a mano: Windows dejaría de arrancar o de actualizarse.","`DISM /Online /Cleanup-Image /StartComponentCleanup` cleans **WinSxS**, the component store, removing superseded old versions that can no longer be uninstalled afterwards. Run it as administrator and let it finish unhurriedly. Explorer misleads about its size because many WinSxS files are hard links to files also counted in other folders: the real space used is less than what Properties adds up. Measure the true size with `DISM /Online /Cleanup-Image /AnalyzeComponentStore`, which also says whether cleanup is recommended. Never delete the WinSxS folder by hand: Windows would stop booting or updating."],"href":"mantenimiento-software.html#tareas"},
    {"c":"Recursos","k":["liberador espacio mientras windows update descarga","disk cleanup while update downloading safe","usar limpieza disco durante actualizacion"],"r":["Usar el **Liberador de espacio** mientras Windows Update está descargando no suele romper nada, pero sí mete ruido. Los archivos en uso se saltan solos: Windows no deja borrar lo que una actualización está escribiendo en ese momento. El problema real es doble: limpieza y descarga pelean por el mismo disco, todo va más lento, y la opción delicada es «Limpieza de actualizaciones de Windows» a mitad de una instalación, que puede dejar la limpieza a medias. La solución ordenada: deja que la actualización termine, reinicia, busca actualizaciones otra vez para confirmar que no queda nada pendiente, y entonces sí, limpia con el equipo ya tranquilo.","Using **Disk Cleanup** while Windows Update is downloading does not usually break anything, but it does add noise. Files in use are skipped on their own: Windows will not let you delete what an update is writing at that moment. The real problem is double: cleanup and download fight over the same disk, everything slows down, and the delicate option is 'Windows Update Cleanup' in the middle of an installation, which can leave the cleanup half-done. The tidy solution: let the update finish, restart, check for updates again to confirm nothing is pending, and only then clean up, with the machine already calm."],"href":"mantenimiento-software.html#tareas"},
    {"c":"Recursos","k":["sensor almacenamiento no borre descargas sorpresa","configurar storage sense descargas nunca","storage sense configure downloads never"],"r":["El **Sensor de almacenamiento** libera espacio solo, pero hay que domarlo para que Descargas no sea su víctima. En Configuración > Sistema > Almacenamiento > Sensor de almacenamiento, pon «Eliminar archivos de mi carpeta Descargas» en **Nunca**: así solo tocará esa carpeta cuando tú lo ordenes. Deja en cambio activado el borrado de temporales y fija la Papelera a un plazo prudente, por ejemplo 30 días, que da margen para recuperar un borrado por error. Revisa la configuración tras cada gran actualización de Windows: a veces los valores vuelven a los predeterminados sin avisar.","**Storage Sense** frees space on its own, but it must be tamed so Downloads is not its victim. In Settings > System > Storage > Storage Sense, set 'Delete files in my Downloads folder' to **Never**: that way it only touches that folder when you order it. Instead, leave temporary-file deletion on and set the Recycle Bin to a prudent period, for example 30 days, which leaves margin to recover an accidental deletion. Recheck the settings after each major Windows update: sometimes the values silently return to the defaults."],"href":"mantenimiento-software.html#rutina"},
    {"c":"Hardware","k":["como usar el visor 3d","controles del visor 3d","agarrar piezas visor","boton derecho mover vista","doble clic enfocar pieza","how to use 3d viewer","drag parts pc3d"],"r":["En el **visor 3D** de PC3D agarras las piezas con el **botón izquierdo**: tira de una pieza para sacarla de la torre y suéltala donde quieras, queda flotando. Al acercarla a su sitio, una **línea roja** te guía y el imán la atrae; si la sueltas cerca, **se encaja sola**. El **botón derecho** mueve la vista, la **rueda** acerca de a poco y el **doble clic** enfoca una pieza.","In the PC3D **3D viewer** you grab parts with the **left button**: drag a part out of the tower and drop it anywhere, it stays floating. As you bring it near its slot, a **red line** guides you and the magnet pulls it in; drop it close and it **snaps into place**. The **right button** moves the view, the **wheel** zooms in gradually and **double-click** focuses a part."],"href":"pc3d.html#visor-3d"},
    {"c":"Hardware","k":["como encender el pc virtual","encender pc3d","boton de encendido pc virtual","pc no enciende visor","falta una pieza no enciende","how to power on virtual pc","virtual pc wont boot missing part"],"r":["El PC virtual arranca **apagado**. Pulsa **Encender** ([[power]]) o el botón físico 3D del frontal: si las 8 piezas están en su sitio, verás el logo de Windows con la ruedita de carga y luego el escritorio. Si **falta una pieza, no enciende**: la pantalla muestra el error, el anillo del botón parpadea en rojo y los ventiladores giran un instante. Si sacas una pieza con el PC encendido, **se apaga de golpe**, como un equipo real.","The virtual PC starts **off**. Press **Power** ([[power]]) or the physical 3D button on the front: if all 8 parts are in place, you will see the Windows logo with the loading spinner and then the desktop. If a **part is missing, it will not boot**: the screen shows the error, the button ring blinks red and the fans spin briefly. If you pull a part out while the PC is on, it **shuts off instantly**, like a real machine."],"href":"pc3d.html#visor-3d"},
    {"c":"Hardware","k":["cuantas piezas tiene el visor","ocho piezas pc3d","piezas de la torre 3d","partes del pc virtual","what parts does the 3d viewer have","8 parts pc3d"],"r":["El visor tiene **8 piezas**: **placa madre, procesador (CPU), ventilador de CPU (cooler), memoria RAM, tarjeta gráfica (GPU), almacenamiento (SSD), fuente de poder (PSU) y unidad óptica**. El panel muestra cuántas van instaladas (01/08) y al hacer clic en una pieza ves su nombre y su función. Quitar el ventilador deja ver el chip; quitar el chip deja ver el zócalo en la placa.","The viewer has **8 parts**: **motherboard, processor (CPU), CPU cooler, RAM, graphics card (GPU), storage (SSD), power supply (PSU) and optical drive**. The panel shows how many are installed (01/08), and clicking a part shows its name and function. Removing the cooler reveals the chip; removing the chip reveals the socket on the board."],"href":"pc3d.html#componentes-3d"},
    {"c":"Hardware","k":["cinematicas visor 3d","vista general nucleo flujo energia","escenas del visor","vistas guiadas pc3d","viewer scenes overview core airflow","guided views pc3d"],"r":["El visor tiene **3 cinemáticas** (vistas guiadas): **01 Vista general**, que muestra el puesto entero con la torre abierta; **02 Núcleo de cálculo**, que enfoca la CPU y la RAM; y **03 Flujo y energía**, que sigue la energía y los datos con partículas de aire y los ventiladores más rápidos. Pulsa el botón de la vista que quieras y la cámara se mueve sola siguiendo la escena.","The viewer has **3 guided scenes**: **01 Overview**, showing the whole station with the open tower; **02 Compute core**, focusing on the CPU and RAM; and **03 Flow and power**, following energy and data with airflow particles and faster fans. Press a scene button and the camera moves on its own along that scene."],"href":"pc3d.html#visor-3d"},
    {"c":"Hardware","k":["desarmar todo visor","deslizador desarmar","como desarmar la torre 3d","restablecer vista visor","disassemble all 3d viewer","explode slider pc3d"],"r":["Con el deslizador **Desarmar** separas las piezas de la torre poco a poco (0 % a 100 %); **Desarmar todo** las separa de golpe. Cada pieza sale en su dirección y queda flotando; para volver a armar, baja el deslizador o usa **Restablecer vista**, que también vuelve a instalar las piezas quitadas.","With the **Disassemble** slider you pull the parts away from the tower little by little (0% to 100%); **Disassemble all** pulls them all apart at once. Each part moves out along its own direction and stays floating; to reassemble, lower the slider or use **Reset view**, which also reinstalls any removed parts."],"href":"pc3d.html#visor-3d"},
    {"c":"Hardware","k":["etiquetas visor 3d","quitar etiquetas piezas","pantalla completa visor","fullscreen pc3d","labels 3d viewer","toggle labels pc3d"],"r":["El botón **Etiquetas** enciende o apaga los nombres de las piezas sobre el modelo 3D, para practicar reconociéndolas sin ayuda. **Pantalla completa** ([[fullscreen]]) agranda el visor a toda la pantalla; pulsa Escape o el mismo botón para salir.","The **Labels** button turns the part names on or off over the 3D model, so you can practice recognizing them without help. **Fullscreen** ([[fullscreen]]) enlarges the viewer to the whole screen; press Escape or the same button to exit."],"href":"pc3d.html#visor-3d"},
    {"c":"Hardware","k":["que es refrigeracion liquida","aio liquid cooler","enfriamiento liquido cpu","aio vs aire","what is aio cooling","liquid cooler vs air"],"r":["La **refrigeración líquida (AIO)** disipa el calor del procesador con un circuito cerrado de líquido, radiador y ventiladores de alta presión estática: un bloque con bomba va sobre el socket de la CPU y las mangueras llevan el líquido caliente al radiador, donde los ventiladores lo enfrían. Rinde más que el aire en CPU calientes y evita el **thermal throttling**, pero cuesta más y ocupa espacio para el radiador.","Liquid cooling (**AIO**) removes heat from the processor with a closed loop of liquid, a radiator and high-static-pressure fans: a pump block sits on the CPU socket and hoses carry the hot liquid to the radiator, where the fans cool it. It beats air cooling on hot CPUs and prevents **thermal throttling**, but it costs more and needs room for the radiator."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["cada cuanto limpiar el pc","frecuencia limpieza pc","cada cuanto limpiar interior pc","limpieza cada cuantos meses","how often clean pc","pc cleaning schedule"],"r":["Frecuencia segura de limpieza del PC: **exterior y filtros cada 1 a 3 meses**, según el polvo, las mascotas y la ventilación; **interior cada 6 a 12 meses**, o antes si suben el ruido y la temperatura; **pasta térmica cada 2 a 4 años**, revisando antes las temperaturas. Trabaja siempre con el equipo **apagado y desconectado**.","Safe PC cleaning schedule: **exterior and filters every 1 to 3 months**, depending on dust, pets and ventilation; **interior every 6 to 12 months**, or sooner if noise and temperature rise; **thermal paste every 2 to 4 years**, checking temperatures first. Always work with the machine **off and unplugged**."],"href":"pc3d.html#mantenimiento"},
    {"c":"Hardware","k":["olor a quemado pc","pc se apaga solo","apagados repentinos pc","ruido electrico pc","burning smell pc","pc shuts down by itself"],"r":["Si hay **olor a quemado, apagados repentinos o ruido eléctrico, deja de usar el equipo y consulta servicio técnico**: no sigas encendiéndolo para probar. Son señales de un fallo eléctrico o de la fuente que puede dañar más piezas. Lo mismo si el equipo se calienta o se apaga solo sin razón clara: ve a revisión.","If there is a **burning smell, sudden shutdowns or electrical noise, stop using the machine and get technical service**: do not keep turning it on to test. These signal an electrical or PSU fault that can damage more parts. The same applies if the machine overheats or turns itself off for no clear reason: take it for service."],"href":"pc3d.html#mantenimiento"},
    {"c":"Hardware","k":["que es spyware","spyware que hace","como entra el spyware","spyware vs virus","what is spyware","spyware signs"],"r":["El **spyware** es un malware que **espía y roba datos** en silencio: contraseñas, lo que escribes o lo que haces en el equipo, sin que lo notes. Entra igual que otros malwares: adjuntos y enlaces sospechosos, programas pirata y memorias USB desconocidas. Señales: el equipo lento, ventanas raras o actividad extraña en tus cuentas. Protégelo con un solo antivirus actualizado y copias de seguridad.","**Spyware** is malware that **spies on you and steals data** silently: passwords, what you type or what you do on the machine, without you noticing. It gets in like other malware: suspicious attachments and links, pirated programs and unknown USB drives. Signs: a slow machine, strange pop-ups or odd activity in your accounts. Protect yourself with one updated antivirus and backups."],"href":"pc3d.html#mantenimiento"},
    {"c":"Hardware","k":["eniac cuanto pesaba","eniac tubos de vacio","eniac 27 toneladas","eniac 20 horas 30 segundos","eniac numbers specs","how heavy was eniac"],"r":["El **ENIAC** (1943-1946) pesaba más de **27 toneladas**, ocupaba **167 m²**, consumía **150 kW** y tenía más de **17.468 tubos de vacío**, 7.200 diodos y 5 millones de uniones soldadas a mano. Nació en la Segunda Guerra Mundial para calcular tablas balísticas: un cálculo que tomaba **20 horas** lo hacía en **30 segundos**. Lo programaban a mano con cables las **6 programadoras pioneras** (Kay McNulty, Betty Jennings, Betty Snyder, Marlyn Wescoff, Ruth Lichterman y Frances Bilas), y de él aprendió John von Neumann el concepto de **programa almacenado**.","**ENIAC** (1943-1946) weighed over **27 tons**, covered **167 m²**, drew **150 kW** and used more than **17,468 vacuum tubes**, 7,200 crystal diodes and 5 million hand-soldered joints. It was built in World War II to compute ballistic tables: a calculation that took **20 hours** now took **30 seconds**. It was programmed by hand with cables by the **6 pioneering programmers** (Kay McNulty, Betty Jennings, Betty Snyder, Marlyn Wescoff, Ruth Lichterman and Frances Bilas), and John von Neumann learned the **stored-program** concept from it."],"href":"hardware.html#historia"},
    {"c":"Hardware","k":["ibm 7090 nasa","ibm 7090 mercury gemini","ibm 7090 transistores","ibm 7090 velocidad","ibm 7090 specs","ibm 7090 fortran lisp"],"r":["El **IBM 7090** (1959) tenía más de **50.000 transistores** de germanio, palabras de **36 bits** y ejecutaba **229.000 instrucciones por segundo**, con 32.768 palabras de memoria (~144 KB). La NASA lo usó en los programas **Mercury y Gemini** para calcular las órbitas de los primeros astronautas. En él se desarrolló FORTRAN y LISP, y en los laboratorios Bell se creó la primera síntesis de voz por computadora («Daisy Bell»).","The **IBM 7090** (1959) had over **50,000** germanium transistors, **36-bit** words and ran **229,000 instructions per second**, with 32,768 words of memory (~144 KB). NASA used it in the **Mercury and Gemini** programs to compute the orbits of the first American astronauts. FORTRAN and LISP were developed on it, and Bell Labs created the first computer speech synthesis («Daisy Bell») on it."],"href":"hardware.html#historia"},
    {"c":"Hardware","k":["altair 8800 precio","altair 8800 intel 8080","altair 8800 ram 256 bytes","altair basic gates allen","altair 8800 specs","altair s-100 bus"],"r":["El **Altair 8800** (1974-1975) costaba **menos de 400 dólares** en kit y montaba el CPU **Intel 8080 a 2 MHz** con apenas **256 bytes de RAM** (expandible a 64 KB). No tenía teclado, monitor ni almacenamiento: se programaba interruptor por interruptor y se leía con luces LED. Su bus de expansión **S-100** se volvió estándar, y **Bill Gates y Paul Allen** escribieron el Altair BASIC, con el que fundaron Microsoft en 1975.","The **Altair 8800** (1974-1975) cost under **400 dollars** as a kit and ran an **Intel 8080 at 2 MHz** with just **256 bytes of RAM** (expandable to 64 KB). It had no keyboard, monitor or storage: you programmed it switch by switch and read the answers on blinking LEDs. Its **S-100** expansion bus became a standard, and **Bill Gates and Paul Allen** wrote Altair BASIC, with which they founded Microsoft in 1975."],"href":"hardware.html#historia"},
    {"c":"Hardware","k":["apple ii procesador","apple ii ram","apple ii visicalc","apple ii wozniak","apple ii specs","apple ii expansion slots"],"r":["El **Apple II** (1977) usaba el **MOS 6502 a 1,023 MHz**, entre **4 KB y 48 KB de RAM**, teclado integrado, sonido y gráficos a color en un televisor, con **8 ranuras de expansión**. Lo diseñó **Steve Wozniak** (hardware) con Steve Jobs (producto). En 1979 llegó **VisiCalc**, la primera hoja de cálculo y la primera «killer application», que disparó las ventas del PC en las empresas.","The **Apple II** (1977) used a **MOS 6502 at 1.023 MHz**, **4 KB to 48 KB of RAM**, an integrated keyboard, sound and color graphics on a TV, with **8 expansion slots**. It was designed by **Steve Wozniak** (hardware) with Steve Jobs (product). In 1979 came **VisiCalc**, the first spreadsheet and the first «killer application», which launched PC sales in business."],"href":"hardware.html#historia"},
    {"c":"Redes","k":["que es rj-45","puerto rj-45 ethernet","puertos fisicos de red","rj45 vs wifi","what is rj-45","network physical ports"],"r":["Los **puertos físicos** de red son las interfaces **RJ-45** para cable de par trenzado (Ethernet) y las interfaces de **radiofrecuencia (Wi-Fi)**, conectadas mediante el bus **PCIe**. La NIC es la tarjeta que lleva esos puertos: por cable usas el RJ-45 y por aire la antena Wi-Fi del equipo.","Physical network **ports** are the **RJ-45** interfaces for twisted-pair cable (Ethernet) and the **radio-frequency (Wi-Fi)** interfaces, connected through the **PCIe** bus. The NIC is the card that carries those ports: by cable you use RJ-45, through the air the machine's Wi-Fi antenna."],"href":"redes.html#redes"},
    {"c":"Redes","k":["flujo de datos en el host","como viajan los paquetes en el pc","ram cpu nic flujo","data flow host ram cpu nic","host data path"],"r":["El **flujo de datos en el host** es así: los paquetes viajan desde la **memoria RAM**, son procesados por la **CPU** y enviados al controlador **NIC**, que los modula y los transmite por el medio físico (cable o Wi-Fi). Por eso la RAM, el procesador y la tarjeta de red trabajan juntos en cada envío.","The **data flow inside the host** goes like this: packets travel from **RAM**, are processed by the **CPU** and sent to the **NIC** controller, which modulates them and transmits them over the physical medium (cable or Wi-Fi). That is why RAM, processor and network card work together on every send."],"href":"redes.html#redes"},
    {"c":"Redes","k":["que es el ttl del paquete","ttl ip que significa","ttl simulador ping","time to live paquete","what is ip ttl","ttl packet simulator"],"r":["El **TTL** (Time To Live) del paquete IP es un contador que baja en 1 cada vez que el paquete pasa por un router: si llega a 0, el router lo descarta para que no dé vueltas infinitas por la red. En el simulador de Redes lo ves en el panel de Capa 3 junto a la IP de origen y destino. No lo confundas con el TTL del DNS, que es cuánto tiempo se guarda una respuesta en caché.","The IP packet's **TTL** (Time To Live) is a counter that drops by 1 every time the packet crosses a router: if it reaches 0, the router drops it so it cannot loop around the network forever. In the Networks simulator you see it in the Layer 3 panel next to the source and destination IP. Do not confuse it with DNS TTL, which is how long an answer stays cached."],"href":"redes.html#simulador-red"},
    {"c":"Redes","k":["simulador ping ips","pc1 192.168.1.10","servidor 10.0.0.80","rtt perdida simulador","ping simulator ips","echo request reply simulator"],"r":["El **simulador de ping** usa datos reales de ejemplo: **PC 1 (192.168.1.10)** y **PC 2 (192.168.1.20)** en la LAN A, el **router gateway 192.168.1.1 / 10.0.0.1** y el **servidor web 10.0.0.80** en la WAN. Elige origen y destino y pulsa «Enviar Ping ICMP»: verás el Echo Request y el Reply viajar por la NIC, el switch (Capa 2) y el router (Capa 3), con el **RTT en ms** y la **pérdida** de paquetes.","The **ping simulator** uses realistic sample data: **PC 1 (192.168.1.10)** and **PC 2 (192.168.1.20)** on LAN A, the **gateway router 192.168.1.1 / 10.0.0.1** and the **web server 10.0.0.80** on the WAN. Pick a source and a destination and press «Send ICMP Ping»: you will see the Echo Request and Reply travel through the NIC, the switch (Layer 2) and the router (Layer 3), with the **RTT in ms** and packet **loss**."],"href":"redes.html#simulador-red"},
    {"c":"Redes","k":["modo hub laboratorio switch","modo switch laboratorio","borrar tabla mac","laboratorio el switch por dentro","switch lab hub mode","clear mac table lab"],"r":["En el laboratorio **«El switch por dentro»** puedes cambiar entre **Modo switch** y **Modo hub**: en modo switch cada trama sale solo por el puerto de su destino, y en modo hub sale por todos. Elige quién envía (PC1-PC4) y quién recibe, pulsa «Enviar trama» y mira cómo la **tabla MAC** se llena puerto a puerto; el botón **«Borrar tabla MAC»** la vacía para practicar desde cero.","In the **«Inside the switch»** lab you can switch between **Switch mode** and **Hub mode**: in switch mode each frame leaves only through its destination port, in hub mode through all of them. Pick a sender (PC1-PC4) and a receiver, press «Send frame» and watch the **MAC table** fill port by port; the **«Clear MAC table»** button empties it so you can practice from scratch."],"href":"redes.html#switch-3d"},
    {"c":"WiFi","k":["como instalar el modem","instalar router paso a paso","conectar cable del proveedor","luces fijas modem dos minutos","how to install modem router","modem setup steps"],"r":["Para **instalar el módem/router**: **1)** conecta el cable del proveedor (fibra/ONT o coaxial/DSL) al puerto de entrada; **2)** enciéndelo y espera unos **2 minutos** hasta que las luces de encendido e internet queden **fijas**; **3)** conéctate por **cable Ethernet** si puedes, o al WiFi con el **SSID y la clave impresos en la etiqueta** del equipo. Con esa conexión lista ya puedes abrir el panel de configuración.","To **install the modem/router**: **1)** plug the provider cable (fiber/ONT or coaxial/DSL) into the input port; **2)** turn it on and wait about **2 minutes** until the power and internet lights stay **solid**; **3)** connect by **Ethernet cable** if you can, or to the WiFi using the **SSID and password printed on the label** on the device. With that connection ready you can open the settings panel."],"href":"wifi.html#instalar-modem"},
    {"c":"WiFi","k":["admin admin cambiar","clave de fabrica modem","usuario clave panel router","cambiar clave admin router","admin admin default password","change router admin password"],"r":["**Nunca dejes el usuario y la clave de fábrica del panel** (tipo **admin/admin**): es la primera combinación que prueba cualquier intruso. Cámbiala por una clave larga y guárdala en un lugar seguro, lejos de las visitas. Lo mismo con la clave del WiFi: más de 12 caracteres y seguridad WPA2 o WPA3, nunca red abierta ni WEP.","**Never leave the panel's factory username and password** (like **admin/admin**): it is the first combination any intruder tries. Change it to a long password and store it somewhere safe, away from visitors. Same for the WiFi password: over 12 characters with WPA2 or WPA3 security, never an open network or old WEP."],"href":"wifi.html#instalar-modem"},
    {"c":"WiFi","k":["wifi llega debil a mi cuarto","wifi debil en mi cuarto","senial wifi debil habitacion","por que el wifi no llega","weak wifi in my room","wifi signal weak room"],"r":["Si el **WiFi llega débil a tu cuarto**, la culpa es de la distancia, los muros y los electrodomésticos, que se comen la señal. Sube el módem a un punto **central y alto**, y si aun así falta, pon el **repetidor a mitad del camino** (donde todavía llegue buena señal): si lo pones dentro del cuarto sin señal, no tiene qué repetir.","If the **WiFi is weak in your room**, distance, walls and appliances are eating the signal. Move the modem to a **central, high** spot, and if that is still not enough, place the **repeater halfway there** (where the signal is still good): if you put it inside the room with no signal, it has nothing to repeat."],"href":"wifi.html#instalar-modem"},
    {"c":"Recursos","k":["como usar el glosario","glosario modo tarjetas","mezclar tarjetas glosario","buscar en el glosario","how to use glossary","glossary flashcards mode"],"r":["El **Glosario** tiene **36 conceptos** de redes, hardware y mantenimiento, con **buscador** y **filtros por tema** (Todos, Redes, Hardware, Mantenimiento). En **Modo tarjetas** toca la tarjeta para ver la definición; **«Mezclar»** cambia el orden para repasar y las flechas pasan a la siguiente o la anterior.","The **Glossary** has **36 terms** on networks, hardware and maintenance, with a **search box** and **topic filters** (All, Networks, Hardware, Maintenance). In **Card mode**, tap a card to see its definition; **«Shuffle»** changes the order for review and the arrows move to the next or previous card."],"href":"recursos.html#glosario"},
    {"c":"Recursos","k":["laboratorio de codigos que hay","codigos powershell laboratorio","que codigos trae el laboratorio","code lab commands list","codigos para copiar powershell"],"r":["El **Laboratorio de Códigos** trae códigos listos para copiar en PowerShell: **Get-ComputerInfo** (diagnóstico del equipo), **ipconfig /all** (tu IP y tu MAC), **ping 8.8.8.8** (¿hay conexión?), **arp -a** (¿quién está en tu red?) e **ipconfig /release** + **ipconfig /renew** (renueva tu IP, como administrador). Además está la tarjeta **«Detecta mi equipo»**, que muestra lo que tu navegador puede ver sin instalar nada.","The **Code Lab** has ready-to-copy PowerShell commands: **Get-ComputerInfo** (hardware diagnostics), **ipconfig /all** (your IP and MAC), **ping 8.8.8.8** (is there a connection?), **arp -a** (who is on your network?) and **ipconfig /release** + **ipconfig /renew** (renew your IP, as administrator). There is also the **«Detect my device»** card, showing what your browser can see without installing anything."],"href":"recursos.html#laboratorio"},
    {"c":"Recursos","k":["malwarebytes free para que sirve","malwarebytes segunda opinion","que es malwarebytes","malwarebytes free vs pro","what is malwarebytes free","malwarebytes second opinion"],"r":["**Malwarebytes Free** es la **segunda opinión antimalware**: análisis bajo demanda, gratis, con versión Pro de pago. Úsalo para revisar un equipo con sospecha de infección, además de tu antivirus principal: no lo tengas como segundo antivirus residente a la vez que Defender.","**Malwarebytes Free** is the **second-opinion antimalware**: on-demand scans, free, with a paid Pro version. Use it to check a machine you suspect is infected, in addition to your main antivirus: do not run it as a second resident antivirus alongside Defender."],"href":"mantenimiento-software.html#programas"},
    {"c":"Recursos","k":["ccleaner free para que sirve","ccleaner limpieza inicio","que es ccleaner","ccleaner vs bleachbit","what is ccleaner free","ccleaner startup manager"],"r":["**CCleaner Free** limpia temporales, caché y archivos inútiles y gestiona el inicio, con más opciones y guía que BleachBit, pero es algo más pesado (eficiencia media) y tiene versión Pro de pago. Es para quien quiere una limpieza guiada sin tocar el registro.","**CCleaner Free** cleans temporary files, cache and junk and manages startup, with more options and guidance than BleachBit, but it is a bit heavier (medium efficiency) and has a paid Pro version. It is for those who want guided cleaning without touching the registry."],"href":"mantenimiento-software.html#programas"},
    {"c":"Recursos","k":["copia de windows veeam","veeam agent free para que sirve","copia de seguridad completa windows","como hacer copia completa sistema","windows backup veeam free","full system backup free"],"r":["**Copia de Windows / Veeam Agent Free** hace la **copia de seguridad completa** del sistema y los archivos, gratis en su uso básico. Es la opción para proteger trabajos, fotos y documentos importantes; la primera copia tarda más. Recuerda la regla 3-2-1: 3 copias, en 2 medios distintos, 1 fuera de casa o en la nube, y comprueba alguna vez que la copia se puede restaurar de verdad.","**Windows Backup / Veeam Agent Free** makes a **full backup** of the system and files, free for basic use. It is the option to protect important work, photos and documents; the first backup takes longer. Remember the 3-2-1 rule: 3 copies, on 2 different media, 1 off-site or in the cloud, and check sometime that the backup can actually be restored."],"href":"mantenimiento-software.html#programas"},
    {"c":"Otro","k":["como entrenar al asistente","ensenar al asistente","abrir el asistente","donde esta el asistente","pestana entrenar","how to train the assistant","teach the chatbot","open the assistant"],"r":["El **asistente** se abre con el botón flotante del chat. Si no sabe algo, en la pestaña **Entrenar** puedes enseñarle la pregunta y su respuesta, y ver las preguntas que no supo responder. Lo aprendido se guarda **solo en este navegador**: en otro equipo o navegador tendrás que enseñarle de nuevo.","Open the **assistant** with the floating chat button. If it does not know something, use the **Train** tab to teach it the question and its answer, and to see the questions it could not answer. What it learns is stored **only in this browser**: on another computer or browser you will have to teach it again."],"href":"index.html"},
    {"c":"Recursos","k":["archivo hosts que es","para que sirve el archivo hosts","editar archivo hosts","bloquear paginas con hosts","hosts file windows","what is the hosts file","block websites with hosts file"],"r":["El **archivo hosts** es una lista local que Windows consulta **antes** de preguntar al DNS: cada línea mapea un dominio a una IP. Sirve para pruebas y bloqueos: agrega `127.0.0.1 sitio.com` al final de `C:\\Windows\\System32\\drivers\\etc\\hosts` (edítalo como administrador) y ese sitio dejará de abrirse en esa PC. Úsalo con cuidado: una entrada vieja puede dejarte sin acceso a un sitio legítimo, y si los cambios no aplican, vacía la caché con `ipconfig /flushdns`.","The **hosts file** is a local list Windows checks **before** asking DNS: each line maps a domain to an IP. It is used for testing and blocking: append `127.0.0.1 site.com` to the end of `C:\\Windows\\System32\\drivers\\etc\\hosts` (edit it as administrator) and that site will stop opening on that PC. Use it carefully: a stale entry can lock you out of a legitimate site, and if changes do not apply, flush the cache with `ipconfig /flushdns`."],"href":"recursos.html#laboratorio"},
    {"c":"Otro","k":["windows defender que es","defender antivirus de windows","proteccion integrada de windows","microsoft defender antivirus","necesito otro antivirus","what is windows defender","windows built in antivirus","do i need another antivirus"],"r":["**Windows Defender** (Microsoft Defender Antivirus) es el antivirus integrado de Windows: se activa solo, se actualiza con Windows Update y ofrece protección en tiempo real, control de comportamiento y de dispositivos sin instalar nada extra. Para uso normal no necesitas otro antivirus de pago: dos antivirus a la vez pelean por recursos y bajan la protección. Refuérzalo activando la **protección contra ransomware** (acceso controlado a carpetas) y la **protección en la nube**, y revisa el historial de amenazas después de cada análisis completo mensual.","**Windows Defender** (Microsoft Defender Antivirus) is Windows' built-in antivirus: it turns on by itself, updates through Windows Update and offers real-time protection, behavior and device control with nothing extra to install. For normal use you do not need another paid antivirus: two antivirus suites fight over resources and lower your protection. Strengthen it by enabling **ransomware protection** (controlled folder access) and **cloud-delivered protection**, and review the threat history after each monthly full scan."],"href":"mantenimiento-software.html#rutina"}
,
    {"c":"Hardware","k":["que es hyperthreading","hilos por nucleo","smt simultaneo","hyper threading vs nucleos fisicos","8 nucleos 16 hilos","what is hyperthreading","hyperthreading vs physical cores"],"r":["El **hyperthreading** (SMT en AMD) divide cada núcleo físico en **2 hilos lógicos**: el procesador aprovecha partes del núcleo que quedaban libres para atender dos tareas a la vez. No duplica el rendimiento: en tareas reales suma entre un 15% y un 30%, y en juegos a veces nada. Un CPU «8 núcleos, 16 hilos» tiene 8 núcleos reales con hyperthreading activado. Se activa o desactiva en la UEFI; desactívalo solo por compatibilidad o seguridad puntual.","**Hyperthreading** (SMT on AMD) splits each physical core into **2 logical threads**: the CPU uses idle parts of the core to handle two tasks at once. It does not double performance: real-world gains are 15-30%, sometimes nothing in games. An \"8-core, 16-thread\" CPU has 8 real cores with hyperthreading enabled. Toggle it in UEFI; disable only for specific compatibility or security cases."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["latencia de la ram","timings cl","dual channel","canales dobles ram","cas latency que es","2x8 vs 1x16","ram latency and dual channel"],"r":["La **latencia RAM** (CL, CAS latency) es cuántos ciclos espera la memoria antes de entregar datos: CL16 a 3600 MHz puede ser más rápida en la práctica que CL18 a 3000. Además, monta los módulos en **doble canal** (revisa el manual de la placa: suelen ir en ranuras alternadas, la 2 y la 4): el ancho de banda se duplica y los gráficos integrados ganan mucho. Un kit de 2×8 GB en doble canal rinde mejor que un módulo solo de 16 GB.","**RAM latency** (CL, CAS latency) is how many memory cycles pass before data is delivered: CL16 at 3600 MHz can beat CL18 at 3000 MHz in practice. Also install modules in **dual channel** (check your motherboard manual: usually alternating slots 2 and 4): bandwidth doubles and integrated graphics gain a lot. A 2×8 GB kit in dual channel outperforms a single 16 GB stick."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["que es el tpm","modulo de plataforma segura","chip tpm windows 11","trusted platform module","requisitos windows 11 tpm","what is tpm","tpm chip windows 11"],"r":["El **TPM** (Trusted Platform Module) es un chip —o una zona del procesador, el «fTPM/PTT»— que guarda claves y secretos de forma aislada del sistema: aunque te roben el disco, no descifran nada sin ese hardware. Windows 11 lo exige como requisito mínimo (TPM 2.0) y lo usa para BitLocker, Windows Hello y el arranque seguro. Se activa en la UEFI: en Intel se llama **PTT** y en AMD **fTPM**.","The **TPM** (Trusted Platform Module) is a chip —or a CPU area called \"fTPM/PTT\"— that stores keys and secrets isolated from the system: even if your drive is stolen, nothing is decrypted without that hardware. Windows 11 requires it (TPM 2.0) and uses it for BitLocker, Windows Hello and secure boot. Enable it in UEFI: on Intel it is called **PTT**, on AMD **fTPM**."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["codigos de pitido","beeps motherboard","post que es","el pc no arranca y pita","diagnosticar arranque pc","beep codes post"],"r":["Al encender, la placa hace el **POST** (autodiagnóstico): si algo esencial falla, avisa con **pitidos** o LEDs según el fabricante (AMI/Award: pitidos largos repetidos suelen ser RAM; 1 corto y varios largos, video). Sin pitidos y sin pantalla: revisa la alimentación del CPU, que la RAM esté bien asentada y la pila CMOS. Las placas modernas muestran códigos hexadecimales o LEDs **CPU/DRAM/VGA/BOOT** que apuntan al componente culpable.","On power-up the board runs the **POST** (self-test): if something essential fails, it signals with **beeps** or LEDs depending on the vendor (AMI/Award: repeated long beeps usually mean RAM; 1 short plus several long, video). No beeps and no display: check CPU power, reseated RAM and the CMOS battery. Modern boards show hex codes or **CPU/DRAM/VGA/BOOT** LEDs pointing at the faulty component."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["que es el overclock","overclocking","subir frecuencia cpu","overclock gpu","vale la pena hacer overclock","what is overclocking"],"r":["El **overclock** fuerza al CPU o GPU a trabajar por encima de su frecuencia oficial para ganar rendimiento gratis... a costa de más calor, consumo y riesgo de inestabilidad. Se sube el multiplicador o la curva de la GPU, se prueba con estrés (Prime95, FurMark) y se ajusta voltaje: si el equipo se cuelga o da errores, vuelves atrás. Hoy el margen es pequeño porque los fabricantes ya dejan los chips cerca de su límite; en portátiles casi nunca conviene por el calor.","**Overclocking** pushes a CPU or GPU above its official frequency for free performance... at the cost of heat, power draw and instability risk. Raise the multiplier or the GPU curve, stress-test (Prime95, FurMark) and tune voltage: if the machine crashes or errors, back off. Modern margins are small because vendors ship chips close to their limit already; on laptops it rarely pays off due to heat."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["que es un nas","almacenamiento en red","nas para casa","servidor de archivos casero","backup en red","what is a nas","network attached storage"],"r":["Un **NAS** es una caja con discos duros y un sistema mínimo que se conecta a tu router y sirve archivos a toda la red: fotos, copias de seguridad y películas, sin depender de una nube de pago. Los modelos de 2 bahías permiten **RAID 1** (espejo): si un disco muere, los datos siguen vivos. Úsalo como copia automática de tus equipos y como nube privada (la mayoría ofrece apps propias). No reemplaza el backup completo: mantén también una copia fuera de casa.","A **NAS** is a box with hard drives and a minimal OS connected to your router that serves files to the whole network: photos, backups and movies, without paying for someone else's cloud. A 2-bay model allows **RAID 1** (mirror): if one disk dies, data survives. Use it as automatic backup for your devices and as a private cloud (most offer their own apps). It does not replace a full backup: keep a copy off-site too."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["que es el airflow","flujo de aire gabinete","ventilacion del pc","pc caliente que hacer","presion positiva ventiladores","airflow case cooling"],"r":["El **airflow** es el recorrido del aire dentro del gabinete: lo ideal es que entre frío por el frente/abajo y salga caliente por arriba/atrás. Instala más ventiladores de entrada que de salida (**presión positiva**: entra menos polvo por las rendijas), retira embalajes que bloqueen ranuras y limpia los filtros cada mes. Un CPU a 90 °C con el chasis a 50 °C no es problema del disipador: es el aire interior el que ya no puede absorber más calor.","**Airflow** is the air path inside the case: ideally cold air enters front/bottom and hot air exits top/rear. Use more intake than exhaust fans (**positive pressure**: less dust through gaps), remove packaging blocking vents and clean filters monthly. A CPU at 90 °C with the chassis at 50 °C is not the cooler's fault: the inside air simply cannot absorb more heat."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["panel oled","monitor oled","oled vs lcd","burn in oled","pantalla oled vale la pena","what is oled panel"],"r":["Un panel **OLED** enciende cada píxel por separado: los negros son negros reales (el píxel se apaga), el contraste y los tiempos de respuesta superan al LCD y no hay fuga de luz. Contra: el **burn-in** (imagen residual tras horas de contenido estático como HUDs o barras de tareas), el precio y un brillo máximo menor que los LED buenos. Para juegos y cine es una delicia; para hojas de cálculo 8 horas al día, un IPS es más prudente.","An **OLED** panel lights each pixel independently: blacks are truly black (the pixel switches off), contrast and response times beat LCD and there is no backlight bleed. Downsides: **burn-in** (residual image after hours of static content like HUDs or taskbars), price and lower peak brightness than good LED panels. Great for gaming and movies; for 8-hour spreadsheets, an IPS is the safer pick."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["que es sata","sata vs nvme","disco sata","interfaz sata","ssd sata velocidad","what is sata","sata vs nvme"],"r":["**SATA** es la interfaz clásica de discos y SSD de 2,5 pulgadas: llega a unos **550 MB/s** reales, suficiente para el sistema pero lejos de un **NVMe** (3.500-7.000 MB/s por PCI Express). Hoy tiene sentido para almacenamiento masivo barato: discos de 4-8 TB para archivos o SSD SATA de reemplazo en PCs viejos que recuperan vida sin gastar mucho. Cuidado con los cables: un SATA mal encajado es de las causas más comunes de «el disco desaparece».","**SATA** is the classic interface for 2.5-inch drives and SSDs: about **550 MB/s** real-world, fine for an OS but far behind **NVMe** (3,500-7,000 MB/s over PCI Express). Today it makes sense for cheap bulk storage: 4-8 TB hard drives for files or SATA SSD swaps in old PCs that come back to life on a budget. Mind the cables: a loose SATA connector is one of the most common causes of \"my drive disappeared\"."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["fuente 80 plus","certificacion 80 plus","eficiencia de la fuente","80 plus gold bronce","elegir fuente pc","what is 80 plus"],"r":["**80 Plus** certifica la eficiencia de una fuente: cuánta energía del enchufe se convierte en corriente útil y cuánta se pierde en calor. Los niveles van de Blanco a Bronce, Oro, Platino y Titanio: una Gold pierde menos del 12% a carga media y calienta menos. No mide calidad de componentes ni estabilidad, solo eficiencia: una fuente puede ser Gold y mala. Para una PC de gama media, Bronce u Oro de marca seria es el punto dulce.","**80 Plus** rates PSU efficiency: how much wall power becomes useful current and how much is lost as heat. Tiers go from White to Bronze, Gold, Platinum and Titanium: a Gold unit wastes under 12% at medium load and runs cooler. It does not measure component quality or stability, only efficiency: a Gold PSU can still be a bad PSU. For a mid-range PC, Bronze or Gold from a reputable brand is the sweet spot."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["factor de forma","atx vs micro atx","mini itx","tamano de placa base","elegir gabinete placa","motherboard form factor"],"r":["El **factor de forma** define el tamaño de placa y gabinete: **ATX** (estándar, 4-7 ranuras y buen flujo de aire), **micro-ATX** (más compacto, 2-4 ranuras, ideal para la mayoría) y **mini-ITX** (17×17 cm, para PCs pequeñas, con solo 2 ranuras de RAM y a veces fuente específica). Antes de comprar revisa que el gabinete soporte tu tamaño de placa, la altura del disipador y el largo de la GPU: son los tres topes clásicos que olvidamos medir.","**Form factor** defines motherboard and case size: **ATX** (standard, 4-7 slots, good airflow), **micro-ATX** (more compact, 2-4 slots, ideal for most builds) and **mini-ITX** (17×17 cm, small PCs, only 2 RAM slots and sometimes a specific PSU). Before buying, check the case supports your board size, cooler height and GPU length: those are the three classic limits people forget to measure."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["uefi vs bios","diferencia uefi bios","que es uefi","firmware de arranque","entrar a la bios","uefi vs bios difference"],"r":["La **BIOS** antigua arranca leyendo el primer sector del disco (MBR), con interfaz de texto y límite de 2 TB por disco. La **UEFI** moderna es un mini-sistema con interfaz gráfica, soporte de discos GPT enormes, arranque rápido y **Secure Boot** (solo ejecuta cargadores firmados, frenando rootkits de arranque). Si tu PC es de los últimos 10 años usas UEFI aunque el menú diga «BIOS»; se entra con F2/Supr/SUPR al encender.","Old **BIOS** boots by reading the disk's first sector (MBR), with a text interface and a 2 TB per-disk limit. Modern **UEFI** is a mini-system with a graphical interface, huge GPT disks, fast boot and **Secure Boot** (only signed loaders run, blocking boot rootkits). If your PC is from the last 10 years you are on UEFI even if the menu says \"BIOS\"; enter with F2/Del at power-on."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["displayport vs hdmi","diferencia displayport hdmi","dp 1.4","hdmi 2.1","cual cable para monitor","displayport vs hdmi difference"],"r":["Ambos llevan video y audio digital, pero: **DisplayPort** manda en PCs (1.4: 4K a 144 Hz con DSC; 2.1: hasta 80 Gbps; admite varios monitores en cadena con MST) y **HDMI** manda en TVs y consolas (2.1: 4K a 120 Hz, VRR, eARC). Para un monitor de PC de alta tasa de refresco, DP suele ser la opción segura; para TV y audio por receptor, HDMI. Elige según lo que soporte TU monitor a TU resolución y tasa, no por el logo del cable.","Both carry digital video and audio, but: **DisplayPort** rules PCs (1.4: 4K 144 Hz with DSC; 2.1: up to 80 Gbps; daisy-chains monitors via MST) and **HDMI** rules TVs and consoles (2.1: 4K 120 Hz, VRR, eARC). For a high-refresh PC monitor, DP is usually the safe choice; for TV and receiver audio, HDMI. Pick whatever YOUR monitor supports at YOUR resolution and refresh rate, not the cable's logo."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["cuanta ram necesito","ram para pc","8gb vs 16gb","memoria recomendada 2025","ram para estudiar y jugar","how much ram do i need"],"r":["Hoy: **8 GB** apenas para ofimática y navegación (con muchas pestañas se queda corto), **16 GB** el estándar cómodo para estudiar, programar y jugar, **32 GB** para edición de video, máquinas virtuales o diseño 3D. La RAM no acelera un PC rápido: evita que uno lento se trabe al abrir programas y pestañas. Compra en kit de 2 módulos (doble canal) y verifica en el Administrador de tareas cuánta usas realmente antes de gastar de más.","Today: **8 GB** barely covers office work and browsing (it chokes with many tabs), **16 GB** is the comfortable standard for study, coding and gaming, **32 GB** for video editing, virtual machines or 3D. RAM does not speed up a fast PC: it stops a slow one from choking when programs and tabs open. Buy a 2-module kit (dual channel) and check Task Manager usage before overspending."],"href":"hardware.html#componentes"},
    {"c":"Hardware","k":["cuantos watts fuente","fuente de alimentacion watts","psu wattage calculator","consumo de la pc","calculadora de fuente","how many watts psu"],"r":["Calcula el consumo real: CPU y GPU son el 80% (un i5 con una RTX 4060 rondan 300 W en carga), y a eso suma 50-100 W del resto del equipo. Elige una fuente con **margen del 30-40%**: para ese equipo, 650 W de calidad sobran y trabajan frías y silenciosas. No compres 1000 W «por si acaso»: la eficiencia óptima está al 40-60% de carga. Los calculadores de los fabricantes (Corsair, be quiet!) te dan el número exacto por componentes.","Estimate real draw: CPU and GPU are 80% of it (an i5 with an RTX 4060 hits about 300 W under load), plus 50-100 W for the rest of the build. Pick a PSU with **30-40% headroom**: for that build, a quality 650 W is plenty and runs cool and quiet. Do not buy 1000 W \"just in case\": peak efficiency sits at 40-60% load. Vendor calculators (Corsair, be quiet!) give you the exact number per component."],"href":"hardware.html#componentes"},
    {"c":"Redes","k":["ssh que es","ssh vs telnet","conexion segura terminal","puerto 22","claves ssh","what is ssh","ssh vs telnet"],"r":["**SSH** es la vía segura para controlar otra máquina por terminal: cifra TODO el tráfico y autentica con contraseña o, mejor, con **claves** (genera la tuya con `ssh-keygen`). Sustituyó a **Telnet**, que envía todo en texto plano: cualquiera mirando la red ve usuario y clave; Telnet solo se justifica en laboratorios aislados. Conecta con `ssh usuario@ip`, copia archivos con `scp` o `sftp`, y el servidor típico escucha en el **puerto 22**.","**SSH** is the secure way to control another machine from a terminal: it encrypts ALL traffic and authenticates with passwords or, better, **keys** (generate yours with `ssh-keygen`). It replaced **Telnet**, which sends everything in plain text: anyone watching the network sees your user and password; Telnet only makes sense in isolated labs. Connect with `ssh user@ip`, copy files with `scp` or `sftp`, and the typical server listens on **port 22**."],"href":"recursos.html#laboratorio"},
    {"c":"Redes","k":["puertos comunes","puerto 80","puerto 443","puerto 3389","puertos tcp mas usados","netstat puertos abiertos","common network ports"],"r":["Un **puerto** identifica el servicio que escucha en una IP; estos son los clásicos: **22** SSH, **53** DNS, **80** HTTP, **443** HTTPS (toda la web moderna), **3389** Escritorio remoto y **445** compartir archivos de Windows (SMB). Saberlos ayuda a configurar firewalls y detectar cosas raras: `netstat -an` en Windows lista conexiones y puertos abiertos; si aparece un servicio escuchando que no reconoces, investiga antes de abrirlo al mundo.","A **port** identifies the service listening on an IP; the classics: **22** SSH, **53** DNS, **80** HTTP, **443** HTTPS (the whole modern web), **3389** Remote Desktop and **445** Windows file sharing (SMB). Knowing them helps configure firewalls and spot oddities: `netstat -an` on Windows lists connections and open ports; if an unrecognized service is listening, investigate before exposing it."],"href":"redes.html#redes"},
    {"c":"Redes","k":["que es el qos","calidad de servicio","priorizar trafico router","qos para videollamadas","lag por descargas","what is qos networking"],"r":["**QoS** (calidad de servicio) le dice a tu router qué tráfico tiene prioridad cuando el ancho de banda se satura: tus videollamadas pasan primero y la descarga del otro equipo espera. Se configura con reglas por dispositivo, puerto o tipo de servicio; los routers modernos incluyen **SQM** (anti-bufferbloat) que hace casi todo solo. Ayuda sobre todo en subidas saturadas: cuando alguien sube a la nube y a los demás se corta la llamada, QoS lo arregla.","**QoS** (quality of service) tells your router which traffic goes first when bandwidth saturates: your video calls pass and the other device's download waits. Configure rules per device, port or service type; modern routers include **SQM** (anti-bufferbloat) that nearly runs itself. It helps most on saturated uploads: when someone backs up to the cloud and everyone else's call stutters, QoS fixes it."],"href":"redes.html#redes"},
    {"c":"Redes","k":["que es el mtu","unidad maxima de transmision","fragmentacion de paquetes","mtu 1500","mtu pppoe vpn","what is mtu"],"r":["El **MTU** es el paquete más grande que un enlace puede transportar: Ethernet estándar usa **1500 bytes**; con PPPoE o VPN queda menos (1492, 1400...). Si un paquete excede el MTU y no se permite fragmentar, se descarta: síntomas clásicos son webs que cargan a medias o que no abren (las peticiones pequeñas sí pasan). Diagnóstico: `ping destino -f -l 1472` en Windows marca el máximo sin fragmentar y desde ahí ajustas el MTU del router.","**MTU** is the largest packet a link can carry: standard Ethernet uses **1500 bytes**; PPPoE or VPNs leave less (1492, 1400...). If a packet exceeds the MTU and fragmentation is disallowed, it is dropped: classic symptoms are half-loading pages or pages that do not open (small requests pass fine). Diagnose: `ping destination -f -l 1472` on Windows finds the max unfragmented size; tune the router MTU from there."],"href":"redes.html#redes"},
    {"c":"Redes","k":["que es poe","power over ethernet","camaras poe","puntos de acceso poe","switch poe","alimentar por cable de red","what is poe"],"r":["**PoE** (Power over Ethernet) alimenta dispositivos por el mismo cable de red: cámaras IP, teléfonos VoIP y puntos de acceso se instalan donde no hay enchufe, solo cable. Hay estándares según potencia (802.3af hasta 15 W, 802.3at «PoE+» 30 W, 802.3bt hasta 90 W) y se necesita un switch PoE o inyectores. La ventaja es enorme en instalación y mantenimiento: un solo cable da datos y energía, y reiniciar el puerto apaga y enciende la cámara sin subir al techo.","**PoE** (Power over Ethernet) powers devices through the network cable itself: IP cameras, VoIP phones and access points install where there is no outlet, only cable. Standards vary by wattage (802.3af up to 15 W, 802.3at \"PoE+\" 30 W, 802.3bt up to 90 W) and you need a PoE switch or injectors. The install and maintenance win is huge: one cable carries data and power, and bouncing the port reboots a camera without climbing a ladder."],"href":"redes.html#redes"},
    {"c":"Redes","k":["que es el jitter","variacion de latencia","llamadas entrecortadas","videollamada se corta","jitter ping test","what is jitter network"],"r":["El **jitter** es la variación de la latencia: si tus paquetes llegan a 20 ms, luego a 60, luego a 15, la llamada se entrecorta aunque la velocidad sea buena. Velocidad alta no lo arregla; lo causan la saturación del WiFi, los búferes llenos del router o una línea inestable. Mide con `ping -n 50 destino` y mira cuánto varían los tiempos, o con tests que reportan jitter. Para videollamadas, lo ideal es menos de 30 ms de variación.","**Jitter** is latency variation: if your packets arrive at 20 ms, then 60, then 15, calls stutter even with good speed. More bandwidth does not fix it; causes are WiFi congestion, full router buffers or an unstable line. Measure with `ping -n 50 destination` and watch the time spread, or with test tools that report jitter. For video calls, aim under 30 ms of variation."],"href":"redes.html#simulador-red"},
    {"c":"Redes","k":["que es cat6","cat5e vs cat6","cat6a","categorias de cable ethernet","que categoria de cable comprar","ethernet cable categories"],"r":["Las categorías de cable marcan velocidad y blindaje: **Cat5e** llega a 1 Gbps (sobra para la mayoría de casas), **Cat6** a 10 Gbps hasta unos 55 m y **Cat6a** a 10 Gbps en 100 m con mejor blindaje contra interferencias. Todos usan el mismo conector RJ45: la diferencia es la calidad del cobre y la precisión del trenzado. Para gigabit doméstico, Cat5e o Cat6 económicos cumplen; gasta en Cat6a solo si tiendes 10 Gbps o hay mucho ruido eléctrico.","Cable categories mark speed and shielding: **Cat5e** handles 1 Gbps (plenty for most homes), **Cat6** 10 Gbps up to about 55 m and **Cat6a** 10 Gbps at 100 m with better shielding against interference. All use the same RJ45 connector; the difference is copper quality and twist precision. For home gigabit, cheap Cat5e or Cat6 is fine; spend on Cat6a only for 10 Gbps runs or electrically noisy places."],"href":"redes.html#redes"},
    {"c":"Redes","k":["zona dmz","dmz router","exponer un servidor","abrir puertos seguro","dmz vs port forwarding","what is dmz"],"r":["La **DMZ** de un router es una zona donde pones un equipo que necesita ser accesible desde internet (un servidor de juego, una cámara): el router le reenvía TODO lo que no coincida con otra regla. Ojo: «DMZ» no añade protección, solo saca al equipo del filtro NAT. Úsala solo en equipos que controlas y con firewall propio activo; para exponer un solo servicio, reenviar únicamente el puerto necesario es más seguro.","A router's **DMZ** is a zone for a machine that must be reachable from the internet (a game server, a camera): the router forwards ALL unmatched traffic to it. Careful: \"DMZ\" adds no protection, it just takes the host out of NAT filtering. Use it only on machines you control with their own firewall active; to expose a single service, forwarding only that port is safer."],"href":"redes.html#redes"},
    {"c":"Otro","k":["que es tor","red tor","navegador tor","onion routing","anonimato online","sitios onion","what is tor"],"r":["**Tor** es una red que enruta tu tráfico por 3 saltos voluntarios cifrando en cada etapa: nadie —ni el primer nodo ni el sitio— conoce a la vez quién eres y qué visitas. El **navegador Tor** es la forma estándar de usarla y también accede a sitios «.onion» que solo existen dentro de la red. Es más lento que la navegación normal, algunos sitios lo bloquean y es legal en la mayoría de países (lo usan periodistas y ONG). No te hace invencible: no escribas datos personales mientras navegas en Tor.","**Tor** routes your traffic through 3 volunteer relays, encrypting at each hop: no one —not the first node, not the site— knows both who you are and what you visit. The **Tor Browser** is the standard way to use it and also reaches \".onion\" sites that only exist inside the network. It is slower than normal browsing, some sites block it and it is legal in most countries (journalists and NGOs rely on it). It does not make you invincible: never type personal data while on Tor."],"href":"index.html"},
    {"c":"Redes","k":["certificado digital ssl","certificado tls","candado https","certificado de un sitio web","lets encrypt gratis","ssl tls certificates"],"r":["El **certificado** de un sitio (SSL/TLS) es un documento digital firmado por una autoridad que confirma «este dominio es quien dice ser»; es lo que activa el candado de **HTTPS**. Cifra el tráfico, pero OJO: el candado no significa que el sitio sea honesto, solo que la conexión no la espían; los estafadores también usan HTTPS. Para tu propia web: **Let's Encrypt** emite certificados válidos gratis y se renuevan solos con certbot.","A site's **certificate** (SSL/TLS) is a digital document signed by an authority confirming \"this domain is who it claims to be\"; it is what enables the **HTTPS** padlock. It encrypts traffic, but NOTE: the padlock does not mean the site is honest, only that the connection is not being spied on; scammers use HTTPS too. For your own site: **Let's Encrypt** issues valid certificates for free and renews automatically with certbot."],"href":"recursos.html#glosario"},
    {"c":"Otro","k":["cifrado extremo a extremo","e2e encryption","whatsapp cifrado","solo tu y el destinatario leen","end to end encryption"],"r":["El **cifrado extremo a extremo** garantiza que solo emisor y receptor leen el mensaje: la app cifra en tu dispositivo y descifra en el del otro, y el servidor solo transporta un texto indescifrable. Es más fuerte que el cifrado «en tránsito» (HTTPS), donde el proveedor SÍ podría leer el contenido en sus servidores. Verifica la clave de contacto o activa la comparación de códigos de seguridad en la app; sin eso, confías en que el software hace lo que promete.","**End-to-end encryption** ensures only sender and receiver read the message: the app encrypts on your device and decrypts on theirs, while the server just carries unreadable text. It is stronger than \"in transit\" encryption (HTTPS), where the provider COULD read content on its servers. Verify contact keys or enable safety-code comparison in the app; without that, you trust the software to do what it promises."],"href":"index.html"},
    {"c":"Redes","k":["fibra optica ftth","que es ftth","onu ont fibra","fibra hasta la casa","fibra simetrica","what is ftth"],"r":["**FTTH** (fibra hasta el hogar) lleva la señal de luz hasta tu casa: dentro del **ONT** (la cajita que convierte fibra en Ethernet) no sufre interferencias ni degradación por distancia como el cobre, y por eso promete 300-1000 Mbps simétricos reales. Del ONT sale un cable a tu router (o el router integra el ONT). Si tu plan de fibra da menos de lo contratado, prueba cable directo al ONT y luego al router: muchas veces el cuello de botella es el WiFi, no la línea.","**FTTH** (fiber to the home) brings the light signal to your door: inside the **ONT** (the box converting fiber to Ethernet) it suffers no interference or distance decay like copper, which is why 300-1000 Mbps symmetric is real. A cable runs from the ONT to your router (or the router has the ONT built in). If your fiber plan underperforms, test a direct cable to the ONT and then the router: often the bottleneck is the WiFi, not the line."],"href":"redes.html#redes"},
    {"c":"Redes","k":["tormenta de broadcast","bucle en la red","la red se cae sola","switches en bucle","broadcast storm loop"],"r":["Una **tormenta de broadcast** ocurre cuando hay un bucle en la red (dos cables que unen los mismos switches, por ejemplo): los paquetes de difusión se multiplican hasta colapsar todo, y la red «se cae» sin causa aparente. Los switches gestionables activan **STP** (spanning tree) que detecta y bloquea bucles. En casa: si agregaste un switch o un cable de más entre equipos y todo murió de golpe, desconecta ese cable sospechoso y prueba de nuevo.","A **broadcast storm** happens when a loop exists in the network (two cables joining the same switches, for example): broadcast packets multiply until everything collapses, and the network \"dies\" with no visible cause. Managed switches enable **STP** (spanning tree) to detect and block loops. At home: if you added a switch or an extra cable and everything died at once, disconnect the suspect cable and test again."],"href":"redes.html#redes"},
    {"c":"Redes","k":["dns secundario","dns de respaldo","redundancia dns","servidor dns alternativo","1.1.1.1 y 8.8.8.8","secondary dns server"],"r":["El **DNS secundario** es el servidor de respaldo que consulta tu equipo cuando el principal no responde: por eso los sistemas piden dos (o más) direcciones. Un error común es poner dos DNS distintos «para tener opciones»: el sistema consulta casi siempre al primero y el segundo solo entra si el primero falla de verdad. Elige pares coherentes (por ejemplo 1.1.1.1 y 1.0.0.1 de Cloudflare, u 8.8.8.8 y 8.8.4.4 de Google) y cambia el DNS en el router para que toda la red se beneficie.","The **secondary DNS** is the backup server your device asks when the primary does not answer: that is why systems ask for two (or more) addresses. A common mistake is mixing two unrelated DNS \"for options\": the system almost always asks the first, and the second only steps in on a true failure. Pick consistent pairs (e.g. 1.1.1.1 and 1.0.0.1 from Cloudflare, or 8.8.8.8 and 8.8.4.4 from Google) and set DNS at the router so the whole network benefits."],"href":"recursos.html#laboratorio"},
    {"c":"WiFi","k":["canales wifi","canal 1 6 11","wifi lento por vecinos","solapamiento de canales","analizador wifi","wifi channels overlap"],"r":["En la banda de **2.4 GHz** solo hay 3 canales que no se solapan: **1, 6 y 11**. Si tu router está en el 3 y el del vecino en el 4, se estorban y los dos van lentos. Abre un analizador de WiFi (app gratuita), mira qué canales usan tus vecinos y quédate en el 1, 6 u 11 más libre. En **5 GHz** hay muchos más canales y llegan menos lejos, así que el problema casi desaparece: usa 5 GHz para velocidad y 2.4 GHz para alcance.","On **2.4 GHz** only 3 channels do not overlap: **1, 6 and 11**. If your router sits on 3 and your neighbor's on 4, they interfere and both slow down. Open a WiFi analyzer (free app), check which channels neighbors use and pick the freest of 1, 6 or 11. On **5 GHz** there are many more channels and they reach less far, so the problem mostly vanishes: use 5 GHz for speed and 2.4 GHz for range."],"href":"wifi.html#instalar-modem"},
    {"c":"WiFi","k":["extensor wifi","red mesh","wifi en toda la casa","repetidor vs mesh","mejorar cobertura wifi","wifi extender vs mesh"],"r":["Un **extensor** repite la señal a mitad de camino: fácil de instalar, pero suele cortar el rendimiento a la mitad y crea dos redes o una sola con zonas muertas. Un sistema **mesh** son varios nodos que hablan entre sí y forman UNA red que te sigue por la casa sin cortes, con gestión central por app. Para pisos pequeños alcanza un extensor bien ubicado; para casas de 2 pisos o muros gruesos, un mesh de 2-3 nodos es la solución seria.","An **extender** repeats the signal halfway: easy to install, but it usually halves throughput and creates two networks or one network with dead zones. A **mesh** system is several nodes that talk to each other and form ONE network that follows you around the house without drops, managed centrally from an app. For small apartments a well-placed extender works; for 2-story houses or thick walls, a 2-3 node mesh is the serious fix."],"href":"wifi.html#instalar-modem"},
    {"c":"WiFi","k":["que es powerline","plc internet por cable electrico","adaptador plc","internet por enchufe","powerline networking"],"r":["Los adaptadores **powerline** (PLC) usan el cableado eléctrico de tu casa para llevar internet: enchufas uno junto al router, otro en la habitación y la señal viaja por la instalación. Funciona bien donde el WiFi no atraviesa muros, PERO depende muchísimo de la instalación eléctrica: circuitos distintos, protectores o enchufes viejos la degradan o la matan. Compra con opción de devolución y prueba: donde el PLC funciona, es la forma más estable de llevar red sin tender cable.","**Powerline** (PLC) adapters use your home's electrical wiring to carry internet: plug one near the router, another in the room, and the signal travels through the installation. It works well where WiFi cannot cross walls, BUT it depends heavily on the electrical setup: separate circuits, surge protectors or old outlets degrade or kill it. Buy with a return option and test: where PLC works, it is the most stable way to get network without running cable."],"href":"wifi.html#instalar-modem"},
    {"c":"WiFi","k":["que es el tethering","hotspot movil","compartir datos moviles","punto de acceso del celular","gasto de datos hotspot","mobile hotspot tethering"],"r":["El **tethering** convierte tu celular en router: activas «punto de acceso / hotspot» y otros equipos navegan con tus datos móviles. Cuidados: consume el plan rápido (un video en HD gasta unos 3 GB por hora), calienta el teléfono y la banda 2.4 GHz por defecto se satura fácil: usa 5 GHz si tu equipo lo ofrece y ponle una clave larga. Vigila también las apps de fondo del PC conectado: las actualizaciones de Windows pueden fundir tu cupo sin que notes.","**Tethering** turns your phone into a router: enable the \"hotspot\" and other devices browse on your mobile data. Watch out: it burns your plan fast (HD video is about 3 GB per hour), heats the phone and the default 2.4 GHz band saturates easily: use 5 GHz if offered and set a long password. Also mind background apps on the connected PC: Windows updates can quietly eat your quota."],"href":"wifi.html#instalar-modem"},
    {"c":"WiFi","k":["que es wps","boton wps riesgo","wps pin vulnerable","conectar sin contrasena wifi","desactivar wps","what is wps"],"r":["**WPS** es el botón del router que conecta dispositivos sin escribir la clave: cómodo, pero su método de **PIN numérico** tiene una falla conocida que permite descifrarlo por fuerza bruta en horas. Recomendación: desactiva WPS en el router si no lo usas, o al menos usa solo el método de botón físico (nunca el PIN). Para conectar invitados de forma segura, activa una **red de invitados** con clave propia, que además aísla tus equipos de los suyos.","**WPS** is the router button that joins devices without typing the key: convenient, but its numeric **PIN** method has a known flaw that lets attackers brute-force it in hours. Recommendation: disable WPS on the router if unused, or at least use only the physical button method (never the PIN). To connect guests safely, enable a **guest network** with its own key, which also isolates their devices from yours."],"href":"wifi.html#instalar-modem"},
    {"c":"WiFi","k":["punto de acceso wifi","ap vs router","convertir router en ap","modo access point","segundo router wifi","access point vs router"],"r":["El **router** reparte IPs, hace de firewall y da WiFi; un **punto de acceso** (AP) solo añade WiFi a una red que ya existe. Cuando el router de tu operadora da mal WiFi, la solución limpia es poner un AP o un router nuevo en «modo punto de acceso» (desactivando DHCP y NAT) conectado por cable: una sola red, sin dobles NAT ni conflictos. Colócalo alto y central, lejos de microondas y espejos que rebota la señal.","The **router** hands out IPs, acts as firewall and provides WiFi; an **access point** (AP) only adds WiFi to an existing network. When your ISP's router has bad WiFi, the clean fix is adding an AP or putting a new router in \"access point mode\" (disabling DHCP and NAT) connected by cable: a single network, no double NAT or conflicts. Place it high and central, away from microwaves and mirrors that bounce the signal."],"href":"wifi.html#instalar-modem"},
    {"c":"WiFi","k":["que es el roaming wifi","roaming 802.11r","wifi se corta al caminar","cambiar de nodo wifi","handoff wifi","wifi roaming handoff"],"r":["El **roaming** WiFi es el cambio de un punto de acceso a otro mientras te mueves: si tu teléfono «se queda pegado» al nodo lejano y la señal muere antes de saltar, la llamada se corta. En redes mesh buenas, el sistema empuja al cliente al nodo más cercano (estándares **802.11k/v/r**); en equipos viejos el cambio tarda segundos. Truco casero: desactiva y activa el WiFi del teléfono, o activa «WiFi agresivo» en los ajustes de desarrollador de Android.","WiFi **roaming** is switching between access points as you move: if your phone \"sticks\" to the far node and the signal dies before jumping, calls drop. Good mesh systems push clients to the nearest node (**802.11k/v/r** standards); on older gear the switch takes seconds. Home trick: toggle the phone's WiFi off and on, or enable \"aggressive WiFi\" in Android developer settings."],"href":"wifi.html#instalar-modem"},
    {"c":"Recursos","k":["que es dxdiag","diagnostico directx","ver mi gpu windows","dxdiag reporte","requisitos de un juego","what is dxdiag"],"r":["**DXDiag** es el diagnóstico gráfico de Windows: pulsa `Win+R`, escribe `dxdiag` y verás tu CPU, RAM, versión de Windows y —en la pestaña Pantalla— tu GPU, driver y versión de DirectX. Es lo primero que pide el soporte de un juego para ver si tu equipo cumple los requisitos. Guarda el reporte completo con «Guardar toda la información» y comparte ese archivo de texto: incluye el modelo exacto de todo el hardware.","**DXDiag** is Windows' graphics diagnostic: press `Win+R`, type `dxdiag` and you will see your CPU, RAM, Windows version and —on the Display tab— your GPU, driver and DirectX version. It is the first thing game support asks to check whether your PC meets requirements. Save the full report with \"Save All Information\" and share that text file: it includes the exact model of every component."],"href":"recursos.html#laboratorio"},
    {"c":"Recursos","k":["que es regedit","registro de windows","editar registro","regedit para que sirve","cambios registro peligro","windows registry editor"],"r":["El **Registro de Windows** es la base de datos con la configuración del sistema y de los programas; **regedit** es su editor (`Win+R` → `regedit`). Permite ajustes que no aparecen en opciones, pero un cambio mal hecho puede impedir que Windows arranque. Regla de oro: antes de tocar, **exporta** la clave (Archivo → Exportar) para poder restaurarla; y desconfía de tutoriales que te hagan borrar ramas completas del registro.","The **Windows Registry** is the database holding system and app configuration; **regedit** is its editor (`Win+R` → `regedit`). It allows tweaks not exposed in settings, but one wrong change can stop Windows from booting. Golden rule: before editing, **export** the key (File → Export) so you can restore it; and distrust tutorials that make you delete whole registry branches."],"href":"mantenimiento-software.html#paso-a-paso"},
    {"c":"Recursos","k":["que es msconfig","inicio limpio","arranque selectivo","detectar programa que cuelga windows","clean boot msconfig"],"r":["**msconfig** (`Win+R` → `msconfig`) controla cómo arranca Windows: con «Inicio selectivo» puedes arrancar sin servicios de terceros para detectar si un programa de fondo causa los cuelgues. El «inicio limpio» (desactivar servicios que no son de Microsoft y reiniciar) es el paso estándar antes de culpar al hardware: si el problema desaparece, reactívalos por mitades hasta dar con el culpable. Para programas que arrancan con Windows, usa hoy el Administrador de tareas → pestaña «Inicio».","**msconfig** (`Win+R` → `msconfig`) controls how Windows boots: \"Selective startup\" can boot without third-party services to detect whether a background program causes the crashes. The \"clean boot\" (disable non-Microsoft services and reboot) is the standard step before blaming hardware: if the problem disappears, re-enable in halves until you find the culprit. For startup apps, use Task Manager → \"Startup\" tab today."],"href":"mantenimiento-software.html#paso-a-paso"},
    {"c":"Recursos","k":["que es tbw","vida util ssd","endurance ssd","desgaste del ssd","cuanto dura un ssd","ssd tbw endurance"],"r":["El **TBW** (terabytes escritos) es la garantía de escritura de un SSD: cuántos TB puedes escribir antes de que el fabricante lo considere gastado (un 500 GB típico: 300-600 TBW). Con uso normal escribes 20-40 TB al año: el SSD duraría 10-15 años, así que en la práctica lo renovarás antes de que muera. Consulta el desgaste real con **CrystalDiskInfo** o el software del fabricante: muestra el porcentaje de vida restante del disco.","**TBW** (terabytes written) is an SSD's write endurance rating: how many TB you can write before the vendor considers it worn (a typical 500 GB drive: 300-600 TBW). Normal use writes 20-40 TB a year: the SSD would last 10-15 years, so in practice you will upgrade long before it dies. Check real wear with **CrystalDiskInfo** or vendor software: it shows the drive's remaining life percentage."],"href":"mantenimiento-software.html#rutina"},
    {"c":"Recursos","k":["que es trim","trim ssd","optimizar unidades windows","mantenimiento ssd","desfragmentar ssd","ssd trim command"],"r":["**TRIM** avisa al SSD qué bloques ya no se usan para que los limpie en segundo plano y las escrituras futuras sean rápidas: sin TRIM, un SSD se degrada con el tiempo. Windows lo activa solo; verifica con `fsutil behavior query DisableDeleteNotify` (respuesta 0 = activo) y no lo desactives. No desfragmente un SSD: no solo no ayuda, sino que lo desgasta; Windows ejecuta una «optimización» mensual que sí es segura.","**TRIM** tells the SSD which blocks are unused so it can clean them in the background and keep future writes fast: without TRIM an SSD degrades over time. Windows enables it automatically; verify with `fsutil behavior query DisableDeleteNotify` (answer 0 = enabled) and leave it on. Never defragment an SSD: it does not help and wears the drive; Windows runs a monthly \"optimize\" pass that is safe."],"href":"mantenimiento-software.html#rutina"},
    {"c":"Recursos","k":["hibernar vs suspender","diferencia suspender hibernar","apagar o hibernar","portatil se calienta en la mochila","hibernation vs sleep"],"r":["**Suspender** deja la RAM alimentada y despierta en segundos (gasta batería mínima); **hibernar** vuelca la RAM al disco (`hiberfil.sys`) y apaga todo: cero consumo y continúas donde lo dejaste, ideal para portátiles que quedan días sin uso. Si el portátil se calienta dentro de la mochila, configura que al cerrar la tapa **hiberne** en vez de suspender. Desactivar la hibernación con `powercfg /h off` libera varios GB de disco, pero pierdes esa función.","**Sleep** keeps RAM powered and wakes in seconds (minimal battery); **hibernate** dumps RAM to disk (`hiberfil.sys`) and powers everything off: zero drain and you resume where you left it, ideal for laptops sitting unused for days. If your laptop gets hot inside the backpack, set the lid-close action to **hibernate** instead of sleep. Disabling hibernation with `powercfg /h off` frees several GB of disk but loses the feature."],"href":"mantenimiento-software.html#rutina"},
    {"c":"Recursos","k":["arranque rapido","fast startup windows","windows tarda en apagar","apagado hibrido","problemas fast startup","fast startup windows 11"],"r":["El **arranque rápido** de Windows combina apagado con hibernación parcial: al apagar, guarda el estado del núcleo para encender más rápido. Suena bien, pero provoca problemas clásicos: el doble arranque no ve el otro sistema, los cambios de UEFI no aplican y los periféricos amanecen raros. Desactívalo en Opciones de energía → «Elegir el comportamiento de los botones» si tu PC no apaga bien; en un SSD el impacto en el arranque es mínimo.","Windows **fast startup** blends shutdown with partial hibernation: on shutdown it saves kernel state to boot faster. Sounds nice, but it causes classic issues: dual-boot not seeing the other OS, UEFI changes not applying and peripherals waking up weird. Disable it in Power Options → \"Choose what the power buttons do\" if your PC does not shut down cleanly; on an SSD the boot-time impact is minimal."],"href":"mantenimiento-software.html#paso-a-paso"},
    {"c":"Recursos","k":["actualizar bios","flash bios","como actualizar uefi","riesgo actualizar bios","bios update riesgo","how to update bios"],"r":["Actualiza la **BIOS/UEFI** solo si necesitas algo concreto: soporte para un CPU nuevo, corrección de un fallo grave o un parche de seguridad. Descarga el archivo EXACTO de tu modelo de placa desde la web del fabricante, lee las instrucciones (muchas placas lo hacen desde USB con un botón, sin CPU), conéctate a un SAI/UPS o con batería cargada y NUNCA apagues a mitad: un corte deja la placa inutilizable. Si todo funciona, «si no está roto, no lo arregles».","Update **BIOS/UEFI** only if you need something specific: new CPU support, a serious bug fix or a security patch. Download the EXACT file for your board model from the vendor site, read the instructions (many boards flash from USB with a button, no CPU needed), stay connected to a UPS or charged battery and NEVER power off midway: a blackout bricks the board. If everything works, \"if it ain't broke, don't fix it\"."],"href":"mantenimiento-software.html#paso-a-paso"},
    {"c":"Recursos","k":["driver del chipset","chipset drivers","drivers de placa base","instalar drivers motherboard","orden para instalar drivers","chipset driver install"],"r":["El **driver del chipset** enseña a Windows a hablar bien con tu placa base: gestión de energía, USB, puertos SATA y sin dispositivos «desconocidos» en el Administrador. Mucha gente instala solo el de la GPU y deja el resto a Windows Update (funciona, pero peor). Después de formatear, el orden ideal: chipset → GPU → red → audio → resto. Descárgalos SIEMPRE de la web del fabricante de la placa, no de instaladores «todo en uno» dudosos.","The **chipset driver** teaches Windows to talk properly to your motherboard: power management, USB, SATA ports and no \"unknown device\" entries in Device Manager. Many people install only the GPU driver and leave the rest to Windows Update (it works, but worse). After a clean install, the ideal order: chipset → GPU → network → audio → rest. ALWAYS download from the board vendor's site, not from shady all-in-one installers."],"href":"mantenimiento-software.html#paso-a-paso"},
    {"c":"Recursos","k":["cola de impresion","print spooler","impresora no imprime","cancelar impresion atascada","limpiar cola impresion","printer spooler fix"],"r":["Cuando un documento atascado bloquea la impresora, vacía la **cola de impresión**: detén el servicio «Cola de impresión» (services.msc), borra los archivos de `C:\\Windows\\System32\\spool\\PRINTERS` y reinicia el servicio. En Windows 11: Configuración → Bluetooth y dispositivos → Impresoras → abrir cola → cancelar todo. Si el spooler se cae solo cada vez que imprimes, el culpable suele ser un driver corrupto: reinstala el driver oficial del fabricante.","When a stuck job blocks the printer, clear the **print queue**: stop the \"Print Spooler\" service (services.msc), delete files in `C:\\Windows\\System32\\spool\\PRINTERS` and restart the service. On Windows 11: Settings → Bluetooth & devices → Printers → open queue → cancel all. If the spooler keeps crashing on every print, a corrupt driver is usually to blame: reinstall the vendor's official driver."],"href":"mantenimiento-software.html#tareas"},
    {"c":"Recursos","k":["drivers firmados","driver whql","controladores certificados","instalar driver sin firmar","actualizador de drivers","whql signed drivers"],"r":["Un driver **firmado** (WHQL) pasó la certificación de Microsoft: el sistema verifica su origen y nadie lo modificó en el camino. Windows moderno se niega a instalar drivers sin firma (o exige aprobarlo a mano), y con razón: un driver corre con más privilegios que casi cualquier programa y uno defectuoso tumba todo el sistema (pantallazos azules). Descarga drivers solo del fabricante o de Windows Update; evita los «actualizadores de drivers» automáticos, que prometen mucho y meten bloatware.","A **signed** driver (WHQL) passed Microsoft certification: the system verifies its origin and nobody tampered with it. Modern Windows refuses unsigned drivers (or requires manual approval), for good reason: a driver runs with more privileges than almost any program and a buggy one takes the whole system down (blue screens). Get drivers only from the vendor or Windows Update; avoid automatic \"driver updaters\" that promise a lot and install bloatware."],"href":"mantenimiento-software.html#programas"},
    {"c":"Recursos","k":["que es wsl","linux en windows","subsistema de linux","wsl2 instalar","programar en linux windows","what is wsl"],"r":["**WSL** (Windows Subsystem for Linux) corre un Linux REAL dentro de Windows sin máquina virtual pesada: instalas con `wsl --install` y en minutos tienes Ubuntu en tu menú. Ideal para programar: las herramientas de Linux (git, python, node, docker) funcionan nativas y tus archivos de Windows se ven en `/mnt/c`. WSL2 usa virtualización ligera: arranca en segundos y consume solo lo que usa. Abre una terminal, escribe `wsl` y estás dentro.","**WSL** (Windows Subsystem for Linux) runs a REAL Linux inside Windows without a heavy VM: install with `wsl --install` and in minutes Ubuntu is in your start menu. Great for coding: Linux tools (git, python, node, docker) run natively and your Windows files show up under `/mnt/c`. WSL2 uses lightweight virtualization: boots in seconds and consumes only what it uses. Open a terminal, type `wsl`, and you are in."],"href":"recursos.html#laboratorio"},
    {"c":"Recursos","k":["que es docker","contenedores","docker vs maquina virtual","contenedor que es","desplegar aplicaciones","what is docker containers"],"r":["Un **contenedor** Docker empaqueta una aplicación con todo lo que necesita (librerías, configuración) para que corra igual en tu PC, en el servidor y en la nube. A diferencia de una máquina virtual, NO lleva su propio sistema operativo: comparte el núcleo y arranca en segundos consumiendo poco. Es el estándar para desplegar y para reproducir entornos de clase o trabajo sin el clásico «en mi PC funciona». Docker Desktop lo trae a Windows y Mac sin dolor.","A Docker **container** packages an app with everything it needs (libraries, config) so it runs the same on your PC, a server and the cloud. Unlike a virtual machine it does NOT carry its own OS: it shares the kernel and starts in seconds with low overhead. It is the standard for deploying and for reproducing class or work environments without the classic \"it works on my machine\". Docker Desktop brings it to Windows and Mac painlessly."],"href":"recursos.html#laboratorio"},
    {"c":"Recursos","k":["formatear el pc","reinstalar windows","restaurar de fabrica","preparar formateo","formatear laptop","how to reset windows"],"r":["Antes de formatear: copia tus archivos (incluye escritorio y carpetas de apps), guarda claves de licencias y **exporta** el navegador (contraseñas y favoritos). Hoy no necesitas USB de instalación: Configuración → Sistema → Recuperación → «Restablecer este PC» → «Eliminar todo» + «Descarga de la nube» reinstala Windows limpio. Tras el formateo, instala los drivers de chipset y GPU ANTES que cualquier otra cosa, y activa copias de seguridad desde el día uno para no repetir el proceso.","Before wiping: copy your files (including Desktop and app folders), save license keys and **export** browser data (passwords and favorites). No install USB needed today: Settings → System → Recovery → \"Reset this PC\" → \"Remove everything\" + \"Cloud download\" reinstalls Windows clean. After the reset, install chipset and GPU drivers FIRST, and enable backups from day one so you never repeat the ordeal."],"href":"mantenimiento-software.html#paso-a-paso"},
    {"c":"Recursos","k":["que es ntfs","sistema de archivos windows","ntfs vs fat32","permisos ntfs","disco externo formato","what is ntfs"],"r":["**NTFS** es el sistema de archivos del Windows moderno: soporta discos enormes, **permisos** por usuario, registro de cambios (journaling) para sobrevivir cortes de luz y compresión. macOS no escribe en él de forma nativa (solo lee) y muchos aparatos (TVs, consolas viejas, cámaras) tampoco: para memorias USB «viajeras» usa **exFAT**, universal y sin el límite de 4 GB por archivo de FAT32. Un disco externo NTFS es perfecto para backups de Windows.","**NTFS** is the modern Windows file system: huge disks, per-user **permissions**, journaling to survive power cuts and compression. macOS cannot write it natively (read only) and many gadgets (TVs, old consoles, cameras) cannot either: for travel USB sticks use **exFAT**, universal and without FAT32's 4 GB per-file limit. An NTFS external drive is perfect for Windows backups."],"href":"mantenimiento-software.html#tareas"},
    {"c":"Recursos","k":["control de cuentas de usuario","uac que es","ventana de permisos windows","avisos de administrador","what is uac"],"r":["El **UAC** (control de cuentas de usuario) es la ventana que pregunta «¿quieres permitir que esta app haga cambios?»: incluso siendo administrador, tus programas corren con permisos bajos hasta que algo los eleva. Molestia a cambio de seguridad real: el malware que entra por tu sesión no puede tocar el sistema sin ese click. No lo desactives; y cuando aparezca, LEE el nombre del programa y el editor verificado antes de aceptar. Si pide permisos algo que no reconoces, algo huele mal.","**UAC** (user account control) is the \"do you want to allow this app to make changes?\" prompt: even as admin, your programs run with low rights until something elevates. Annoyance in exchange for real security: malware landing in your session cannot touch the system without that click. Do not disable it; and when it pops up, READ the program name and verified publisher before accepting. If something you do not recognize asks for rights, something smells bad."],"href":"mantenimiento-software.html#alertas"},
    {"c":"Recursos","k":["cifrado del disco","bitlocker que es","cifrar disco duro","robo de laptop proteccion","clave de recuperacion bitlocker","disk encryption bitlocker"],"r":["El **cifrado de disco** (BitLocker en Windows Pro, o «Cifrado del dispositivo» en Home) vuelve ilegible el disco para quien no tenga la clave: si te roban el portátil, no abren tus archivos conectando el disco a otra máquina. Actívalo y GUARDA la clave de recuperación fuera del equipo (impresa o en tu cuenta Microsoft). El costo de rendimiento es mínimo en hardware moderno y es de las protecciones con mejor relación esfuerzo-beneficio que existen.","**Disk encryption** (BitLocker on Windows Pro, or \"Device encryption\" on Home) makes the drive unreadable without the key: if your laptop is stolen, nobody opens your files by plugging the disk elsewhere. Enable it and SAVE the recovery key off the device (printed or in your Microsoft account). Performance cost is tiny on modern hardware and it is one of the best effort-to-benefit protections available."],"href":"mantenimiento-software.html#rutina"},
    {"c":"Recursos","k":["monitorear temperatura","temperatura cpu","hwmonitor","pc se apaga solo","temperatura normal cpu","monitor cpu temperature"],"r":["Vigila las temperaturas con **HWMonitor**, HWiNFO o el lector del BIOS: CPU en reposo 30-50 °C, en carga 60-85 °C; más de 95 °C sostenidos significa que algo va mal (disipador con polvo, pasta térmica seca, flujo de aire bloqueado o curva de ventiladores mal hecha). Un equipo que se apaga solo en juegos casi siempre es problema térmico o de fuente. Una limpieza con aire comprimido cada 3-6 meses previene el 90% de los casos.","Watch temperatures with **HWMonitor**, HWiNFO or the BIOS readout: CPU idle 30-50 °C, load 60-85 °C; sustained 95 °C+ means something is wrong (dusty cooler, dry thermal paste, blocked airflow or a bad fan curve). A PC that shuts down mid-game is almost always thermal or PSU related. Compressed-air cleaning every 3-6 months prevents 90% of cases."],"href":"mantenimiento-software.html#rutina"},
    {"c":"Otro","k":["que es un honeypot","trampa de seguridad","servidor señuelo","deteccion de intrusos","what is a honeypot"],"r":["Un **honeypot** (tarro de miel) es un sistema señuelo: parece un servidor o servicio vulnerable pero está vigilado, y su única función es atraer atacantes para estudiarlos y alejarlos de lo real. Todo el que toca un honeypot es, por definición, un intruso: no hay falsos positivos. Las empresas los usan para detectar movimientos tempranos dentro de su red; tú puedes probar uno en casa con contenedores como T-Pot y ver en minutos cuántos escaneos recibe tu IP.","A **honeypot** is a decoy system: it looks like a vulnerable server or service but is fully monitored, and its only job is attracting attackers to study them and keep them away from what is real. Anyone touching a honeypot is by definition an intruder: zero false positives. Companies use them to catch early movement inside their network; you can try one at home with containers like T-Pot and watch in minutes how many scans your IP gets."],"href":"mantenimiento-software.html#alertas"},
    {"c":"Otro","k":["vulnerabilidad zero day","dia cero","ataque de dia cero","exploit 0day","parche de seguridad","zero day vulnerability"],"r":["Un **zero day** es una vulnerabilidad que el fabricante aún no conoce: lleva «cero días» de vida conocida y, por tanto, no hay parche. Por eso son las más valiosas en el mercado negro y las más peligrosas. Tu defensa son hábitos, no productos: actualiza TODO en cuanto salga el parche (los zero days dejan de serlo al publicarse la corrección), minimiza el software instalado y usa cuentas sin permisos de admin para el día a día. Los navegadores actualizados neutralizan la mayoría de los ataques web de este tipo.","A **zero day** is a vulnerability the vendor does not know about yet: it has been known for \"zero days\" and no patch exists. That is why they sell high on the black market and hurt the most. Your defense is habits, not products: patch EVERYTHING as soon as updates land (zero days stop being zero days once the fix ships), run minimal software and use non-admin accounts for daily work. Updated browsers neutralize most web-based attacks of this kind."],"href":"mantenimiento-software.html#alertas"},
    {"c":"Otro","k":["que es un keylogger","registrador de teclas","robo de contrasenas teclado","keylogger hardware","protegerse keylogger","what is a keylogger"],"r":["Un **keylogger** registra cada tecla que pulsas y guarda o envía el log: con él, una contraseña segura da igual, porque el ladrón la lee directamente. Llega en adjuntos maliciosos, instaladores piratas o hasta en dispositivos USB físicos en cajeros y PCs públicos. Defensa: activa la **verificación en dos pasos** (aunque copien tu clave, no entran sin el segundo factor), usa un gestor de contraseñas con autollenado (no tecleas, no te registran) y en PCs ajenos no entres a cuentas críticas.","A **keylogger** records every key you press and stores or ships the log: with it, password strength does not matter, because the thief reads it directly. It arrives in malicious attachments, pirated installs or even USB hardware devices on ATMs and public PCs. Defense: enable **two-factor authentication** (even with your password copied, they cannot enter without the second factor), use a password manager with autofill (nothing typed, nothing recorded) and never touch critical accounts on public PCs."],"href":"mantenimiento-software.html#alertas"},
    {"c":"Otro","k":["que es un rootkit","malware profundo","rootkit de arranque","malware que se oculta","limpiar rootkit","what is a rootkit"],"r":["Un **rootkit** es malware que se instala en las capas más profundas del sistema (núcleo, firmware o arranque) y su especialidad es **ocultarse**: procesos, archivos y conexiones que el antivirus no ve porque el propio sistema miente. Es el tipo más difícil de limpiar: muchas veces la única solución segura es formatear y, en rootkits de firmware, reflashear o cambiar hardware. Prevención: Secure Boot activo, firmware al día y nunca ejecutar instaladores de dudosa procedencia con permisos de admin.","A **rootkit** is malware installed at the deepest layers (kernel, firmware or boot) specialized in **hiding**: processes, files and connections the antivirus cannot see because the system itself lies. It is the hardest type to clean: often the only safe fix is a full wipe, and for firmware rootkits a reflash or hardware swap. Prevention: Secure Boot on, firmware updated and never running shady installers with admin rights."],"href":"mantenimiento-software.html#alertas"},
    {"c":"Otro","k":["que es el spyware","software espia","espionaje de apps","permisos de apps","rastreo de datos","what is spyware"],"r":["El **spyware** se instala (o tú lo instalas al aceptar permisos) y recopila silenciosamente tus datos: historial, ubicación, contactos, pulsaciones, y los vende o envía. No rompe nada: su negocio es pasar desapercibido. Síntomas: batería que se agota de golpe, datos móviles que se esfuman y anuncios sospechosamente afinados. Defensa: descarga apps solo de tiendas oficiales, revisa permisos (¿por qué una linterna quiere tu ubicación?) y revoca los que no cuadran.","**Spyware** installs itself (or you install it by accepting permissions) and silently harvests your data: history, location, contacts, keystrokes, then sells or ships it. It breaks nothing: its business is staying invisible. Symptoms: sudden battery drain, mobile data vanishing and suspiciously well-tuned ads. Defense: download apps only from official stores, review permissions (why does a flashlight need your location?) and revoke the ones that do not add up."],"href":"mantenimiento-software.html#alertas"},
    {"c":"Otro","k":["ingenieria social","manipulacion para robar","el eslabon mas debil","estafas sociales","pretexto seguridad","social engineering attack"],"r":["La **ingeniería social** no ataca computadoras: ataca personas. Consiste en convencer por llamada, mensaje o en persona a alguien de dar datos, códigos o acceso, usando urgencia («su cuenta será bloqueada»), autoridad falsa («soy de sistemas») o miedo. Está detrás de la mayoría de las brechas grandes: no necesitan hackear si tú les abres la puerta. Reglas: nadie legítimo pide tu contraseña ni tus códigos 2FA; si hay «urgencia», es señal de alerta; y verifica llamando tú al número oficial.","**Social engineering** does not attack computers: it attacks people. It convinces someone by call, message or in person to hand over data, codes or access, using urgency (\"your account will be locked\"), fake authority (\"IT department here\") or fear. It drives most major breaches: no hacking needed when you open the door. Rules: no legitimate party asks for your password or 2FA codes; \"urgency\" is a red flag; verify by calling the official number yourself."],"href":"mantenimiento-software.html#alertas"},
    {"c":"Otro","k":["que es el vishing","phishing por llamada","estafa telefonica banco","voz clonada ia","llamada falso banco","vishing voice phishing"],"r":["El **vishing** es phishing por teléfono: alguien dice ser tu banco, tu operadora o soporte técnico y pide códigos, «validar» una transferencia o instalar una app de «ayuda». Con IA ahora clonan voces: una llamada «de tu familiar en apuros» suena real. Defensa: cuelga y llama TÚ al número oficial (el de la tarjeta o la web, no el que te dictan); ningún banco pide códigos por teléfono; y una palabra secreta de familia neutraliza los clones de voz.","**Vishing** is phishing over the phone: someone claims to be your bank, carrier or tech support and asks for codes, to \"validate\" a transfer or install a \"help\" app. With AI they now clone voices: a call \"from a relative in trouble\" sounds real. Defense: hang up and call the official number YOURSELF (the one on your card or their website, not one they dictate); no bank asks for codes over the phone; and a family safe word defeats voice clones."],"href":"mantenimiento-software.html#alertas"},
    {"c":"Otro","k":["que es un deepfake","video falso ia","clonar voz","deepfake fraudes","detectar deepfake","what is a deepfake"],"r":["Un **deepfake** es audio o video sintético generado por IA que imita la voz o el rostro de alguien: pasó de curiosidad a herramienta de fraude (estafas de «jefe» pidiendo transferencias, extorsión con videos falsos, noticias inventadas). Señales: parpadeo raro, labios desincronizados, iluminación que no cuadra y manos con dedos extraños. Defensa: verifica por otro canal antes de actuar ante pedidos de dinero, acuerda palabras clave con familia y equipo, y publica menos voz y video tuyos en abierto.","A **deepfake** is AI-generated audio or video imitating someone's voice or face: it went from curiosity to fraud tool (\"boss\" scams requesting transfers, extortion with fake videos, invented news). Tells: odd blinking, lip desync, inconsistent lighting and hands with strange fingers. Defense: verify through another channel before acting on money requests, agree on code words with family and team, and publish less of your voice and face in the open."],"href":"index.html"},
    {"c":"Otro","k":["que es el phishing","correo falso","suplantacion de identidad","enlace malicioso","pagina clonada","what is phishing"],"r":["El **phishing** es la estafa por mensaje: un correo, SMS o chat imita a tu banco, tienda o servicio y te lleva a una página clonada para robar usuario y contraseña. Señales: remitente con dominio casi igual, urgencia artificial, enlaces que apuntan a otro dominio (pasa el cursor antes de hacer click) y «errores de redacción». Nunca entres a tus cuentas desde el enlace del mensaje: escribe la web tú mismo o usa la app oficial. El 2FA convierte credenciales robadas en un problema menor.","**Phishing** is scam-by-message: an email, SMS or chat impersonates your bank, store or service and leads to a cloned page harvesting your credentials. Tells: lookalike sender domain, artificial urgency, links pointing to another domain (hover before clicking) and \"awkward wording\". Never reach your accounts through the message's link: type the site yourself or use the official app. 2FA turns stolen credentials into a minor problem."],"href":"mantenimiento-software.html#alertas"},
    {"c":"Otro","k":["que es el ransomware","secuestro de datos","archivos encriptados virus","rescate de archivos","proteccion ransomware backup","what is ransomware"],"r":["El **ransomware** cifra todos tus archivos y pide rescate por devolverlos: entra por adjuntos, accesos remotos con contraseña débil o vulnerabilidades sin parchear, y se propaga a discos conectados y a la red. Pagar no garantiza nada (y financia el próximo ataque). Tu única defensa seria: **copias de seguridad** automáticas, con una copia DESCONECTADA o en la nube con versiones (el ransomware cifra lo que alcanza a tocar), 2FA en accesos remotos y actualizaciones al día. Ante una infección: desconecta la red, no pagues y restaura desde backup.","**Ransomware** encrypts all your files and demands payment to restore them: it arrives via attachments, remote access with weak passwords or unpatched flaws, and spreads to connected drives and the network. Paying guarantees nothing (and funds the next attack). Your only serious defense: **automatic backups** with one copy DISCONNECTED or versioned in the cloud (ransomware encrypts whatever it can reach), 2FA on remote access and updates applied. On infection: disconnect, do not pay, restore from backup."],"href":"mantenimiento-software.html#alertas"},
    {"c":"Otro","k":["que es el malware","software malicioso","tipos de malware","virus troyano gusano diferencia","sintomas de malware","what is malware"],"r":["**Malware** es el paraguas para todo software malicioso: **virus** (se pega a archivos), **gusano** (se copia solo por la red), **troyano** (se disfraza de app útil), **ransomware** (cifra y cobra), **spyware** (espía) y **rootkits** (se esconden en lo profundo). Los síntomas van de lentitud y ventanas extrañas a cuentas secuestradas. Ante sospecha: desconecta de la red, escanea con un antivirus actualizado (el de Windows basta) y si no remite, copia tus datos y formatea: es más rápido que limpiar a ciegas.","**Malware** is the umbrella for all malicious software: **viruses** (attach to files), **worms** (self-copy over the network), **trojans** (disguise as useful apps), **ransomware** (encrypt and extort), **spyware** (spy) and **rootkits** (hide deep). Symptoms range from slowness and weird pop-ups to hijacked accounts. On suspicion: disconnect from the network, scan with an updated antivirus (Windows' own is fine) and if it persists, copy your data and wipe: faster than cleaning blind."],"href":"mantenimiento-software.html#alertas"},
    {"c":"Otro","k":["contrasena segura","crear contrasena fuerte","frases de contraseña","longitud vs complejidad","reutilizar contrasenas","strong password tips"],"r":["Una contraseña fuerte hoy es **larga y única**, no «compleja»: `mi-perro-se-llama-toby-y-come-2-veces` es más segura que `P@ss2024!` porque la longitud vence a la matemática del hackeo. Reglas: mínimo 14-16 caracteres, una distinta por servicio (las filtraciones reutilizan correos y claves) y nada de datos personales ni patrones. La solución no es la memoria sino un **gestor de contraseñas**: tú recuerdas una sola, él genera y guarda el resto. Revisa si tus claves se filtraron en haveibeenpwned.com.","A strong password today is **long and unique**, not \"complex\": `my-dog-is-called-toby-and-eats-twice` beats `P@ss2024!` because length wins over hacking math. Rules: 14-16 characters minimum, a different one per service (breaches recycle emails and keys) and no personal data or patterns. The answer is not memory but a **password manager**: you remember one, it generates and stores the rest. Check leaked keys at haveibeenpwned.com."],"href":"mantenimiento-software.html#rutina"},
    {"c":"Otro","k":["gestor de contrasenas","password manager","bitwarden 1password","guardar contrasenas seguro","master password","password manager how it works"],"r":["Un **gestor de contraseñas** (Bitwarden, 1Password, KeePassXC) guarda todas tus claves cifradas detrás de una master contraseña: genera claves largas y únicas, las autocompleta SOLO en sitios legítimos (el dominio debe coincidir) y se sincroniza entre tus equipos. Es más seguro que guardarlo solo en el navegador y muchísimo que reutilizar claves o apuntarlas en notas. La master debe ser larga (una frase) y con 2FA activado: si la pierdes, lo pierdes todo; guarda tu kit de emergencia impreso.","A **password manager** (Bitwarden, 1Password, KeePassXC) stores all your keys encrypted behind one master password: it generates long unique passwords, autofills them ONLY on legitimate sites (the domain must match) and syncs across your devices. Safer than browser-only storage and far better than reusing passwords or keeping them in notes. The master must be long (a passphrase) with 2FA enabled: lose it, lose everything; keep an emergency kit printed."],"href":"mantenimiento-software.html#rutina"},
    {"c":"Otro","k":["huella digital navegacion","fingerprinting","rastreo sin cookies","perfil unico navegador","privacidad online","browser fingerprinting"],"r":["La **huella digital** web te identifica sin cookies: combinan tu navegador, resolución, fuentes, GPU, idioma y hábitos en un perfil casi único que te sigue entre sitios aunque borres las cookies. Por eso las apps y webs «gratis» son gratis: tu perfil vale dinero publicitario. Mitigación real: navegadores que bloquean scripts de rastreo (Firefox con protección mejorada, Brave), bloqueadores como uBlock Origin, y asumir que el anonimato total online no existe: decide qué datos vale la pena entregar.","Web **fingerprinting** identifies you without cookies: it combines browser, resolution, fonts, GPU, language and habits into a near-unique profile that follows you across sites even after clearing cookies. That is why \"free\" apps and sites are free: your profile is worth ad money. Real mitigation: browsers that block tracking scripts (Firefox with enhanced protection, Brave), blockers like uBlock Origin, and accepting that total online anonymity does not exist: decide which data is worth giving away."],"href":"index.html"},
    {"c":"Otro","k":["que es una passkey","llaves de acceso","passkeys vs contrasenas","inicio sin contrasena","futuro sin passwords","what is a passkey"],"r":["Una **passkey** (llave de acceso) reemplaza a la contraseña: tu dispositivo genera un par de claves, guarda la privada bajo tu huella o PIN y el sitio solo tiene la pública. No hay nada que teclear ni phishear: el inicio falla si el dominio no es el real y no viaja ningún secreto por la red. Se sincroniza entre tus equipos vía iCloud o Google y se desbloquea con biometría. Cada vez más servicios las ofrecen (Google, Apple, Microsoft, banca): actívalas donde existan, manteniendo una contraseña fuerte como respaldo.","A **passkey** replaces the password: your device generates a key pair, keeps the private one behind your fingerprint or PIN and the site only holds the public one. Nothing to type or phish: sign-in fails on the wrong domain and no secret travels the network. They sync across your devices via iCloud or Google and unlock with biometrics. More services offer them every month (Google, Apple, Microsoft, banking): enable them where available, keeping a strong password as backup."],"href":"mantenimiento-software.html#rutina"},
    {"c":"Otro","k":["visor pc 3d","como usar el visor 3d","explorar la pc en 3d","pc3d","despiece 3d computadora","3d pc viewer how to use"],"r":["El **Visor PC 3D** del sitio te deja explorar el interior de una computadora en tres dimensiones: gira la escena, acércate a cada pieza y hazle click para ver qué hace y cómo se conecta con las demás. Puedes **desarmar** el equipo pieza por pieza con el control de despiece, activar las etiquetas de componentes y ponerlo a pantalla completa para presentaciones. Es la forma más didáctica de entender la placa, el CPU, la RAM y la fuente antes de abrir una real.","The site's **3D PC Viewer** lets you explore the inside of a computer in three dimensions: rotate the scene, zoom into each part and click it to learn what it does and how it connects to the rest. You can **disassemble** the machine piece by piece with the explode control, toggle component labels and go fullscreen for presentations. It is the most didactic way to understand the board, CPU, RAM and PSU before opening a real one."],"href":"pc3d.html#visor-3d"},
    { c: 'Hardware', k: ['que es el apu', 'apu amd', 'procesador con graficos integrados apu'], r: ['Una APU es un procesador que integra la CPU y la GPU en el mismo chip, por lo que no necesita tarjeta gráfica dedicada para dar video. Es ideal para equipos básicos, ofimática y juegos ligeros, pero rinde menos que una gráfica dedicada en juegos exigentes.', 'An APU is a processor that integrates the CPU and GPU on the same chip, so it needs no dedicated graphics card to display video. It suits basic PCs, office work and light gaming, but performs worse than a dedicated GPU in demanding games.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['que es el monitor curvo', 'monitor curvo', 'monitor curvo vale la pena'], r: ['Un monitor curvo tiene la pantalla ligeramente doblada hacia el usuario para que los bordes queden a la misma distancia que el centro. Esto da una sensación más envolvente y reduce la fatiga visual, sobre todo en pantallas grandes y ultrawide.', 'A curved monitor has its screen slightly bent toward the user so the edges sit at the same distance as the center. This feels more immersive and reduces eye strain, especially on large and ultrawide screens.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['que es el monitor ultrawide', 'monitor ultrawide', 'monitor 21 9'], r: ['Un monitor ultrawide es más ancho que uno normal, con proporción 21:9 en lugar de 16:9, y equivale a tener dos pantallas juntas sin el marco del medio. Es útil para multitarea, edición de video y juegos, aunque algunos juegos viejos no aprovechan todo el ancho.', 'An ultrawide monitor is wider than a normal one, with a 21:9 aspect ratio instead of 16:9, like having two screens side by side without the middle bezel. It helps multitasking, video editing and gaming, although some older games do not use the full width.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['como aplicar pasta termica', 'aplicar pasta termica', 'cuanta pasta termica poner'], r: ['Para aplicar pasta térmica limpia el procesador y el disipador, pon una gota del tamaño de un guisante en el centro del chip y presiona el disipador encima para que se reparta sola. No pongas demasiada ni la extiendas con los dedos, porque el exceso puede salir por los bordes y empeorar el contacto.', 'To apply thermal paste, clean the processor and the heatsink, place a pea-sized drop in the center of the chip, and press the heatsink down so it spreads by itself. Do not use too much or spread it with your fingers, because excess paste can leak out the edges and worsen contact.'], href: 'pc3d.html#mantenimiento' },
    { c: 'Hardware', k: ['switches del teclado mecanico', 'switch lineal tactil clicky', 'tipos de switch teclado'], r: ['Los switches son los interruptores bajo cada tecla de un teclado mecánico y hay tres tipos principales: lineales, que bajan suaves; táctiles, con un pequeño tope al pulsar; y clicky, que además hacen un clic sonoro. Los lineales se prefieren para jugar y los táctiles o clicky para escribir, aunque es cuestión de gusto.', 'Switches are the mechanisms under each key of a mechanical keyboard, and there are three main types: linear, which press down smoothly; tactile, with a small bump when pressed; and clicky, which also make an audible click. Linear switches are preferred for gaming and tactile or clicky ones for typing, although it is a matter of taste.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['sensor optico vs laser', 'sensor del mouse', 'mouse laser vs optico'], r: ['El sensor óptico usa luz LED o infrarroja y funciona mejor sobre alfombrillas, mientras el sensor láser lee casi cualquier superficie pero puede acelerar de forma irregular. Para jugar, el sensor óptico suele ser más preciso y predecible.', 'An optical sensor uses LED or infrared light and works best on mouse pads, while a laser sensor reads almost any surface but can accelerate unevenly. For gaming, the optical sensor is usually more accurate and predictable.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['supresor de picos para pc', 'supresor de picos', 'protector contra picos pc'], r: ['Un supresor de picos es una regleta o dispositivo que absorbe los aumentos bruscos de voltaje y protege el PC de rayos y fallas de la red eléctrica. No es lo mismo que un UPS: el supresor no da energía cuando se va la luz, solo protege contra picos.', 'A surge protector is a power strip or device that absorbs sudden voltage spikes and protects the PC from lightning and power grid faults. It is not the same as a UPS: the protector gives no power during an outage, it only guards against spikes.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['que es el vrm', 'vrm placa base', 'fases vrm placa'], r: ['El VRM es el circuito de la placa base que convierte los 12 V de la fuente en el voltaje bajo y estable que necesita el procesador. Un VRM con más fases y disipadores entrega energía más limpia y se calienta menos, algo clave para procesadores potentes o con overclock.', 'The VRM is the motherboard circuit that converts the 12 V from the power supply into the low, stable voltage the processor needs. A VRM with more phases and heatsinks delivers cleaner power and runs cooler, which matters for powerful or overclocked processors.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['ranura pcie x1', 'pcie x1 para que sirve', 'para que sirve el pcie x1'], r: ['La ranura PCIe x1 es la más pequeña de la placa base y sirve para tarjetas que necesitan poco ancho de banda, como tarjetas de sonido, de red WiFi o adaptadores USB. Las tarjetas x1 también encajan en ranuras más grandes como x4, x8 o x16.', 'The PCIe x1 slot is the smallest on the motherboard and fits cards that need little bandwidth, such as sound cards, WiFi cards or USB adapters. An x1 card also fits in larger x4, x8 or x16 slots.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['cuanta memoria ram necesito', 'cuanta ram para jugar', '8 o 16 gb ram'], r: ['Para ofimática y navegación bastan 8 GB de RAM, para jugar y trabajar con varias apps a la vez lo recomendable hoy es 16 GB, y para edición de video o máquinas virtuales conviene 32 GB o más. Si la RAM se llena, el PC usa el disco como apoyo y todo se vuelve más lento.', 'For office work and browsing, 8 GB of RAM is enough; for gaming and running several apps at once, 16 GB is the recommended amount today, and for video editing or virtual machines 32 GB or more is better. If RAM fills up, the PC uses the disk as backup and everything slows down.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['polling rate del mouse', 'polling rate mouse', 'tasa de sondeo mouse'], r: ['El polling rate es cuántas veces por segundo el mouse informa su posición al PC: a 1000 Hz lo hace cada milisegundo y el cursor responde más fluido. Un valor alto ayuda en juegos rápidos, pero gasta más batería en un mouse inalámbrico.', 'Polling rate is how many times per second the mouse reports its position to the PC: at 1000 Hz it reports every millisecond and the cursor feels smoother. A high value helps in fast games, but it drains the battery faster on a wireless mouse.'], href: 'hardware.html#componentes' },
    { c: 'Hardware', k: ['que es un dac', 'dac para pc', 'dac audio pc'], r: ['Un DAC es un convertidor que transforma el audio digital del PC en señal analógica para los audífonos o altavoces, y todos los equipos ya tienen uno integrado. Un DAC externo mejora la calidad del sonido y evita el ruido eléctrico que se cuela en la salida de audio de la placa base.', 'A DAC is a converter that turns the digital audio from the PC into an analog signal for headphones or speakers, and every computer already has one built in. An external DAC improves sound quality and avoids the electrical noise that leaks into the motherboard audio output.'], href: 'hardware.html#componentes' },
    { c: 'Redes', k: ['como calcular subredes paso a paso', 'calcular hosts de una subred', 'formula para calcular subredes'], r: ['Para calcular una subred toma la direccion de red y la mascara, por ejemplo 192.168.1.0/26 da 4 subredes de 62 hosts utiles cada una, porque 2 bits prestados crean 4 redes y quedan 6 bits de host. El primer host es la red mas 1, el ultimo es el broadcast menos 1, y el broadcast es la ultima direccion del rango.', 'To calculate a subnet take the network address and the mask: for example, 192.168.1.0/26 gives 4 subnets of 62 usable hosts each, because 2 borrowed bits create 4 networks and 6 host bits remain. The first host is the network plus 1, the last is the broadcast minus 1, and the broadcast is the last address in the range.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['mascara de subred 255.255.255.192', 'que significa la mascara /26', 'mascara /26 cuantos hosts permite'], r: ['La mascara 255.255.255.192 equivale a /26: los primeros 26 bits son de red y quedan 6 bits de host, lo que da 64 direcciones en total y 62 hosts utiles, porque se restan la direccion de red y la de broadcast. Es una mascara comun para dividir una red /24 en 4 subredes iguales.', 'The mask 255.255.255.192 equals /26: the first 26 bits are network and 6 host bits remain, giving 64 addresses in total and 62 usable hosts, because the network and broadcast addresses are excluded. It is a common mask to split a /24 network into 4 equal subnets.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['diferencia entre nat y pat', 'nat vs pat que cambia', 'pat sobrecarga de puertos'], r: ['NAT traduce una direccion IP privada a una publica, mientras que PAT, tambien llamada sobrecarga de NAT, traduce ademas el puerto, asi muchos equipos comparten una sola IP publica con puertos distintos. En casa el router usa PAT: cada conexion sale con la misma IP publica pero con un puerto de origen diferente.', 'NAT translates a private IP address to a public one, while PAT, also called NAT overload, also translates the port, so many devices share a single public IP using different ports. At home the router uses PAT: every connection leaves with the same public IP but a different source port.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['dns recursivo como funciona', 'consulta dns recursiva paso a paso', 'servidor dns recursivo vs autoritativo'], r: ['En una consulta recursiva tu equipo pregunta a un servidor DNS y ese servidor hace todo el trabajo: consulta la raiz, luego el dominio de nivel superior y luego el servidor autoritativo, hasta devolverte la IP final. El servidor autoritativo es el que guarda los registros oficiales de un dominio, mientras el recursivo solo busca la respuesta por ti y la guarda en cache.', 'In a recursive query your device asks a DNS server and that server does all the work: it queries the root, then the top-level domain, then the authoritative server, until it returns the final IP. The authoritative server holds the official records of a domain, while the recursive one only looks up the answer for you and caches it.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['como crear una reserva dhcp en el router', 'reserva dhcp por direccion mac', 'configurar reserva dhcp paso a paso'], r: ['Para crear una reserva DHCP entra al panel del router, busca la seccion de DHCP o LAN, y asocia la direccion MAC del equipo con la IP que quieres que siempre reciba. Asi el equipo sigue usando DHCP, pero el servidor le entrega siempre la misma IP, ideal para impresoras o servidores caseros.', 'To create a DHCP reservation open the router panel, find the DHCP or LAN section, and bind the device MAC address to the IP you want it to always receive. The device keeps using DHCP, but the server always hands it the same IP, which is ideal for printers or home servers.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['puerto 53 para que sirve', 'puerto 25 smtp para que sirve', 'puerto 110 y 143 correo'], r: ['El puerto 53 es el de DNS y traduce nombres de dominio a direcciones IP, el 25 es SMTP para enviar correo entre servidores, y el 110 (POP3) y el 143 (IMAP) son para recibir correo. Si el puerto 53 esta bloqueado, el navegador no resuelve ningun nombre y parece que no hay internet aunque la conexion funcione.', 'Port 53 is DNS and translates domain names into IP addresses, port 25 is SMTP for sending mail between servers, and ports 110 (POP3) and 143 (IMAP) are for receiving mail. If port 53 is blocked, the browser cannot resolve any name and it looks like there is no internet even though the connection works.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['como crear una regla en el firewall', 'reglas de firewall permitir o bloquear', 'firewall de entrada y salida diferencia'], r: ['Una regla de firewall define si se permite o se bloquea un trafico segun su origen, destino, puerto y protocolo; por ejemplo, permitir el puerto 443 entrante solo a un servidor web. Las reglas de entrada controlan lo que llega a tu equipo y las de salida lo que sale de el, y por defecto se suele bloquear la entrada y permitir la salida.', 'A firewall rule defines whether traffic is allowed or blocked based on its source, destination, port and protocol; for example, allowing inbound port 443 only to a web server. Inbound rules control what reaches your device and outbound rules control what leaves it, and by default inbound is usually blocked while outbound is allowed.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['cuando usar cable cruzado hoy en dia', 'cable cruzado entre dos pc sin switch', 'auto mdix cable cruzado ya no hace falta'], r: ['El cable cruzado conecta dos equipos directamente sin switch, porque cruza los pines de envio y recepcion para que ambos puedan hablarse. Hoy casi no hace falta, porque la mayoria de tarjetas de red y switches tienen Auto-MDIX y detectan solos si deben cruzar la senal, asi que un cable directo suele funcionar igual.', 'A crossover cable connects two devices directly without a switch, because it swaps the transmit and receive pins so both can talk to each other. Today it is rarely needed, because most network cards and switches have Auto-MDIX and detect on their own whether to cross the signal, so a straight cable usually works the same.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['ventajas de la fibra optica sobre el cobre', 'fibra optica inmunidad interferencias', 'distancia maxima fibra vs cobre ethernet'], r: ['La fibra optica usa luz en vez de electricidad, asi que no sufre interferencias electromagneticas, alcanza distancias mucho mayores y soporta mas velocidad que el cobre. El cobre Ethernet llega a unos 100 metros por tramo, mientras la fibra multimodo supera los 500 metros y la monomodo llega a kilometros.', 'Fiber optics uses light instead of electricity, so it suffers no electromagnetic interference, reaches much longer distances and supports higher speeds than copper. Copper Ethernet reaches about 100 meters per run, while multimode fiber exceeds 500 meters and single-mode fiber reaches kilometers.'], href: 'redes.html#alcance-redes' },
    { c: 'Redes', k: ['que hace cada capa del modelo osi', 'capa de transporte osi que hace', 'capa de aplicacion osi ejemplos'], r: ['El modelo OSI tiene 7 capas: fisica transmite bits, enlace mueve tramas en la red local, red enruta paquetes con IP, transporte entrega datos con TCP o UDP, sesion gestiona la conexion, presentacion traduce y cifra los datos, y aplicacion ofrece los servicios que usan los programas, como HTTP o DNS. Cuando algo falla, ubicar la capa ayuda a saber si es el cable, la IP o la aplicacion.', 'The OSI model has 7 layers: physical transmits bits, data link moves frames on the local network, network routes packets with IP, transport delivers data with TCP or UDP, session manages the connection, presentation translates and encrypts data, and application provides the services programs use, like HTTP or DNS. When something fails, finding the layer helps tell whether it is the cable, the IP or the application.'], href: 'redes.html#redes' },
    { c: 'Redes', k: ['diferencia entre latencia y jitter', 'latencia vs jitter en videojuegos', 'jitter alto que causa en llamadas'], r: ['La latencia es el tiempo que tarda un paquete en ir y volver, mientras el jitter es cuanto varia esa latencia entre un paquete y otro. Puedes tener latencia baja con jitter alto, y eso se nota en llamadas y videojuegos con voz entrecortada y movimientos a tirones.', 'Latency is the time a packet takes to go and return, while jitter is how much that latency varies from one packet to the next. You can have low latency with high jitter, and that shows up in calls and games as choppy voice and jerky movement.'], href: 'redes.html#simulador-red' },
    { c: 'Redes', k: ['como usar tracert en windows', 'tracert para diagnosticar internet lento', 'interpretar resultados de tracert'], r: ['En Windows abre el simbolo del sistema y escribe tracert seguido de una direccion, por ejemplo tracert 8.8.8.8, para ver cada salto que recorre el paquete hasta su destino con su tiempo de respuesta. Si un salto muestra tiempos muy altos o asteriscos de perdida, el problema esta en ese tramo o en ese router, y a partir de ahi ya no es tu red local.', 'On Windows open the command prompt and type tracert followed by an address, for example tracert 8.8.8.8, to see every hop the packet takes to its destination with its response time. If a hop shows very high times or asterisks for loss, the problem is in that stretch or that router, and from there on it is no longer your local network.'], href: 'redes.html#simulador-red' },
    { c: 'Recursos', k: ['glosario por categorias', 'filtrar glosario por tema', 'terminos de redes glosario'], r: ['En el Glosario de la página de Recursos puedes filtrar los términos por tema, por ejemplo redes o hardware, para estudiar solo lo que necesitas. Así encuentras más rápido cada definición sin recorrer toda la lista.', 'In the Glossary on the Recursos page you can filter terms by topic, such as networking or hardware, to study only what you need. That way you find each definition faster without scrolling through the whole list.'], href: 'recursos.html#glosario' },
    { c: 'Recursos', k: ['para que sirve el glosario', 'que es el glosario', 'donde esta el glosario'], r: ['El Glosario de la página de Recursos reúne las definiciones de los términos de hardware y redes que se usan en el sitio, como CPU, RAM o dirección IP. Sirve para consultar rápido un término cuando no recuerdas qué significa.', 'The Glossary on the Recursos page gathers definitions of the hardware and networking terms used on the site, such as CPU, RAM or IP address. It is useful for quickly looking up a term when you do not remember what it means.'], href: 'recursos.html#glosario' },
    { c: 'Recursos', k: ['repasar con el glosario', 'estudiar con tarjetas', 'modo estudio glosario'], r: ['El modo estudio del Glosario muestra los términos como tarjetas: primero ves el término y tratas de recordar su significado antes de voltear la tarjeta. Puedes mezclar las tarjetas para repasar en orden aleatorio y ponerte a prueba.', 'The Glossary study mode shows terms as flashcards: first you see the term and try to recall its meaning before flipping the card. You can shuffle the cards to review in random order and test yourself.'], href: 'recursos.html#glosario' },
    { c: 'Recursos', k: ['ipconfig release', 'liberar ip', 'liberar direccion ip'], r: ['El comando ipconfig /release libera la dirección IP que tu equipo recibió del router, y se usa junto con ipconfig /renew para pedir una nueva. Escríbelo en el Símbolo del sistema cuando tu red da problemas de IP.', 'The ipconfig /release command releases the IP address your computer got from the router, and it is used together with ipconfig /renew to request a new one. Type it in the Command Prompt when your network has IP problems.'], href: 'recursos.html#laboratorio' },
    { c: 'Recursos', k: ['netstat', 'conexiones activas netstat', 'ver conexiones de mi pc'], r: ['El comando netstat muestra las conexiones activas de tu equipo, con la dirección remota y el puerto de cada una. Escríbelo en el Símbolo del sistema para ver qué programas están conectados a la red.', 'The netstat command shows your computer’s active connections, with the remote address and port of each one. Type it in the Command Prompt to see which programs are connected to the network.'], href: 'recursos.html#laboratorio' },
    { c: 'Recursos', k: ['nslookup', 'consultar dns nslookup', 'ver ip de un dominio'], r: ['El comando nslookup consulta un servidor DNS para saber la dirección IP de un dominio, por ejemplo nslookup google.com. Sirve para comprobar si un problema es de DNS cuando una página no abre.', 'The nslookup command queries a DNS server to find the IP address of a domain, for example nslookup google.com. It helps you check whether a problem is DNS-related when a page does not load.'], href: 'recursos.html#laboratorio' },
    { c: 'Recursos', k: ['getmac', 'direccion mac con comando', 'ver mac con comando'], r: ['El comando getmac muestra la dirección MAC de las tarjetas de red de tu equipo sin abrir menús. Escríbelo en el Símbolo del sistema y copia la dirección física que aparece.', 'The getmac command shows the MAC address of your computer’s network cards without opening menus. Type it in the Command Prompt and copy the physical address shown.'], href: 'recursos.html#laboratorio' },
    { c: 'Recursos', k: ['systeminfo', 'informacion del sistema comando', 'ver datos completos de mi pc'], r: ['El comando systeminfo muestra los datos completos de tu equipo: versión de Windows, procesador, memoria RAM instalada y fecha de instalación. Escríbelo en el Símbolo del sistema cuando necesites conocer las características de tu PC.', 'The systeminfo command shows your computer’s full details: Windows version, processor, installed RAM and installation date. Type it in the Command Prompt when you need to know your PC’s specifications.'], href: 'recursos.html#laboratorio' },
    { c: 'Recursos', k: ['cuanta ram tengo', 'ver ram instalada', 'memoria ram instalada'], r: ['Para ver cuánta RAM tiene tu equipo, abre el Administrador de tareas con Ctrl + Shift + Esc, ve a Rendimiento y luego a Memoria. Ahí verás la RAM instalada, la que está en uso y la velocidad.', 'To see how much RAM your computer has, open Task Manager with Ctrl + Shift + Esc, go to Performance and then Memory. There you will see the installed RAM, how much is in use and its speed.'], href: 'recursos.html#laboratorio' },
    { c: 'Recursos', k: ['netsh wlan show profiles', 'perfiles wifi guardados', 'ver redes wifi guardadas'], r: ['El comando netsh wlan show profiles muestra las redes WiFi guardadas en tu equipo. Escríbelo en el Símbolo del sistema para ver a qué redes te has conectado antes.', 'The netsh wlan show profiles command shows the WiFi networks saved on your computer. Type it in the Command Prompt to see which networks you have connected to before.'], href: 'recursos.html#laboratorio' },
    { c: 'Otro', k: ['que es la regla 3 2 1 de copias de seguridad', 'regla tres dos uno para respaldos', 'copias en tres lugares distintos'], r: ['La regla 3-2-1 dice: guarda 3 copias de tus archivos, en 2 tipos de almacenamiento distintos, y 1 copia fuera de casa o en la nube.', 'The 3-2-1 rule says: keep 3 copies of your files, on 2 different types of storage, and 1 copy off-site or in the cloud.'], href: 'mantenimiento-software.html#rutina' },
    { c: 'Otro', k: ['crear un punto de restauracion antes de instalar algo', 'restaurar el sistema a un punto anterior', 'punto de restauracion para deshacer cambios'], r: ['Antes de instalar un programa o un driver, crea un punto de restauración en Windows para poder deshacer los cambios si algo falla.', 'Before installing a program or a driver, create a restore point in Windows so you can undo the changes if something goes wrong.'], href: 'mantenimiento-software.html#paso-a-paso' },
    { c: 'Otro', k: ['actualizar drivers desde la pagina del fabricante', 'descargar drivers solo del fabricante', 'drivers oficiales sin programas de terceros'], r: ['Descarga los drivers solo desde la página oficial del fabricante de tu PC o del componente, nunca desde programas que prometen actualizarlos todos solos.', 'Download drivers only from the official website of your PC or component maker, never from programs that promise to update them all by themselves.'], href: 'mantenimiento-software.html#programas' },
    { c: 'Otro', k: ['desinstalar programas que no uso', 'quitar programas que vienen preinstalados', 'eliminar bloatware de mi pc'], r: ['Desinstala los programas que no usas y el bloatware preinstalado desde Configuración, Aplicaciones: liberas espacio, reduces el inicio lento y cierras posibles riesgos.', 'Uninstall programs you do not use and preinstalled bloatware from Settings, Apps: you free space, reduce slow startup and close possible risks.'], href: 'mantenimiento-software.html#programas' },
    { c: 'Otro', k: ['phishing por sms o whatsapp', 'smishing mensajes falsos por sms', 'me llego un mensaje sospechoso por whatsapp'], r: ['El smishing es phishing por SMS o WhatsApp: mensajes urgentes con enlaces falsos que roban tus datos. No pulses el enlace y verifica siempre por el canal oficial.', 'Smishing is phishing by SMS or WhatsApp: urgent messages with fake links that steal your data. Do not tap the link and always verify through the official channel.'], href: 'mantenimiento-software.html#alertas' },
    { c: 'Otro', k: ['verificacion en dos pasos con app autenticadora', 'activar el segundo factor con aplicacion autenticadora', 'codigos de autenticador en vez de sms'], r: ['Activa la verificación en dos pasos con una app autenticadora, que genera códigos temporales en tu móvil y es más segura que recibirlos por SMS.', 'Turn on two-step verification with an authenticator app, which generates temporary codes on your phone and is safer than receiving them by SMS.'], href: 'mantenimiento-software.html#rutina' },
    { c: 'Otro', k: ['que hacer si me roban la cuenta', 'recuperar una cuenta robada', 'me hackearon la cuenta que hago'], r: ['Si te roban una cuenta, cambia la contraseña desde el sitio oficial, revisa el correo y el teléfono de recuperación, activa la verificación en dos pasos y avisa a tus contactos.', 'If an account is stolen, change the password from the official site, check the recovery email and phone, turn on two-step verification and warn your contacts.'], href: 'mantenimiento-software.html#alertas' },
    { c: 'Otro', k: ['programas que se abren al iniciar windows', 'windows tarda mucho en arrancar', 'desactivar programas de inicio lento'], r: ['Si Windows tarda en arrancar, abre el Administrador de tareas, pestaña Inicio, y desactiva los programas que no necesitas al encender el PC.', 'If Windows takes long to start, open Task Manager, go to the Startup tab, and disable the programs you do not need when the PC turns on.'], href: 'mantenimiento-software.html#rutina' },
    { c: 'WiFi', k: ['que es mlo wifi 7', 'multi link operation wifi', 'wifi 7 conexiones simultaneas', 'mlo varias bandas a la vez'], r: ['MLO (Multi-Link Operation) es la gran novedad de WiFi 7: el dispositivo se conecta al router por varias bandas a la vez (2.4, 5 y 6 GHz) en lugar de usar solo una. Así suma velocidad, baja la latencia y si una banda se satura, el tráfico pasa a otra sin cortar la conexión.', 'MLO (Multi-Link Operation) is the big new feature of WiFi 7: the device connects to the router over several bands at once (2.4, 5 and 6 GHz) instead of using only one. That adds speed, lowers latency, and if one band gets congested, traffic moves to another without dropping the connection.'], href: 'wifi.html' },
    { c: 'WiFi', k: ['canal 320 mhz wifi 7', 'que es 4k qam wifi', 'wifi 7 320 mhz 4k qam', 'canales mas anchos wifi 7'], r: ['WiFi 7 duplica el ancho de canal hasta 320 MHz y usa modulación 4K-QAM, que mete más datos en cada transmisión que el 1024-QAM de WiFi 6. En la práctica, eso da más velocidad máxima, pero solo se nota cerca del router y con dispositivos WiFi 7.', 'WiFi 7 doubles channel width up to 320 MHz and uses 4K-QAM modulation, which packs more data into each transmission than the 1024-QAM of WiFi 6. In practice, that gives higher top speed, but you only notice it close to the router and with WiFi 7 devices.'], href: 'wifi.html' },
    { c: 'WiFi', k: ['control parental wifi router', 'limitar internet hijos router', 'horario wifi para niños', 'bloquear paginas router'], r: ['El control parental del router permite poner horarios de internet por dispositivo, bloquear páginas y pausar el WiFi de un equipo desde la app o el panel del router. Es más eficaz que hacerlo en cada celular, porque se aplica a toda la red de la casa.', 'The parental controls on your router let you set internet schedules per device, block websites, and pause WiFi on a device from the router app or admin panel. It works better than setting it on each phone, because it applies to the whole home network.'], href: 'wifi.html' },
    { c: 'WiFi', k: ['alguien roba mi wifi', 'como saber si me roban wifi', 'detectar intrusos en mi wifi', 'vecino conectado a mi wifi'], r: ['Para saber si alguien usa tu WiFi, revisa la lista de dispositivos conectados en el panel o la app del router y busca equipos que no reconozcas. Si encuentras un intruso, cambia la clave por una larga con WPA3, desactiva WPS y expulsa el dispositivo desconocido.', 'To check if someone is using your WiFi, look at the list of connected devices in the router panel or app and look for devices you do not recognize. If you find an intruder, change the password to a long one with WPA3, turn off WPS, and remove the unknown device.'], href: 'wifi.html' },
    { c: 'WiFi', k: ['wifi publico es seguro', 'usar wifi gratis con seguridad', 'vpn en wifi publico', 'peligros wifi publico'], r: ['El WiFi público no es seguro por sí solo: cualquiera en la misma red puede espiar el tráfico sin cifrar, por eso nunca hagas pagos ni entres al banco en una red abierta. Usa una VPN, verifica que las páginas tengan HTTPS y desactiva el uso compartido de archivos mientras estés conectado.', 'Public WiFi is not safe by itself: anyone on the same network can spy on unencrypted traffic, so never make payments or log into your bank on an open network. Use a VPN, check that websites use HTTPS, and turn off file sharing while you are connected.'], href: 'wifi.html' },
    { c: 'WiFi', k: ['compartir wifi con codigo qr', 'qr para compartir wifi', 'generar qr de mi wifi', 'pasar clave wifi con qr'], r: ['Puedes compartir tu WiFi con un código QR sin dictar la clave: en Android está en Ajustes, WiFi, tocar la red y Compartir; en iPhone se genera desde Atajos o con la app del router. Quien escanea el código se conecta al instante, sin escribir la contraseña.', 'You can share your WiFi with a QR code without saying the password out loud: on Android go to Settings, WiFi, tap the network and Share; on iPhone, generate it from Shortcuts or with the router app. Anyone who scans the code connects instantly, without typing the password.'], href: 'wifi.html' },
    { c: 'Redes Challenge', k: ['como entrar a una sala del modo kahoot', 'entrar a una sala kahoot redes challenge', 'como unirse a una partida kahoot', 'sala cerrada no puedo entrar al juego'], r: ['Para entrar a una sala del modo Kahoot, el admin primero debe abrir la sala; sin sala abierta el botón Iniciar juego queda bloqueado. Luego escribes tu nombre y apellido y entras a esperar el Start del admin con la cuenta regresiva 5-4-3-2-1.', 'To join a Kahoot mode room, the admin must open the room first; without an open room the Start game button stays locked. Then you type your first and last name and wait for the admin to press Start with the 5-4-3-2-1 countdown.'], href: 'redes_challenge/index.html' },
    { c: 'Redes Challenge', k: ['como se calculan los puntos por rapidez en redes challenge', 'puntos por rapidez redes challenge', 'cuantos puntos da responder rapido', 'bonus por rapidez en el juego kahoot'], r: ['Cada respuesta correcta vale 10 puntos base, más un bonus de hasta 5 puntos según lo rápido que respondas dentro de los 20 segundos por pregunta. El máximo es 15 puntos por pregunta y 150 en total, y el TOP 5 se actualiza en vivo.', 'Each correct answer is worth 10 base points, plus a bonus of up to 5 points depending on how fast you answer within the 20 seconds per question. The maximum is 15 points per question and 150 in total, and the live TOP 5 updates in real time.'], href: 'redes_challenge/index.html' },
  ];
  const SUGGEST = [
    ['¿Qué es la RAM?', 'What is RAM?'],
    ['¿Cómo trabaja un switch?', 'How does a switch work?'],
    ['¿Cómo veo mi IP y mi MAC?', 'How do I see my IP and MAC?'],
    ['Instalar un repetidor WiFi', 'Set up a WiFi repeater'],
    ['¿Qué es throughput?', 'What is throughput?'],
    ['¿Cómo limpio mi PC?', 'How do I clean my PC?'],
    ['¿Hub o switch?', 'Hub or switch?'],
    ['¿Por qué no abre 192.168.1.1?', 'Why does 192.168.1.1 not open?'],
    ['¿Qué es el mantenimiento por software?', 'What is software maintenance?'],
    ['Mi PC no enciende, ¿qué hago?', 'My PC will not turn on, what do I do?']
  ];
  const CATS = ['Hardware', 'Redes', 'WiFi', 'Recursos', 'Redes Challenge', 'Otro'];

  /* ===== Persistencia (lo enseñado y lo no respondido vive en este navegador) ===== */
  const loadArr = (k, d) => { try { const v = JSON.parse(localStorage.getItem(k)); return Array.isArray(v) ? v : d; } catch (e) { return d; } };
  const storeArr = (k, v) => { try { localStorage.setItem(k, JSON.stringify(v)); } catch (e) {} };
  let learned = loadArr('nvision_bot_learned', []);
  let missed = loadArr('nvision_bot_missed', []);
  let editIdx = -1;

  /* ===== Motor de coincidencia (mismo modelo que FinBot) ===== */
  const STOP = new Set('de la el los las un una unos unas y o u que en es por para con como se mi mis me a al del lo su sus te tu yo si no mas muy cual cuales cuanto quien cuando donde quiero puedo debo hay ser son esta este eso esa the a an of to in is are what how do does can i you it and or for on with my me hacer debe deben'.split(' '));
  const norm = (s) => (s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9\s]/g, ' ');
  const stem = (w) => (w.length > 5 ? w.slice(0, 5) : w);
  const toks = (s) => [...new Set(norm(s).split(/\s+/).filter((w) => w && !STOP.has(w)).map(stem))];
  function bestMatch(q) {
    const qt = toks(q);
    let top = { score: 0, e: null, key: '' };
    if (!qt.length) return top;
    const all = [...learned.map((e) => ({ c: e.c, k: e.k, r: [e.r, e.r], href: null })), ...KB];
    for (const e of all) for (const key of e.k) {
      const kt = toks(key);
      if (!kt.length) continue;
      const inter = kt.filter((w) => qt.includes(w)).length;
      if (!inter) continue;
      const score = (inter / kt.length + inter / qt.length) / 2;
      if (score > top.score + 1e-9) top = { score, e, key };
    }
    return top;
  }

  /* ===== Contexto de conversación: seguir hablando del tema ===== */
  /* Antes el chatbot no tenía memoria: cada pregunta se respondía sola y
     "¿qué más?" no tenía tokens (STOP lo vaciaba) y caía en el fallback.
     Ahora guarda el último tema respondido y las fichas ya mostradas. */
  let lastTopic = null; // { e, key, c }
  let shownKeys = new Set();
  let shownKeyToks = new Set(); // tokens de k[0] ya mostrados: evita repetir casi la misma ficha (ej. dos de dual channel)
  const FOLLOWUPS = new Set(['que mas', 'y que mas', 'dime mas', 'cuentame mas', 'sigue', 'continua', 'y eso', 'y de eso', 'algo mas', 'que mas hay', 'hay mas', 'y luego', 'y despues', 'mas', 'mas detalles', 'detalles', 'dame un ejemplo', 'un ejemplo', 'y un ejemplo', 'explicame mas', 'profundiza', 'what else', 'tell me more', 'more', 'go on', 'continue', 'more details', 'give me an example', 'an example', 'and then', 'tell me more about it', 'what about that']);
  const isPureFollowUp = (q) => FOLLOWUPS.has(norm(q).trim().replace(/\s+/g, ' '));
  function relatedEntries(topic) {
    const tk = new Set(toks(topic.key));
    const all = [...learned.map((e) => ({ c: e.c, k: e.k, r: [e.r, e.r], href: null })), ...KB];
    return all
      .filter((e) => e !== topic.e && !shownKeyToks.has(toks(e.k[0]).join(',')))
      .map((e) => {
        let s = 0;
        if (e.c === topic.c) s += 2;
        const kt = new Set();
        e.k.forEach((k) => toks(k).forEach((w) => kt.add(w)));
        tk.forEach((w) => { if (kt.has(w)) s += 1; });
        return { e, s };
      })
      .filter((x) => x.s > 0)
      .sort((a, b) => b.s - a.s);
  }
  function rememberTopic(b) {
    lastTopic = { e: b.e, key: b.key, c: b.e.c };
    shownKeys.add(b.e.k[0]);
    shownKeyToks.add(toks(b.e.k[0]).join(','));
  }
  function askFollowUp(q) {
    if (!lastTopic) {
      say(L() === 1 ? 'First ask me about a topic — for example, "what is RAM?" — and then you can say "what else?" and I will keep going on that topic.' : 'Primero pregúntame de un tema —por ejemplo, "¿qué es la RAM?"— y después me puedes decir "¿qué más?" y sigo hablando de ese tema.', q, null, null);
      return;
    }
    const rel = relatedEntries(lastTopic).filter((x) => !shownKeys.has(x.e.k[0]));
    if (!rel.length) {
      say(L() === 1 ? 'That was the main thing about ' + lastTopic.key + '. Ask me about another topic and I will keep going on that one.' : 'Eso era lo principal de ' + lastTopic.key + '. Pregúntame de otro tema y sigo hablando de ese.', q, null, lastTopic.e.href);
      return;
    }
    const next = rel[0].e;
    shownKeys.add(next.k[0]);
    shownKeyToks.add(toks(next.k[0]).join(','));
    lastTopic = { e: next, key: next.k[0], c: next.c };
    const more = relatedEntries(lastTopic).filter((x) => !shownKeys.has(x.e.k[0])).slice(0, 2);
    let extra = '';
    if (more.length) {
      extra = L() === 1
        ? '\n\nYou can also ask me: «' + more.map((x) => x.e.k[0]).join('», «') + '».'
        : '\n\nTambién puedes preguntarme: «' + more.map((x) => x.e.k[0]).join('», «') + '».';
    }
    say((L() === 1 ? 'Sure, about ' + next.k[0] + ' I can also tell you: ' : 'Claro, sobre ' + next.k[0] + ' también te cuento: ') + next.r[L()] + extra, q, null, next.href);
  }

  /* ===== Construcción del panel ===== */
  const assistant = document.createElement('aside');
  assistant.className = 'local-assistant';
  assistant.innerHTML = `
    <div class="local-assistant-panel" id="local-assistant-panel" hidden>
      <div class="local-assistant-header">
        <div><strong data-i18n="assistant_title">Asistente NVISION</strong><small data-i18n="assistant_status">Chat entrenado</small></div>
        <button class="local-assistant-close" type="button" aria-label="Cerrar" data-i18n-title="assistant_close_title">×</button>
      </div>
      <div class="local-assistant-body">
        <div class="la-tabs" role="tablist">
          <button type="button" class="la-tab is-active" data-tab="chat" data-i18n="assistant_tab_chat">Chat</button>
          <button type="button" class="la-tab" data-tab="train" data-i18n="assistant_tab_train">Entrenar</button>
        </div>
        <div class="la-view la-view-chat">
          <p class="local-assistant-welcome" data-i18n="assistant_welcome">Pregúntame sobre el contenido del sitio. Si no sé algo, puedes enseñármelo en la pestaña Entrenar.</p>
          <div class="la-log" aria-live="polite"></div>
          <div class="la-chips"></div>
          <form class="local-assistant-form">
            <input class="local-assistant-input" type="text" autocomplete="off" maxlength="300" data-i18n-placeholder="assistant_placeholder" placeholder="Escribe tu pregunta…">
            <button class="local-assistant-submit" type="submit" data-i18n-title="assistant_search" title="Enviar" aria-label="Enviar">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m22 2-7 20-4-9-9-4Z"></path><path d="M22 2 11 13"></path></svg>
            </button>
          </form>
        </div>
        <div class="la-view la-view-train" hidden>
          <div class="la-stats"><span><b class="la-n-base">0</b> <span data-i18n="assistant_stats_base">respuestas base</span></span><span><b class="la-n-learn">0</b> <span data-i18n="assistant_stats_learned">enseñadas por ti</span></span></div>
          <div class="la-card">
            <h3 class="la-form-title" data-i18n="assistant_teach_title">Enseñar una respuesta nueva</h3>
            <label data-i18n="assistant_teach_q">Formas de preguntarlo (una por línea)</label>
            <textarea class="la-tk" rows="3" placeholder="qué es un switch&#10;cómo trabaja un switch"></textarea>
            <label data-i18n="assistant_teach_a">Respuesta</label>
            <textarea class="la-tr" rows="3"></textarea>
            <label data-i18n="assistant_teach_cat">Categoría</label>
            <select class="la-tc"></select>
            <div class="la-row">
              <button type="button" class="la-btn la-save" data-i18n="assistant_save">Guardar</button>
              <button type="button" class="la-btn la-alt la-cancel" data-i18n="assistant_cancel_edit" hidden>Cancelar edición</button>
            </div>
            <div class="la-toast" role="status"></div>
          </div>
          <div class="la-card">
            <h3 data-i18n="assistant_test_title">Probar al asistente</h3>
            <input class="la-test" type="text" data-i18n-placeholder="assistant_test_ph" placeholder="Escribe una pregunta para ver qué entiende">
            <div class="la-test-out la-hint"></div>
          </div>
          <div class="la-card"><h3 data-i18n="assistant_missed_title">Preguntas sin respuesta</h3><div class="la-missed"></div></div>
          <div class="la-card"><h3 data-i18n="assistant_learned_title">Lo que le has enseñado</h3><div class="la-learned"></div></div>
          <div class="la-card">
            <h3 data-i18n="assistant_backup_title">Respaldo</h3>
            <textarea class="la-bk" rows="3" placeholder="JSON"></textarea>
            <div class="la-row">
              <button type="button" class="la-btn la-alt la-exp" data-i18n="assistant_export">Exportar</button>
              <button type="button" class="la-btn la-alt la-imp" data-i18n="assistant_import">Importar</button>
              <button type="button" class="la-btn la-alt la-reset" data-i18n="assistant_reset">Borrar lo aprendido</button>
            </div>
          </div>
        </div>
      </div>
    </div>
    <button class="local-assistant-toggle" type="button" aria-controls="local-assistant-panel" aria-expanded="false" title="Abrir asistente" aria-label="Abrir asistente" data-i18n-title="assistant_toggle_title">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M20 11.5a7.5 7.5 0 0 1-8 7.5 8.5 8.5 0 0 1-4-.9L4 19l1.2-3.1A7.4 7.4 0 0 1 4.5 12 7.5 7.5 0 0 1 12 4.5a7.5 7.5 0 0 1 8 7z"></path><path d="M8 11h.01M12 11h.01M16 11h.01"></path></svg>
    </button>`;
  document.body.appendChild(assistant);

  const $ = (sel) => assistant.querySelector(sel);
  const panel = $('.local-assistant-panel');
  const toggle = $('.local-assistant-toggle');
  const closeBtn = $('.local-assistant-close');
  const form = $('.local-assistant-form');
  const input = $('.local-assistant-input');
  const log = $('.la-log');
  const chipsBox = $('.la-chips');
  const L = () => (currentLang === 'en' ? 1 : 0);
  const T = () => translations[currentLang] || translations.es;
  const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
  const fmt = (s) => iconize(esc(s).replace(/\*\*(.+?)\*\*/g, '<b>$1</b>').replace(/\n/g, '<br>'));

  /* ===== Chat ===== */
  function addMsg(role, text, q, href) {
    const d = document.createElement('div');
    d.className = 'la-msg ' + role;
    d.innerHTML = fmt(text);
    if (href) {
      const a = document.createElement('a');
      a.className = 'la-open';
      a.href = href;
      a.textContent = T().assistant_open;
      d.appendChild(a);
    }
    if (role === 'bot' && q) {
      const f = document.createElement('div');
      f.className = 'la-fb';
      const up = document.createElement('button');
      up.type = 'button'; up.innerHTML = ICONS.thumb_up; up.title = T().assistant_up; up.setAttribute('aria-label', T().assistant_up);
      up.addEventListener('click', () => { f.innerHTML = fmt(T().assistant_thanks); });
      const down = document.createElement('button');
      down.type = 'button'; down.innerHTML = ICONS.thumb_down + ' ' + esc(T().assistant_down);
      down.addEventListener('click', () => goTeach(q));
      f.append(up, down);
      d.appendChild(f);
    }
    log.appendChild(d);
    log.scrollTop = log.scrollHeight;
    return d;
  }
  function say(text, q, teachQ, href) {
    setTimeout(() => {
      addMsg('bot', text, q, href);
      if (q && lastTopic) {
        const moreBtn = document.createElement('button');
        moreBtn.type = 'button';
        moreBtn.className = 'la-chip';
        moreBtn.textContent = L() === 1 ? 'What else?' : '¿Qué más?';
        moreBtn.addEventListener('click', () => ask(L() === 1 ? 'What else?' : '¿Qué más?'));
        log.lastChild.appendChild(moreBtn);
      }
      if (teachQ) {
        const b = document.createElement('button');
        b.type = 'button';
        b.className = 'la-chip';
        b.textContent = T().assistant_teach_this;
        b.addEventListener('click', () => goTeach(teachQ));
        log.lastChild.appendChild(b);
      }
    }, 350);
  }
  function ask(text) {
    text = (text || '').trim();
    if (!text) return;
    addMsg('user', text);
    // 1) "¿qué más?" solo: seguir con el último tema
    if (isPureFollowUp(text)) { askFollowUp(text); return; }
    // 2) "¿qué más de X?": quitar el "qué más" y buscar X; si no calza, seguir con el tema
    const nq = norm(text);
    if (nq.startsWith('que mas ') || nq.startsWith('what else ')) {
      const rest = text.replace(/^[¿\s]*qu[eé]\s*m[aá]s\s*/i, '').replace(/^what else\s*/i, '');
      const br = rest ? bestMatch(rest) : { score: 0 };
      if (br.score >= 0.4) { rememberTopic(br); say(br.e.r[L()], text, null, br.e.href); return; }
      askFollowUp(text); return;
    }
    // 3) "¿y eso cómo funciona / para qué sirve?": completar con el último tema
    if (lastTopic && /\b(eso|esto|ello|esa|ese|esta|este|that|this|it)\b/.test(nq) && toks(text).length <= 4) {
      const ba = bestMatch(text + ' ' + lastTopic.key);
      if (ba.score >= 0.4) { rememberTopic(ba); say(ba.e.r[L()], text, null, ba.e.href); return; }
    }
    const b = bestMatch(text);
    if (b.score >= 0.4) { rememberTopic(b); say(b.e.r[L()], text, null, b.e.href); return; }
    if (!missed.includes(text)) {
      missed.unshift(text);
      missed = missed.slice(0, 30);
      storeArr('nvision_bot_missed', missed);
    }
    say(T().assistant_fallback, null, text, null);
  }
  function renderChips() {
    chipsBox.replaceChildren();
    SUGGEST.forEach((pair) => {
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'la-chip';
      b.textContent = pair[L()];
      b.addEventListener('click', () => ask(pair[L()]));
      chipsBox.appendChild(b);
    });
  }

  /* ===== Pestañas ===== */
  function showTab(name) {
    assistant.querySelectorAll('.la-tab').forEach((t) => t.classList.toggle('is-active', t.dataset.tab === name));
    $('.la-view-chat').hidden = name !== 'chat';
    $('.la-view-train').hidden = name !== 'train';
    if (name === 'train') renderTrain();
  }
  assistant.querySelectorAll('.la-tab').forEach((t) => t.addEventListener('click', () => showTab(t.dataset.tab)));
  function goTeach(q) {
    showTab('train');
    resetTeachForm();
    $('.la-tk').value = q || '';
    $('.la-tr').focus();
  }

  /* ===== Entrenamiento ===== */
  const tcSel = $('.la-tc');
  CATS.forEach((c) => { const o = document.createElement('option'); o.textContent = c; tcSel.appendChild(o); });
  function toast(msg) {
    const el = $('.la-toast');
    el.textContent = msg;
    setTimeout(() => { if (el.textContent === msg) el.textContent = ''; }, 3000);
  }
  function resetTeachForm() {
    editIdx = -1;
    $('.la-tk').value = '';
    $('.la-tr').value = '';
    tcSel.value = 'Otro';
    $('.la-cancel').hidden = true;
    $('.la-form-title').textContent = T().assistant_teach_title;
  }
  $('.la-cancel').addEventListener('click', resetTeachForm);
  $('.la-save').addEventListener('click', () => {
    const k = $('.la-tk').value.split('\n').map((s) => s.trim()).filter(Boolean);
    const r = $('.la-tr').value.trim();
    if (!k.length || !r) { toast(T().assistant_need_both); return; }
    const entry = { c: tcSel.value, k, r };
    if (editIdx >= 0) learned[editIdx] = entry; else learned.unshift(entry);
    missed = missed.filter((m) => !k.some((x) => norm(x) === norm(m)));
    storeArr('nvision_bot_learned', learned);
    storeArr('nvision_bot_missed', missed);
    resetTeachForm();
    renderTrain();
    toast(T().assistant_saved_toast);
  });
  function itemRow(mainHtml, buttons) {
    const row = document.createElement('div');
    row.className = 'la-item';
    const main = document.createElement('div');
    main.innerHTML = mainHtml;
    const btns = document.createElement('span');
    btns.className = 'la-item-btns';
    buttons.forEach(([label, fn]) => {
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'la-btn la-sm';
      b.textContent = label;
      b.addEventListener('click', fn);
      btns.appendChild(b);
    });
    row.append(main, btns);
    return row;
  }
  function renderTrain() {
    $('.la-n-base').textContent = KB.length;
    $('.la-n-learn').textContent = learned.length;
    const missedBox = $('.la-missed');
    missedBox.replaceChildren();
    if (!missed.length) {
      const p = document.createElement('p'); p.className = 'la-hint'; p.textContent = T().assistant_missed_empty; missedBox.appendChild(p);
    }
    missed.forEach((m, i) => {
      missedBox.appendChild(itemRow(esc(m), [
        [T().assistant_teach_btn, () => goTeach(m)],
        [T().assistant_remove_btn, () => { missed.splice(i, 1); storeArr('nvision_bot_missed', missed); renderTrain(); }]
      ]));
    });
    const learnedBox = $('.la-learned');
    learnedBox.replaceChildren();
    if (!learned.length) {
      const p = document.createElement('p'); p.className = 'la-hint'; p.textContent = T().assistant_learned_empty; learnedBox.appendChild(p);
    }
    learned.forEach((e, i) => {
      const head = `<span class="la-tag">${esc(e.c)}</span> <b>${esc(e.k[0])}</b>${e.k.length > 1 ? ` <small>+${e.k.length - 1}</small>` : ''}<br><small>${esc(e.r.slice(0, 110))}${e.r.length > 110 ? '…' : ''}</small>`;
      learnedBox.appendChild(itemRow(head, [
        [T().assistant_edit_btn, () => { editIdx = i; $('.la-tk').value = e.k.join('\n'); $('.la-tr').value = e.r; tcSel.value = e.c; $('.la-cancel').hidden = false; $('.la-form-title').textContent = T().assistant_edit_title; }],
        [T().assistant_delete_btn, () => { if (confirm(T().assistant_confirm_delete)) { learned.splice(i, 1); storeArr('nvision_bot_learned', learned); resetTeachForm(); renderTrain(); } }]
      ]));
    });
  }
  $('.la-test').addEventListener('input', (ev) => {
    const q = ev.target.value;
    const out = $('.la-test-out');
    if (!q.trim()) { out.textContent = ''; return; }
    const b = bestMatch(q);
    const p = Math.round(b.score * 100);
    out.innerHTML = b.score >= 0.4
      ? `${esc(T().assistant_match)} «<b>${esc(b.key)}</b>» (${p} %).<br>${fmt(b.e.r[L()].slice(0, 160))}…`
      : `${esc(T().assistant_no_match)} (${p} %).`;
  });
  $('.la-exp').addEventListener('click', () => {
    const bk = $('.la-bk');
    bk.value = JSON.stringify(learned, null, 1);
    bk.select();
    try { navigator.clipboard.writeText(bk.value); } catch (e) {}
  });
  $('.la-imp').addEventListener('click', () => {
    try {
      const a = JSON.parse($('.la-bk').value);
      if (!Array.isArray(a)) throw new Error('bad');
      const ok = a.filter((x) => x && Array.isArray(x.k) && x.k.length && typeof x.r === 'string' && x.r.trim())
        .map((x) => ({ c: CATS.includes(x.c) ? x.c : 'Otro', k: x.k.map(String), r: x.r }));
      learned = [...ok, ...learned];
      storeArr('nvision_bot_learned', learned);
      renderTrain();
      toast(ok.length + ' ' + T().assistant_imported);
    } catch (e) { toast(T().assistant_import_bad); }
  });
  $('.la-reset').addEventListener('click', () => {
    if (!confirm(T().assistant_confirm_reset)) return;
    learned = [];
    missed = [];
    storeArr('nvision_bot_learned', learned);
    storeArr('nvision_bot_missed', missed);
    resetTeachForm();
    renderTrain();
  });

  /* ===== Abrir / cerrar y primer saludo ===== */
  let greeted = false;
  toggle.addEventListener('click', () => {
    const isOpen = !panel.hidden;
    panel.hidden = isOpen;
    toggle.setAttribute('aria-expanded', String(!isOpen));
    if (!isOpen) {
      renderChips();
      if (!greeted) { greeted = true; say(KB[0].r[L()], null, null, null); }
      input.focus();
    }
  });
  closeBtn.addEventListener('click', () => {
    panel.hidden = true;
    toggle.setAttribute('aria-expanded', 'false');
  });
  form.addEventListener('submit', (event) => {
    event.preventDefault();
    const v = input.value;
    input.value = '';
    ask(v);
  });
}

function setupCursorEffect() {
  if (window.matchMedia('(pointer: coarse)').matches || window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;

  const effect = document.createElement('div');
  effect.className = 'cursor-effect';
  effect.setAttribute('aria-hidden', 'true');
  effect.innerHTML = '<span class="cursor-aura"></span><span class="cursor-dot"></span>';
  document.body.appendChild(effect);

  let frame = 0;
  window.addEventListener('pointermove', (event) => {
    if (frame) cancelAnimationFrame(frame);
    frame = requestAnimationFrame(() => {
      effect.style.setProperty('--cursor-x', `${event.clientX}px`);
      effect.style.setProperty('--cursor-y', `${event.clientY}px`);
      effect.classList.add('is-visible');
      frame = 0;
    });
  }, { passive: true });

  document.documentElement.addEventListener('mouseleave', () => effect.classList.remove('is-visible'));
}

document.addEventListener('DOMContentLoaded', () => {
  setupThemeToggle();
  setupLanguageDropdown();
  setupCopyButton();
  setupDetector();
  setupMobileMenu();
  setupSectionNavigation();
  setupNavigationDropdowns();
  setupHistoryToggle();
  setupComponentToggles();
  setupMaintenanceToolImages();
  setupNetworkSimulator();
  setupSwitchLab();
  setupLocalAssistant();
  setupCursorEffect();
  applyLanguage(currentLang);
});



function setupHistoryToggle() {
  const historyButtons = document.querySelectorAll('.btn-expand-history');
  historyButtons.forEach((btn) => {
    btn.addEventListener('click', () => {
      let targetId = btn.getAttribute('data-target');
      if (!targetId && btn.id === 'toggle-eniac-btn') {
        targetId = 'eniac-detail-box';
      }
      const detailPanel = document.getElementById(targetId);
      if (!detailPanel) return;

      const isExpanded = btn.getAttribute('aria-expanded') === 'true';
      const nextState = !isExpanded;

      btn.setAttribute('aria-expanded', String(nextState));
      detailPanel.hidden = !nextState;

      const textSpan = btn.querySelector('.btn-expand-text');
      if (textSpan) {
        const key = nextState ? 'btn_hide_full_history' : 'btn_see_full_history';
        textSpan.setAttribute('data-i18n', key);
        if (translations[currentLang] && translations[currentLang][key]) {
          textSpan.textContent = translations[currentLang][key];
        }
      }

      if (nextState) {
        detailPanel.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
      }
    });
  });
}

function setupComponentToggles() {
  const compButtons = document.querySelectorAll('.btn-component-expand');
  compButtons.forEach((btn) => {
    btn.addEventListener('click', () => {
      const targetId = btn.getAttribute('data-target');
      const targetBox = document.getElementById(targetId);
      if (!targetBox) return;

      const isExpanded = btn.getAttribute('aria-expanded') === 'true';
      const nextState = !isExpanded;

      btn.setAttribute('aria-expanded', String(nextState));
      targetBox.hidden = !nextState;

      const textSpan = btn.querySelector('.comp-btn-text');
      if (textSpan) {
        const key = nextState ? 'btn_hide_component_img' : 'btn_view_component_img';
        textSpan.setAttribute('data-i18n', key);
        if (translations[currentLang] && translations[currentLang][key]) {
          textSpan.textContent = translations[currentLang][key];
        }
      }
    });
  });
}


function setupMaintenanceToolImages() {
  const toolImages = {
    'Juego de destornilladores': 'https://jensa.vtexassets.com/arquivos/ids/161306-800-800?v=638188042753000000&width=800&height=800&aspect=true',
    'Pulsera antiestática': 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTHIlvAxb8SWQnWT1tSrBmRa3LFzUeqdscmSiBerjNlcg&s=10',
    'Aire comprimido': 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTqSPbG2H8ImniMSLt5Xm3rwyTiNe8bgjbbZchfrYN19A&s=10',
    'Pasta térmica': 'https://acf.geeknetic.es/imgri/imagenes/auto/20/06/17/eaj-jgv-71t7np6iz6l-sl1500.jpg?f=webp',
    'Paño de microfibra': 'https://www.esmero.com.co/wp-content/uploads/2020/06/esmero_panos_microfibra_azul_task.jpg',
    'Compressed air': 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTqSPbG2H8ImniMSLt5Xm3rwyTiNe8bgjbbZchfrYN19A&s=10',
    'Thermal paste': 'https://acf.geeknetic.es/imgri/imagenes/auto/20/06/17/eaj-jgv-71t7np6iz6l-sl1500.jpg?f=webp',
    'Microfiber cloth': 'https://www.esmero.com.co/wp-content/uploads/2020/06/esmero_panos_microfibra_azul_task.jpg'
  };

  document.querySelectorAll('.pc3d-tool-card').forEach((card) => {
    const image = card.querySelector('img');
    if (!image) return;
    const replacement = toolImages[image.alt];
    if (replacement) image.src = replacement;
    if (image.alt === 'Brochas de limpieza' || image.alt === 'Bridas organizadoras') {
      card.hidden = true;
    }
  });
}

function setupSwitchLab() {
  const svg = document.getElementById('swl-svg');
  if (!svg) return;
  const fromSel = document.getElementById('swl-from');
  const toSel = document.getElementById('swl-to');
  const sendBtn = document.getElementById('swl-send');
  const resetBtn = document.getElementById('swl-reset');
  const caption = document.getElementById('swl-caption');
  const tbody = document.getElementById('swl-mac-body');
  const modeSwitchBtn = document.getElementById('swl-mode-switch');
  const modeHubBtn = document.getElementById('swl-mode-hub');
  const deviceName = document.getElementById('swl-device-name');
  const framesLayer = document.getElementById('swl-frames');
  const NS = 'http://www.w3.org/2000/svg';
  const PCS = [
    { x: 180, mac: 'AA:BB:CC:00:00:01' },
    { x: 320, mac: 'AA:BB:CC:00:00:02' },
    { x: 460, mac: 'AA:BB:CC:00:00:03' },
    { x: 600, mac: 'AA:BB:CC:00:00:04' }
  ];
  const MID_Y = 70, PC_Y = 292;
  const learned = new Map(); // puerto -> indice de PC
  let mode = 'switch';
  let busy = false;

  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const t = key => translations[currentLang]?.[key] || key;
  function cap(key, params = {}) {
    let txt = t(key);
    for (const k in params) txt = txt.replaceAll('{' + k + '}', params[k]);
    caption.innerHTML = iconize(txt);
  }
  const pcName = i => 'PC' + (i + 1);

  function renderTable(hiPort = null) {
    tbody.innerHTML = '';
    const row = cells => {
      const tr = document.createElement('tr');
      cells.forEach(c => { const td = document.createElement('td'); td.textContent = c; tr.appendChild(td); });
      return tr;
    };
    if (mode === 'hub') {
      const tr = row([t('swl_table_hub')]);
      tr.firstChild.colSpan = 3; tr.className = 'swl-note-row';
      tbody.appendChild(tr); return;
    }
    if (!learned.size) {
      const tr = row([t('swl_table_empty')]);
      tr.firstChild.colSpan = 3; tr.className = 'swl-note-row';
      tbody.appendChild(tr); return;
    }
    [...learned.entries()].sort((a, b) => a[0] - b[0]).forEach(([port, pc]) => {
      const tr = row(['P' + port, PCS[pc].mac, pcName(pc)]);
      if (port === hiPort) tr.className = 'is-new';
      tbody.appendChild(tr);
    });
  }

  function flashPc(i) {
    const el = document.getElementById('swl-pc-' + i);
    if (!el) return;
    el.classList.add('is-hit');
    setTimeout(() => el.classList.remove('is-hit'), 1100);
  }
  function flashPort(p) {
    const el = document.getElementById('swl-port-' + p);
    if (!el) return;
    el.classList.add('is-active-port');
    setTimeout(() => el.classList.remove('is-active-port'), 900);
  }

  function makeDot() {
    const c = document.createElementNS(NS, 'circle');
    c.setAttribute('r', '9');
    c.setAttribute('class', 'swl-frame');
    framesLayer.appendChild(c);
    return c;
  }
  function moveAlong(dot, pts) {
    return new Promise(res => {
      const segs = []; let total = 0;
      for (let i = 1; i < pts.length; i++) {
        const len = Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]);
        segs.push({ a: pts[i - 1], b: pts[i], len }); total += len;
      }
      const dur = Math.max(260, total / 0.42);
      const t0 = performance.now();
      (function frame(now) {
        const p = Math.min(1, (now - t0) / dur);
        let d = p * total;
        for (const sg of segs) {
          if (d <= sg.len) {
            const k = sg.len ? d / sg.len : 0;
            dot.setAttribute('cx', sg.a[0] + (sg.b[0] - sg.a[0]) * k);
            dot.setAttribute('cy', sg.a[1] + (sg.b[1] - sg.a[1]) * k);
            break;
          }
          d -= sg.len;
        }
        if (p < 1) requestAnimationFrame(frame); else res();
      })(t0);
    });
  }

  async function travel(from, to) {
    const dot = makeDot();
    flashPort(from + 1);
    await moveAlong(dot, [[PCS[from].x, PC_Y], [PCS[from].x, MID_Y], [PCS[to].x, MID_Y], [PCS[to].x, PC_Y]]);
    flashPort(to + 1); flashPc(to);
    dot.remove();
  }
  async function upToSwitch(from) {
    const dot = makeDot();
    flashPort(from + 1);
    await moveAlong(dot, [[PCS[from].x, PC_Y], [PCS[from].x, MID_Y]]);
    return dot;
  }
  async function floodFromSwitch(from) {
    const jobs = [];
    for (let i = 0; i < 4; i++) {
      if (i === from) continue;
      const dot = makeDot();
      jobs.push((async () => {
        await moveAlong(dot, [[PCS[from].x, MID_Y], [PCS[i].x, MID_Y], [PCS[i].x, PC_Y]]);
        flashPort(i + 1); flashPc(i);
        dot.remove();
      })());
    }
    await Promise.all(jobs);
  }

  async function send() {
    if (busy) return;
    const from = parseInt(fromSel.value, 10);
    const to = parseInt(toSel.value, 10);
    if (from === to) return;
    busy = true; sendBtn.disabled = true;

    if (mode === 'hub') {
      cap('swl_cap_send', { from: pcName(from), to: pcName(to) });
      await sleep(650);
      cap('swl_cap_hub');
      const hdot = await upToSwitch(from);
      await floodFromSwitch(from);
      hdot.remove();
      cap('swl_cap_hub_done', { to: pcName(to) });
      busy = false; sendBtn.disabled = false;
      return;
    }

    cap('swl_cap_send', { from: pcName(from), to: pcName(to) });
    await sleep(650);
    cap('swl_cap_enter', { from: pcName(from), port: from + 1 });
    // La trama sube hasta el switch y espera ahi mientras decide
    const dot = await upToSwitch(from);

    // Aprende el origen
    if (!learned.has(from + 1)) {
      learned.set(from + 1, from);
      renderTable(from + 1);
      cap('swl_cap_learn', { from: pcName(from), port: from + 1 });
      await sleep(1500);
    }
    cap('swl_cap_lookup', { to: pcName(to) });
    await sleep(1000);

    if (learned.has(to + 1)) {
      cap('swl_cap_forward', { port: to + 1 });
      await sleep(900);
      await moveAlong(dot, [[PCS[from].x, MID_Y], [PCS[to].x, MID_Y], [PCS[to].x, PC_Y]]);
      flashPort(to + 1); flashPc(to);
      dot.remove();
      cap('swl_cap_done', { to: pcName(to) });
    } else {
      cap('swl_cap_flood', { to: pcName(to) });
      await sleep(1000);
      await floodFromSwitch(from);
      dot.remove();
      // Aprende el destino con la respuesta
      learned.set(to + 1, to);
      renderTable(to + 1);
      cap('swl_cap_reply', { to: pcName(to), port: to + 1 });
      await sleep(1600);
      await travel(to, from);
      cap('swl_cap_done', { to: pcName(to) });
    }
    busy = false; sendBtn.disabled = false;
  }

  function setMode(m) {
    mode = m;
    modeSwitchBtn.classList.toggle('is-active', m === 'switch');
    modeHubBtn.classList.toggle('is-active', m === 'hub');
    deviceName.textContent = m === 'hub' ? 'HUB' : 'SWITCH';
    renderTable();
    cap(m === 'hub' ? 'swl_caption_hub_idle' : 'swl_caption_idle');
  }

  [fromSel, toSel].forEach(sel => sel.addEventListener('change', () => {
    if (fromSel.value === toSel.value) {
      const other = sel === fromSel ? toSel : fromSel;
      other.value = String((parseInt(sel.value, 10) + 1) % 4);
    }
  }));
  sendBtn.addEventListener('click', send);
  resetBtn.addEventListener('click', () => { learned.clear(); renderTable(); cap('swl_caption_idle'); });
  modeSwitchBtn.addEventListener('click', () => setMode('switch'));
  modeHubBtn.addEventListener('click', () => setMode('hub'));
  renderTable();
}

/* =========================================================
   LÓGICA DEL SIMULADOR INTERACTIVO DE PING & TRÁNSITO ICMP
   ========================================================= */

function setupNetworkSimulator() {
  const startBtn = document.getElementById('sim-start-btn');
  const resetBtn = document.getElementById('sim-reset-btn');
  const sourceSelect = document.getElementById('sim-source-select');
  const targetSelect = document.getElementById('sim-target-select');
  const packet = document.getElementById('sim-packet');
  const packetText = document.getElementById('packet-type-text');
  const consoleBody = document.getElementById('sim-console');
  const statusTag = document.getElementById('sim-status-tag');
  const inspL2 = document.getElementById('insp-l2-info');
  const inspL3 = document.getElementById('insp-l3-info');
  const inspStat = document.getElementById('insp-stat-info');
  const stage = document.getElementById('sim-stage');

  if (!startBtn || !stage) return;

  const devices = {
    pc1: { id: 'node-pc1', ip: '192.168.1.10', mac: '00:1A:2B:3C:4D:01', name: 'PC 1' },
    pc2: { id: 'node-pc2', ip: '192.168.1.20', mac: '00:1A:2B:3C:4D:02', name: 'PC 2' },
    switch: { id: 'node-switch', ip: 'L2 Switch', mac: 'CAM Table', name: 'Switch LAN' },
    router: { id: 'node-router', ip: '192.168.1.1', mac: '00:00:5E:00:53:01', name: 'Gateway Router' },
    server: { id: 'node-server', ip: '10.0.0.80', mac: 'AA:BB:CC:DD:EE:80', name: 'Web Server' }
  };

  let isRunning = false;
  let currentDevice = null;

  const tr = (key, vars) => {
    let out = (translations[currentLang] && translations[currentLang][key]) || (translations.es && translations.es[key]) || '';
    if (vars) Object.keys(vars).forEach((k) => { out = out.split('{' + k + '}').join(String(vars[k])); });
    return out;
  };

  function log(msg, type = 'info') {
    if (!consoleBody) return;
    const p = document.createElement('p');
    p.className = `console-line ${type}`;
    p.textContent = msg;
    consoleBody.appendChild(p);
    consoleBody.scrollTop = consoleBody.scrollHeight;
  }

  function getDeviceCenter(devKey) {
    const el = document.getElementById(devices[devKey].id);
    if (!el || !stage) return { x: 50, y: 50 };
    const stageRect = stage.getBoundingClientRect();
    const elRect = el.getBoundingClientRect();
    const x = elRect.left - stageRect.left + elRect.width / 2;
    const y = elRect.top - stageRect.top + elRect.height / 2;
    return { x, y };
  }

  function movePacketTo(devKey, callback, duration = 750) {
    const coords = getDeviceCenter(devKey);
    setActiveRoute(currentDevice, devKey);
    positionPacket(coords);
    currentDevice = devKey;
    setTimeout(callback, duration);
  }

  function positionPacket(coords) {
    const packetWidth = packet.offsetWidth;
    const packetHeight = packet.offsetHeight;
    const maxX = Math.max(4, stage.clientWidth - packetWidth - 4);
    const x = Math.min(Math.max(4, coords.x - packetWidth / 2), maxX);
    const y = Math.max(4, coords.y - packetHeight - 8);
    packet.style.transform = `translate(${x}px, ${y}px)`;
  }

  function setActiveRoute(fromKey, toKey) {
    document.querySelectorAll('.sim-wire-glow').forEach(wire => wire.classList.remove('pulse'));
    stage.classList.toggle('reply-mode', packet.classList.contains('reply'));
    const route = [fromKey, toKey].sort().join('-');
    const wireByRoute = {
      'pc1-switch': 'wire-active-pc1',
      'pc2-switch': 'wire-active-pc2',
      'router-switch': 'wire-active-sr',
      'router-server': 'wire-active-dest'
    };
    const wire = document.getElementById(wireByRoute[route]);
    if (wire) wire.classList.add('pulse');
  }

  function highlightDevice(devKey) {
    document.querySelectorAll('.sim-device').forEach(d => {
      d.classList.remove('processing-packet', 'processing-reply', 'active-source', 'active-target');
    });
    const el = document.getElementById(devices[devKey].id);
    if (el) {
      el.classList.add(packet.classList.contains('reply') ? 'processing-reply' : 'processing-packet');
    }
  }

  function updateSelectionsUI() {
    document.querySelectorAll('.sim-device').forEach(d => {
      d.classList.remove('active-source', 'active-target');
    });
    const srcEl = document.getElementById(devices[sourceSelect.value]?.id);
    const dstEl = document.getElementById(devices[targetSelect.value]?.id);
    if (srcEl) srcEl.classList.add('active-source');
    if (dstEl) dstEl.classList.add('active-target');
  }

  sourceSelect.addEventListener('change', updateSelectionsUI);
  targetSelect.addEventListener('change', updateSelectionsUI);
  updateSelectionsUI();

  resetBtn.addEventListener('click', () => {
    isRunning = false;
    startBtn.disabled = false;
    packet.hidden = true;
    packet.className = 'packet-traveler';
    currentDevice = null;
    setActiveRoute(null, null);
    document.querySelectorAll('.sim-device').forEach(d => {
      d.classList.remove('processing-packet', 'processing-reply');
    });
    consoleBody.innerHTML = '<p class="console-line info">' + tr('sim_log_reset') + '</p>';
    statusTag.textContent = translations[currentLang]?.sim_status_ready || 'LISTO';
    statusTag.className = 'sim-status-idle';
    inspL2.textContent = tr('red_insp_l2_init');
    inspL3.textContent = 'IP Src: -- | IP Dst: -- | TTL: --';
    inspStat.textContent = tr('red_insp_stat_init');
    updateSelectionsUI();
  });

  startBtn.addEventListener('click', () => {
    const src = sourceSelect.value;
    const dst = targetSelect.value;

    if (src === dst) {
      log(tr('sim_log_same_host'), 'info');
      return;
    }

    if (isRunning) return;
    isRunning = true;
    startBtn.disabled = true;
    statusTag.textContent = tr('sim_status_transmitting');
    statusTag.className = 'sim-status-running';
    consoleBody.innerHTML = '';

    const srcDev = devices[src];
    const dstDev = devices[dst];

    log(tr('sim_log_icmp_start', { src: srcDev.name, srcIp: srcDev.ip, dst: dstDev.name, dstIp: dstDev.ip }), 'req');

    // Posición inicial del paquete
    const initPos = getDeviceCenter(src);
    packet.hidden = false;
    packet.className = 'packet-traveler';
    currentDevice = src;
    setActiveRoute(null, null);
    packetText.textContent = tr('red_sim_packet_sending');
    positionPacket(initPos);

    inspL2.textContent = tr('sim_insp_frame', { a: srcDev.mac, b: srcDev.ip.startsWith('192.168.1') && dstDev.ip.startsWith('10.0.0') ? devices.router.mac : dstDev.mac });
    inspL3.textContent = `IP Src: ${srcDev.ip} -> IP Dst: ${dstDev.ip} | Protocol: 1 (ICMP) | TTL: 64`;
    inspStat.textContent = tr('sim_insp_calc');

    // RUTA DE IDA
    const isSameSubnet = dst === 'pc2';

    // Paso 1: Salida del Host a Switch
    setTimeout(() => {
      log(tr('sim_log_host_nic', { name: srcDev.name }), 'l2');
      highlightDevice(src);
      movePacketTo('switch', () => {
        highlightDevice('switch');
        log(tr('sim_log_switch_cam'), 'l2');

        if (isSameSubnet) {
          // Destino local: Switch entrega directo a PC2
          setTimeout(() => {
            movePacketTo(dst, () => {
              highlightDevice(dst);
              log(tr('sim_log_dest_ok', { name: dstDev.name }), 'rep');
              startReturnTrip(srcDev, dstDev, true);
            });
          }, 600);
        } else {
          // Destino WAN: Switch entrega al Router Gateway
          setTimeout(() => {
            log(tr('sim_log_switch_wan'), 'l2');
            movePacketTo('router', () => {
              highlightDevice('router');
              log(tr('sim_log_router_l3'), 'l3');
              inspL3.textContent = `IP Src: ${srcDev.ip} -> IP Dst: ${dstDev.ip} | Protocol: 1 (ICMP) | TTL: 63`;

              // Router a Servidor
              setTimeout(() => {
                log(tr('sim_log_router_wan', { name: dstDev.name }), 'l3');
                movePacketTo('server', () => {
                  highlightDevice('server');
                  log(tr('sim_log_web_server'), 'rep');
                  startReturnTrip(srcDev, dstDev, false);
                });
              }, 650);
            });
          }, 650);
        }
      });
    }, 400);

    function startReturnTrip(srcD, dstD, isLocal) {
      setTimeout(() => {
        packet.classList.add('reply');
        packetText.textContent = tr('sim_packet_received');
        log(tr('sim_log_icmp_reply', { a: dstD.ip, b: srcD.ip }), 'rep');
        inspL2.textContent = `Trama: ${dstD.mac} -> ${srcD.mac}`;

        if (isLocal) {
          movePacketTo('switch', () => {
            highlightDevice('switch');
            log(tr('sim_log_switch_reply', { name: srcD.name }), 'l2');
            setTimeout(() => {
              movePacketTo(src, () => finishPing(true));
            }, 600);
          });
        } else {
          movePacketTo('router', () => {
            highlightDevice('router');
            log(tr('sim_log_router_reply'), 'l3');
            setTimeout(() => {
              movePacketTo('switch', () => {
                highlightDevice('switch');
                log(tr('sim_log_switch_final', { name: srcD.name }), 'l2');
                setTimeout(() => {
                  movePacketTo(src, () => finishPing(false));
                }, 600);
              });
            }, 600);
          });
        }
      }, 700);
    }

    function finishPing(isLocal) {
      highlightDevice(src);
      const rtt = isLocal ? (Math.random() * 2 + 1).toFixed(2) : (Math.random() * 8 + 24).toFixed(2);
      log(tr('sim_log_success', { ip: dstDev.ip, ttl: isLocal ? 64 : 63, rtt }), 'rep');
      log(tr('sim_log_summary'), 'info');
      inspStat.textContent = tr('sim_insp_connected', { rtt });
      statusTag.textContent = tr('sim_status_done');
      statusTag.className = 'sim-status-idle';
      startBtn.disabled = false;
      isRunning = false;
      setTimeout(() => {
        document.querySelectorAll('.sim-device').forEach(d => {
          d.classList.remove('processing-packet', 'processing-reply');
        });
      }, 1000);
    }
  });
}